def _cfg_value(cid, player=None):
    # The VIP panel must always identify its featured plant as Winter Melon. Whether the
    # player can use it is independently controlled by VIP privilege 41.
    if cid == "iVIPSpecialPlant":
        return str(_VIP_PLANT)
    if cid in SERVER_CONFIG_OVERRIDES:
        return SERVER_CONFIG_OVERRIDES[cid]
    return "" if cid.startswith("s") else "1"


def make_server_config_entries(player=None):
    """Encode each config id as a Dto_ServerConfig {1:id, 2:value} sub-message,
    wrapped as repeated field 19 of Cmd_Init_SC. Player-aware for per-account config (iVIPSpecialPlant)."""
    out = b""
    for cid in SERVER_CONFIG_IDS:
        dto = pb_string(1, cid) + pb_string(2, _cfg_value(cid, player))
        out += pb_tag(19, 2) + uvarint(len(dto)) + dto
    return out


def make_battle_formation_sc():
    """Cmd_Battle_GetFormation_SC with one minimal attack formation.
    Needed so getAttackBattleTeam() is non-empty AND has totalPower>0 — otherwise
    refreshFightPower()'s best-team stays null and the role/HUD panel crashes.
    Dto_FormationInfo fields: cardPos(1), formationId(2), leaderUid(3), totalPower(4),
    teamId(5), status(6), recoverHpCost(7), isDefend(8)."""
    # BattleCardFormationVO.totalPower is COMPUTED from cardPos[].powerEle[] entries
    # whose ele == E_PowerEle_total(0) — the totalPower field is ignored. So give the
    # formation one cardPos with a 'total' power element, else the VO's power is 0 and
    # refreshFightPower picks a null best-team.
    power = pb_varint_field(1, 0) + pb_varint_field(2, 100)   # Dto_CardPower{ele=total, value=100}
    cardpos = (pb_varint_field(1, 0)                          # Dto_CardPosInfo.posIndex=0
               + pb_tag(6, 2) + uvarint(len(power)) + power)  # .powerEle[0]
    formation = (pb_tag(1, 2) + uvarint(len(cardpos)) + cardpos  # Dto_FormationInfo.cardPos[0]
                 + pb_varint_field(2, 1)     # formationId
                 + pb_varint_field(4, 100)   # totalPower (VO ignores this; harmless)
                 + pb_varint_field(5, 1)      # teamId (matches defaultTeamId)
                 + pb_varint_field(6, 1)      # status = home
                 + pb_varint_field(8, 0))     # isDefend = 0 -> attack team
    team = pb_tag(2, 2) + uvarint(len(formation)) + formation  # repeated team, field 2
    return team + pb_varint_field(3, 1) + pb_varint_field(4, 1)  # teamMaxNum=1, defaultTeamId=1


def make_signin_getinfo_sc():
    """Cmd_SignIn_GetInfo_SC. Must include signInInfo (field 1 = Dto_SignIn_Info) or the
    client's loadSignInInfo() dereferences null."""
    dto = (pb_varint_field(1, 0) + pb_varint_field(2, 0) + pb_varint_field(3, 0)
           + pb_varint_field(4, 0) + pb_varint_field(5, 0))
    return pb_tag(1, 2) + uvarint(len(dto)) + dto


def make_td_getstageinfo_sc():
    """Cmd_TD_GetStageInfo_SC. stageId must match actorLatestTDLevel.stageId(=1) so the
    client's loadCmd_TD_GetStageInfo_SC builds stage-1 levels from its template; otherwise
    onCmd_TD_RequestStageInfo_SC's getLevelByLevelId(2,1) returns null and crashes."""
    return pb_varint_field(1, 1)  # stageId = 1


# Messages that crash the client when empty — send populated responses instead.
# (Battle needs a non-empty team OR defaultTeamId!=0; the generic populator can't
#  know an array gets indexed, so this one stays explicit.)
SPECIAL_SC = {
    # Cmd_Battle_GetFormation is now a request handler (needs the player's real team/cards).
    # Cmd_TD_GetStageInfo_SC is now a request handler (needs the player's passed levels).
}


# --- generic response populator ------------------------------------------------
# Most init handlers crash on an EMPTY _SC because they dereference a nested message
# field (e.g. roleGuildInfo.guildId) that is null. Fix: read the _SC's field defs from
# the decompiled source and emit every single (non-repeated) TYPE_MESSAGE field as an
# empty-but-present sub-message, recursively. Scalars default fine; arrays stay [].
CMD_DIR = os.path.abspath(os.path.join(
    os.path.dirname(os.path.abspath(__file__)), "..", "Assets", "src", "PVZ", "Cmd"))

_MSG_FIELD_RE = re.compile(
    r'(?<!Repeated)FieldDescriptor\$TYPE_MESSAGE\("[^"]+","[A-Za-z0-9_]+",'
    r'(\d+) << 3 \| WireType\.LENGTH_DELIMITED,([A-Za-z0-9_]+)')
# Int64/UInt64 fields are OBJECTS in AS3 (have .low/.high) -> null-crash like messages.
_I64_FIELD_RE = re.compile(
    r'(?<!Repeated)FieldDescriptor\$TYPE_(?:INT64|UINT64)\("[^"]+","[A-Za-z0-9_]+",'
    r'(\d+) << 3')


@functools.lru_cache(maxsize=None)
def _fields(class_name):
    """(single message fields [(num,dto)], single int64/uint64 fields [num])."""
    path = os.path.join(CMD_DIR, class_name + ".as")
    if not os.path.isfile(path):
        return (), ()
    txt = open(path, encoding="utf-8", errors="replace").read()
    msgs = tuple((int(n), dto) for n, dto in _MSG_FIELD_RE.findall(txt))
    i64s = tuple(int(n) for n in _I64_FIELD_RE.findall(txt))
    return msgs, i64s


def populate_message(class_name, depth=5):
    """Bytes for a message with every nested message field present-but-empty and every
    Int64/UInt64 field set to 0 (both are objects that null-crash when accessed)."""
    if depth <= 0:
        return b""
    msgs, i64s = _fields(class_name)
    out = b""
    for num, dto in msgs:
        sub = populate_message(dto, depth - 1)
        out += pb_tag(num, 2) + uvarint(len(sub)) + sub
    for num in i64s:
        out += pb_varint_field(num, 0)
    return out


def response_for(sc_name):
    """Body bytes for a server->client _SC message name."""
    if sc_name in SPECIAL_SC:
        return SPECIAL_SC[sc_name]()
    return populate_message(sc_name.rsplit(".", 1)[-1])


# --- level rewards (from clientDB levelselectInfo.txt) ----------------------------
# Each TD level defines its own rewards; we grant those instead of a flat amount.
#   firstCoin  = coins on FIRST clear      bonusCoin = coins on a repeat clear
#   bonusExp   = exp reward                bonusPlant= a plantId unlocked on first clear
#   bonusItems = "itemId:amt;..." (needs the bag system — deferred)
_LEVEL_REWARDS = None
_CLIENTDB_PATH = os.path.abspath(os.path.join(
    os.path.dirname(os.path.abspath(__file__)), "..", "webroot", "clientDB.txt"))


def load_level_rewards():
    """Parse levelselectInfo.txt out of the clientDB archive once; cache the result.
    Returns {(stage, level, sub): {firstCoin, bonusCoin, bonusExp, bonusPlant, bonusItems}}."""
    global _LEVEL_REWARDS
    if _LEVEL_REWARDS is not None:
        return _LEVEL_REWARDS
    _LEVEL_REWARDS = {}
    if not os.path.isfile(_CLIENTDB_PATH):
        log.warning("clientDB.txt not found (%s) — TD rewards fall back to defaults",
                    _CLIENTDB_PATH)
        return _LEVEL_REWARDS
    data = open(_CLIENTDB_PATH, "rb").read()
    pos, body = 0, None
    while pos + 4 <= len(data):                       # big-endian [len][name][len][tsv] archive
        nlen = int.from_bytes(data[pos:pos + 4], "big"); pos += 4
        name = data[pos:pos + nlen].decode("utf-8", "replace"); pos += nlen
        dlen = int.from_bytes(data[pos:pos + 4], "big"); pos += 4
        chunk = data[pos:pos + dlen]; pos += dlen
        if name == "levelselectInfo.txt":
            body = chunk
            break
    if body is None:
        return _LEVEL_REWARDS
    rows = [r for r in body.decode("utf-8", "replace").replace("\r", "").split("\n") if r.strip()]
    hdr = rows[0].split("\t"); ci = {c: i for i, c in enumerate(hdr)}

    def col(c, k, d=""):
        i = ci.get(k)
        return c[i] if i is not None and i < len(c) else d

    def num(c, k):
        try:
            return int(col(c, k, "0"))
        except ValueError:
            return 0

    for r in rows[1:]:
        c = r.split("\t")
        if col(c, "challengeLevelId", "0") not in ("0", ""):
            continue  # main levels only (challenges handled separately)
        key = (num(c, "stageId"), num(c, "levelId"), num(c, "subLevelId"))
        _LEVEL_REWARDS[key] = {
            "firstCoin": num(c, "firstCoin"), "bonusCoin": num(c, "bonusCoin"),
            "bonusExp": num(c, "bonusExp"), "bonusPlant": num(c, "bonusPlant"),
            "bonusItems": col(c, "bonusItems", ""),
        }
    log.info("loaded %d TD level reward templates from clientDB", len(_LEVEL_REWARDS))
    return _LEVEL_REWARDS


def level_reward(stage, level, sub):
    return load_level_rewards().get((stage, level, sub), {})


# Lab materials have no tower-defence drop table in any shipped clientDB. The ItemInfo gainWay
# strings point at adventure chapters, while the requested local-server behavior is to let normal
# TD clears also supply them. Keep that addition deterministic and deliberately small: one actual
# Lab reagent per successful authored main TD level, rotating through materials that both exist in
# ItemInfo as reagent items and are referenced by Lab.txt costs. Never replace the authored level
# rewards, and do not grant anything for the tutorial or an unknown level.
_TD_LAB_MATERIAL_IDS = None


def td_lab_material_ids():
    """The sorted ItemInfo reagent ids used by Lab.txt unlock/upgrade costs."""
    global _TD_LAB_MATERIAL_IDS
    if _TD_LAB_MATERIAL_IDS is None:
        item_rows = _read_clientdb_table("ItemInfo.txt")
        reagent_ids = set()
        if item_rows:
            headers = {name: i for i, name in enumerate(item_rows[0])}
            id_col, type_col = headers.get("id"), headers.get("type")
            if id_col is not None and type_col is not None:
                for row in item_rows[1:]:
                    try:
                        if int(row[type_col]) == 8:
                            reagent_ids.add(int(row[id_col]))
                    except (ValueError, IndexError):
                        continue

        lab_cost_ids = set()
        for bottle in load_lab().values():
            for level in bottle.get("levels", {}).values():
                for key in ("unlockCost", "upgradeCost"):
                    lab_cost_ids.update(item_id for item_id, _amount in level.get(key, []))
        _TD_LAB_MATERIAL_IDS = tuple(sorted(reagent_ids & lab_cost_ids))
        log.info("loaded %d usable TD laboratory material ids: %s",
                 len(_TD_LAB_MATERIAL_IDS), _TD_LAB_MATERIAL_IDS)
    return _TD_LAB_MATERIAL_IDS


def td_lab_material_reward(stage, level, sub):
    """Return exactly one deterministic Lab reagent for an authored normal TD level win."""
    key = (int(stage), int(level), int(sub))
    if min(key) <= 0:
        return []
    authored_levels = sorted(k for k in load_level_rewards() if k[0] > 0)
    try:
        sequence = authored_levels.index(key)
    except ValueError:
        return []
    materials = td_lab_material_ids()
    if not materials:
        return []
    return [(materials[sequence % len(materials)], 1)]


# --- latestTDLevel sanitizer (prevents the town #1009) -----------------------------
# The town's CityProxy.onCmd_TD_RequestStageInfo_SC reads
#   getLevelByLevelId(actorLatestTDLevel.levelId + 1, 1).unlocked
# with NO null check. If the player's saved latestTDLevel is out of range for the real
# level templates (e.g. a GM-set td_stage=11 that doesn't exist, or a td_level past the
# stage's last level), that lookup returns null and the whole town crashes on load.
# We clamp the saved value into a valid template range at login so the client can't null-deref.
_TD_STAGE_MAXES = None


def td_stage_maxes():
    """(stages, subs): {stageId: max main levelId}, {(stage,level): max subLevelId} from the
    level templates. Real story stages only (stageId>0)."""
    global _TD_STAGE_MAXES
    if _TD_STAGE_MAXES is None:
        stages, subs = {}, {}
        for (stage, level, sub) in load_level_rewards():
            if stage > 0:
                stages[stage] = max(stages.get(stage, 0), level)
                subs[(stage, level)] = max(subs.get((stage, level), 0), sub)
        _TD_STAGE_MAXES = (stages, subs)
    return _TD_STAGE_MAXES


def sanitize_td_progress(player):
    """Clamp the player's latestTDLevel (td_stage/td_level/td_sub) to real template ranges
    and persist any correction. Returns True if it changed. Out-of-range values crash the
    town (#1009) via CityProxy's unguarded getLevelByLevelId(levelId+1,1)."""
    # Stage 0 is intentionally outside the normal TD template table. While the
    # account is in the new-player guide, leave it untouched so Init_SC can route
    # the client to the tutorial map.
    if player.get("tutorial_active"):
        return False
    stages, subs = td_stage_maxes()
    if not stages:
        return False
    stage = player.get("td_stage", 1) or 1
    level = player.get("td_level", 1) or 1
    sub = player.get("td_sub", 1) or 1
    orig = (stage, level, sub)
    if stage not in stages:                       # unknown stage -> highest real stage
        stage = max(stages)
    level = max(1, min(level, stages[stage]))     # 1 .. this stage's last level
    sub = max(1, min(sub, subs.get((stage, level), 1)))  # 1 .. that level's last sub
    if (stage, level, sub) != orig:
        player["td_stage"], player["td_level"], player["td_sub"] = stage, level, sub
        store.save_player(player["uin"], td_stage=stage, td_level=level, td_sub=sub)
        log.info("    sanitized latestTDLevel %s -> %s (out-of-range would crash the town)",
                 orig, (stage, level, sub))
        return True
    return False


def _read_clientdb_table(table_name):
    """Return the tab-separated rows (list of list of str) of a clientDB table, or []."""
    if not os.path.isfile(_CLIENTDB_PATH):
        return []
    data = open(_CLIENTDB_PATH, "rb").read()
    pos, body = 0, None
    while pos + 4 <= len(data):
        nlen = int.from_bytes(data[pos:pos + 4], "big"); pos += 4
        name = data[pos:pos + nlen].decode("utf-8", "replace"); pos += nlen
        dlen = int.from_bytes(data[pos:pos + 4], "big"); pos += 4
        chunk = data[pos:pos + dlen]; pos += dlen
        if name == table_name:
            body = chunk
            break
    if body is None:
        return []
    return [r.split("\t") for r in body.decode("utf-8", "replace").replace("\r", "").split("\n")
            if r.strip()]


# Role leveling: levelInfo.txt.needExp[L] = exp to advance from level L to L+1. actorExp is
# the exp WITHIN the current level (the client's bar is actorExp / needExp[actorLevel]).
_LEVEL_EXP = None


def need_exp(level):
    """Exp required to advance FROM `level` to level+1 (0 if at/above the table's max)."""
    global _LEVEL_EXP
    if _LEVEL_EXP is None:
        _LEVEL_EXP = {}
        rows = _read_clientdb_table("levelInfo.txt")
        if rows:
            hdr = rows[0]; ci = {c: i for i, c in enumerate(hdr)}
            for c in rows[1:]:
                try:
                    _LEVEL_EXP[int(c[ci["id"]])] = int(c[ci["needExp"]])
                except (ValueError, KeyError, IndexError):
                    pass
        log.info("loaded %d role-level exp thresholds", len(_LEVEL_EXP))
    return _LEVEL_EXP.get(int(level), 0)


def normalize_level(player):
    """Consume the player's accumulated exp into level-ups. exp is kept as the progress
    within the current level. Only ever levels UP (a gm-set high level with low exp is
    safe). Returns True if the level increased."""
    level = int(player.get("level", 1))
    exp = int(player.get("exp", 0))
    start = level
    guard = 0
    while guard < 500:
        need = need_exp(level)
        if need <= 0 or exp < need:
            break
        exp -= need
        level += 1
        guard += 1
    player["level"], player["exp"] = level, exp
    return level > start


# --- role-exp economy -------------------------------------------------------------
# clientDB levelselectInfo.bonusExp is empty for almost every level (only 3 stage-1 levels,
# 200 total) — the original game computed role exp SERVER-side. So we grant a computed amount
# per clear from BOTH normal-mode TD and adventure/fuben, first-clear + a reduced replay amount,
# scaled by content depth. Tune these two constants to speed up / slow down leveling.
_ROLE_EXP_BASE = 120        # role exp for a first clear at depth 1
_ROLE_EXP_PER_DEPTH = 45    # extra per difficulty tier (TD stage / fuben chapter)


def role_exp_for_clear(depth, is_first):
    """Role exp for clearing a level/stage. depth = difficulty tier (TD stage 1..5 or fuben
    chapter 1..13); deeper gives more. Replays give ~1/3 so grinding still levels you (slowly)."""
    base = _ROLE_EXP_BASE + _ROLE_EXP_PER_DEPTH * max(0, int(depth) - 1)
    return base if is_first else max(30, base // 3)


def grant_role_exp(player, exp):
    """Add role exp, fold it into level-ups, persist, and return the sync messages: Cmd_SyncExp_SC
    always, plus Cmd_SyncLevel_SC + live building unlocks on a level-up. Used by paths that don't
    already do their own leveling (e.g. fuben/adventure wins)."""
    exp = int(exp)
    if exp <= 0:
        return []
    old_level = int(player.get("level", 1))
    player["exp"] = int(player.get("exp", 0)) + exp
    leveled = normalize_level(player)
    store.save_player(player["uin"], exp=player["exp"], level=player["level"])
    msgs = [("PVZ.Cmd.Cmd_SyncExp_SC", pb_varint_field(1, player["exp"]))]
    if leveled:
        msgs.append(("PVZ.Cmd.Cmd_SyncLevel_SC", pb_varint_field(1, player["level"])))
        msgs += building_unlock_messages(old_level, player["level"])
    return msgs


# --- bag / items -----------------------------------------------------------------
def parse_bonus_items(spec):
    """"id:num;id:num" -> [(item_id, num)]  (level bonusItems / gate needItems format)."""
    out = []
    for part in (spec or "").split(";"):
        if ":" in part:
            a, b = part.split(":", 1)
            try:
                out.append((int(a), int(b)))
            except ValueError:
                pass
    return out


def build_item_dto(item_id, count):
    """Dto_ItemInfo{uid(1), id(2), num(3)}. We use uid = item_id (one stack per item type),
    which is stable so Cmd_Item_Update_SC updates the same stack (BagProxy keys by uid)."""
    return (pb_varint_field(1, item_id)      # uid (Int64) — reuse item_id as a stable stack id
            + pb_varint_field(2, item_id)    # id (the item template id)
            + pb_varint_field(3, count))     # num (stack count)


def make_bag_info(player):
    """Cmd_Item_GetBagInfo_SC: all(1)=every stack, bNext omitted(=false) so it's the last
    page (client then runs initItems + finishes the Init_BagItemInfo init task)."""
    d = b""
    for item_id, count in store.get_items(player["uin"]):
        dto = build_item_dto(item_id, count)
        d += pb_tag(1, 2) + uvarint(len(dto)) + dto   # all (field 1, repeated Dto_ItemInfo)
    for equipment in store.get_equipments(player["uin"]):
        dto = build_equipment_item_dto(equipment)
        d += pb_tag(1, 2) + uvarint(len(dto)) + dto
    return d


def grant_items(player, changes):
    """Apply [(item_id, delta)] to the bag; return a Cmd_Item_Update_SC (name, body) that
    syncs the NEW counts to the client, or None if nothing changed."""
    dtos = b""
    for item_id, delta in changes:
        if not delta:
            continue
        new_count = store.add_item(player["uin"], item_id, delta)
        dto = build_item_dto(item_id, new_count)      # num<=0 -> client removes the stack
        dtos += pb_tag(1, 2) + uvarint(len(dto)) + dto  # changeItems (field 1)
    if not dtos:
        return None
    return ("PVZ.Cmd.Cmd_Item_Update_SC", dtos)


def handle_get_bag_info(cmd_data, player):
    """Cmd_Item_GetBagInfo_CS -> Cmd_Item_GetBagInfo_SC (the player's whole bag)."""
    items = store.get_items(player["uin"])
    equipment = store.get_equipments(player["uin"])
    log.info("    bag info: %d item stack(s), %d equipment object(s)", len(items), len(equipment))
    return make_bag_info(player)


_ITEM_SELL_INFO = None


def load_item_sell_info():
    """Cache ItemInfo's authoritative isCanSell/sellPrice values by item template id."""
    global _ITEM_SELL_INFO
    if _ITEM_SELL_INFO is None:
        _ITEM_SELL_INFO = {}
        rows = _read_clientdb_table("ItemInfo.txt")
        if rows:
            headers = rows[0]
            col = {name: index for index, name in enumerate(headers)}
            for row in rows[1:]:
                try:
                    item_id = int(row[col["id"]])
                    can_sell = int(row[col["isCanSell"]])
                    sell_price = int(row[col["sellPrice"]])
                except (ValueError, KeyError, IndexError):
                    continue
                _ITEM_SELL_INFO[item_id] = (can_sell, max(0, sell_price))
        log.info("loaded %d item sell templates", len(_ITEM_SELL_INFO))
    return _ITEM_SELL_INFO


def handle_item_sellitems(cmd_data, player):
    """Sell the requested ordinary bag stacks using ItemInfo.sellPrice.

    Cmd_Item_SellItems_CS.items is repeated Dto_Id64Num: id is the bag stack uid
    (our normal stacks use their template id as the stable uid), num is the amount.
    The client updates its bag model only from Cmd_Item_Update_SC and then treats
    Cmd_Item_SellItems_SC as the successful completion notification.
    """
    uin = int(player["uin"])
    requested = {}
    for submessage in parse_repeated_submessages(cmd_data, 1):
        fields = parse_varint_fields(submessage)
        item_uid, amount = int(fields.get(1, 0)), int(fields.get(2, 0))
        if item_uid <= 0 or amount <= 0:
            return []
        requested[item_uid] = requested.get(item_uid, 0) + amount
        if requested[item_uid] > 0xFFFFFFFF:
            return []
    if not requested:
        return []

    templates = load_item_sell_info()
    counts = dict(store.get_items(uin))
    total_coin = 0
    for item_uid, amount in requested.items():
        template = templates.get(item_uid)
        if (not template or not template[0] or template[1] <= 0
                or counts.get(item_uid, 0) < amount):
            log.info("    bag sell DENIED: uin=%d item=%d amount=%d can_sell=%s held=%d",
                     uin, item_uid, amount, bool(template and template[0]),
                     counts.get(item_uid, 0))
            return []
        total_coin += amount * template[1]

    # Validate the whole request before changing anything, then persist stack counts.
    item_updates = b""
    for item_uid, amount in requested.items():
        new_count = store.add_item(uin, item_uid, -amount)
        item_updates += pb_bytes(1, build_item_dto(item_uid, new_count))
    player["coin"] = int(player.get("coin") or 0) + total_coin
    store.save_player(uin, coin=player["coin"])

    log.info("    bag sold: uin=%d stacks=%d items=%d coin=+%d",
             uin, len(requested), sum(requested.values()), total_coin)
    return [
        ("PVZ.Cmd.Cmd_Item_Update_SC", item_updates),
        ("PVZ.Cmd.Cmd_SyncCoin_SC", pb_varint_field(1, player["coin"])),
        ("PVZ.Cmd.Cmd_Item_SellItems_SC", b""),
    ]


# --- backpack chests (Cmd_Item_Use_CS) -----------------------------------------------
# Chests won in a mode land in the bag as ordinary item stacks — 僵尸岛宝箱 4071 from the
# island ladder, 普通/优秀/高级/稀有炼狱宝箱 4091..4094 from 无尽炼狱. The bag's 使用 button
# sends Cmd_Item_Use_CS{itemId(1), iNum(2), pwdtag(3)}; there was no handler for it, so the
# server answered with an empty 0-byte frame, the client popped a use error and the chest
# could never be opened (and stayed stuck in the bag).
# Their payouts have no clientDB drop table — CastleBox.txt only covers 城堡冒险's own
# 3801..3839 boxes and endlessReward.txt is a rank->coin table — so the contents are defined
# here and scaled by the chest's own ItemInfo quality.
_CHEST_SUBTYPES = {200, 203, 204, 217, 218, 224, 226, 235}   # ItemInfo type 2 + these = a chest
_CHEST_OPEN_REWARDS = {                       # chest itemId -> [(itemId, amount)] per chest
    4071: ((2013, 30), (1, 8000), (2002, 3), (53900, 10)),      # 僵尸岛宝箱
    4091: ((1, 3000), (2002, 2), (2013, 10)),                   # 普通炼狱宝箱
    4092: ((1, 6000), (2002, 3), (2013, 20), (2104, 1)),        # 优秀炼狱宝箱
    4093: ((1, 12000), (2002, 5), (2013, 40), (2104, 2), (54400, 15)),   # 高级炼狱宝箱
    4094: ((1, 25000), (2002, 8), (2013, 80), (2104, 3), (54900, 10)),   # 稀有炼狱宝箱
}
_CHEST_FALLBACK_BY_QUALITY = {                # any other chest: pay out by its quality
    1: ((1, 2000), (2002, 1)),
    2: ((1, 4000), (2002, 2), (2013, 10)),
    3: ((1, 8000), (2002, 3), (2013, 20), (2104, 1)),
    4: ((1, 15000), (2002, 5), (2013, 40), (2104, 2)),
    5: ((1, 30000), (2002, 8), (2013, 80), (2104, 3)),
}
_CHEST_INDEX = None


def load_chest_index():
    """{itemId: (name, quality, isMultiUse)} for every chest template in ItemInfo.txt —
    ItemInfo type 2 combined with one of _CHEST_SUBTYPES. Cached after the first call."""
    global _CHEST_INDEX
    if _CHEST_INDEX is None:
        _CHEST_INDEX = {}
        rows = _read_clientdb_table("ItemInfo.txt")
        if rows:
            hdr = rows[0]; ci = {c: i for i, c in enumerate(hdr)}

            def col(row, key):
                i = ci.get(key)
                return row[i] if i is not None and i < len(row) else ""
            for r in rows[1:]:
                try:
                    if int(col(r, "type") or 0) != 2:
                        continue
                    if int(col(r, "subType") or 0) not in _CHEST_SUBTYPES:
                        continue
                    _CHEST_INDEX[int(col(r, "id"))] = (
                        col(r, "name"), max(1, min(5, int(col(r, "quality") or 1))),
                        int(col(r, "isMulUse") or 0) == 1)
                except (ValueError, IndexError):
                    continue
        log.info("loaded %d chest templates", len(_CHEST_INDEX))
    return _CHEST_INDEX


def handle_item_use(cmd_data, player):
    """Cmd_Item_Use_CS -> open a backpack chest (or acknowledge an ordinary usable item).

    Chests are consumed and their contents paid out; the client animates the opening from
    Cmd_Item_OpenChest_SC and settles the use flow on Cmd_Item_Use_SC. Anything that isn't a
    chest still gets a Cmd_Item_Use_SC ack so the bag never errors out on 使用.
    """
    uin = int(player["uin"])
    fields = parse_varint_fields(cmd_data)
    item_id = int(fields.get(1, 0))
    want = max(1, int(fields.get(2, 0) or 1))
    chest = load_chest_index().get(item_id)
    if chest is None:
        log.info("    item use: uin=%d item=%d — no chest template, ack only", uin, item_id)
        return [("PVZ.Cmd.Cmd_Item_Use_SC",
                 pb_varint_field(1, item_id) + pb_varint_field(2, want))]
    name, quality, multi = chest
    held = store.get_item_count(uin, item_id)
    if held <= 0:
        log.info("    chest use DENIED: uin=%d %s(%d) held=%d", uin, name, item_id, held)
        return [("PVZ.Cmd.Cmd_Item_Use_SC", pb_varint_field(1, item_id) + pb_varint_field(2, 0))]
    count = min(want, held) if multi else 1
    loot = _CHEST_OPEN_REWARDS.get(item_id) or _CHEST_FALLBACK_BY_QUALITY.get(quality) or ((1, 1000),)
    loot = [(iid, amt * count) for iid, amt in loot]
    # 碎片槽按天轮换：宝箱不再天天给火龙草/椰子加农炮/地刺，每天 0 点换一批高稀有碎片。
    today_pick = daily_fragments(1, salt=item_id)[0]
    loot = [(today_pick if iid in _DAILY_FRAGMENT_REPLACED else iid, amt) for iid, amt in loot]

    messages = []
    consumed = grant_items(player, [(item_id, -count)])   # the chest leaves the bag
    if consumed:
        messages.append(consumed)
    messages += grant_fuben_reward(player, loot)          # currencies -> HUD sync, rest -> bag
    # Cmd_Item_OpenChest_SC{usedItemId(1), allItems(2,rep), openedItems(3,rep)}
    body = pb_varint_field(1, item_id)
    for iid, amt in loot:
        dto = pb_varint_field(1, iid) + pb_varint_field(2, amt)
        body += pb_tag(2, 2) + uvarint(len(dto)) + dto
        body += pb_tag(3, 2) + uvarint(len(dto)) + dto
    messages.append(("PVZ.Cmd.Cmd_Item_OpenChest_SC", body))
    messages.append(("PVZ.Cmd.Cmd_Item_Use_SC",
                     pb_varint_field(1, item_id) + pb_varint_field(2, count)))
    log.info("    chest opened: uin=%d %s(%d) x%d -> %s", uin, name, item_id, count, loot)
    return messages


# --- chlorophyll merge (叶绿素合成, ModuleCard 强化面板) --------------------------------
# Cmd_Item_MergeChlorophyll_CS{itemBaseId(1), isAll(2)} -> Cmd_Item_MergeChlorophyll_SC{itemBaseId(1)}.
# Rule (client UI + player report): 5 个 N 星叶绿素 -> 1 个 (N+1) 星叶绿素. Family 2101..2105
# (一星..五星), 五星 is the top (Error_Card_WrongChlorophyllLevel if merged further).
# isAll=0 merges ONE batch of 5; isAll=1 cascades upward as far as the bag allows
# (一键合成: 25x 一星 -> 5x 二星 -> 1x 三星). The client updates its bag ONLY from
# Cmd_Item_Update_SC (same pattern as selling), then reads SC.itemBaseId as the result stack.
_CHLOROPHYLL_TOP = 2105
_CHLOROPHYLL_MERGE_INPUT = 5          # 5 lower-tier -> 1 next-tier


def handle_item_mergechlorophyll(cmd_data, player):
    fields = parse_varint_fields(cmd_data)
    item_base_id = int(fields.get(1, 0))
    merge_all = bool(int(fields.get(2, 0)))
    uin = int(player["uin"])
    if not 2101 <= item_base_id <= _CHLOROPHYLL_TOP:
        log.info("    chlorophyll merge DENIED: itemBaseId=%d not in 2101..2105", item_base_id)
        return []
    counts = dict(store.get_items(uin))
    changes = []                      # [(item_id, delta)] for the final Cmd_Item_Update_SC
    result_id = item_base_id
    current = item_base_id
    while current < _CHLOROPHYLL_TOP:
        have = counts.get(current, 0)
        if merge_all:
            batches = have // _CHLOROPHYLL_MERGE_INPUT
        else:
            batches = 1 if have >= _CHLOROPHYLL_MERGE_INPUT else 0
        if batches <= 0:
            break
        spent = batches * _CHLOROPHYLL_MERGE_INPUT
        made = batches
        counts[current] = have - spent
        nxt = current + 1
        counts[nxt] = counts.get(nxt, 0) + made
        changes.append((current, -spent))
        changes.append((nxt, made))
        result_id = nxt
        log.info("    chlorophyll merge: %dx item %d -> %dx item %d", spent, current, made, nxt)
        if not merge_all:
            break
        current = nxt
    if not changes:
        # Not enough material (or already 五星): the client shows the generic failure state.
        log.info("    chlorophyll merge DENIED: uin=%d item=%d held=%d (need %d)",
                 uin, item_base_id, counts.get(item_base_id, 0), _CHLOROPHYLL_MERGE_INPUT)
        return []
    item_updates = b""
    for item_id, delta in changes:
        new_count = store.add_item(uin, item_id, delta)
        item_updates += pb_bytes(1, build_item_dto(item_id, new_count))
    # SC.itemBaseId = the highest merged stack; the bag sync comes from Cmd_Item_Update_SC.
    return [
        ("PVZ.Cmd.Cmd_Item_Update_SC", item_updates),
        ("PVZ.Cmd.Cmd_Item_MergeChlorophyll_SC", pb_varint_field(1, result_id)),
    ]


# --- card equipment -----------------------------------------------------------
# Equipment is a proper BagItemVO, not a stack of a normal material: its stable uid and Dto_EquipInfo
# are what the Flash client uses to populate the card slots, equipment bag, leveling and rank panels.
_EQUIPMENT_TABLES = None


def _load_equipment_tables():
    global _EQUIPMENT_TABLES
    if _EQUIPMENT_TABLES is None:
        tables = {}
        for name in ("EquipmentItem.txt", "EquipmentLevel.txt", "EquipmentRank.txt",
                     "EquipmentPool.txt", "EquipmentPart.txt", "EquipmentBead.txt"):
            rows = _read_clientdb_table(name)
            if not rows:
                tables[name] = {}
                continue
            headers = rows[0]
            tables[name] = {
                tuple(row[i] if i < len(row) else "" for i in range(len(headers))):
                dict(zip(headers, row)) for row in rows[1:]
            }
        _EQUIPMENT_TABLES = tables
    return _EQUIPMENT_TABLES


def _equip_row(table, **keys):
    rows = _load_equipment_tables().get(table, {}).values()
    for row in rows:
        try:
            if all(str(row.get(key, "")) == str(value) for key, value in keys.items()):
                return row
        except (TypeError, ValueError):
            continue
    return None


def _equip_int(row, key, default=0):
    try:
        return int(float((row or {}).get(key) or default))
    except (TypeError, ValueError):
        return int(default)


def _equip_properties(equipment):
    """Final equipment attributes expected by Dto_EquipEffect.

    Item base properties are already in display units. Level/rank template values for the four
    primary stats are stored in hundredths, matching the client's EquipmentAttribute transform.
    """
    item = next((r for r in _load_equipment_tables()["EquipmentItem.txt"].values()
                 if _equip_int(r, "id") == int(equipment["item_id"])), None)
    if not item:
        return {}
    props = {}

    def add_spec(spec, separator, scale_primary=False):
        for part in (spec or "").split(";"):
            if separator not in part:
                continue
            try:
                attr, value = part.split(separator, 1)
                attr, value = int(attr), float(value)
                if scale_primary and attr in (1, 2, 3, 5):
                    value /= 100.0
                props[attr] = props.get(attr, 0.0) + value
            except (TypeError, ValueError):
                continue

    add_spec(item.get("originalProperty"), ",")
    equip_type = _equip_int(item, "equipType")
    rank = _equip_int(item, "rank", 1)
    level = int(equipment.get("level") or 0)
    rank_row = _equip_row("EquipmentRank.txt", type=equip_type, rank=rank)
    level_row = _equip_row("EquipmentLevel.txt", type=equip_type, level=level)
    if rank_row:
        add_spec(rank_row.get("originalProperty"), ":", True)
    if level_row:
        add_spec(level_row.get("originalProperty"), ":", True)
    return {key: value for key, value in props.items() if value}


def _apply_card_equipment_bonus(stats, uin, card_uid):
    """Fold equipped gear's flat attributes into the card snapshot sent to the client/battle."""
    attr_to_stat = {1: "atk", 2: "def_", 3: "hp", 4: "shield", 5: "ability",
                    6: "hit", 7: "dodge", 8: "critical", 9: "tough", 10: "immune"}
    for equipment in store.get_equipments(uin):
        if int(equipment.get("card_uid") or 0) != int(card_uid):
            continue
        for attr, value in _equip_properties(equipment).items():
            stat = attr_to_stat.get(attr)
            if stat:
                total = stats.get(stat, 0) + value
                stats[stat] = int(round(total)) if attr <= 5 else float(total)
    return stats


def _equipment_info_dto(equipment):
    item = next((r for r in _load_equipment_tables()["EquipmentItem.txt"].values()
                 if _equip_int(r, "id") == int(equipment["item_id"])), None)
    rank = _equip_int(item, "rank", 1)
    d = (pb_varint_field(2, rank)                                  # quality
         + pb_int64_field(3, int(equipment.get("card_uid") or 0)) # iCardUId (0 = in bag)
         + pb_varint_field(4, int(equipment.get("level") or 0))
         + pb_varint_field(5, int(equipment.get("exp") or 0))
         + pb_varint_field(6, int(equipment.get("grade_percent") or 0))
         + pb_varint_field(7, int(equipment.get("is_clone") or 0)))
    # The shipped EquipmentLevelViewCE has exactly two current/next property rows.  The
    # rank/level templates can introduce a third effect type (e.g. ability or HP), and the
    # decompiled client mediator iterates every effect then dereferences a nonexistent row,
    # raising ActionScript Error #1009 whenever the equipment screen opens or refreshes.
    # Keep the two primary attributes in the client DTO; _equip_properties remains complete
    # for server-side card stats and combat calculations.
    for attr, value in sorted(_equip_properties(equipment).items()):
        if attr not in (1, 2):
            continue
        effect = pb_varint_field(1, attr) + pb_float_field(2, float(value))
        d += pb_tag(1, 2) + uvarint(len(effect)) + effect
    return d


def build_equipment_item_dto(equipment):
    info = _equipment_info_dto(equipment)
    return (pb_int64_field(1, int(equipment["uid"]))
            + pb_varint_field(2, int(equipment["item_id"]))
            + pb_varint_field(3, 1)
            + pb_tag(4, 2) + uvarint(len(info)) + info)


def _equipment_item_update(equipments=(), removed=()):
    body = b""
    for equipment in equipments:
        dto = build_equipment_item_dto(equipment)
        body += pb_tag(1, 2) + uvarint(len(dto)) + dto
    for equipment in removed:
        dto = (pb_int64_field(1, int(equipment["uid"]))
               + pb_varint_field(2, int(equipment["item_id"]))
               + pb_varint_field(3, 0))
        body += pb_tag(1, 2) + uvarint(len(dto)) + dto
    return ("PVZ.Cmd.Cmd_Item_Update_SC", body) if body else None


def _equipment_costs(spec):
    return [(item_id, amount) for item_id, amount in parse_bonus_items(spec) if item_id and amount > 0]


def _equipment_afford(player, costs):
    return all(store.get_item_count(player["uin"], item_id) >= amount
               for item_id, amount in costs)


def _equipment_template(item_id):
    return next((r for r in _load_equipment_tables()["EquipmentItem.txt"].values()
                 if _equip_int(r, "id") == int(item_id)), None)


def _equipment_pool_state(player):
    state = store.get_equipment_state(player["uin"])
    pool = _equip_row("EquipmentPool.txt", id=state["pool_id"]) or _equip_row(
        "EquipmentPool.txt", id=1)
    now = int(time.time())
    if pool:
        cap = _equip_int(pool, "capability")
        elapsed = max(0, now - int(state.get("last_energy_at") or now))
        regen_per_second = _equip_int(pool, "recover") / 100.0 / 60.0
        energy = min(cap, int(state["current_energy"] + elapsed * regen_per_second))
        state["current_energy"] = energy
        state["last_energy_at"] = now
        store.update_equipment_state(player["uin"], current_energy=energy, last_energy_at=now)
    return state, pool


def _equipment_energy_info(player):
    state, pool = _equipment_pool_state(player)
    part = _equip_row("EquipmentPart.txt", id=state["part_id"])
    bead_num = store.get_item_count(player["uin"], 2046)
    return ("PVZ.Cmd.Cmd_Equip_EnergyInfo_SC",
            pb_varint_field(1, state["pool_id"])
            + pb_varint_field(2, state["current_energy"])
            + pb_varint_field(3, bead_num)
            + pb_varint_field(4, state["part_id"])
            + pb_varint_field(5, state["auto_use_bead"])
            + pb_varint_field(6, state["current_exp"])
            + pb_varint_field(7, state["buy_count"]))


def _equipment_part_info(player):
    state = store.get_equipment_state(player["uin"])
    part = _equip_row("EquipmentPart.txt", id=state["part_id"])
    if not part:
        return ("PVZ.Cmd.Cmd_Equip_AttachInfo_SC", b"")
    today = time.strftime("%Y%m%d")
    # The client uses canTakeFirst itself to decide whether the clickable reward icon is
    # visible; keeping the template amount here after a claim leaves a dead, re-clickable icon.
    first_available = 0 if state["first_claimed"] else _equip_int(part, "firstReward")
    daily_available = _equip_int(part, "dailyReward")
    d = (pb_varint_field(1, state["part_id"])
         + pb_varint_field(2, daily_available)
         + pb_varint_field(3, state.get("daily_claim_day") == today)
         + pb_varint_field(4, first_available)
         + pb_varint_field(5, state["first_claimed"])
         + pb_varint_field(6, state["buy_count"]))
    return ("PVZ.Cmd.Cmd_Equip_AttachInfo_SC", d)


def _equipment_updates_for_rows(uin, uids):
    return [row for uid in sorted(set(int(x) for x in uids))
            if (row := store.get_equipment(uin, uid)) is not None]


def _equipment_set_energy(player, state, amount):
    """Persist bounded pool energy; energy spent also advances the pool's lifetime upgrade XP."""
    _, pool = _equipment_pool_state(player)
    if not pool:
        return state
    cap = _equip_int(pool, "capability")
    new_energy = max(0, min(cap, int(amount)))
    spent = max(0, int(state["current_energy"]) - new_energy)
    state["current_energy"] = new_energy
    state["last_energy_at"] = int(time.time())
    if spent:
        state["current_exp"] = int(state["current_exp"]) + spent
    store.update_equipment_state(player["uin"], current_energy=new_energy,
                                 last_energy_at=state["last_energy_at"],
                                 current_exp=state["current_exp"])
    return state


def _equipment_upgrade_level(equipment, exp_gain):
    item = _equipment_template(equipment["item_id"])
    equip_type = _equip_int(item, "equipType")
    rank = _equip_int(item, "rank", 1)
    rank_template = _equip_row("EquipmentRank.txt", type=equip_type, rank=rank)
    max_level = _equip_int(rank_template, "levelLimit", 10)
    level = int(equipment["level"])
    exp = int(equipment["exp"]) + int(exp_gain)
    while level < max_level:
        level_template = _equip_row("EquipmentLevel.txt", type=equip_type, level=level)
        need = _equip_int(level_template, "needExp")
        if need <= 0 or exp < need:
            break
        exp -= need
        level += 1
    if level >= max_level:
        exp = 0
    equipment["level"], equipment["exp"] = level, exp
    return equipment


def _equipment_rank_upgrade(equipment):
    item = _equipment_template(equipment["item_id"])
    equip_type = _equip_int(item, "equipType")
    rank = _equip_int(item, "rank", 1)
    next_rank = rank + 1
    if not item or not _equip_row("EquipmentRank.txt", type=equip_type, rank=rank):
        return False
    next_item = 30000 + (equip_type - 1) * 100 + next_rank
    if not _equipment_template(next_item):
        return False
    equipment["grade_percent"] = int(equipment["grade_percent"]) + 20
    if equipment["grade_percent"] >= 100:
        equipment["item_id"] = next_item
        equipment["grade_percent"] = 0
    return True


def handle_equip_energy_info(cmd_data, player):
    return _equipment_energy_info(player)[1]


def handle_equip_attach_info(cmd_data, player):
    return _equipment_part_info(player)[1]


def handle_equip_create(cmd_data, player):
    item_id = parse_varint_fields(cmd_data).get(1, 0)
    template = _equipment_template(item_id)
    if not template or _equip_int(template, "rank") != 1:
        return []
    costs = _equipment_costs(template.get("originalMaterial"))
    if not costs or not _equipment_afford(player, costs):
        log.info("    equipment craft denied: item=%d missing material(s)", item_id)
        return []
    item_updates = [grant_items(player, [(iid, -amount) for iid, amount in costs])]
    uid = store.next_equipment_uid(player["uin"])
    store.add_equipment(player["uin"], uid, item_id)
    equipment = store.get_equipment(player["uin"], uid)
    item_updates.append(_equipment_item_update([equipment]))
    # Send the complete new bag object BEFORE Create_SC: the client's Create event immediately
    # issues the automatic wear request, so that request and the subsequent card refresh can see it.
    item_updates.append(("PVZ.Cmd.Cmd_Equip_Create_SC",
                         pb_varint_field(1, item_id) + pb_int64_field(2, uid)))
    log.info("    equipment crafted: uid=%d item=%d (%s)", uid, item_id, template.get("id"))
    messages = [message for message in item_updates if message]
    messages += _quest_record_condition(player, 20, 0, 1)
    return messages


def handle_equip_wear(cmd_data, player):
    fields = parse_varint_fields(cmd_data)
    card_uid, equip_uid = fields.get(1, 0), fields.get(2, 0)
    equipment = store.get_equipment(player["uin"], equip_uid)
    cards = {uid: (card_id, level) for uid, card_id, level, _exp in store.get_cards(player["uin"])}
    item = _equipment_template(equipment["item_id"]) if equipment else None
    if not equipment or card_uid not in cards or not item:
        return []
    if _equip_int(item, "plantType") not in (0, cards[card_uid][0] // 10 * 10):
        # Most existing templates are plantType=0; restricted gear must match its template's card.
        card_info = _BATTLE_CARDS.get(cards[card_uid][0], {})
        if _equip_int(item, "plantType") not in (0, int(card_info.get("tdId") or 0)):
            return []
    position = _equip_int(item, "position")
    changed = []
    for other in store.get_equipments(player["uin"]):
        other_item = _equipment_template(other["item_id"])
        if (int(other["uid"]) != int(equip_uid) and int(other["card_uid"]) == int(card_uid)
                and _equip_int(other_item, "position") == position):
            store.update_equipment(player["uin"], other["uid"], card_uid=0)
            changed.append(other["uid"])
    store.update_equipment(player["uin"], equip_uid, card_uid=card_uid)
    changed.append(equip_uid)
    rows = _equipment_updates_for_rows(player["uin"], changed)
    update = _equipment_item_update(rows)
    sc = ("PVZ.Cmd.Cmd_Equip_WearEquip_SC",
          pb_int64_field(1, card_uid) + pb_int64_field(2, equip_uid))
    load_battle_cards()
    card_sync = build_card_sync_sc(player["uin"], card_uid, cards[card_uid][0], 0)
    return [message for message in (update, card_sync, sc) if message]


def handle_equip_takeoff(cmd_data, player):
    equip_uid = parse_varint_fields(cmd_data).get(1, 0)
    equipment = store.get_equipment(player["uin"], equip_uid)
    if not equipment or not equipment["card_uid"]:
        return []
    card_uid = int(equipment["card_uid"])
    card = next((row for row in store.get_cards(player["uin"]) if row[0] == card_uid), None)
    store.update_equipment(player["uin"], equip_uid, card_uid=0)
    load_battle_cards()
    card_sync = build_card_sync_sc(player["uin"], card_uid, card[1], 0) if card else None
    return [message for message in (_equipment_item_update([store.get_equipment(player["uin"], equip_uid)]),
            card_sync, ("PVZ.Cmd.Cmd_Equip_TakeoffEquip_SC", pb_int64_field(1, equip_uid))) if message]


def _equipment_card_sync(player, equipment):
    """Refresh the owning card whenever worn equipment changes its computed attributes."""
    card_uid = int(equipment.get("card_uid") or 0)
    if not card_uid:
        return None
    card = next((row for row in store.get_cards(player["uin"]) if row[0] == card_uid), None)
    if not card:
        return None
    load_battle_cards()
    return build_card_sync_sc(player["uin"], card_uid, card[1], 0)


def _equipment_add_exp(player, equip_uid, all_available=False):
    equipment = store.get_equipment(player["uin"], equip_uid)
    if not equipment:
        return []
    state, _ = _equipment_pool_state(player)
    exp_messages = []
    auto_bead_update = None
    while True:
        item = _equipment_template(equipment["item_id"])
        if not item:
            break
        equip_type = _equip_int(item, "equipType")
        rank = _equip_int(item, "rank", 1)
        rank_template = _equip_row("EquipmentRank.txt", type=equip_type, rank=rank)
        level = int(equipment["level"])
        if level >= _equip_int(rank_template, "levelLimit", 10):
            break
        level_template = _equip_row("EquipmentLevel.txt", type=equip_type, level=level)
        cost = max(1, _equip_int(level_template, "costEnergy"))
        if state["current_energy"] < cost and state.get("auto_use_bead"):
            bead_count = store.get_item_count(player["uin"], 2046)
            pool = _equip_row("EquipmentPool.txt", id=state["pool_id"])
            bead_value = max(1, _equip_int(pool, "recover"))
            needed = (cost - int(state["current_energy"]) + bead_value - 1) // bead_value
            used = min(bead_count, needed)
            if used:
                state["current_energy"] += used * bead_value
                state["last_energy_at"] = int(time.time())
                store.update_equipment_state(player["uin"], current_energy=state["current_energy"],
                                             last_energy_at=state["last_energy_at"])
                auto_bead_update = grant_items(player, [(2046, -used)])
        if state["current_energy"] < cost:
            break
        state = _equipment_set_energy(player, state, int(state["current_energy"]) - cost)
        equipment = _equipment_upgrade_level(equipment, cost)
        info = pb_varint_field(1, cost) + pb_varint_field(2, 0)  # addExp, criticalTimes
        exp_messages.append(info)
        if not all_available:
            break
    if not exp_messages:
        return []
    store.update_equipment(player["uin"], equip_uid,
                           level=equipment["level"], exp=equipment["exp"])
    equipment = store.get_equipment(player["uin"], equip_uid)
    info = _equipment_info_dto(equipment)
    if all_available:
        add_exp = b"".join(pb_tag(2, 2) + uvarint(len(entry)) + entry for entry in exp_messages)
        main = ("PVZ.Cmd.Cmd_Equip_AddAllExp_SC",
                pb_int64_field(1, equip_uid) + add_exp
                + pb_tag(3, 2) + uvarint(len(info)) + info)
    else:
        entry = exp_messages[0]
        main = ("PVZ.Cmd.Cmd_Equip_AddExp_SC",
                pb_int64_field(1, equip_uid)
                + pb_tag(2, 2) + uvarint(len(entry)) + entry
                + pb_tag(3, 2) + uvarint(len(info)) + info)
    return [message for message in (_equipment_item_update([equipment]),
                                    _equipment_card_sync(player, equipment), auto_bead_update,
                                    main, _equipment_energy_info(player)) if message]


def handle_equip_add_exp(cmd_data, player):
    return _equipment_add_exp(player, parse_varint_fields(cmd_data).get(1, 0), False)


def handle_equip_add_all_exp(cmd_data, player):
    return _equipment_add_exp(player, parse_varint_fields(cmd_data).get(1, 0), True)


def handle_equip_upgrade(cmd_data, player):
    equip_uid = parse_varint_fields(cmd_data).get(1, 0)
    equipment = store.get_equipment(player["uin"], equip_uid)
    if not equipment:
        return []
    item = _equipment_template(equipment["item_id"])
    equip_type, rank = _equip_int(item, "equipType"), _equip_int(item, "rank", 1)
    recipe = _equip_row("EquipmentRank.txt", type=equip_type, rank=rank)
    costs = _equipment_costs(recipe.get("originalMaterial") if recipe else "")
    energy_cost = _equip_int(recipe, "costEnergy")
    state, _ = _equipment_pool_state(player)
    if (not recipe or _equip_int(recipe, "upgradeCount") <= 0 or not costs
            or not _equipment_afford(player, costs) or state["current_energy"] < energy_cost):
        return []
    if not _equipment_rank_upgrade(equipment):
        return []
    store.update_equipment(player["uin"], equip_uid, item_id=equipment["item_id"],
                           grade_percent=equipment["grade_percent"])
    updates = [grant_items(player, [(iid, -amount) for iid, amount in costs])]
    state = _equipment_set_energy(player, state, int(state["current_energy"]) - energy_cost)
    equipment = store.get_equipment(player["uin"], equip_uid)
    info = _equipment_info_dto(equipment)
    sc = ("PVZ.Cmd.Cmd_Equip_Upgrade_SC",
          pb_int64_field(1, equip_uid)
          + pb_varint_field(2, equipment["grade_percent"])
          + pb_tag(3, 2) + uvarint(len(info)) + info
          + pb_varint_field(4, equipment["item_id"]))
    updates.extend([_equipment_item_update([equipment]), _equipment_card_sync(player, equipment),
                    sc, _equipment_energy_info(player)])
    return [message for message in updates if message]


def handle_equip_use_bead(cmd_data, player):
    state, pool = _equipment_pool_state(player)
    if not pool or state["current_energy"] >= _equip_int(pool, "capability"):
        return []
    count = store.get_item_count(player["uin"], 2046)
    if count <= 0:
        return []
    bead_value = max(1, _equip_int(pool, "recover"))
    missing = _equip_int(pool, "capability") - state["current_energy"]
    used = min(count, max(1, (missing + bead_value - 1) // bead_value))
    state["current_energy"] = min(_equip_int(pool, "capability"),
                                  int(state["current_energy"]) + used * bead_value)
    state["last_energy_at"] = int(time.time())
    store.update_equipment_state(player["uin"], current_energy=state["current_energy"],
                                 last_energy_at=state["last_energy_at"])
    item_update = grant_items(player, [(2046, -used)])
    return [message for message in (item_update,
            ("PVZ.Cmd.Cmd_Equip_UseBead_SC", b""), _equipment_energy_info(player)) if message]


def handle_equip_auto_use_bead(cmd_data, player):
    enabled = parse_varint_fields(cmd_data).get(1, 0)
    store.update_equipment_state(player["uin"], auto_use_bead=1 if enabled else 0)
    return [_equipment_energy_info(player)]


def handle_equip_part_reward(cmd_data, player, first=False):
    state = store.get_equipment_state(player["uin"])
    part = _equip_row("EquipmentPart.txt", id=state["part_id"])
    if not part:
        return []
    if first:
        if state["first_claimed"]:
            return []
        amount = _equip_int(part, "firstReward")
        if amount <= 0:
            return []
        store.update_equipment_state(player["uin"], first_claimed=1)
    else:
        today = time.strftime("%Y%m%d")
        if state.get("daily_claim_day") == today:
            return []
        amount = _equip_int(part, "dailyReward")
        if amount <= 0:
            return []
        store.update_equipment_state(player["uin"], daily_claim_day=today)
    item_update = grant_items(player, [(2046, amount)])
    log.info("    equipment %s bead reward: %d", "first" if first else "daily", amount)
    return [message for message in (item_update, _equipment_part_info(player),
                                     _equipment_energy_info(player)) if message]


def handle_equip_first_bead(cmd_data, player):
    return handle_equip_part_reward(cmd_data, player, True)


def handle_equip_daily_bead(cmd_data, player):
    return handle_equip_part_reward(cmd_data, player, False)


def handle_equip_part_upgrade(cmd_data, player):
    fields = parse_varint_fields(cmd_data)
    use_ticket = bool(fields.get(1, 0))
    state = store.get_equipment_state(player["uin"])
    part = _equip_row("EquipmentPart.txt", id=state["part_id"])
    next_part = _equip_row("EquipmentPart.txt", id=int(state["part_id"]) + 1)
    if not part or not next_part:
        return []
    costs = _equipment_costs(part.get("originalMaterial"))
    short = [(iid, max(0, amount - store.get_item_count(player["uin"], iid)))
             for iid, amount in costs]
    short = [(iid, amount) for iid, amount in short if amount]
    ticket_cost = sum(amount for _iid, amount in short) * _equip_int(part, "cost")
    if short and (not use_ticket or int(player.get("ticket") or 0) < ticket_cost
                  or int(player.get("vip_level") or 0) < _equip_int(part, "needVIP")):
        return []
    consume = [(iid, -min(amount, store.get_item_count(player["uin"], iid)))
               for iid, amount in costs
               if min(amount, store.get_item_count(player["uin"], iid)) > 0]
    updates = [grant_items(player, consume)] if consume else []
    if short:
        player["ticket"] = int(player.get("ticket") or 0) - ticket_cost
        store.save_player(player["uin"], ticket=player["ticket"])
        updates.append(("PVZ.Cmd.Cmd_SyncTicket_SC", pb_varint_field(1, player["ticket"])))
    store.update_equipment_state(player["uin"], part_id=int(next_part["id"]),
                                 first_claimed=0)
    updates.extend([_equipment_part_info(player), _equipment_energy_info(player)])
    return [message for message in updates if message]


def handle_equip_pool_upgrade(cmd_data, player):
    state, pool = _equipment_pool_state(player)
    next_pool = _equip_row("EquipmentPool.txt", id=int(state["pool_id"]) + 1)
    if (not pool or not next_pool or state["current_exp"] < _equip_int(pool, "needExp")
            or state["part_id"] < _equip_int(pool, "needPartID")):
        return []
    store.update_equipment_state(player["uin"], pool_id=int(next_pool["id"]), current_exp=0,
                                 current_energy=min(int(state["current_energy"]),
                                                    _equip_int(next_pool, "capability")),
                                 last_energy_at=int(time.time()))
    return [("PVZ.Cmd.Cmd_Equip_PoolUp_SC", b""), _equipment_energy_info(player)]


def handle_equip_clone(cmd_data, player):
    """Clone a selected equipment object into a bag-only copy (client marks it as disposable)."""
    equip_uid = parse_varint_fields(cmd_data).get(1, 0)
    equipment = store.get_equipment(player["uin"], equip_uid)
    if not equipment:
        return []
    clones = [item for item in store.get_equipments(player["uin"]) if item["is_clone"]]
    if len(clones) >= 24:
        return []
    uid = store.next_equipment_uid(player["uin"])
    store.add_equipment(player["uin"], uid, equipment["item_id"], 0, equipment["level"],
                        equipment["exp"], equipment["grade_percent"], 1)
    item_update = _equipment_item_update([store.get_equipment(player["uin"], uid)])
    return [message for message in (item_update, ("PVZ.Cmd.Cmd_Equip_CloneEquip_SC", b"")) if message]


def handle_equip_sell_clones(cmd_data, player):
    clones = [item for item in store.get_equipments(player["uin"]) if item["is_clone"]]
    if not clones:
        return []
    for item in clones:
        store.remove_equipment(player["uin"], item["uid"])
    update = _equipment_item_update(removed=clones)
    return [message for message in (update, ("PVZ.Cmd.Cmd_Equip_SellAllClone_SC", b"")) if message]


def handle_equip_buy_bead(cmd_data, player):
    """Buy the next configured pack using the client's explicit paid action."""
    state = store.get_equipment_state(player["uin"])
    template = _equip_row("EquipmentBead.txt", id=int(state["buy_count"]) + 1)
    if not template:
        return []
    cost, count = _equip_int(template, "cost"), _equip_int(template, "count")
    # The bead-buy dialog uses paid diamonds. Prefer gift diamonds, then paid diamonds, matching
    # other client purchase flows while never allowing a negative balance.
    gift = int(player.get("present_ticket") or 0)
    paid = int(player.get("ticket") or 0)
    if gift + paid < cost:
        return []
    spend_gift = min(gift, cost)
    spend_paid = cost - spend_gift
    if spend_gift:
        player["present_ticket"] = gift - spend_gift
        store.save_player(player["uin"], present_ticket=player["present_ticket"])
    if spend_paid:
        player["ticket"] = paid - spend_paid
        store.save_player(player["uin"], ticket=player["ticket"])
    store.update_equipment_state(player["uin"], buy_count=int(state["buy_count"]) + 1)
    bag_update = grant_items(player, [(2046, count)])
    messages = [bag_update]
    messages.extend([("PVZ.Cmd.Cmd_SyncTicket_SC", pb_varint_field(1, player["ticket"])),
                     ("PVZ.Cmd.Cmd_SyncPresentTicket_SC", pb_varint_field(1, player["present_ticket"]))])
    messages.extend([_equipment_energy_info(player), _equipment_part_info(player)])
    return [message for message in messages if message]


# --- gate templates (needStars / needItems) from clientDB levelselectGateInfo.txt ------
_GATE_TEMPLATES = None


_BUILDINGS = None
# buildingInfo marks event-only buildings with unlockRoleLv=999.  Building 150 is the actual
# 捉小偷/护农田 entrance and must remain visible for this restored activity.
_RESTORED_EVENT_BUILDINGS = {150}


def load_buildings():
    """[(buildingId, unlockRoleLv)] from clientDB buildingInfo.txt (the town buildings)."""
    global _BUILDINGS
    if _BUILDINGS is None:
        _BUILDINGS = []
        rows = _read_clientdb_table("buildingInfo.txt")
        if rows:
            hdr = rows[0]; ci = {c: i for i, c in enumerate(hdr)}
            for c in rows[1:]:
                try:
                    _BUILDINGS.append((int(c[ci["id"]]), int(c[ci["unlockRoleLv"]])))
                except (ValueError, KeyError, IndexError):
                    pass
        log.info("loaded %d town buildings", len(_BUILDINGS))
    return _BUILDINGS


def handle_get_building_info(cmd_data, player):
    """Cmd_City_GetBuildingInfo_CS -> Cmd_City_GetBuildingInfo_SC. The town renders EXACTLY the
    buildings we list (CityData.buildingList -> CityMapView). Send every building the player's
    level has unlocked (buildingInfo.txt unlockRoleLv <= level); leveling up reveals more.
    (The two unlockRoleLv=999 buildings are event-only and never qualify.)"""
    level = int(player.get("level", 1))
    unlocked = [bid for bid, need in load_buildings()
                if need <= level or bid in _RESTORED_EVENT_BUILDINGS]
    log.info("    town buildings: level=%d -> %d unlocked %s", level, len(unlocked), unlocked)
    d = b""
    for bid in unlocked:
        dto = pb_varint_field(1, bid)                    # Dto_BuildingInfo{buildingType}
        d += pb_tag(1, 2) + uvarint(len(dto)) + dto      # buildingInfo (field 1, repeated)
    return d


def building_unlock_messages(old_level, new_level):
    """[(Cmd_SyncBuildingInfo_SC, body)] for every building whose unlockRoleLv is crossed going
    old_level -> new_level. The client (LoginService) reacts to each by cityData.addNewBuilding(type)
    + ChangeBuilding, so a newly-unlocked building appears LIVE in the town instead of only after a
    restart (which is when the town otherwise re-requests the whole list)."""
    msgs = []
    if new_level <= old_level:
        return msgs
    for bid, need in load_buildings():
        if old_level < need <= new_level:
            dto = pb_varint_field(1, bid)                # Dto_BuildingInfo{buildingType}
            body = pb_tag(1, 2) + uvarint(len(dto)) + dto  # buildingInfo (field 1)
            msgs.append(("PVZ.Cmd.Cmd_SyncBuildingInfo_SC", body))
    if msgs:
        log.info("    live-unlocked buildings (lvl %d->%d): %s", old_level, new_level,
                 [b for b, n in load_buildings() if old_level < n <= new_level])
    return msgs


# --- adventure / fuben (副本) ------------------------------------------------------
_FUBEN_CHAPTERS = None
_FUBEN_STAGES = None


def load_fuben_chapters():
    """[(chapterId, levelNeed)] sorted, from clientDB FubenChapterTemplate.txt."""
    global _FUBEN_CHAPTERS
    if _FUBEN_CHAPTERS is None:
        _FUBEN_CHAPTERS = []
        rows = _read_clientdb_table("FubenChapterTemplate.txt")
        if rows:
            hdr = rows[0]; ci = {c: i for i, c in enumerate(hdr)}
            for c in rows[1:]:
                try:
                    _FUBEN_CHAPTERS.append((int(c[ci["id"]]), int(c[ci["levelNeed"]])))
                except (ValueError, KeyError, IndexError):
                    pass
        _FUBEN_CHAPTERS.sort()
        log.info("loaded %d fuben chapters", len(_FUBEN_CHAPTERS))
    return _FUBEN_CHAPTERS


def load_fuben_stages():
    """{(chapterId, mode): [stageId,...]} from clientDB fuben.txt."""
    global _FUBEN_STAGES
    if _FUBEN_STAGES is None:
        _FUBEN_STAGES = {}
        rows = _read_clientdb_table("fuben.txt")
        if rows:
            hdr = rows[0]; ci = {c: i for i, c in enumerate(hdr)}
            for c in rows[1:]:
                try:
                    ch, st, md = (int(c[ci["chapterId"]]), int(c[ci["stageId"]]),
                                  int(c[ci["mode"]]))
                    _FUBEN_STAGES.setdefault((ch, md), []).append(st)
                except (ValueError, KeyError, IndexError):
                    pass
        for k in _FUBEN_STAGES:
            _FUBEN_STAGES[k].sort()
        log.info("loaded fuben stages for %d chapter/mode combos", len(_FUBEN_STAGES))
    return _FUBEN_STAGES


# itemId -> (player field, Cmd_Sync_SC) for the currencies we persist + push to the HUD.
# Everything else in a reward (keys, plant fragments, armor materials, puzzle pieces) is a bag
# item. Town prosperity (2) IS a bag item (client ItemInfo subtype SUB_TYPE_TOWN_PROSPERITY):
# quest/fuben rewards land in the items table and the town UI reads the stack from the bag.
# Plant EXP (5) has no local model — the client auto-hides it from the win chest, so we show
# it in the report but don't persist it.
_CURRENCY_SYNC = {
    1: ("coin", "PVZ.Cmd.Cmd_SyncCoin_SC"),
    3: ("sun", "PVZ.Cmd.Cmd_SyncSun_SC"),
    4: ("present_ticket", "PVZ.Cmd.Cmd_SyncPresentTicket_SC"),  # 钻石/gift diamond (ItemID.GiftDiamond1)
    6: ("friend_point", "PVZ.Cmd.Cmd_SyncFriendPoint_SC"),
    7: ("fame", "PVZ.Cmd.Cmd_SyncFame_SC"),
}
_UNMODELED_CURRENCIES = {5}      # plant exp — displayed, not persisted

_FUBEN_REWARDS = None
_FUBEN_ENERGY = {}          # {(chapterId, mode, stageId): energyCost} — populated by load_fuben_rewards


def load_fuben_rewards():
    """{(chapterId, mode, stageId): (required, first, optional)} from clientDB fuben.txt.
    required/first = [(itemId, num)] — bonusRequired is granted every clear, bonusFirst only on
    the first clear. optional = [(itemId, num, chance)] rolled per clear (chance out of 10000)."""
    global _FUBEN_REWARDS
    if _FUBEN_REWARDS is None:
        _FUBEN_REWARDS = {}
        rows = _read_clientdb_table("fuben.txt")
        if rows:
            hdr = rows[0]; ci = {c: i for i, c in enumerate(hdr)}

            def col(c, k):
                i = ci.get(k)
                return c[i] if i is not None and i < len(c) else ""
            for c in rows[1:]:
                try:
                    key = (int(col(c, "chapterId")), int(col(c, "mode")), int(col(c, "stageId")))
                except ValueError:
                    continue
                optional = []
                for part in (col(c, "bonusOptional") or "").split(";"):
                    bits = part.split(":")
                    if len(bits) == 3:
                        try:
                            optional.append((int(bits[0]), int(bits[1]), int(bits[2])))
                        except ValueError:
                            pass
                _FUBEN_REWARDS[key] = (parse_bonus_items(col(c, "bonusRequired")),
                                       parse_bonus_items(col(c, "bonusFirst")), optional)
                try:
                    _FUBEN_ENERGY[key] = int(float(col(c, "energyCost") or 0))
                except ValueError:
                    pass
        log.info("loaded fuben rewards for %d stages", len(_FUBEN_REWARDS))
    return _FUBEN_REWARDS


def fuben_energy_cost(chapter, mode, stage):
    """The energy (体力) an adventure stage costs to fight, from clientDB fuben.txt (5 for ch1)."""
    load_fuben_rewards()
    return _FUBEN_ENERGY.get((chapter, mode, stage), 0)


def fuben_stage_reward(chapter, mode, stage, is_first):
    """Merged loot [(itemId, num)] for clearing a stage: bonusRequired (always) + bonusFirst
    (first clear only) + rolled bonusOptional. Duplicate ids are summed."""
    required, first, optional = load_fuben_rewards().get((chapter, mode, stage), ([], [], []))
    merged = {}

    def add(pairs):
        for iid, num in pairs:
            merged[iid] = merged.get(iid, 0) + num
    add(required)
    if is_first:
        add(first)
    for iid, num, chance in optional:
        if random.randint(1, 10000) <= chance:
            merged[iid] = merged.get(iid, 0) + num
    return sorted(merged.items())


def grant_fuben_reward(player, reward_items):
    """Apply a fuben reward: known currencies -> player fields (+ HUD Cmd_Sync_SC with the new
    total), unmodeled exp-type currencies (5) -> skipped, everything else -> the bag
    (Cmd_Item_Update_SC). Returns the (sc_name, body) sync messages to append."""
    msgs, bag_changes = [], []
    for iid, num in reward_items:
        if iid in _CURRENCY_SYNC:
            field, sc = _CURRENCY_SYNC[iid]
            player[field] = int(player.get(field, 0)) + num
            store.save_player(player["uin"], **{field: player[field]})
            msgs.append((sc, pb_varint_field(1, player[field])))
        elif iid in _UNMODELED_CURRENCIES:
            continue
        else:
            bag_changes.append((iid, num))
    upd = grant_items(player, bag_changes)   # sends NEW absolute counts (no double-count)
    if upd:
        msgs.append(upd)
    return msgs


# --- energy (体力) — consumed to fight adventure stages, regenerates over time, capped by role level --
# Must match the client-facing regen config (SERVER_CONFIG_OVERRIDES iRecoverEnergy*). The server is the
# source of truth: `energy` + `energy_time` (when that value was current); on any access we lazily add the
# energy that regenerated since. Cap = the role level's energyMax (levelInfo.txt) + the VIP cap privilege.
_ENERGY_REGEN_INTERVAL = 120   # seconds per +_ENERGY_REGEN_PER (keep == iRecoverEnergyInterval config)
_ENERGY_REGEN_PER = 1
_VIP_ENERGY_MAX_PRIV = 19      # VIP "体力上限增加" — adds its param to the energy cap
_LEVEL_ENERGY_MAX = None


def _load_level_energy_max():
    """{roleLevel: energyMax} from clientDB levelInfo.txt (100 @ lvl1, +~1/level)."""
    global _LEVEL_ENERGY_MAX
    if _LEVEL_ENERGY_MAX is None:
        _LEVEL_ENERGY_MAX = {}
        rows = _read_clientdb_table("levelInfo.txt")
        if rows:
            hdr = rows[0]; ci = {c: i for i, c in enumerate(hdr)}
            for r in rows[1:]:
                try:
                    _LEVEL_ENERGY_MAX[int(r[ci["id"]])] = int(r[ci["energyMax"]])
                except (ValueError, KeyError, IndexError):
                    pass
        log.info("loaded energyMax for %d role levels", len(_LEVEL_ENERGY_MAX))
    return _LEVEL_ENERGY_MAX


def energy_cap(player):
    """Max energy for this player: role level's energyMax + the VIP cap privilege (priv 19) param."""
    lvl = int(player.get("level", 1))
    base = _load_level_energy_max().get(lvl) or (99 + lvl)   # fallback tracks the ~+1/level curve
    return base + vip_privileges(player).get(_VIP_ENERGY_MAX_PRIV, 0)


def current_energy(player):
    """The player's energy right now, lazily folding in time-based regen since energy_time. Persists the
    new value + energy_time when they change. Energy ABOVE the cap (e.g. from a gift) is left as-is (no
    regen, not clamped down)."""
    now = int(time.time())
    cur = int(player.get("energy") or 0)
    cap = energy_cap(player)
    last = int(player.get("energy_time") or 0) or now
    if cur >= cap:
        if int(player.get("energy_time") or 0) != now:     # at/over cap: park the clock at now
            player["energy_time"] = now
            store.save_player(player["uin"], energy_time=now)
        return cur
    ticks = (now - last) // _ENERGY_REGEN_INTERVAL if _ENERGY_REGEN_INTERVAL > 0 else 0
    if ticks > 0:
        cur = min(cap, cur + ticks * _ENERGY_REGEN_PER)
        # advance the clock by exactly the consumed ticks (keep the remainder), or park at now if full.
        player["energy"] = cur
        player["energy_time"] = now if cur >= cap else last + ticks * _ENERGY_REGEN_INTERVAL
        store.save_player(player["uin"], energy=cur, energy_time=player["energy_time"])
    return cur


def consume_energy(player, amount):
    """Spend `amount` energy (from the regen-current value); returns True if it could be paid. Starts the
    regen clock from now (you just dropped below cap). Caller sends the sync + processes the action."""
    cur = current_energy(player)
    if amount <= 0:
        return True
    if cur < amount:
        return False
    player["energy"] = cur - amount
    player["energy_time"] = int(time.time())     # regen counts from the moment of spending
    store.save_player(player["uin"], energy=player["energy"], energy_time=player["energy_time"])
    return True


def energy_sync_msg(player):
    """('Cmd_SyncEnergy_SC', current-energy) — push whenever energy changes so the HUD bar updates."""
    return ("PVZ.Cmd.Cmd_SyncEnergy_SC", pb_varint_field(1, current_energy(player)))


# --- buy energy (spend diamonds for +energy, escalating cost, daily-limited) --------
_ENERGY_BUY = None
_ENERGY_BUY_TIMES_BASE = 5     # base diamond energy-buys/day (== iEnergyBuyTimes config); VIP priv 4 adds more
_VIP_ENERGY_BUY_PRIV = 4       # VIP "每日体力购买次数增加" — adds its param to the daily buy limit


def load_energy_buy():
    """{buyNum: (costItemId, costAmount, energyAdd)} from FubenEnargysTemplate.txt — the Nth diamond buy of
    the day costs needRes (item4=gift diamond, 50..400) for enargyAdd (80) energy."""
    global _ENERGY_BUY
    if _ENERGY_BUY is None:
        _ENERGY_BUY = {}
        rows = _read_clientdb_table("FubenEnargysTemplate.txt")
        if rows:
            hdr = rows[0]; ci = {c: i for i, c in enumerate(hdr)}
            for r in rows[1:]:
                try:
                    res = r[ci["needRes"]].split(":")
                    _ENERGY_BUY[int(r[ci["id"]])] = (int(res[0]), int(res[1]), int(r[ci["enargyAdd"]]))
                except (ValueError, KeyError, IndexError):
                    pass
        log.info("loaded %d energy-buy tiers", len(_ENERGY_BUY))
    return _ENERGY_BUY


def _energy_buy_reset(player):
    """Reset today's diamond energy-buy counter on a new day."""
    today = time.strftime("%Y%m%d")
    if (player.get("buy_energy_day") or "") != today:
        player["buy_energy_num"], player["buy_energy_day"] = 0, today
        store.save_player(player["uin"], buy_energy_num=0, buy_energy_day=today)


def energy_buy_limit(player):
    """Diamond energy-buys allowed per day: base + the VIP buy-count privilege (priv 4)."""
    return _ENERGY_BUY_TIMES_BASE + vip_privileges(player).get(_VIP_ENERGY_BUY_PRIV, 0)


def handle_market_buyenergy(cmd_data, player):
    """Cmd_Market_BuyEnergy_CS -> spend diamonds for +energy (FubenEnargysTemplate: Nth buy = cost/amount),
    up to energy_buy_limit/day. -> Cmd_Market_BuyEnergy_SC{buyNum} + SyncEnergy (+ diamond sync)."""
    _energy_buy_reset(player)
    uin = player["uin"]
    n = int(player.get("buy_energy_num") or 0) + 1              # this would be the Nth buy today
    tbl = load_energy_buy()
    tpl = tbl.get(n) or (tbl.get(max(tbl)) if tbl else None)
    buynum_sc = ("PVZ.Cmd.Cmd_Market_BuyEnergy_SC", pb_varint_field(1, int(player.get("buy_energy_num") or 0)))
    if not tpl or n > energy_buy_limit(player):
        return [buynum_sc]                                     # over the daily limit — the client blocks first
    cost_item, cost_amt, add = tpl
    field = _CURRENCY_SYNC.get(cost_item, ("present_ticket", ""))[0]
    if int(player.get(field, 0)) < cost_amt:
        return [buynum_sc]                                     # can't afford (client blocks first)
    charge = grant_fuben_reward(player, [(cost_item, -cost_amt)])   # deduct the diamonds (+ HUD sync)
    player["buy_energy_num"] = n
    player["energy"] = current_energy(player) + add            # fold regen in, then add (may overflow cap)
    store.save_player(uin, buy_energy_num=n, energy=player["energy"])
    log.info("    BUY ENERGY: +%d energy for %dx item %d (buy #%d/%d, uin=%d)",
             add, cost_amt, cost_item, n, energy_buy_limit(player), uin)
    return [("PVZ.Cmd.Cmd_Market_BuyEnergy_SC", pb_varint_field(1, n)),
            ("PVZ.Cmd.Cmd_SyncEnergy_SC", pb_varint_field(1, player["energy"]))] + charge


# --- TD cart purchase (spend gold diamonds) ---------------------------------
_TD_CART_COST_GOLD_DIAMOND = 1  # iBuyCartCostTicket


def _handle_td_buycart(cmd_data, player, response_name):
    """Buy one lawn mower for the current TD battle with gold diamonds only.

    The Flash client already enforces iBuyCartTimesLimit for the battle.  The
    server must still acknowledge the purchase and sync ticket, otherwise the
    client leaves the mower locked even though the player has gold diamonds.
    """
    cart_id = int(parse_varint_fields(cmd_data).get(5, 0))
    if cart_id <= 0 or int(player.get("ticket") or 0) < _TD_CART_COST_GOLD_DIAMOND:
        return []
    player["ticket"] -= _TD_CART_COST_GOLD_DIAMOND
    store.save_player(player["uin"], ticket=player["ticket"])
    log.info("    TD BUY CART: cart %d for %d gold diamond (uin=%d)",
             cart_id, _TD_CART_COST_GOLD_DIAMOND, player["uin"])
    body = pb_varint_field(1, cart_id) + pb_varint_field(2, 0)  # cartId, remainTimes
    return [(response_name, body),
            ("PVZ.Cmd.Cmd_SyncTicket_SC", pb_varint_field(1, player["ticket"]))]


def handle_td_buycart(cmd_data, player):
    return _handle_td_buycart(cmd_data, player, "PVZ.Cmd.Cmd_TD_BuyCart_SC")


def handle_dailytd_buycart(cmd_data, player):
    return _handle_td_buycart(cmd_data, player, "PVZ.Cmd.Cmd_DailyTD_BuyCart_SC")


def handle_noendtd_buycart(cmd_data, player):
    return _handle_td_buycart(cmd_data, player, "PVZ.Cmd.Cmd_NoEndTD_BuyCart_SC")


_FUBEN_BONUS = None


def load_fuben_bonus():
    """{(chapterId, mode): (starsMax, itemId, amount)} from clientDB FubenBonusTemplate.txt — the
    per-chapter star-reward chest (bonus = "itemId:amount", claimable once starsMax stars earned)."""
    global _FUBEN_BONUS
    if _FUBEN_BONUS is None:
        _FUBEN_BONUS = {}
        rows = _read_clientdb_table("FubenBonusTemplate.txt")
        if rows:
            hdr = rows[0]; ci = {c: i for i, c in enumerate(hdr)}

            def col(c, k):
                i = ci.get(k)
                return c[i] if i is not None and i < len(c) else ""
            for c in rows[1:]:
                try:
                    ch, md = int(col(c, "id")), int(col(c, "mode"))
                    stars_max = int(float(col(c, "starsMax") or 0))
                    iid, amount = col(c, "bonus").split(":")
                    _FUBEN_BONUS[(ch, md)] = (stars_max, int(iid), int(amount))
                except (ValueError, KeyError, IndexError):
                    pass
        log.info("loaded %d fuben bonus-chest templates", len(_FUBEN_BONUS))
    return _FUBEN_BONUS


def _fuben_box_taken_flag(uin, chapter, mode):
    """1 if the player has claimed this chapter+mode star-chest, else 0 (for GetStageInfo)."""
    return 1 if store.is_fuben_box_taken(uin, chapter, mode) else 0


def handle_fuben_requestrewardbox(cmd_data, player):
    """Cmd_Fuben_RequestRewardBox_CS{chapterid(1), mode(2)} -> Cmd_Fuben_RequestRewardBox_SC
    {chapterid(1), mode(2)}. The client reads the chest's item from its own FubenBonusTemplate and
    flies it to the bag on retCode==0; we grant it authoritatively (gift diamond -> HUD sync) and
    record the claim so it won't re-open. Claimable = starsMax stars earned in that chapter+mode and
    not already taken; an invalid/duplicate request is a silent no-op (no fake grant)."""
    f = parse_varint_fields(cmd_data)
    chapter, mode = f.get(1, 0), f.get(2, 0)
    uin = player["uin"]
    stars_max, item_id, amount = load_fuben_bonus().get((chapter, mode), (0, 0, 0))
    have = sum(store.get_fuben_passed(uin, chapter, mode).values())
    if (not chapter or not mode or stars_max <= 0 or have < stars_max
            or store.is_fuben_box_taken(uin, chapter, mode)):
        log.info("    fuben reward box DENIED: chapter=%d mode=%d have=%d/%d taken=%s",
                 chapter, mode, have, stars_max, store.is_fuben_box_taken(uin, chapter, mode))
        return []                      # silent no-op — the client only asks when legitimately open
    store.take_fuben_box(uin, chapter, mode)
    sc = pb_varint_field(1, chapter) + pb_varint_field(2, mode)   # echo -> setTakenReward + itemFly
    messages = [("PVZ.Cmd.Cmd_Fuben_RequestRewardBox_SC", sc)]
    messages += grant_fuben_reward(player, [(item_id, amount)])   # gift diamond -> field + sync
    log.info("    fuben reward box CLAIMED: chapter=%d mode=%d -> item %d x%d (stars %d/%d)",
             chapter, mode, item_id, amount, have, stars_max)
    return messages


def _fuben_chapter_cleared(uin, chapter):
    """True if every normal-mode stage of a chapter has been beaten (gates the next chapter)."""
    normal_stages = load_fuben_stages().get((chapter, 1), [])
    return bool(normal_stages) and len(store.get_fuben_passed(uin, chapter, 1)) >= len(normal_stages)


_FUBEN_SWEEP_PRIVILEGE = 14        # VipPrivilegeInfo: 冒险副本/傀儡战境扫荡
_FUBEN_MULTI_SWEEP_PRIVILEGE = 15  # VipPrivilegeInfo: 冒险连续扫荡
_FUBEN_MULTI_SWEEP_TIMES = 10


def _fuben_sweep_access(player, stars):
    """Return the stage DTO's sweep flags and supported bulk count.

    The client's lineup window reads canSingleSweep/canMultiSweep directly from the stage DTO; when
    absent they default false and both sweep buttons disappear. Its shipped hint says VIP can sweep
    1/2-star clears while non-VIP needs 3 stars. VIP entitlement is privilege 14 in VipInfo.txt; the
    optional 10x button requires privilege 15 (VipPrivilegeInfo: 冒险连续扫荡).
    """
    privileges = vip_privileges(player)
    required_stars = 1 if _FUBEN_SWEEP_PRIVILEGE in privileges else 3
    can_single = int(stars or 0) >= required_stars
    can_multi = can_single and _FUBEN_MULTI_SWEEP_PRIVILEGE in privileges
    return can_single, can_multi, _FUBEN_MULTI_SWEEP_TIMES if can_multi else 0


def _fuben_stage_info_dto(player, chapter, mode, stage, stars):
    """Dto_Fuben_StageInfo fields 1-9, including the sweep controls' eligibility."""
    can_single, can_multi, multi_times = _fuben_sweep_access(player, stars)
    # Adventure stages have no server-side daily attempt counter, so hasLimit/times stay false/zero.
    return (pb_varint_field(1, chapter) + pb_varint_field(2, mode)
            + pb_varint_field(3, stage) + pb_varint_field(4, stars)
            + pb_varint_field(5, 0) + pb_varint_field(6, 0)
            + pb_varint_field(7, 1 if can_single else 0)
            + pb_varint_field(8, 1 if can_multi else 0)
            + pb_varint_field(9, multi_times))


def handle_fuben_getchapterinfo(cmd_data, player):
    """Cmd_Fuben_GetChapterInfo_CS -> Cmd_Fuben_GetChapterInfo_SC. Unlock chapters by PROGRESS,
    contiguously: chapter N+1 opens only once N is fully cleared (and level >= levelNeed). A
    chapter with a Dto becomes unlocked (FubenChapterVO.loadDto). This keeps the set contiguous
    AND makes getLastUnlockedFubenStageVo() return the player's real FRONTIER chapter (so the
    map opens there, not the highest level-gated one). Dto_Fuben_ChapterInfo{chapterid(1),
    star(2), lastEasyStageId(3), lastHardStageId(4)}."""
    level = int(player.get("level", 1))
    uin = player["uin"]
    d, n = b"", 0
    for ch, need in load_fuben_chapters():
        if need > level:
            break                          # level gate — can't reach this chapter yet
        normal = store.get_fuben_passed(uin, ch, 1)   # {stage: star}
        elite = store.get_fuben_passed(uin, ch, 2)
        star = sum(normal.values()) + sum(elite.values())
        dto = (pb_varint_field(1, ch) + pb_varint_field(2, star)
               + pb_varint_field(3, max(normal) if normal else 0)     # lastEasyStageId
               + pb_varint_field(4, max(elite) if elite else 0))      # lastHardStageId
        d += pb_tag(1, 2) + uvarint(len(dto)) + dto
        n += 1
        if not _fuben_chapter_cleared(uin, ch):
            break                          # frontier reached — stop unlocking further chapters
    log.info("    fuben chapters: level=%d -> %d unlocked (progress-gated)", level, n)
    return d


def handle_fuben_getstageinfo(cmd_data, player):
    """Cmd_Fuben_GetStageInfo_CS{chapterid, modeid} -> Cmd_Fuben_GetStageInfo_SC. Send a
    Dto_Fuben_StageInfo ONLY for the cleared stages (loadDto -> unlocked+star); the client then
    setUnlocked()s the next stage after the highest cleared, and un-reached stages stay locked.
    If none are cleared yet, send just stage 1 so it appears unlocked (and to avoid the client's
    empty-list null-deref). Dto_Fuben_StageInfo{chapterid(1),modeid(2),stageid(3),star(4),
    hasLimit(5),times(6),canSingleSweep(7),canMultiSweep(8),multiSweeptTimes(9)}."""
    f = parse_varint_fields(cmd_data)
    chapter, mode = f.get(1, 1), f.get(2, 1)
    note_battle_scene(player, "fuben")      # the adventure lineup window previews the enemy squad
    all_stages = load_fuben_stages().get((chapter, mode), [])
    passed = store.get_fuben_passed(player["uin"], chapter, mode)   # {stageId: star}
    send = sorted(passed) if passed else (all_stages[:1] if all_stages else [])
    taken = _fuben_box_taken_flag(player["uin"], chapter, mode)
    log.info("    fuben stage info: chapter=%d mode=%d -> send %s (%d cleared of %d) boxTaken=%d",
             chapter, mode, send, len(passed), len(all_stages), taken)
    d = b""
    for st in send:
        dto = _fuben_stage_info_dto(player, chapter, mode, st, passed.get(st, 0))
        d += pb_tag(1, 2) + uvarint(len(dto)) + dto     # stageinfo (field 1, repeated)
    d += pb_varint_field(2, taken)                      # hasTakeReward (field 2) — chest claimed?
    return d


def handle_fuben_sweep(cmd_data, player):
    """Cmd_Fuben_Sweep_CS: sweep an already-cleared stage and grant its configured loot."""
    f = parse_varint_fields(cmd_data)
    chapter, mode, stage = f.get(1, 0), f.get(2, 0), f.get(3, 0)
    times = f.get(4, 1)
    multi_sweep = bool(f.get(5, 0))
    if chapter <= 0 or mode <= 0 or stage <= 0 or times not in (1, _FUBEN_MULTI_SWEEP_TIMES):
        return []
    passed = store.get_fuben_passed(player["uin"], chapter, mode)
    can_single, can_multi, _multi_times = _fuben_sweep_access(player, passed.get(stage, 0))
    if times == 1:
        if multi_sweep or not can_single:
            return []
    elif not multi_sweep or not can_multi:
        return []
    energy_cost = (fuben_energy_cost(chapter, mode, stage) or 5) * times
    if not consume_energy(player, energy_cost):
        return []
    merged = {}
    for _ in range(times):
        for item_id, amount in fuben_stage_reward(chapter, mode, stage, False):
            merged[item_id] = merged.get(item_id, 0) + amount
    # The local 集字 event awards one 海贝 per successful adventure clear.
    # Put it in the reward DTO itself so the sweep popup and saved bag agree.
    merged[hotspot_events.SHELL] = merged.get(hotspot_events.SHELL, 0) + times
    rewards = sorted(merged.items())
    reward_body = b""
    for item_id, amount in rewards:
        reward_body += pb_tag(4, 2) + uvarint(len(build_item_dto(item_id, amount))) + build_item_dto(item_id, amount)
    fight_reward = pb_varint_field(1, 0) + pb_varint_field(2, 0) + reward_body
    card_exp = pb_varint_field(1, 0) + pb_varint_field(2, 0) + pb_varint_field(3, 0)
    sweep = (pb_tag(1, 2) + uvarint(len(fight_reward)) + fight_reward
             + pb_tag(2, 2) + uvarint(len(card_exp)) + card_exp)
    messages = [("PVZ.Cmd.Cmd_Fuben_Sweep_SC", pb_tag(1, 2) + uvarint(len(sweep)) + sweep)]
    messages += grant_fuben_reward(player, rewards)
    _daily_quest_touch(player, "fuben", times)
    messages.append(energy_sync_msg(player))
    log.info("    FUBEN SWEEP: chapter=%d mode=%d stage=%d times=%d rewards=%s",
             chapter, mode, stage, times, rewards)
    return messages


# --- battle cards (the card-RPG combat units) from clientDB battleCard.txt -------------
# Plants and zombies are both "battle cards": id=cardId, tdId maps a card to its TD plant
# (0 for zombies), planClassName = the plan-machine animation, initial*/grow* = stats.
_BATTLE_CARDS = None
_TD_TO_CARD = None

# battleCard.txt stats are the COLLECTIBLE-card scale (endgame numbers: sunflower 36k HP, mummy
# 270k HP). The ADVENTURE display uses a much smaller scale — the wiki Day-1 mummy is ~2970 HP =
# the mummy card (270000) compressed ~91x. Raw card stats made the player's combat power ~170x the
# zombies; the intended balance (early-version screenshot) is only ~2x. We divide every card's
# hp/atk/def/ability by this one factor at load time, so ALL consumers — almanac (raw-attribute),
# collection (card package), formation (lineup 战力), and the plant battle units — shrink together
# and stay consistent. Zombies keep their own hand-tuned wiki stats in build_battle_units (they don't
# read these), so this only brings the PLANT side down. D=80 => 4 starters ~1.35x, a fuller 6-plant
# team ~2x the zombie total (990) — "a little higher, not drastically higher".
_ADV_STAT_SCALE = 80


def load_battle_cards():
    """{cardId: {tdId,name,type,plan,hp,atk,def_,star,skill1,skill2}} + {tdPlantId: base star-1
    cardId} from battleCard.txt. Stats are the card's star-1 base (level 1); good enough for v1."""
    global _BATTLE_CARDS, _TD_TO_CARD
    if _BATTLE_CARDS is None:
        _BATTLE_CARDS, _TD_TO_CARD = {}, {}
        rows = _read_clientdb_table("battleCard.txt")
        if rows:
            hdr = rows[0]; ci = {c: i for i, c in enumerate(hdr)}

            def col(c, k, d="0"):
                i = ci.get(k)
                return c[i] if i is not None and i < len(c) else d
            for c in rows[1:]:
                try:
                    cid = int(col(c, "id"))
                except ValueError:
                    continue
                td = int(col(c, "tdId") or 0)
                # Store RAW (unscaled) initial + grow-per-level so stats can be computed at ANY card
                # level (card_stats_at_level). The `hp/atk/def_/ability` keys stay the LEVEL-1 scaled
                # values (adventure scale, see _ADV_STAT_SCALE) for callers that want the base.
                s = _ADV_STAT_SCALE
                _BATTLE_CARDS[cid] = {
                    "tdId": td, "name": col(c, "name", ""), "type": int(col(c, "type") or 0),
                    "fruitType": int(col(c, "fruitType") or 0),
                    "rarity": int(col(c, "rarity") or 1),
                    "icon": int(col(c, "icon") or 0),
                    "recycleItemId": int((col(c, "recycleItemString", "0,0").split(",") + ["0"])[0] or 0),
                    "recycleItemNum": int((col(c, "recycleItemString", "0,0").split(",") + ["0", "0"])[1] or 0),
                    "plan": col(c, "planClassName", ""),
                    "hp": max(1, int(col(c, "initialHp") or 0) // s),
                    "atk": int(col(c, "initialAttack") or 0) // s,
                    "def_": int(col(c, "initialDefense") or 0) // s, "star": int(col(c, "star") or 1),
                    # awakeLevel drives the 洗炼 attribute caps (clientDB baptizeLimit.txt)
                    "awakeLevel": int(col(c, "awakeLevel") or 0),
                    "skill1": int(col(c, "skillId1") or 0), "skill2": int(col(c, "skillId2") or 0),
                    "leader_skill": int(col(c, "leaderSkillId") or 0),
                    "quality": int(col(c, "quality") or 1),
                    "ability": int(col(c, "initialAbility") or 0) // s,
                    "maxLv": int(col(c, "maxLv") or 1),
                    "init_hp": int(col(c, "initialHp") or 0), "grow_hp": int(col(c, "growHp") or 0),
                    "init_atk": int(col(c, "initialAttack") or 0), "grow_atk": int(col(c, "growAttack") or 0),
                    "init_def": int(col(c, "initialDefense") or 0), "grow_def": int(col(c, "growDefense") or 0),
                    "init_abi": int(col(c, "initialAbility") or 0), "grow_abi": int(col(c, "growAbility") or 0),
                    # 护盾 (蓝盾)：battleCard 每张卡都有 initialShield/growShield 独立血池。
                    # 战斗里伤害先扣盾再扣血，点击植物时客户端血条上方画蓝盾条，靠的就是这个值。
                    "shield": max(0, int(col(c, "initialShield") or 0)) // s,
                    "init_shield": int(col(c, "initialShield") or 0),
                    "grow_shield": int(col(c, "growShield") or 0),
                    # These four rates use basis points in battleCard. They are
                    # probabilities, unlike the primary stats compressed above.
                    "hit": int(col(c, "initialHit") or 0),
                    "dodge": int(col(c, "initialDodge") or 0),
                    "critical": int(col(c, "initialCritical") or 0),
                    "tough": int(col(c, "initialTough") or 0),
                    "init_hit": int(col(c, "initialHit") or 0),
                    "grow_hit": int(col(c, "growHit") or 0),
                    "init_dodge": int(col(c, "initialDodge") or 0),
                    "grow_dodge": int(col(c, "growDodge") or 0),
                    "init_critical": int(col(c, "initialCritical") or 0),
                    "grow_critical": int(col(c, "growCritical") or 0),
                    "init_tough": int(col(c, "initialTough") or 0),
                    "grow_tough": int(col(c, "growTough") or 0),
                }
                # base card for a TD plant = the lowest cardId sharing that tdId (star-1, quality-1).
                if td and (td not in _TD_TO_CARD or cid < _TD_TO_CARD[td]):
                    _TD_TO_CARD[td] = cid
        log.info("loaded %d battle cards (%d TD-plant mappings)", len(_BATTLE_CARDS), len(_TD_TO_CARD))
    return _BATTLE_CARDS


def card_stats_at_level(card_id, level):
    """A card's adventure-scaled stats at a given card LEVEL. stat = (initial + grow*(level-1)) /
    _ADV_STAT_SCALE. Returns a dict shaped like a _BATTLE_CARDS entry (hp/atk/def_/ability + name/
    skill1/skill2/quality/star), so it drops into card_power / build_* unchanged. Level 1 == the base."""
    load_battle_cards()
    b = _BATTLE_CARDS.get(card_id)
    if not b:
        return {"hp": 1, "atk": 0, "def_": 0, "ability": 0, "skill1": 0, "skill2": 0,
                "hit": 0, "dodge": 0, "critical": 0, "tough": 0,
                "quality": 1, "star": 1, "name": "?"}
    lv = max(1, int(level or 1))
    s = _ADV_STAT_SCALE
    def at(init, grow):
        return (init + grow * (lv - 1)) // s
    return {
        "hp": max(1, at(b["init_hp"], b["grow_hp"])), "atk": at(b["init_atk"], b["grow_atk"]),
        "def_": at(b["init_def"], b["grow_def"]), "ability": at(b["init_abi"], b["grow_abi"]),
        "shield": max(0, at(b["init_shield"], b["grow_shield"])),   # 护盾血池（蓝盾条）
        "hit": b["init_hit"] + b["grow_hit"] * (lv - 1),
        "dodge": b["init_dodge"] + b["grow_dodge"] * (lv - 1),
        "critical": b["init_critical"] + b["grow_critical"] * (lv - 1),
        "tough": b["init_tough"] + b["grow_tough"] * (lv - 1),
        "skill1": b["skill1"], "skill2": b["skill2"], "quality": b["quality"], "star": b["star"],
        "name": b["name"], "level": lv,
    }


_CARD_FRUIT_INFO = None


def load_card_fruit_info():
    """Index cardFruitInfo.txt by (plant fruitType, fruit-slot quality, level)."""
    global _CARD_FRUIT_INFO
    if _CARD_FRUIT_INFO is None:
        _CARD_FRUIT_INFO = {}
        rows = _read_clientdb_table("cardFruitInfo.txt")
        if rows:
            hdr = rows[0]; ci = {c: i for i, c in enumerate(hdr)}
            for row in rows[1:]:
                try:
                    key = (int(row[ci["cardType"]]), int(row[ci["quilty"]]),
                           int(row[ci["level"]]))
                    _CARD_FRUIT_INFO[key] = {
                        "attack": int(row[ci["attack"]]), "defence": int(row[ci["defence"]]),
                        "life": int(row[ci["life"]]), "ability": int(row[ci["ability"]]),
                        "hit": int(row[ci["hit"]]), "dodge": int(row[ci["dodge"]]),
                        "critical": int(row[ci["critical"]]), "tough": int(row[ci["tough"]]),
                        "intitate": int(row[ci["intitate"]]), "needItems": row[ci["needItems"]],
                        "isSuperCatalytic": int(row[ci["isSuperCatalytic"]]),
                        "openLevel": int(row[ci["openLevel"]]),
                        "totalFightPower": int(row[ci["totalFightPower"]]),
                    }
                except (KeyError, IndexError, TypeError, ValueError):
                    continue
        log.info("loaded %d card-fruit templates", len(_CARD_FRUIT_INFO))
    return _CARD_FRUIT_INFO


def _card_fruit_stat_bonus(uin, uid, card_id):
    """Return scaled battle stats from all of an owned plant's upgraded fruit slots."""
    load_battle_cards()
    fruit_type = int((_BATTLE_CARDS.get(card_id) or {}).get("fruitType", 0))
    if not fruit_type or not uid:
        return {"atk": 0, "def_": 0, "hp": 0, "ability": 0,
                "hit": 0, "dodge": 0, "critical": 0, "tough": 0}
    templates = load_card_fruit_info()
    bonus = {"atk": 0, "def_": 0, "hp": 0, "ability": 0,
             "hit": 0, "dodge": 0, "critical": 0, "tough": 0}
    for slot, level in store.get_card_fruits(uin, uid).items():
        info = templates.get((fruit_type, int(slot), int(level)))
        if not info:
            continue
        bonus["atk"] += info["attack"] // _ADV_STAT_SCALE
        bonus["def_"] += info["defence"] // _ADV_STAT_SCALE
        bonus["hp"] += info["life"] // _ADV_STAT_SCALE
        bonus["ability"] += info["ability"] // _ADV_STAT_SCALE
        for field in ("hit", "dodge", "critical", "tough"):
            bonus[field] += info[field]
    return bonus


def _apply_card_fruit_bonus(stats, uin, uid, card_id):
    bonus = _card_fruit_stat_bonus(uin, uid, card_id)
    for key, value in bonus.items():
        stats[key] = stats.get(key, 0) + value
    return stats


# --- plant prestige evolution + armour -------------------------------------------
_PLANT_EVOLUTION = None
_PLANT_ARMOR = None
_EVOLUTION_ATTRS = ("atk", "def_", "hp", "ability", "critical", "dodge", "hit", "tough")


def load_plant_evolution():
    """Load the 200-level 威望 tree and its seven plant-type stat weight profiles."""
    global _PLANT_EVOLUTION
    if _PLANT_EVOLUTION is not None:
        return _PLANT_EVOLUTION
    data = {"levels": {}, "types": {}}
    for table, target in (("plantEvolutionLevelTemplate.txt", "levels"),
                          ("plantEvolutionTypeTemplate.txt", "types")):
        rows = _read_clientdb_table(table)
        if not rows:
            continue
        ci = {name: i for i, name in enumerate(rows[0])}
        for row in rows[1:]:
            try:
                row_id = int(row[ci["id"]])
                if target == "levels":
                    costs = parse_bonus_items(row[ci["needItemStr"]])
                    data[target][row_id] = {
                        "main": int(row[ci["mainPropPF"]]),
                        "secondary": int(row[ci["secondaryPropPF"]]),
                        "extra": int(row[ci["extraBuff"]]),
                        "speed": int(row[ci["speed"]]),
                        "cost": costs[0] if costs else (43, 0),
                    }
                else:
                    data[target][row_id] = [int(row[ci[name]]) for name in (
                        "attackWeight", "defenceWeight", "hpWeight", "skillWeight",
                        "criticalWeight", "dodgeWeight", "hitWeight", "toughWeight")]
            except (KeyError, IndexError, TypeError, ValueError):
                continue
    _PLANT_EVOLUTION = data
    log.info("loaded prestige evolution: %d levels, %d plant types",
             len(data["levels"]), len(data["types"]))
    return data


def _prestige_bonus(uin, uid, card_id):
    level = store.get_card_evolve_level(uin, uid)
    if level <= 0:
        return {key: 0 for key in _EVOLUTION_ATTRS}
    data = load_plant_evolution()
    row = data["levels"].get(level)
    fruit_type = int((_BATTLE_CARDS.get(card_id) or {}).get("fruitType", 0))
    weights = data["types"].get(fruit_type)
    if not row or not weights:
        return {key: 0 for key in _EVOLUTION_ATTRS}
    out = {}
    # This is the client's GameGloble.fightPower2PropVal conversion.
    primary_sum = max(1, sum(weights[:4]))
    secondary_sum = max(1, sum(weights[4:]))
    conversions = (2, 1, 6, 1, 2, 2, 2, 2)
    for i, key in enumerate(_EVOLUTION_ATTRS):
        pool = row["main"] if i < 4 else row["secondary"]
        denom = primary_sum if i < 4 else secondary_sum
        out[key] = int(pool * weights[i] * conversions[i] / denom + 0.5)
    # extraBuff is stored in basis points by the original client.
    if row["extra"]:
        for key in out:
            out[key] += int(out[key] * row["extra"] / 10000.0 + 0.5)
    return out


def _apply_prestige_bonus(stats, uin, uid, card_id):
    for key, value in _prestige_bonus(uin, uid, card_id).items():
        stats[key] = stats.get(key, 0) + value
    return stats


def load_plant_armor():
    global _PLANT_ARMOR
    if _PLANT_ARMOR is not None:
        return _PLANT_ARMOR
    data = {"levels": {}, "star_need": {}, "crystals": {}, "increase": [], "star_prop": {}}
    tables = {name: _read_clientdb_table(name) for name in (
        "plantArmorLevelInfo.txt", "plantArmorStarNeedInfo.txt", "plantArmorCrystalInfo.txt",
        "plantArmorIncreaseInfo.txt", "plantArmorStarPropInfo.txt")}
    for name, rows in tables.items():
        if not rows:
            continue
        ci = {col: i for i, col in enumerate(rows[0])}
        for row in rows[1:]:
            try:
                if name == "plantArmorLevelInfo.txt":
                    data["levels"][int(row[ci["id"]])] = (int(row[ci["exp"]]), int(row[ci["needStar"]]))
                elif name == "plantArmorStarNeedInfo.txt":
                    costs = parse_bonus_items(row[ci["needItemNumStr"]])
                    key = (int(row[ci["armorType"]]), int(row[ci["star"]]), int(row[ci["subStar"]]))
                    data["star_need"][key] = {"cost": costs[0] if costs else (0, 0),
                                                   "role": int(row[ci["needRoleLV"]])}
                elif name == "plantArmorCrystalInfo.txt":
                    props = {int(x.split(":")[0]): int(x.split(":")[1])
                             for x in row[ci["propStr"]].split(",") if ":" in x}
                    item_id = int(row[ci["id"]])
                    data["crystals"][item_id] = {
                        "level": int(row[ci["level"]]), "hole": int(row[ci["holeID"]]),
                        "props": props, "speed": int(row[ci["speed"]]),
                        "need": int(row[ci["levelUpNeedNum"]]),
                        "next": int(row[ci["levelUpItemID"]]),
                    }
                elif name == "plantArmorIncreaseInfo.txt":
                    data["increase"].append({
                        "sub": int(row[ci["level"]]), "gem_level": int(row[ci["crystalType"]]),
                        "need": int(row[ci["needCrystalNum"]]), "role": int(row[ci["needCityLv"]]),
                        "percent": int(row[ci["addPercent"]]),
                    })
                else:
                    row_id = int(row[ci["id"]])
                    data["star_prop"][row_id] = {
                        "atk": int(row[ci["attack"]]), "def_": int(row[ci["defence"]]),
                        "hp": int(row[ci["hp"]]), "ability": int(row[ci["ability"]]),
                        "grow_atk": int(row[ci["growAttack"]]),
                        "grow_def_": int(row[ci["growDefence"]]),
                        "grow_hp": int(row[ci["growHp"]]),
                        "grow_ability": int(row[ci["growAbility"]]),
                    }
            except (KeyError, IndexError, TypeError, ValueError):
                continue
    _PLANT_ARMOR = data
    log.info("loaded plant armour: %d levels, %d stars, %d crystals",
             len(data["levels"]), len(data["star_prop"]), len(data["crystals"]))
    return data


def _armor_growth(uin, role_level=999):
    """Return crystal level -> (owned count, unlocked amplification tier, percent)."""
    armor = load_plant_armor()
    owned = dict(store.get_items(uin))       # ONE bulk query, not one per crystal type
    counts = {level: 0 for level in range(1, 11)}
    for item_id, info in armor["crystals"].items():
        counts[info["level"]] += owned.get(item_id, 0)
    for item_id in store.get_all_card_armor_gems(uin):
        info = armor["crystals"].get(item_id)
        if info:
            counts[info["level"]] += 1
    out = {}
    for level, count in counts.items():
        eligible = [row for row in armor["increase"] if row["gem_level"] == level
                    and count >= row["need"] and role_level >= row["role"]]
        best = max(eligible, key=lambda row: row["sub"], default=None)
        out[level] = (count, best["sub"] if best else 0, best["percent"] if best else 0)
    return out


def _armor_bonus(uin, uid, card_id, role_level=999, growth=None):
    armor = load_plant_armor()
    fruit_type = int((_BATTLE_CARDS.get(card_id) or {}).get("fruitType", 0))
    # growth only depends on (uin, role_level) — callers iterating many cards pass a shared one.
    if growth is None:
        growth = _armor_growth(uin, role_level)
    out = {"atk": 0, "def_": 0, "hp": 0, "ability": 0}
    for armor_type, state in store.get_card_armors(uin, uid).items():
        key = fruit_type * 1000 + armor_type * 100 + state["star"] * 10 + state["substar"]
        prop = armor["star_prop"].get(key)
        if prop:
            for field in out:
                # Armour tables are centi-units; then compress to this local server's adventure scale.
                out[field] += (prop[field] + prop["grow_" + field] * state["level"]) // (100 * _ADV_STAT_SCALE)
        for item_id in state["gems"].values():
            crystal = armor["crystals"].get(item_id)
            if not crystal:
                continue
            amp = growth.get(crystal["level"], (0, 0, 0))[2]
            for attr_id, amount in crystal["props"].items():
                field = {1: "atk", 2: "def_", 3: "hp", 5: "ability"}.get(attr_id)
                if field:
                    amount += amount * amp // 10000
                    out[field] += amount // (100 * _ADV_STAT_SCALE)
    return out


def _apply_armor_bonus(stats, uin, uid, card_id, role_level=999, growth=None):
    for key, value in _armor_bonus(uin, uid, card_id, role_level, growth=growth).items():
        stats[key] = stats.get(key, 0) + value
    return stats


# --- card genes (植物基因) ----------------------------------------------------------
_CARD_DNA = None
_DNA_ATTR_STATS = {1: "atk", 2: "def_", 3: "hp", 5: "ability",
                   6: "hit", 7: "dodge", 8: "critical", 9: "tough"}


def load_card_dna():
    """Load the same gene-choice, enhancement, refund and trial tables used by ModuleCardDNA."""
    global _CARD_DNA
    if _CARD_DNA is not None:
        return _CARD_DNA
    data = {"info": {}, "choose": {}, "factor": {}, "param": {}, "reset": {},
            "test": {}, "test_reset": {}, "test_limit": {}}

    def rows_by_name(table):
        rows = _read_clientdb_table(table)
        if not rows:
            return []
        ci = {name: index for index, name in enumerate(rows[0])}
        return [(row, ci) for row in rows[1:]]

    def val(row, ci, key, default="0"):
        i = ci.get(key)
        return row[i] if i is not None and i < len(row) else default

    for row, ci in rows_by_name("cardDNAInfo.txt"):
        try:
            data["info"][(int(val(row, ci, "cardType")), int(val(row, ci, "quilty")))] = [
                int(x) for x in val(row, ci, "chooseListStr", "").split(",") if x]
        except ValueError:
            continue
    for row, ci in rows_by_name("cardDNAChooseInfo.txt"):
        try:
            key = (int(val(row, ci, "type")), int(val(row, ci, "level")))
            data["choose"][key] = {
                "type_name": int(val(row, ci, "typeNameID")),
                "add": int(val(row, ci, "addProp")),
                "total": int(val(row, ci, "totalAddProp")),
                "items": parse_bonus_items(val(row, ci, "needItemStr", "")),
                "clip": int(val(row, ci, "needClipNum")),
                "plant_level": int(val(row, ci, "needPlantLV")),
            }
        except ValueError:
            continue
    for row, ci in rows_by_name("cardDNAFactorInfo.txt"):
        try:
            key = (int(val(row, ci, "cardType")), int(val(row, ci, "quilty")),
                   int(val(row, ci, "level")))
            data["factor"][key] = {
                "attack": int(val(row, ci, "attack")), "defense": int(val(row, ci, "defence")),
                "hp": int(val(row, ci, "life")), "ability": int(val(row, ci, "ability")),
                "hit": int(val(row, ci, "hit")), "dodge": int(val(row, ci, "dodge")),
                "critical": int(val(row, ci, "critical")), "tough": int(val(row, ci, "tough")),
                "items": parse_bonus_items(val(row, ci, "needItemStr", "")),
                "plant_level": int(val(row, ci, "needPlantLV")),
                "probability": int(val(row, ci, "probability")),
                "fail_exp": int(val(row, ci, "failExp")),
                "max_probability": int(val(row, ci, "maxProbability")),
            }
        except ValueError:
            continue
    for row, ci in rows_by_name("cardDNAParamInfo.txt"):
        try:
            data["param"][int(val(row, ci, "id"))] = {
                "scale": int(val(row, ci, "param")) / 10000.0,
                "recycle_factor": parse_bonus_items(val(row, ci, "recycleFactorNeedItemStr", "")),
                "recycle_dna": parse_bonus_items(val(row, ci, "recycleDNANeedItemStr", "")),
            }
        except ValueError:
            continue
    for row, ci in rows_by_name("cardDNAResetInfo.txt"):
        try:
            data["reset"][int(val(row, ci, "id"))] = parse_bonus_items(val(row, ci, "needItemStr", ""))
        except ValueError:
            continue
    for row, ci in rows_by_name("cardDNATestLevelInfo.txt"):
        try:
            data["test"][(int(val(row, ci, "mode")), int(val(row, ci, "stageID")),
                          int(val(row, ci, "levelID")))] = {
                "power": int(val(row, ci, "monsterFP")),
                "reward_text": val(row, ci, "rewardItemStr", ""),
            }
        except ValueError:
            continue
    for table, target in (("cardDNATestReset.txt", "test_reset"),
                          ("cardDNATestLimit.txt", "test_limit")):
        for row, ci in rows_by_name(table):
            try:
                key = int(val(row, ci, "id"))
                if target == "test_reset":
                    target_cost = parse_bonus_items(val(row, ci, "needItemStr", ""))
                    data[target][key] = target_cost[0] if target_cost else (37, 0)
                else:
                    data[target][key] = {"open": int(val(row, ci, "isOpen")),
                                         "requirement": val(row, ci, "challengeLimit", ""),
                                         "tip": val(row, ci, "openLimitTip", "")}
            except ValueError:
                continue
    _CARD_DNA = data
    log.info("loaded gene templates: %d plant-stage choices, %d attribute levels, %d factor levels, %d trial levels",
             len(data["info"]), len(data["choose"]), len(data["factor"]), len(data["test"]))
    return data


def _dna_scale(card_info):
    return load_card_dna()["param"].get(int(card_info.get("rarity", 1)), {"scale": 1.0})["scale"]


def _dna_scaled_cost(costs, scale):
    return [(int(iid), max(0, int(int(amount) * scale))) for iid, amount in costs if amount]


def _dna_gene_proto(gene_id, gene):
    return (pb_varint_field(1, gene_id) + pb_varint_field(2, gene["factor_level"])
            + pb_varint_field(3, gene["factor_exp"]) + pb_varint_field(4, gene["attribute"])
            + pb_varint_field(5, gene["level"]))


def _dna_default_gene(gene_id):
    return {"factor_level": 0, "factor_exp": 0, "attribute": 0, "level": 0}


def _dna_gene_info_body(uid, card, gene_rows):
    """Build GetGeneInfo_SC including non-null base/percent Dto_CardAttribute terms."""
    load_battle_cards()
    card_id = card[1]
    card_info = _BATTLE_CARDS.get(card_id, {})
    card_type = int(card_info.get("fruitType", 0))
    level = int(card[2])
    genes = b""
    for gene_id, gene in sorted(gene_rows.items()):
        dto = _dna_gene_proto(gene_id, gene)
        genes += pb_bytes(2, dto)

    stats = card_stats_at_level(card_id, level)
    totals = {attr: 0 for attr in _DNA_ATTR_STATS}
    dna = load_card_dna()
    scale = _dna_scale(card_info)
    for gene_id, gene in gene_rows.items():
        attr = int(gene["attribute"])
        info = dna["choose"].get((attr, int(gene["level"])))
        if info and info["type_name"] in totals:
            totals[info["type_name"]] += int(info["total"] * scale)

    # Dto_CardAttribute uses hundredths for base and percentage terms; the client applies
    # base * 0.01 * percent * 0.0001. Always send both nested terms to avoid null access.
    base_fields = {1: "atk", 2: "def_", 3: "hp", 5: "ability", 6: "hit",
                   7: "dodge", 8: "critical", 9: "tough"}
    base = b""
    percent = b""
    for field, key in base_fields.items():
        base += pb_varint_field(field, int(stats.get(key, 0)) * 100)
        percent += pb_varint_field(field, int(totals.get(field, 0)) * 100)
    term_base, term_percent = pb_bytes(1, base), pb_bytes(2, percent)
    attribute = term_base + term_percent
    return (pb_int64_field(1, uid) + genes + pb_bytes(3, attribute))


def _card_gene_stat_bonus(uin, uid, card_id, card_level=None):
    """Resolve the card's persisted gene factors and chosen paths to combat stat additions."""
    load_battle_cards()
    card_info = _BATTLE_CARDS.get(int(card_id), {})
    card_type = int(card_info.get("fruitType", 0))
    if not card_type or not uid:
        return {key: 0 for key in ("atk", "def_", "hp", "ability", "hit", "dodge", "critical", "tough")}
    if card_level is None:
        owned = next((row for row in store.get_cards(uin) if int(row[0]) == int(uid)), None)
        card_level = int(owned[2]) if owned else 1
    dna = load_card_dna()
    scale = _dna_scale(card_info)
    bonus = {key: 0 for key in ("atk", "def_", "hp", "ability", "hit", "dodge", "critical", "tough")}
    for gene_id, gene in store.get_card_genes(uin, uid).items():
        for level in range(1, min(int(gene["factor_level"]), 10) + 1):
            factor = dna["factor"].get((card_type, gene_id, level))
            if factor:
                bonus["atk"] += int(factor["attack"] * 0.01 * scale)
                bonus["def_"] += int(factor["defense"] * 0.01 * scale)
                bonus["hp"] += int(factor["hp"] * 0.01 * scale)
                bonus["ability"] += int(factor["ability"] * 0.01 * scale)
                for key in ("hit", "dodge", "critical", "tough"):
                    bonus[key] += int(factor[key] * scale)
        attr = int(gene["attribute"])
        choice = dna["choose"].get((attr, int(gene["level"])))
        stat = _DNA_ATTR_STATS.get(choice["type_name"]) if choice else None
        if stat:
            current = card_stats_at_level(card_id, card_level).get(stat, 0)
            bonus[stat] += int(current * int(choice["total"] * scale) / 10000)
    return bonus


def _apply_card_gene_bonus(stats, uin, uid, card_id, card_level=None):
    for key, value in _card_gene_stat_bonus(uin, uid, card_id, card_level).items():
        stats[key] = stats.get(key, 0) + value
    return stats


def deployed_stat_bonus(player):
    """The combined all-deployed-plant stat bonus from the Lab + World Tree + VIP (priv 25-28) + equipped
    Nutrition reagents, added to EVERY plant on the field (formation/battle). This is
    what turns Lab/Tree/VIP/Nutrition investment into real fighting power, so a developed/VIP account
    out-powers content a fresh one can't."""
    lab = lab_stat_bonus(player)
    tree = wt_stat_bonus(player)
    vip = vip_stat_bonus(player)
    nut = nutrition_stat_bonus(player)
    return {field: sum(source.get(field, 0) for source in (lab, tree, vip, nut))
            for field in ("atk", "def_", "hp", "ability",
                          "hit", "dodge", "critical", "tough")}


def effective_card_stats(player, card_id, level, bonus=None, uid=None):
    """A DEPLOYED plant's battle stats: its card-level stats plus the Lab + World Tree deployed bonus.
    Pass a precomputed `bonus` (deployed_stat_bonus) when stat-ing a whole team so it's only summed once."""
    st = dict(card_stats_at_level(card_id, level))
    b = bonus if bonus is not None else deployed_stat_bonus(player)
    st["atk"] = st.get("atk", 0) + b["atk"]
    st["def_"] = st.get("def_", 0) + b["def_"]
    st["hp"] = max(1, st.get("hp", 0) + b["hp"])
    st["ability"] = st.get("ability", 0) + b.get("ability", 0)
    for field in ("hit", "dodge", "critical", "tough"):
        st[field] = st.get(field, 0) + b.get(field, 0)
    # Card-local progression must follow the selected UID, not another duplicate plant.
    cards = store.get_cards(player["uin"])
    owned_uid = uid if uid is not None else next(
        (_uid for _uid, cid, _card_level, _exp in cards if cid == card_id), None)
    forge_level = 0
    if owned_uid is not None:
        puzzle_bonus = card_puzzle_finish_bonus(
            store.get_card_fill_quality(player["uin"], owned_uid))
        for field in ("atk", "def_", "hp", "ability"):
            st[field] += puzzle_bonus[field]
        forge_level = store.get_card_forge_level(player["uin"], owned_uid)
    if forge_level:
        for row in load_card_forge().get(card_id, []):
            if row["level"] <= forge_level:
                for field in ("atk", "def_", "hp", "ability"):
                    st[field] += row[field]
    if owned_uid is not None:
        _apply_card_fruit_bonus(st, player["uin"], owned_uid, card_id)
        _apply_card_gene_bonus(st, player["uin"], owned_uid, card_id, level)
        _apply_card_baptize_bonus(st, player["uin"], owned_uid)
        _apply_prestige_bonus(st, player["uin"], owned_uid, card_id)
        _apply_armor_bonus(st, player["uin"], owned_uid, card_id, int(player.get("level", 1)))
        owned_card = next((row for row in cards if int(row[0]) == int(owned_uid)), None)
        _apply_card_avatar_bonus(st, player, owned_uid, owned_card)
    return st


# --- card XP / leveling curve (cardLevel.txt) -------------------------------------
# totalExp[L] = cumulative XP to REACH level L; needLevel[L] = the ACCOUNT (role) level required to
# reach card level L (so a low-level account can't max a card). Stats grow per card level (above).
_CARD_LEVEL_CURVE = None       # sorted list of (level, totalExp, needLevel)


def load_card_level_curve():
    global _CARD_LEVEL_CURVE
    if _CARD_LEVEL_CURVE is None:
        _CARD_LEVEL_CURVE = []
        rows = _read_clientdb_table("cardLevel.txt")
        if rows:
            hdr = rows[0]; ci = {c: i for i, c in enumerate(hdr)}
            for r in rows[1:]:
                def col(k):
                    i = ci.get(k)
                    return r[i] if i is not None and i < len(r) else "0"
                try:
                    _CARD_LEVEL_CURVE.append((int(col("level")), int(col("totalExp")), int(col("needLevel"))))
                except ValueError:
                    continue
            _CARD_LEVEL_CURVE.sort()
        log.info("loaded card level curve (%d levels)", len(_CARD_LEVEL_CURVE))
    return _CARD_LEVEL_CURVE


def card_level_from_exp(total_exp, card_id, account_level):
    """The card level reached with `total_exp` cumulative XP, capped by the card's maxLv AND the
    account-level gate (cardLevel.needLevel). Returns (level, total_exp_kept). We never level past the
    gate, and we clamp stored exp to the cap's totalExp so the bar doesn't overflow a capped card."""
    load_card_level_curve()
    load_battle_cards()
    max_lv = _BATTLE_CARDS.get(card_id, {}).get("maxLv", 1)
    level, cap_total = 1, 0
    for lv, tot, need in _CARD_LEVEL_CURVE:
        if lv > max_lv or need > account_level:
            break
        cap_total = tot
        if total_exp >= tot:
            level = lv
        else:
            break
    return level, min(total_exp, cap_total)


def card_exp_within_level(total_exp, level):
    """XP earned INSIDE the current level (total_exp - the level's cumulative totalExp) — the bar fill."""
    load_card_level_curve()
    base = next((tot for lv, tot, _need in _CARD_LEVEL_CURVE if lv == level), 0)
    return max(0, total_exp - base)


# Exp items that add plant XP when fed to a card (小经验豆/经验豆/诱人经验豆, id 2002/2003/2004, ...).
# Parsed from ItemInfo.txt desc "增加植物<N>点经验" so ANY exp bean is covered automatically.
_CARD_EXP_ITEMS = None


def card_exp_items():
    """{itemId: expValue} for every 'adds N plant EXP' bean in ItemInfo.txt."""
    global _CARD_EXP_ITEMS
    if _CARD_EXP_ITEMS is None:
        _CARD_EXP_ITEMS = {}
        rows = _read_clientdb_table("ItemInfo.txt")
        if rows:
            hdr = rows[0]; ci = {c: i for i, c in enumerate(hdr)}
            for r in rows[1:]:
                def col(k):
                    i = ci.get(k)
                    return r[i] if i is not None and i < len(r) else ""
                m = re.search(r"增加植物(\d+)点经验", col("desc"))
                if m:
                    try:
                        _CARD_EXP_ITEMS[int(col("id"))] = int(m.group(1))
                    except ValueError:
                        pass
        log.info("loaded %d card-exp items %s", len(_CARD_EXP_ITEMS), _CARD_EXP_ITEMS)
    return _CARD_EXP_ITEMS


def add_card_exp(player, uid, card_id, gain):
    """Add `gain` plant XP to a card (by uid), recompute its level (capped by maxLv + the account level),
    and persist. Returns (old_level, new_level, new_total_exp, within_level_exp). No-op if gain<=0."""
    uin = player["uin"]
    card = next((c for c in store.get_cards(uin) if c[0] == uid), None)
    if not card or gain <= 0:
        return None
    _uid, cid, old_level, cur_exp = card
    account_level = int(player.get("level", 1))
    new_level, new_total = card_level_from_exp(cur_exp + gain, cid, account_level)
    store.set_card_level(uin, uid, new_level, new_total)
    return old_level, new_level, new_total, card_exp_within_level(new_total, new_level)


def build_card_sync_sc(uin, uid, card_id, action_from):
    """Cmd_Card_SyncFullInfo_SC{changeCardList(1)=[Dto_CardFullInfo], actionFrom(4)} for ONE changed
    card at its current stored level/exp — the client updates the card + plays the level-up feedback."""
    card = next((c for c in store.get_cards(uin) if c[0] == uid), None)
    if not card:
        return None
    _uid, cid, level, total_exp = card
    st = card_stats_at_level(cid, level)
    forge_level = store.get_card_forge_level(uin, uid)
    for row in load_card_forge().get(cid, []):
        if row["level"] <= forge_level:
            for field in ("atk", "def_", "hp", "ability"):
                st[field] += row[field]
    fill_stage = store.get_card_fill_quality(uin, uid)
    fill_quality, fill_evolve = _card_fill_display(fill_stage)
    puzzle_bonus = card_puzzle_finish_bonus(fill_stage)
    for field in ("atk", "def_", "hp", "ability"):
        st[field] += puzzle_bonus[field]
    _apply_card_fruit_bonus(st, uin, uid, cid)
    _apply_card_gene_bonus(st, uin, uid, cid, level)
    _apply_card_equipment_bonus(st, uin, uid)
    _apply_card_baptize_bonus(st, uin, uid)
    _apply_prestige_bonus(st, uin, uid, cid)
    _apply_armor_bonus(st, uin, uid, cid)
    avatar_player = store.get_or_create_player(uin)[0]
    _apply_card_avatar_bonus(st, avatar_player, uid, card)
    prestige_level = store.get_card_evolve_level(uin, uid)
    selected_armor = store.get_card_armor_type(uin, uid)
    selected_star = store.get_card_armors(uin, uid).get(selected_armor, {}).get("star", 0)
    info = build_card_full_info(
        uid, cid, level, st, card_exp_within_level(total_exp, level),
        forge_level, fill_quality, fill_evolve, prestige_level, selected_armor, selected_star,
        _card_avatar_selected(avatar_player, uid, card), _card_gene_active_stage(uin, uid),
        power_elements=_card_power_source_elements(avatar_player, uid, cid, level))
    body = pb_tag(1, 2) + uvarint(len(info)) + info + pb_varint_field(4, action_from)  # changeCardList, actionFrom
    return ("PVZ.Cmd.Cmd_Card_SyncFullInfo_SC", body)


def td_plant_to_card(plant_id):
    """(cardId, stats) for a TD plantId's base battle card, or (None, None) if unmapped."""
    load_battle_cards()
    cid = _TD_TO_CARD.get(int(plant_id))
    return (cid, _BATTLE_CARDS[cid]) if cid else (None, None)


_VALID_TD_PLANTS = None


def valid_td_plants():
    """The set of plantIds that are actually TOWER-DEFENSE plants (clientDB tdPlantInfo.txt) — i.e. can
    be planted on the TD lawn. Adventure/card-only plants are NOT in here. Used to keep the TD roster
    (player['plants']) clean: TD plants may be recruited as adventure cards, but drawing/recruiting an
    adventure card must NOT add a plant to TD (and a non-TD plant in unlockPlantList crashes the TD
    choose-card screen — TDBasicChooseCard.InitializeComponent #1009s with no valid plant template)."""
    global _VALID_TD_PLANTS
    if _VALID_TD_PLANTS is None:
        _VALID_TD_PLANTS = set()
        rows = _read_clientdb_table("tdPlantInfo.txt")
        if rows:
            hdr = rows[0]; idc = hdr.index("id") if "id" in hdr else 0
            for r in rows[1:]:
                if idc < len(r) and r[idc].isdigit():
                    _VALID_TD_PLANTS.add(int(r[idc]))
        log.info("loaded %d valid TD plants", len(_VALID_TD_PLANTS))
    return _VALID_TD_PLANTS


def rebuild_td_roster(player):
    """Rebuild the TD plant roster from what the player LEGITIMATELY earned in tower defense: the starter
    plants plus each cleared TD level's bonusPlant. Everything else is dropped — a drawn/recruited CARD is
    adventure-only and must NOT become a TD plant (that's how adventure plants leaked into the TD chooser).
    Persists the change (removes leaked, restores any missing earned plant); the drawn CARDS stay in the
    collection (cards table) for adventure. Returns the removed plant ids. Idempotent."""
    uin = player["uin"]
    legit = set(store.STARTER_PLANTS)
    for stg, lvl, sub in store.get_all_passed_levels(uin):
        bp = level_reward(stg, lvl, sub).get("bonusPlant") or 0
        if bp:
            legit.add(bp)
    # VIP3's exclusive plant (Winter Melon, priv 41) is a legitimate TD plant — grant + keep it (so it's
    # owned for getUnlockPlant + usable in TD). It's dropped again automatically if VIP is turned off.
    if _VIP_PLANT_PRIV in vip_privileges(player):
        legit.add(_VIP_PLANT)
    current = set(player.get("plants", []))
    removed = sorted(current - legit)
    for p in removed:
        store.remove_plant(uin, p)
    for p in sorted(legit - current):        # restore any earned plant that's missing (e.g. a starter)
        store.unlock_plant(uin, p)
    player["plants"] = sorted(legit)
    return removed


def card_power(stats):
    """Return the battle-power value used by card/formation/battle DTOs.

    The old local implementation only included attack, defence and one tenth of
    HP.  That made skill power, hit, dodge, critical and toughness invisible to
    the displayed power even though the client received those attributes.  The
    original client keeps the four combat-rate attributes on the same (large)
    integer scale as the primary stats, so they are converted through the small
    secondary-stat divisor instead of being added one-for-one.  Keeping the
    conversion integer based also matches the old HUD rounding behaviour.
    """
    primary = (
        int(stats.get("atk", 0))
        + int(stats.get("def_", 0))
        + int(stats.get("hp", 0)) // 10
    )
    secondary = sum(
        int(stats.get(field, 0))
        for field in ("ability", "hit", "dodge", "critical", "tough")
    ) // 1000
    return max(0, primary + secondary)


def _dto_card_power_element(element, value, speed=None):
    """Encode one Dto_CardPower entry; ``speed=None`` keeps the optional field absent."""
    body = pb_varint_field(1, int(element)) + pb_int64_field(2, max(0, int(value or 0)))
    if speed is not None:
        body += pb_int64_field(3, max(0, int(speed or 0)))
    return body


def _power_element_fields(elements, field_number):
    """Serialize a list of (element, power, optional speed) as repeated Dto_CardPower fields."""
    out = b""
    for element, value, speed in elements or ():
        body = _dto_card_power_element(element, value, speed)
        out += pb_tag(field_number, 2) + uvarint(len(body)) + body
    return out


def _card_power_source_elements(player, uid, card_id, level, include_deployed=False,
                                _growth=None, _cards_by_uid=None, _shared=None):
    """Return accurate Dto_CardPower breakdowns for the progression sources this server models.

    Each source value is measured as the change in the same card_power() calculation used for the
    card's total, so the source rows add back to the reported total despite integer rounding. Sources
    with no implemented contribution are omitted rather than presented as guessed values.
    ``_growth``/``_cards_by_uid`` let the card-package loop share one armor-growth computation and
    one collection lookup across the whole roster instead of re-querying per card.
    """
    uin = int(player["uin"])
    uid, card_id, level = int(uid), int(card_id), int(level)
    stats = dict(card_stats_at_level(card_id, level))
    for row in load_card_forge().get(card_id, []):
        if row["level"] <= store.get_card_forge_level(uin, uid):
            for field in ("atk", "def_", "hp", "ability"):
                stats[field] = stats.get(field, 0) + row[field]

    sources = {1: card_power(stats)}  # nature/base includes level, rarity and forge progression

    def apply_source(element, apply):
        before = card_power(stats)
        apply()
        sources[element] = sources.get(element, 0) + card_power(stats) - before

    fill_stage = store.get_card_fill_quality(uin, uid)
    apply_source(17, lambda: stats.update({
        field: stats.get(field, 0) + card_puzzle_finish_bonus(fill_stage).get(field, 0)
        for field in ("atk", "def_", "hp", "ability")
    }))
    apply_source(16, lambda: _apply_card_fruit_bonus(stats, uin, uid, card_id))
    apply_source(19, lambda: _apply_card_gene_bonus(stats, uin, uid, card_id, level))
    apply_source(2, lambda: _apply_card_equipment_bonus(stats, uin, uid))
    apply_source(14, lambda: _apply_card_baptize_bonus(stats, uin, uid))
    refine_combat_delta = sources.get(14, 0)
    # The original CardItemVO reads ele=14 as BaptizeAttribute.power, in the
    # refine panel's raw power units (and its speed field as baptize_speed).
    # Keep that established DTO meaning when it fits inside the reported total;
    # if the local combat-power scale is smaller, fall back to the measured
    # combat-stat delta below rather than emitting a negative base component.
    refine_state = store.get_card_baptize(uin, uid)
    sources[14] = baptize_power(refine_state)
    apply_source(22, lambda: _apply_prestige_bonus(stats, uin, uid, card_id))
    apply_source(21, lambda: _apply_armor_bonus(
        stats, uin, uid, card_id, int(player.get("level", 1)), growth=_growth))
    card = (_cards_by_uid or {}).get(uid)
    if card is None:
        card = next((row for row in store.get_cards(uin) if int(row[0]) == uid),
                    (uid, card_id, level, 0))
    apply_source(18, lambda: _apply_card_avatar_bonus(stats, player, uid, card,
                                                      _shared=_shared))

    if include_deployed:
        # These are independent sources in ConstGlobal.PROP_SHOW_ORDER and are applied to every
        # deployed plant by effective_card_stats(). Keep them separate for the hover breakdown.
        for element, get_bonus in ((4, lab_stat_bonus), (5, nutrition_stat_bonus),
                                   (6, vip_stat_bonus), (7, wt_stat_bonus)):
            bonus = get_bonus(player)
            def add_bonus(b=bonus):
                for field, value in b.items():
                    stats[field] = stats.get(field, 0) + value
            apply_source(element, add_bonus)

    total = card_power(stats)
    # Keep source rows additive. The raw refine score can be on a larger scale
    # than this server's combat stat conversion, so use its measured stat delta
    # only when the exact value would make the base row negative.
    other_sum = sum(value for element, value in sources.items() if element not in (0, 1))
    if other_sum > total:
        sources[14] = max(0, int(refine_combat_delta))
        other_sum = sum(value for element, value in sources.items() if element not in (0, 1))
    sources[1] = max(0, total - other_sum)
    speed = baptize_speed(refine_state)
    result = [(0, total, speed)]
    for element, value in sources.items():
        if int(value) != 0 or (element == 14 and speed > 0):
            result.append((int(element), int(value), speed if element == 14 else None))
    return result


# A real owned card needs uid > 10000 — the client's checkIsRealCard() is `uid.toNumber() > 10000`;
# a smaller uid is treated as a not-owned "template" card, so getBattleCardFullInfo() returns null and
# the lineup crashes. We derive a stable, unique uid from the cardId with this offset.
_CARD_UID_BASE = 10_000_000


def _friend_help_uid(role_id, card_id):
    """Return a stable, non-player UID for a friend's borrowed card.

    Adventure stores the UID from ``Dto_FriendInfo.helpPlant.base.uid`` in its
    formation.  Using the role id alone (the old implementation) made the
    client unable to resolve that UID back to a card and it subsequently built
    a ``CardItemVO`` with cardId=0.  Keep the UID deterministic so the friend
    list and the formation response always agree, while keeping it distinct
    from the player's normal ``_CARD_UID_BASE + cardId`` collection UIDs.
    """
    role_id = max(0, int(role_id or 0))
    card_id = max(1, int(card_id or 1))
    return role_id * 1_000_000 + card_id


def ensure_player_cards(player):
    """Give the player a battle card for every TD plant they own (one per plant type, level 1). This is
    the card COLLECTION the player's house shows and that formations reference by uid. uid = base+cardId
    (>10000 so the client counts it as a REAL owned card). Idempotent by card_id; auto-migrates old rows
    that used uid==cardId (<=10000)."""
    uin = player["uin"]
    # Older local awakening code erased forge despite every next awakening requiring +5.
    load_battle_cards()
    for old_uid, old_cid, _, _ in store.get_cards(uin):
        if _card_awake_level(old_cid) > 0 and not load_card_forge().get(old_cid):
            if store.get_card_forge_level(uin, old_uid) < 5:
                store.set_card_forge_level(uin, old_uid, 5)
    load_battle_cards()
    existing = store.get_cards(uin)
    # migrate: any card on the old scheme (uid <= 10000) -> wipe collection + formation and regenerate.
    if any(uid <= 10000 for uid, _cid, _lvl, _exp in existing):
        store.clear_cards_and_formation(uin)
        existing = []
        log.info("    migrated uin=%d card uids to real (>10000) scheme (wiped + regen)", uin)
    have = {cid for _uid, cid, _lvl, _exp in existing}
    # Same-species cards are legitimate separate instances (recruitment, awakening,
    # and Plant Test requirements). Never erase them merely because tdId matches.
    # tdIds already covered by an owned card (e.g. a RECRUITED star-up card, cardId != the star-1 base):
    # don't also auto-grant the base card for that plant, or the plant would appear twice.
    have_td = {_BATTLE_CARDS[cid]["tdId"] for _uid, cid, _lvl, _exp in existing
               if _BATTLE_CARDS.get(cid) and _BATTLE_CARDS[cid].get("tdId")}
    # Awakened variants still cover the owned base TD plant: do not grant a new
    # star-1 copy at every login after awakening changes the variant's tdId.
    have_td.update(_card_avatar_plant_id(row) for row in existing)
    granted = 0
    for pid in player.get("plants", []):
        if int(pid) in have_td:
            continue
        cid, _st = td_plant_to_card(pid)
        if cid and cid not in have and store.add_card(uin, _CARD_UID_BASE + cid, cid, 1):
            have.add(cid)
            have_td.add(int(pid))
            granted += 1
    if granted:
        log.info("    granted %d new battle card(s) from owned plants (uin=%d)", granted, uin)
    return granted


def _card_gene_active_stage(uin, uid):
    """Dto_CardBaseInfo.geneId is the highest activated DNA stage, not its factor level."""
    return max((int(stage) for stage, gene in store.get_card_genes(uin, uid).items()
                if int(gene.get("level") or 0) > 0), default=0)


def build_card_full_info(uid, card_id, level, stats, exp=0, forge_level=0,
                         card_quality=None, card_rank=0, evolve_level=0,
                         armor_type=0, armor_star=0, avatar_id=0, gene_id=0,
                         power_elements=None):
    """Dto_CardFullInfo{base(1)=Dto_CardBaseInfo, power(2), attack(3), defense(4), hp(5,U64),
    shield(6,U64), ability(7)}. Dto_CardBaseInfo{uid(1,I64), cardId(2), exp(3), level(4),
    forgeLevel(5), currentHp(6,U64), health(7), zombieIslandHp(8), avatarId(9),
    quality(10), rank(11), geneId(13), newZombieIslandHp(14), armorType(15), armorStar(16), evolveLevel(17)}.
    exp = the card's XP WITHIN its current level (bar fill). This is one entry of Cmd_Card_GetPackage_SC.all
    (the collection).

    zombieIslandHp/newZombieIslandHp are the plant's HP inside 勇闯僵尸岛 (normal / adv tab). The island's
    prepare view masks a plant whose island HP is 0, so an omitted (0) value would make EVERY plant look
    dead and the island unfightable — we always report it FULL, i.e. the island never permanently wounds
    the collection (the original game charged items to heal plants between waves)."""
    quality = int(card_quality if card_quality is not None else stats.get("quality", 1))
    stage = card_puzzle_stage_for_display(quality, card_rank)
    # Keep the base DTO's wire layout aligned with the decompiled client.  In
    # particular, avatarId is field 9; field 7 is the health percentage.  A
    # previous wardrobe patch put the avatar in field 7, which made otherwise
    # valid cards look malformed to lineup/formation views.
    hp = max(1, int(stats.get("hp", 0) or 1))
    base = (pb_int64_field(1, uid) + pb_varint_field(2, card_id) + pb_varint_field(3, exp)
            + pb_varint_field(4, level) + pb_varint_field(5, int(forge_level))
            + pb_int64_field(6, hp)                    # currentHp
            + pb_varint_field(7, 100)                   # health percentage
            + pb_varint_field(8, hp)                    # zombieIslandHp
            + pb_varint_field(9, int(avatar_id))        # selected costume
            + pb_varint_field(10, quality)
            + pb_varint_field(11, int(card_rank))
            + pb_varint_field(13, max(0, int(gene_id)))
            + pb_varint_field(14, stats.get("hp", 0))    # newZombieIslandHp (adv island tab)
            + pb_varint_field(15, int(armor_type))
            + pb_varint_field(16, int(armor_star))
            + pb_varint_field(17, int(evolve_level)))
    fill_power = (pb_varint_field(1, 17) + pb_int64_field(2, _card_fill_power(stage))
                  + pb_int64_field(3, 0))
    fill_power_field = pb_tag(13, 2) + uvarint(len(fill_power)) + fill_power
    refine_power = int(stats.get("refine_power", 0) or 0)
    refine_speed = int(stats.get("refine_speed", 0) or 0)
    refine_power_field = b""
    if refine_power or refine_speed:
        refine = (pb_varint_field(1, 14) + pb_int64_field(2, refine_power)
                  + pb_int64_field(3, refine_speed))
        refine_power_field = pb_tag(13, 2) + uvarint(len(refine)) + refine
    power_fields = (_power_element_fields(power_elements, 13) if power_elements is not None
                    else fill_power_field + refine_power_field)
    return (pb_tag(1, 2) + uvarint(len(base)) + base
            + pb_varint_field(2, card_power(stats))         # power
            + pb_varint_field(3, stats.get("atk", 0))       # attack
            + pb_varint_field(4, stats.get("def_", 0))      # defense
            + pb_varint_field(5, stats.get("hp", 0))        # hp (U64)
            + pb_varint_field(6, max(0, int(stats.get("shield", 0) or 0)))   # shield (U64, 蓝盾池)
            + power_fields
            + pb_varint_field(7, stats.get("ability", 0))   # ability
            + pb_float_field(8, stats.get("hit", 0))
            + pb_float_field(9, stats.get("dodge", 0))
            + pb_float_field(10, stats.get("critical", 0))
            + pb_float_field(11, stats.get("tough", 0)))


def handle_card_getpackage(cmd_data, player):
    """Cmd_Card_GetPackage_CS -> Cmd_Card_GetPackage_SC{all(1)=[Dto_CardFullInfo], leaderAddParam(2)}.
    The player's whole battle-card COLLECTION — loaded into battleCardModel at login
    (setBattleCardList). Without it the player owns no cards, so the house/lineup/formation are empty
    and anything that renders the team null-derefs. We build one card per owned plant (ensure_player_cards)."""
    ensure_player_cards(player)
    if not int(player.get("armor_prestige_granted", 0)):
        # The original reward sources are among the missing online-only systems.  A one-time,
        # deliberately finite stash makes both restored panels usable without turning them into GM mode.
        for item_id, amount in ((43, 5000), (98904, 200), (98901, 100), (98902, 100),
                                (98903, 100), (98001, 12), (98011, 12), (98021, 12), (98031, 12)):
            store.add_item(player["uin"], item_id, amount)
        player["armor_prestige_granted"] = 1
        player["prestige"] = store.get_item_count(player["uin"], 43)
        store.save_player(player["uin"], armor_prestige_granted=1, prestige=player["prestige"])
        log.info("    granted one-time armour/prestige starter materials (uin=%d)", player["uin"])
    if not int(player.get("plant_coin_granted", 0)):
        # 神奇兑换 (ExchangeStore 5) is fed by 碎片回收: a one-time, finite stash of both currencies makes
        # that window — and the 碎片 the player already owns — usable without turning the economy into GM
        # mode. Anything bought/spent afterwards is earned by recycling 碎片.
        for item_id, amount in ((_PLANT_COIN_ITEM, 5000), (_MYSTERY_COIN_ITEM, 500)):
            store.add_item(player["uin"], item_id, amount)
        player["plant_coin_granted"] = 1
        store.save_player(player["uin"], plant_coin_granted=1)
        log.info("    granted one-time 植物币/神奇植物币 starter stash (uin=%d)", player["uin"])
    load_battle_cards()
    cards = store.get_cards(player["uin"])
    # Roster-wide shared state: armor growth depends only on (uin, role level), and the
    # power-source breakdown needs the collection by uid — compute BOTH once, not per card.
    role_level = int(player.get("level", 1))
    armor_growth = _armor_growth(player["uin"], role_level)
    cards_by_uid = {int(row[0]): row for row in cards}
    # Per-card DB state reused by the avatar-status checks (they were re-querying the
    # store once per COSTUME — ~34 extra queries per card at 118 cards).
    shared = {"avatars": {}, "fill": {}}
    d = b""
    for uid, card_id, level, _exp in cards:
        if card_id not in _BATTLE_CARDS:
            continue
        st = card_stats_at_level(card_id, level)         # stats at the card's stored LEVEL
        forge_level = store.get_card_forge_level(player["uin"], uid)
        for row in load_card_forge().get(card_id, []):
            if row["level"] <= forge_level:
                for field in ("atk", "def_", "hp", "ability"):
                    st[field] += row[field]
        fill_stage = store.get_card_fill_quality(player["uin"], uid)
        shared["fill"][uid] = fill_stage
        shared["avatars"][uid] = store.get_card_avatars(player["uin"], uid)
        fill_quality, fill_evolve = _card_fill_display(fill_stage)
        puzzle_bonus = card_puzzle_finish_bonus(fill_stage)
        for field in ("atk", "def_", "hp", "ability"):
            st[field] += puzzle_bonus[field]
        _apply_card_fruit_bonus(st, player["uin"], uid, card_id)
        _apply_card_gene_bonus(st, player["uin"], uid, card_id, level)
        _apply_card_equipment_bonus(st, player["uin"], uid)
        _apply_card_baptize_bonus(st, player["uin"], uid)
        _apply_prestige_bonus(st, player["uin"], uid, card_id)
        _apply_armor_bonus(st, player["uin"], uid, card_id, role_level, growth=armor_growth)
        card_row = (uid, card_id, level, _exp)
        _apply_card_avatar_bonus(st, player, uid, card_row, _shared=shared)
        prestige_level = store.get_card_evolve_level(player["uin"], uid)
        selected_armor = store.get_card_armor_type(player["uin"], uid)
        selected_star = store.get_card_armors(player["uin"], uid).get(selected_armor, {}).get("star", 0)
        info = build_card_full_info(
            uid, card_id, level, st,
            forge_level=forge_level,
            card_quality=fill_quality, card_rank=fill_evolve, evolve_level=prestige_level,
            armor_type=selected_armor, armor_star=selected_star,
            avatar_id=_card_avatar_selected(player, uid, card_row, _shared=shared),
            gene_id=_card_gene_active_stage(player["uin"], uid),
            power_elements=_card_power_source_elements(
                player, uid, card_id, level,
                _growth=armor_growth, _cards_by_uid=cards_by_uid, _shared=shared))
        d += pb_tag(1, 2) + uvarint(len(info)) + info        # all (field 1, repeated Dto_CardFullInfo)
    d += pb_varint_field(2, 0)                               # leaderAddParam
    log.info("    card package: %d card(s) in collection %s", len(cards),
             [(c[1], _BATTLE_CARDS.get(c[1], {}).get("name", "?")) for c in cards])
    return d


# --- card recruiting (spend plant fragments to unlock a plant — the 酒吧/Bar) -----------
# The plant-specific fragments (碎片-<plant>, item ids 51xxx) are spent at the Bar to "recruit"
# (招募) that plant's battle card. RecruitCardInfoTemplate maps recruitCardId -> costItemID + count.
# WARNING: the template's `consumeReputation` column is misnamed — it is really the piece COUNT
# (the recruit UI shows have/consumeReputation of costItemID and enables recruit when have>=it).
_RECRUIT_RECIPES = None


def load_recruit_recipes():
    """{recruitCardId: (costItemId, count)} for every recruit row that costs fragments."""
    global _RECRUIT_RECIPES
    if _RECRUIT_RECIPES is None:
        _RECRUIT_RECIPES = {}
        rows = _read_clientdb_table("RecruitCardInfoTemplate.txt")
        if rows:
            hdr = rows[0]; ci = {c: i for i, c in enumerate(hdr)}

            def col(c, k, d="0"):
                i = ci.get(k)
                return c[i] if i is not None and i < len(c) else d
            for c in rows[1:]:
                try:
                    cid = int(col(c, "id"))
                    item = int(col(c, "costItemID") or 0)
                    cnt = int(col(c, "consumeReputation") or 0)   # really the fragment count
                except ValueError:
                    continue
                if cid and item and cnt:
                    _RECRUIT_RECIPES[cid] = (item, cnt)
        log.info("loaded %d card recruit recipes", len(_RECRUIT_RECIPES))
    return _RECRUIT_RECIPES


def handle_card_recruit(cmd_data, player):
    """Cmd_Card_Recruit_CS{cardId} -> spend the plant's fragments to recruit that plant card into the
    collection (this is how you unlock/craft a new plant). Recipe: costItemID x count. On success we
    deduct the fragments, add the battle card (uid=base+cardId), unlock its TD plant, and push
    Cmd_Card_SyncFullInfo_SC{addCardList, actionFrom=CardRecruit(26)} (client shows the success popup +
    CARD_ADDED) plus item/plant syncs. Rejects (no-op) if the recipe/card is unknown, the card is
    already owned, or the player lacks enough fragments."""
    load_battle_cards()
    f = parse_varint_fields(cmd_data)
    card_id = f.get(1, 0)
    uin = player["uin"]
    recipe = load_recruit_recipes().get(card_id)
    stats = _BATTLE_CARDS.get(card_id)
    if not recipe or not stats:
        log.info("    recruit REJECTED: cardId=%d has no recipe/stats", card_id)
        return []
    item_id, need = recipe
    new_star = stats.get("star", 1)
    td = stats.get("tdId") or 0
    # Does the player already own a card for this PLANT (any star)? A plant's fragment recipe can be a
    # higher star than the star-1 base they start with (e.g. sunflower's recipe is the ★2 card), so
    # recruiting = "acquire OR star-up in place" — never a duplicate second card for the same plant.
    owned = None  # (uid, cardId, star, level)
    for uid_, cid_, lvl_, _exp in store.get_cards(uin):
        st_ = _BATTLE_CARDS.get(cid_)
        if st_ and st_.get("tdId") == td:
            owned = (uid_, cid_, st_.get("star", 1), lvl_)
            break
    if owned and owned[2] >= new_star:
        log.info("    recruit REJECTED: already own %s at star %d (>= recruit star %d)",
                 stats.get("name", "?"), owned[2], new_star)
        return []
    have = store.get_item_count(uin, item_id)
    if have < need:
        log.info("    recruit REJECTED: %s needs %dx item %d, have %d",
                 stats.get("name", "?"), need, item_id, have)
        return []
    # Success: spend the fragments, then either star-up the existing card in place or add a new one.
    messages = []
    item_upd = grant_items(player, [(item_id, -need)])
    if owned:
        uid, level = owned[0], owned[3]
        store.upgrade_card(uin, uid, card_id)             # keep uid (formation stays valid), bump star
        dto = build_card_full_info(uid, card_id, level, stats)
        sync = pb_tag(1, 2) + uvarint(len(dto)) + dto     # changeCardList (field 1) -> CARD_PROP_UPDATED
        action = "STAR-UP %s ->star %d" % (stats.get("name", "?"), new_star)
    else:
        uid = _CARD_UID_BASE + card_id
        store.add_card(uin, uid, card_id, 1)
        dto = build_card_full_info(uid, card_id, 1, stats)
        sync = pb_tag(2, 2) + uvarint(len(dto)) + dto     # addCardList (field 2) -> CARD_ADDED + popup
        action = "RECRUITED %s (star %d)" % (stats.get("name", "?"), new_star)
    sync += pb_varint_field(4, 26)                        # actionFrom = ActionFrom_CardRecruit
    messages.append(("PVZ.Cmd.Cmd_Card_SyncFullInfo_SC", sync))
    # NOTE: recruiting an adventure CARD does NOT unlock the TD plant. TD plants -> adventure cards
    # (ensure_player_cards) is one-way; cards must not leak back into the TD roster (player['plants']).
    if item_upd:
        messages.append(item_upd)
    log.info("    %s uin=%d: -%dx item %d (had %d), uid=%d (card-only, no TD unlock)",
             action, uin, need, item_id, have, uid)
    messages += _quest_observe_card_progress(player)
    return messages


# --- card-pack gacha (the 酒吧 draw shop = ModuleBattleCardMarket, Building_Bar) ----------
# 3 packs (BattleCardMarketConst): 1=OnePacket (single), 2=TenPacket (x10), 3=FriendPoint. Costs from
# BattleCardMarketSetting.txt costStr "item:amt": g1 240 diamond / 1 draw-ticket(2025), g2 2160 / 10
# tickets, g3 500 friend points. Draws roll star-1 PLANT base cards (tdId>=1000, cardId=tdId+star) and
# EVERY roll goes into the collection — a plant you already own simply gets a second copy (see
# _add_drawn_card), which is what the reveal animation implies. Group 1 is a free single draw in our
# sandbox; a one-time 10 draw-ticket stash lets you try the ten-draw too.
_CARD_MARKET_POOL = None
_CARD_MARKET_COST = None
_CARD_MARKET_COUNT = {1: 1, 2: 10, 3: 5}        # cards per draw (must match the reveal's card slots:
                                                # OnePacket 1, TenPacket 5x2 rounds, FriendPoint 5)
_DRAW_TICKET_ITEM = 2025
_FRIEND_POINT_ITEM = 6
_CARD_MARKET_STARTER_TICKETS = 10               # one ten-draw's worth, granted once


def card_market_pool():
    """The draw pool as [(bagItemId, cardId)]. The gacha reveal renders BAG ITEMS (CardItemFactory.
    updateCardItemByBagItemId), so we must draw a card BAG-ITEM id (ItemInfo type=4 TYPE_CARD, id 2xxxx,
    with cardItemId='<cardId>:count'), not a raw battle cardId. Each maps to a plant battle card that we
    then add to the collection. ~121 plant card items exist (various stars)."""
    global _CARD_MARKET_POOL
    if _CARD_MARKET_POOL is None:
        load_battle_cards()
        _CARD_MARKET_POOL = []
        rows = _read_clientdb_table("ItemInfo.txt")
        if rows:
            hdr = rows[0]; ci = {c: i for i, c in enumerate(hdr)}
            for c in rows[1:]:
                try:
                    bid, typ, cit = int(c[ci["id"]]), int(c[ci["type"]]), c[ci["cardItemId"]]
                except (ValueError, KeyError, IndexError):
                    continue
                if typ != 4 or not cit or ":" not in str(cit):     # 4 = ItemType.TYPE_CARD
                    continue
                try:
                    card_id = int(str(cit).split(":")[0])
                except ValueError:
                    continue
                if card_id in _BATTLE_CARDS and (_BATTLE_CARDS[card_id].get("tdId") or 0) >= 1000:
                    _CARD_MARKET_POOL.append((bid, card_id))
    return _CARD_MARKET_POOL


def load_card_market_cost():
    """{groupId: {'pay':(itemId,amt), 'ticket':(itemId,amt)|None}} from BattleCardMarketSetting.txt."""
    global _CARD_MARKET_COST
    if _CARD_MARKET_COST is None:
        _CARD_MARKET_COST = {}
        rows = _read_clientdb_table("BattleCardMarketSetting.txt")
        if rows:
            hdr = rows[0]; ci = {c: i for i, c in enumerate(hdr)}

            def pair(sv):
                try:
                    a, b = sv.split(":"); return (int(a), int(b))
                except (ValueError, AttributeError):
                    return None
            for c in rows[1:]:
                try:
                    gid = int(c[ci["id"]])
                except (ValueError, KeyError, IndexError):
                    continue
                nc = ci.get("needCardNum")
                _CARD_MARKET_COST[gid] = {"pay": pair(c[ci["costStr"]]),
                                          "ticket": pair(c[nc]) if nc is not None and nc < len(c) else None}
    return _CARD_MARKET_COST


def _wrap_repeated(field, dtos):
    """Concatenate a list of message bodies as a repeated length-delimited field."""
    return b"".join(pb_tag(field, 2) + uvarint(len(d)) + d for d in dtos)


# groupId -> (freeTimes, freeCD). isFree = freeTimes!=0 && freeCD==0. Group 1 = a free single draw.
_CARD_MARKET_FREE = {1: (1, 0), 2: (0, 0), 3: (0, 0)}


def _card_market_freeinfo_dto(gid):
    """One Dto_Card_MarketFreeInfo{groupId(1), freeTimes(2), freeCD(3)}."""
    ft, cd = _CARD_MARKET_FREE.get(gid, (0, 0))
    return pb_varint_field(1, gid) + pb_varint_field(2, ft) + pb_varint_field(3, cd)


def _card_market_freeinfo_dtos():
    """All 3 packs' free-info DTOs (Cmd_Card_GetMarketInfo_SC.freeInfos is REPEATED)."""
    return [_card_market_freeinfo_dto(gid) for gid in (1, 2, 3)]


def handle_card_getmarketinfo(cmd_data, player):
    """Cmd_Card_GetMarketInfo_CS -> Cmd_Card_GetMarketInfo_SC{freeInfos(1), luckyFlowerNum(2),
    group1ExtractNum(5)}. Renders the 3 packs (so clicking one has non-null data). Also hands out a
    one-time stash of draw tickets so the ten-draw is testable."""
    uin = player["uin"]
    extra = []
    if not int(player.get("card_market_granted") or 0):
        upd = grant_items(player, [(_DRAW_TICKET_ITEM, _CARD_MARKET_STARTER_TICKETS)])
        player["card_market_granted"] = 1
        store.save_player(uin, card_market_granted=1)
        if upd:
            extra.append(upd)
        log.info("    card market: granted %d starter draw tickets to uin=%d", _CARD_MARKET_STARTER_TICKETS, uin)
    body = (_wrap_repeated(1, _card_market_freeinfo_dtos())
            + pb_varint_field(2, 0)                          # luckyFlowerNum
            + pb_varint_field(5, 0))                         # group1ExtractNum
    return [("PVZ.Cmd.Cmd_Card_GetMarketInfo_SC", body)] + extra


def _card_market_pay(player, gid):
    """Deduct a pack's cost (ticket-first then diamonds for g1/g2; friend points for g3). Returns the
    HUD sync messages, or None if unaffordable. Group 1 is free (empty list)."""
    if gid == 1:
        return []                                            # free single draw
    cost = load_card_market_cost().get(gid, {})
    uin = player["uin"]
    if gid == 2:
        ticket, pay = cost.get("ticket"), cost.get("pay")
        if ticket and store.get_item_count(uin, ticket[0]) >= ticket[1]:
            upd = grant_items(player, [(ticket[0], -ticket[1])])
            return [upd] if upd else []
        if pay and pay[0] == 4:                              # 4 = diamond
            return _spend_diamonds(player, pay[1])
        return None
    if gid == 3:                                             # friend points
        pay = cost.get("pay")
        if pay and pay[0] == _FRIEND_POINT_ITEM and int(player.get("friend_point") or 0) >= pay[1]:
            player["friend_point"] = int(player.get("friend_point") or 0) - pay[1]
            store.save_player(uin, friend_point=player["friend_point"])
            return [("PVZ.Cmd.Cmd_SyncFriendPoint_SC", pb_varint_field(1, player["friend_point"]))]
        return None
    return None


def _card_free_uid(uin, card_id, taken):
    """A free uid for a NEW copy of `card_id`: _CARD_UID_BASE + cardId, bumped while it is taken.

    CARD DUPLICATES ARE SUPPORTED on purpose: the client's 卡牌库 keys its list by uid, and a pull that
    owns the plant already must still hand over a second (third, …) copy instead of coins — see
    _add_drawn_card. `taken` is the caller's live set of every owned uid (mutated in place)."""
    uid = _CARD_UID_BASE + int(card_id)
    while uid in taken:
        uid += 1
    taken.add(uid)
    return uid


def _add_drawn_card(player, card_id, taken=None):
    """Add ONE drawn plant card to the collection and return (uid, Dto_CardFullInfo bytes).

    EVERY pull lands in the 卡牌库 — duplicates included (the 酒吧/神秘卡包 gacha used to pay coins for a
    plant the player already owned, so the reveal showed a card that then "disappeared"). A drawn card is
    adventure-only: it does NOT unlock the TD plant (no leak into player['plants'])."""
    uin = player["uin"]
    if taken is None:
        taken = {c[0] for c in store.get_cards(uin)}
    uid = _card_free_uid(uin, card_id, taken)
    store.add_card(uin, uid, card_id, 1)
    return uid, build_card_full_info(uid, card_id, 1, card_stats_at_level(card_id, 1))


def handle_card_extract(cmd_data, player):
    """Cmd_Card_Extract_CS{groupId} -> draw the pack. Charge the cost, roll card BAG-ITEMS and add the
    mapped battle card to the collection (a duplicate plant becomes ANOTHER copy, not coins), then reply
    Cmd_Card_Extract_SC{items(1)=[Dto_IdNum(bagItemId,1)], luckyFlowerNum(2), freeInfos(3)=SINGLE,
    group1ExtractNum(5)} + Cmd_Card_SyncFullInfo_SC{addCardList, actionFrom=CardExtract(25)} +
    currency/plant syncs.

    The 酒吧's group-1 result is a plant card.  Item 2003 (经验豆) is a separate bonus granted once per
    card draw; it is sent by the separate Cmd_Item_Update_SC bonus sync and persisted in the bag, not
    placed in Cmd_Card_Extract_SC.items and not used as a replacement card.
    Duplicate plants are stored as additional card copies."""
    gid = parse_varint_fields(cmd_data).get(1, 0)
    if gid not in _CARD_MARKET_COUNT:
        return []
    uin = player["uin"]
    load_battle_cards()
    pay_msgs = _card_market_pay(player, gid)
    if pay_msgs is None:
        log.info("    card extract group %d REJECTED: can't afford", gid)
        return []                                            # client normally blocks this
    pool = card_market_pool()
    items, add_dtos = [], []
    taken = {c[0] for c in store.get_cards(uin)}                 # every uid we already own
    bean_bonus = 0
    for _ in range(_CARD_MARKET_COUNT[gid]):
        bag_id, card_id = random.choice(pool)
        items.append(bag_id)                                     # the reveal renders this BAG-ITEM id
        _uid, dto = _add_drawn_card(player, card_id, taken)      # new plant AND duplicates land here
        add_dtos.append(dto)
        bean_bonus += 1                                           # bonus, separate from the plant card
    free = _card_market_freeinfo_dto(gid)                     # freeInfos(3) is a SINGLE msg here (not repeated)
    extract = (_wrap_repeated(1, [pb_varint_field(1, bid) + pb_varint_field(2, 1) for bid in items])
               + pb_varint_field(2, 0)                       # luckyFlowerNum
               + pb_tag(3, 2) + uvarint(len(free)) + free    # freeInfos (single)
               + pb_varint_field(5, 0))                      # group1ExtractNum
    messages = []
    if add_dtos:                                             # Cmd_Card_SyncFullInfo_SC{addCardList(2), actionFrom(4)}
        sync = _wrap_repeated(2, add_dtos) + pb_varint_field(4, 25)
        messages.append(("PVZ.Cmd.Cmd_Card_SyncFullInfo_SC", sync))
    messages.append(("PVZ.Cmd.Cmd_Card_Extract_SC", extract))
    messages += pay_msgs
    bean_msg = grant_items(player, [(2003, bean_bonus)]) if bean_bonus else None
    if bean_msg:
        messages.append(bean_msg)
    messages += _quest_record_condition(player, 12, 0, 1)
    messages += _quest_observe_card_progress(player)
    log.info("    card extract group %d: %d drawn, %d card(s) added to the collection", gid, len(items),
             len(add_dtos))
    return messages


# --- Mystery Card Pack (神秘卡包, the 卡吧/CardBar = ModuleCardBar, Building_CardBar) ---------
# Five reveals: featured plant OR its fragments, an enticing bean, three material rewards.
# ItemInfo 1091 describes the random-material bundle; it is unpacked, not awarded as a scroll.
# Original screenshots establish counts/cost/pity but not drop rates. The local roll weights below
# are approximations, deliberately separate from the authoritative clientDB plant/item identities.
_MYSTERY_TICKET_ITEM = 1103
_MYSTERY_PRICE = 500
_MYSTERY_REFRESH_COST = 5000                     # retain existing local refresh price (not pictured)
_MYSTERY_LUCK_MAX = 10000
_MYSTERY_LUCK_STEP = 500
_MYSTERY_PLANT_CHANCE = 0.05                     # local estimate, not a recovered official rate
_MYSTERY_MATERIAL_ROLLS = (
    (210, (30, 50)), (211, (10, 15)), (2018, (3,)), (2131, (30,)),
    (1, (150000,)), (2101, (1,)), (2046, (1, 3)), (2020, (1, 3)),
)
_MYSTERY_FEATURES = None


def _draw_card_items(player, count, owned_tds, min_star=1):
    """Roll `count` card BAG-ITEMS from the pack pool (>= min_star) and add EVERY pull to the collection
    (a duplicate plant becomes another copy — see _add_drawn_card). Mutates owned_tds (kept for callers
    that want to know which plant families were already owned). Returns
    (bag_ids, add_dtos, plant_msgs, dupe_coins=0). Shared by the Brewery gacha style + Mystery pack."""
    pool = [(b, c) for b, c in card_market_pool() if _BATTLE_CARDS[c].get("star", 1) >= min_star]
    if not pool:
        pool = card_market_pool()
    uin = player["uin"]
    bag_ids, add_dtos, plant_msgs = [], [], []
    taken = {c[0] for c in store.get_cards(uin)}
    for _ in range(count):
        bag_id, card_id = random.choice(pool)
        td = _BATTLE_CARDS[card_id].get("tdId")
        bag_ids.append(bag_id)
        owned_tds.add(td)
        _uid, dto = _add_drawn_card(player, card_id, taken)
        add_dtos.append(dto)
    return bag_ids, add_dtos, plant_msgs, 0


def _mystery_features():
    """bag item -> (battle template, matching fragment), using the ORIGINAL mystery tip pool.

    Later cards' IDs do not follow the early TD/star arithmetic. Resolve both bag/fragment by their
    ItemInfo names rather than borrowing the brewery pool or assuming 50000 + tdId.
    """
    global _MYSTERY_FEATURES
    if _MYSTERY_FEATURES is None:
        load_battle_cards()
        tips = _read_clientdb_table("mysteryCardTip.txt")
        names = {name.strip() for row in tips[1:] for value in row
                 for name in re.findall(r">([^<>]+)\(3星\)", value)}
        rows = _read_clientdb_table("ItemInfo.txt")
        ci = {name: index for index, name in enumerate(rows[0])}
        fragments = {row[ci["name"]][3:]: int(row[ci["id"]]) for row in rows[1:]
                     if row[ci["name"]].startswith("碎片-")}
        features = {}
        for row in rows[1:]:
            name = row[ci["name"]]
            if not name.endswith("(3星)") or name[:-4] not in names:
                continue
            card_id = int(row[ci["cardItemId"]].split(":")[0] or 0)
            fragment = fragments.get(name[:-4])
            if card_id in _BATTLE_CARDS and fragment:
                features[int(row[ci["id"]])] = (card_id, fragment)
        if not features:
            raise RuntimeError("Mystery pack has no valid clientDB feature/fragment mappings")
        _MYSTERY_FEATURES = features
    return _MYSTERY_FEATURES


def _mystery_gen_weekly(exclude=None):
    return random.choice([item for item in _mystery_features() if item != exclude]
                         or list(_mystery_features()))


def _mystery_gen_dailies(weekly):
    """The board previews a matching fragment, the bonus bean and the random-material scroll."""
    return [_mystery_features()[weekly][1], 2004, 1091]


def _mystery_save_board(player, parts):
    player["mystery_board"] = ",".join(str(x) for x in parts)
    store.save_player(player["uin"], mystery_board=player["mystery_board"])


def _mystery_get_board(player):
    """(weekly, [3 dailies]) — PERSISTED per player so the board is stable across visits; generated +
    saved on first open (only the refresh button rerolls it)."""
    raw = (player.get("mystery_board") or "").strip()
    parts = [int(x) for x in raw.split(",") if x.strip().isdigit()] if raw else []
    features = _mystery_features()
    weekly = parts[0] if parts and parts[0] in features else (
        28303 if 28303 in features else _mystery_gen_weekly())
    expected = [weekly] + _mystery_gen_dailies(weekly)
    if parts != expected:
        parts = expected
        _mystery_save_board(player, parts)
    if not int(player.get("mystery_version") or 0):
        # Preserve the old 0..100 counter's percentage, once; never rescale on later visits.
        luck = max(0, int(player.get("mystery_luck") or 0))
        player["mystery_luck"] = min(_MYSTERY_LUCK_MAX, luck * 100 if luck <= 100 else luck)
        player["mystery_version"] = 1
        store.save_player(player["uin"], mystery_luck=player["mystery_luck"], mystery_version=1)
    return parts[0], parts[1:]


def _mystery_board_dto(weekly, dailies):
    """Dto_MysteryCard{weeklyCard(1)=bagItemId, dailyCard(2, repeated)=[3 bagItemIds],
    refreshNeedItem(3)=Dto_IdNum(coin, cost)}."""
    d = pb_varint_field(1, weekly)
    for x in dailies:
        d += pb_varint_field(2, x)                               # dailyCard (repeated, unpacked)
    refresh = pb_varint_field(1, 1) + pb_varint_field(2, _MYSTERY_REFRESH_COST)   # Dto_IdNum{coin, cost}
    d += pb_tag(3, 2) + uvarint(len(refresh)) + refresh
    return d


def handle_card_getmysterycardinfo(cmd_data, player):
    """Cmd_Card_GetMysteryCardInfo_CS -> Cmd_Card_GetMysteryCardInfo_SC{card(1)=Dto_MysteryCard,
    luckValue(2)}. Opening a board must not create free tickets or award loot."""
    weekly, dailies = _mystery_get_board(player)                 # persisted -> stable across visits
    card = _mystery_board_dto(weekly, dailies)
    body = pb_tag(1, 2) + uvarint(len(card)) + card + pb_varint_field(2, int(player.get("mystery_luck") or 0))
    return [("PVZ.Cmd.Cmd_Card_GetMysteryCardInfo_SC", body)]


def handle_card_buymysterycard(cmd_data, player):
    """One ticket (client buys shop 103 for 500 yellow diamonds) -> exactly FIVE reward cards.
    Currency, inventory, card creation and pity commit together; the reveal uses those same rewards.
    Direct protocol callers without a ticket may also pay 500 yellow diamonds, never sunlight.
    """
    uin = player["uin"]
    weekly, _ = _mystery_get_board(player)
    old_luck = int(player.get("mystery_luck") or 0)
    luck = old_luck + _MYSTERY_LUCK_STEP
    jackpot = luck >= _MYSTERY_LUCK_MAX
    card_id, fragment = _mystery_features()[weekly]
    plant_roll = jackpot or random.random() < _MYSTERY_PLANT_CHANCE
    rewards = [(weekly, 1) if plant_roll else (fragment, random.choice((2, 2, 2, 4))), (2004, 1)]
    for _ in range(3):
        item_id, counts = random.choice(_MYSTERY_MATERIAL_ROLLS)
        rewards.append((item_id, random.choice(counts)))
    new_luck = 0 if plant_roll else luck
    # Construct resource/card DTOs before charging, so a missing template cannot eat the payment.
    uid, dto = None, None
    if plant_roll:
        uid = _card_free_uid(uin, card_id, {c[0] for c in store.get_cards(uin)})
        dto = build_card_full_info(uid, card_id, 1, card_stats_at_level(card_id, 1))
    result = store.purchase_mystery_pack(uin, rewards[1:] if plant_roll else rewards,
                                       (uid, card_id) if plant_roll else None,
                                       old_luck, new_luck, _MYSTERY_TICKET_ITEM, _MYSTERY_PRICE)
    if result is None:
        log.info("    mystery buy REJECTED: insufficient payment or stale pity state")
        return []
    player.update(result["wallet"])
    player["mystery_luck"] = new_luck
    # Do not coalesce repeated item IDs here: two plant-coin rolls still render TWO cards.
    body = (_wrap_repeated(1, [pb_varint_field(1, iid) + pb_varint_field(2, count)
                              for iid, count in rewards]) + pb_varint_field(2, new_luck))
    messages = []
    if dto:
        messages.append(("PVZ.Cmd.Cmd_Card_SyncFullInfo_SC", _wrap_repeated(2, [dto]) + pb_varint_field(4, 25)))
    messages.append(("PVZ.Cmd.Cmd_Card_BuyMysteryCard_SC", body))
    updates = [build_item_dto(iid, count) for iid, count in result["items"].items()]
    if updates:
        messages.append(("PVZ.Cmd.Cmd_Item_Update_SC", _wrap_repeated(1, updates)))
    for field, sc in (("coin", "PVZ.Cmd.Cmd_SyncCoin_SC"), ("ticket", "PVZ.Cmd.Cmd_SyncTicket_SC")):
        if field in result["changed_wallet"]:
            messages.append((sc, pb_varint_field(1, player[field])))
    log.info("    mystery buy: rewards=%s luck=%d%s", rewards, new_luck, " JACKPOT" if jackpot else "")
    return messages


def handle_card_refreshmysterycard(cmd_data, player):
    """Cmd_Card_RefreshMysteryCard_CS -> spend coins to change the featured plant. Reply
    Cmd_Card_RefreshMysteryCard_SC{card(1)=Dto_MysteryCard} + a coin sync."""
    uin = player["uin"]
    if int(player.get("coin") or 0) < _MYSTERY_REFRESH_COST:
        log.info("    mystery refresh REJECTED: need %d coin", _MYSTERY_REFRESH_COST)
        return []                                                # client checks coins first
    previous, _ = _mystery_get_board(player)
    weekly = _mystery_gen_weekly(exclude=previous)
    dailies = _mystery_gen_dailies(weekly)
    coin_msgs = grant_fuben_reward(player, [(1, -_MYSTERY_REFRESH_COST)])
    _mystery_save_board(player, [weekly] + dailies)
    card = _mystery_board_dto(weekly, dailies)
    log.info("    mystery refresh: -%d coin, feature=%d", _MYSTERY_REFRESH_COST, weekly)
    return [("PVZ.Cmd.Cmd_Card_RefreshMysteryCard_SC", pb_tag(1, 2) + uvarint(len(card)) + card)] + coin_msgs


def handle_card_levelup(cmd_data, player):
    """Cmd_Card_LevelUp_CS{cardUId(1,I64), itemBaseId(2)} -> feed ONE exp bean to a card. Consume the
    item, add its plant XP, recompute the card's level (capped by maxLv + account level), and push
    Cmd_Item_Update_SC followed by
    Cmd_Card_SyncFullInfo_SC{changeCardList=[card], actionFrom=CardLevelUp(32)}.
    No-op if the card/item is unknown or the player owns none of the bean."""
    f = parse_varint_fields(cmd_data)
    uid = f.get(1, 0)
    item_id = f.get(2, 0)
    uin = player["uin"]
    gain = card_exp_items().get(item_id, 0)
    card = next((c for c in store.get_cards(uin) if c[0] == uid), None)
    if not card or gain <= 0 or store.get_item_count(uin, item_id) < 1:
        log.info("    card level-up REJECTED: uid=%d item=%d gain=%d owns=%s",
                 uid, item_id, gain, bool(card))
        return []
    card_id = card[1]
    item_upd = grant_items(player, [(item_id, -1)])       # consume 1 bean
    old_lv, new_lv, total, _within = add_card_exp(player, uid, card_id, gain)
    messages = []
    sync = build_card_sync_sc(uin, uid, card_id, 32)      # ActionFrom_CardLevelUp
    # The card sync triggers the bean panel's CARD_PROP_UPDATED redraw. Deliver
    # the inventory change first so its count labels show the just-consumed bean.
    if item_upd:
        messages.append(item_upd)
    if sync:
        messages.append(sync)
    messages += _quest_record_condition(player, 16, 0, 1)
    messages += _quest_observe_card_progress(player)
    log.info("    CARD LEVEL-UP: uid=%d card=%d fed item %d (+%d exp) lvl %d->%d (totalExp=%d)",
             uid, card_id, item_id, gain, old_lv, new_lv, total)
    return messages


def handle_card_fasterlevelup(cmd_data, player):
    """Handle the card-house one-click experience-bean upgrade.

    The client protocol uses ``costItemList`` entries of ``Dto_IdNum``
    (field 1 = item id, field 2 = quantity).  An earlier implementation read
    fields 2/3 as if these were ``Dto_ItemInfo`` entries, so every real client
    request decoded as item 0 / quantity 0 and the button appeared to do
    nothing.  Accept the exact Dto_IdNum wire shape, while retaining a small
    compatibility fallback for old tools that still send Dto_ItemInfo.
    """
    uid = parse_varint_fields(cmd_data).get(1, 0)
    uin = player["uin"]
    card = next((c for c in store.get_cards(uin) if c[0] == uid), None)
    if not card:
        log.info("    card FAST level-up REJECTED: uid=%d not owned", uid)
        return []
    card_id = card[1]
    total_exp, consume = 0, []
    for sub in parse_repeated_submessages(cmd_data, 2):        # costItemList (repeated Dto_ItemInfo)
        it = parse_varint_fields(sub)
        if 3 in it:                                           # legacy Dto_ItemInfo(uid,id,num)
            item_id, num = it.get(2, 0), it.get(3, 0)
        else:                                                  # actual Dto_IdNum(id,num)
            item_id, num = it.get(1, 0), it.get(2, 0)
        per = card_exp_items().get(item_id, 0)
        have = store.get_item_count(uin, item_id)
        use = min(num, have) if (per and num) else 0
        if use > 0:
            total_exp += per * use
            consume.append((item_id, -use))
    if total_exp <= 0:
        log.info("    card FAST level-up REJECTED: uid=%d no usable beans (list=%s)", uid, consume)
        return []
    item_upd = grant_items(player, consume)
    old_lv, new_lv, tot, _within = add_card_exp(player, uid, card_id, total_exp)
    messages = [("PVZ.Cmd.Cmd_Card_FasterLevelUp_SC", pb_int64_field(1, uid))]   # SC echoes cardUId
    sync = build_card_sync_sc(uin, uid, card_id, 20)          # ActionFrom_AddExpLevelUp
    if sync:
        messages.append(sync)
    if item_upd:
        messages.append(item_upd)
    messages += _quest_record_condition(player, 16, 0, 1)
    messages += _quest_observe_card_progress(player)
    log.info("    CARD FAST LEVEL-UP: uid=%d card=%d +%d exp (%s) lvl %d->%d",
             uid, card_id, total_exp, consume, old_lv, new_lv)
    return messages


# --- card enhancement slots / puzzle exchange / star upgrade ----------------------
# Puzzle board dimensions and tier counts come from clientDB cardPuzzle.txt.
_CARD_PUZZLE = None


def load_card_puzzle():
    """Load puzzle completion attributes from the client's cardPuzzle table."""
    global _CARD_PUZZLE
    if _CARD_PUZZLE is None:
        _CARD_PUZZLE = {}
        rows = _read_clientdb_table("cardPuzzle.txt")
        if rows:
            header = {name: index for index, name in enumerate(rows[0])}
            for row in rows[1:]:
                try:
                    puzzle_id = int(row[header["id"]])
                    finish = {}
                    for field, stat in (("1", "atk"), ("2", "def_"),
                                        ("3", "hp"), ("5", "ability")):
                        value = row[header["originalFinishAttribute"]]
                        for item in value.split(";"):
                            kind, amount = item.split(":", 1)
                            if kind == field:
                                # ClientDB card attributes use centi-units.
                                finish[stat] = int(amount) // 100
                                break
                    _CARD_PUZZLE[puzzle_id] = {
                        "quality": int(row[header["quality"]]),
                        "rank": int(row[header["rank"]]),
                        "width": int(row[header["puzzleWidth"]]),
                        "height": int(row[header["puzzleHeight"]]),
                        "finish": finish,
                        # Ordered piece item/count recipes, one entry per board cell.
                        # Purchase, fill and recycle all use this same configuration.
                        "cost": parse_bonus_items(row[header["originalCostItem"]]),
                    }
                except (KeyError, IndexError, ValueError):
                    continue
        log.info("loaded %d card puzzle stages", len(_CARD_PUZZLE))
    return _CARD_PUZZLE


def card_puzzle_finish_bonus(stage):
    """Return cumulative attributes from puzzle boards completed before `stage`."""
    stage = max(1, int(stage))
    bonus = {"atk": 0, "def_": 0, "hp": 0, "ability": 0}
    for puzzle_id in range(1, stage):
        for field, amount in load_card_puzzle().get(puzzle_id, {}).get("finish", {}).items():
            bonus[field] += amount
    return bonus


def card_puzzle_stage_for_display(quality, rank):
    """Map a puzzle quality/rank pair back to its cardPuzzle row id."""
    for stage, puzzle in load_card_puzzle().items():
        if puzzle["quality"] == int(quality) and puzzle["rank"] == int(rank):
            return stage
    return 1


def _card_fill_display(stage):
    """Map internal board stage to (colour quality, +evolve level, material band)."""
    stage = max(1, int(stage))
    puzzle = load_card_puzzle().get(stage)
    if puzzle:
        return puzzle["quality"], puzzle["rank"]
    # Keep a safe fallback if a clientDB is incomplete.
    color = 1 if stage == 1 else 2 + (stage - 2) // 4
    evolve = 0 if color == 1 else (stage - 2) % 4
    return color, evolve


def _card_fill_cell_count(stage):
    """Number of puzzle cells for an internal board stage."""
    stage = max(1, int(stage))
    puzzle = load_card_puzzle().get(stage)
    if puzzle:
        return puzzle["width"] * puzzle["height"]
    color, _evolve = _card_fill_display(stage)
    side = color + 2
    return side * side


def _card_fill_max_index(uin, uid):
    return _card_fill_cell_count(store.get_card_fill_quality(uin, uid)) - 1


def _card_fill_power(stage):
    """Aggregate fill power exposed through Dto_CardPower.ele=fill."""
    stage = max(1, int(stage))
    return _card_fill_cell_count(stage) * (40 + stage * 10)


_CARD_FORGE = None
_CARD_FORGE_CHANCES = None


def load_card_forge_chances():
    """Load forge material success chances keyed by (card star, material item)."""
    global _CARD_FORGE_CHANCES
    if _CARD_FORGE_CHANCES is None:
        _CARD_FORGE_CHANCES = {}
        rows = _read_clientdb_table("CardForgeChance.txt")
        if rows:
            header = {name: index for index, name in enumerate(rows[0])}
            for row in rows[1:]:
                try:
                    key = (int(row[header["forgeCardStarLv"]]),
                           int(row[header["costItemID"]]))
                    _CARD_FORGE_CHANCES[key] = int(row[header["successChance"]])
                except (KeyError, IndexError, ValueError):
                    continue
        log.info("loaded %d card forge chance entries", len(_CARD_FORGE_CHANCES))
    return _CARD_FORGE_CHANCES


def load_card_forge():
    global _CARD_FORGE
    if _CARD_FORGE is None:
        _CARD_FORGE = {}
        for row in _read_clientdb_table("CardForgeTemplate.txt")[1:]:
            try:
                _CARD_FORGE.setdefault(int(row[1]), []).append({
                    "level": int(row[2]), "cost": int(row[3]),
                    "atk": int(row[4]) // 100, "def_": int(row[5]) // 100,
                    "hp": int(row[6]) // 100, "ability": int(row[8]) // 100})
            except (IndexError, TypeError, ValueError):
                continue
        for rows in _CARD_FORGE.values():
            rows.sort(key=lambda value: value["level"])
        log.info("loaded %d card forge templates", sum(map(len, _CARD_FORGE.values())))
    return _CARD_FORGE


def _owned_card(player, uid):
    return next((card for card in store.get_cards(player["uin"]) if card[0] == uid), None)


def _card_piece_item(card_id):
    """pieceDrop.txt uses 51xxx ids: 50000 + the card family's TD plant id."""
    load_battle_cards()
    td_id = (_BATTLE_CARDS.get(card_id) or {}).get("tdId", 0)
    return 50000 + int(td_id) if td_id else 0


def handle_card_getfillinfo(cmd_data, player):
    """Read progress without granting free materials or changing the inventory."""
    uid = parse_varint_fields(cmd_data).get(1, 0)
    if not _owned_card(player, uid):
        return []
    body = pb_int64_field(1, uid)
    for index in store.get_card_filled_indices(player["uin"], uid):
        body += pb_varint_field(2, index)
    return body


def _puzzle_piece_recipe(uin, uid, index):
    stage = store.get_card_fill_quality(uin, uid)
    puzzle = load_card_puzzle().get(stage, {})
    costs = puzzle.get("cost", [])
    if index < 0 or index >= len(costs):
        return None
    item, count = costs[index]
    return (stage, item, count) if item > 0 and count > 0 else None


def handle_card_getplantseedinfo(cmd_data, player):
    uid = parse_varint_fields(cmd_data).get(1, 0)
    card = _owned_card(player, uid)
    if not card:
        return []
    load_battle_cards()
    fruit_type = int((_BATTLE_CARDS.get(card[1]) or {}).get("fruitType", 0))
    if not fruit_type:
        return pb_int64_field(1, uid)
    templates = load_card_fruit_info()
    seeds = b""
    for slot, level in store.get_card_fruits(player["uin"], uid).items():
        if (fruit_type, int(slot), int(level)) not in templates:
            continue
        seed = pb_varint_field(1, int(slot)) + pb_varint_field(2, int(level))
        seeds += pb_tag(2, 2) + uvarint(len(seed)) + seed
    return pb_int64_field(1, uid) + seeds


def handle_card_upgradeplantseed(cmd_data, player):
    """Upgrade one fruit slot using the exact clientDB recipe and persist the new level."""
    fields = parse_varint_fields(cmd_data)
    uid, slot = fields.get(1, 0), fields.get(2, 0)
    card = _owned_card(player, uid)
    if not card:
        log.info("    fruit upgrade rejected: uin=%s unknown card uid=%d", player.get("uin"), uid)
        return []
    load_battle_cards()
    card_info = _BATTLE_CARDS.get(card[1]) or {}
    fruit_type = int(card_info.get("fruitType", 0))
    if not fruit_type or int(card_info.get("type", 0)) != 2:
        log.info("    fruit upgrade rejected: uid=%d is not a fruit-bearing plant", uid)
        return []

    templates = load_card_fruit_info()
    current_level = int(store.get_card_fruits(player["uin"], uid).get(slot, 0))
    next_info = templates.get((fruit_type, int(slot), current_level + 1))
    if not next_info:
        log.info("    fruit upgrade rejected: uid=%d slot=%d at max/invalid level %d",
                 uid, slot, current_level)
        return []
    if int(player.get("level", 1)) < next_info["openLevel"]:
        log.info("    fruit upgrade rejected: uid=%d slot=%d requires role level %d",
                 uid, slot, next_info["openLevel"])
        return []

    costs = parse_bonus_items(next_info["needItems"])
    if not costs or any(store.get_item_count(player["uin"], item_id) < amount
                        for item_id, amount in costs):
        log.info("    fruit upgrade rejected: uid=%d slot=%d insufficient materials %s",
                 uid, slot, costs)
        return []

    store.set_card_fruit_level(player["uin"], uid, slot, current_level + 1)
    seed = pb_varint_field(1, int(slot)) + pb_varint_field(2, current_level + 1)
    response = (pb_int64_field(1, uid) + pb_tag(2, 2) + uvarint(len(seed)) + seed)
    messages = [("PVZ.Cmd.Cmd_Card_UpgradePlantSeed_SC", response)]
    card_sync = build_card_sync_sc(player["uin"], uid, card[1], 266)  # CardUpgradePlantSeed
    if card_sync:
        messages.append(card_sync)
    item_update = grant_items(player, [(item_id, -amount) for item_id, amount in costs])
    if item_update:
        messages.append(item_update)
    log.info("    fruit upgraded: uid=%d card=%d type=%d slot=%d %d->%d cost=%s",
             uid, card[1], fruit_type, slot, current_level, current_level + 1, costs)
    return messages


def handle_card_fill(cmd_data, player):
    fields = parse_varint_fields(cmd_data)
    uid, index = fields.get(1, 0), fields.get(2, -1)
    if not _owned_card(player, uid):
        return []
    recipe = _puzzle_piece_recipe(player["uin"], uid, index)
    if not recipe:
        return []
    stage, piece_item, required = recipe
    remaining = store.consume_puzzle_piece(player["uin"], uid, stage, index, piece_item, required)
    if remaining is None:
        log.info("    card fill REJECTED: uid=%d index=%d", uid, index)
        return []
    body = pb_int64_field(1, uid) + pb_varint_field(2, index)
    item = build_item_dto(piece_item, remaining)
    return [("PVZ.Cmd.Cmd_Card_Fill_SC", body),
            ("PVZ.Cmd.Cmd_Item_Update_SC", pb_tag(1, 2) + uvarint(len(item)) + item)]


def handle_card_finishfill(cmd_data, player):
    uid = parse_varint_fields(cmd_data).get(1, 0)
    card = _owned_card(player, uid)
    filled = store.get_card_filled_indices(player["uin"], uid) if card else []
    if not card or not filled:
        return []
    complete = len(set(filled)) >= _card_fill_cell_count(store.get_card_fill_quality(player["uin"], uid))
    if not complete:
        log.info("    card puzzle not complete: uid=%d filled=%d/%d", uid, len(set(filled)),
                 _card_fill_cell_count(store.get_card_fill_quality(player["uin"], uid)))
        return []
    if complete:
        quality = store.get_card_fill_quality(player["uin"], uid) + 1
        store.set_card_fill_quality(player["uin"], uid, quality)
    # The client builds the completion dialog from its current card model when it
    # handles FinishFill_SC.  Send the updated card first, otherwise the dialog
    # still reads the old white 0-stage card and only changes after the dialog is
    # already on screen.
    messages = []
    store.clear_card_filled_indices(player["uin"], uid)
    sync = build_card_sync_sc(player["uin"], uid, card[1], 84)
    if sync:
        messages.append(sync)
    log.info("    card puzzle complete: uid=%d quality %d->%d", uid, quality - 1, quality)
    messages.append(("PVZ.Cmd.Cmd_Card_FinishFill_SC", pb_int64_field(1, uid)))
    messages += _quest_observe_card_progress(player)
    return messages


def handle_card_batchfill(cmd_data, player):
    fields = parse_varint_fields(cmd_data)
    uid = fields.get(1, 0)
    indexes = parse_repeated_varint(cmd_data, 2)
    accepted = []
    for index in indexes:
        body = pb_int64_field(1, uid) + pb_varint_field(2, index)
        if handle_card_fill(body, player):
            accepted.append(index)
    if not accepted:
        return []
    body = pb_int64_field(1, uid)
    for index in accepted:
        body += pb_varint_field(2, index)
    # handle_card_fill persists each consumed piece, but its per-piece item
    # updates are intentionally folded into this batch response.  Send the
    # final counts too, otherwise the server save changes while the bag UI
    # continues showing the pre-batch quantities.
    quality = store.get_card_fill_quality(player["uin"], uid)
    fill_quality, fill_evolve = _card_fill_display(quality)
    item_updates = b""
    for index in accepted:
        item_id = load_card_puzzle()[quality]["cost"][index][0]
        item = build_item_dto(item_id, store.get_item_count(player["uin"], item_id))
        item_updates += pb_tag(1, 2) + uvarint(len(item)) + item
    messages = [("PVZ.Cmd.Cmd_Card_BatchFill_SC", body)]
    if item_updates:
        messages.append(("PVZ.Cmd.Cmd_Item_Update_SC", item_updates))
    return messages


def handle_card_forge(cmd_data, player):
    fields = parse_varint_fields(cmd_data)
    uid = fields.get(1, 0)
    materials = parse_repeated_varint(cmd_data, 2)
    card = _owned_card(player, uid)
    if not card:
        log.info("    card forge rejected: uin=%s unknown card uid=%d materials=%s",
                 player.get("uin"), uid, materials)
        return []
    rows = load_card_forge().get(card[1], [])
    forge_level = store.get_card_forge_level(player["uin"], uid)
    row = next((value for value in rows if value["level"] == forge_level + 1), None)
    # The client decides whether the Enhance button is enabled from the card's
    # star-specific forge template.  Keep the server-side boundary identical:
    # once the current star has no next template, only star-up may proceed.
    max_forge_level = max((value["level"] for value in rows), default=0)
    if not row or forge_level >= max_forge_level:
        log.info("    card forge rejected: uid=%d card=%d forge=%d/%d (no next template)",
                 uid, card[1], forge_level, max_forge_level)
        return [("PVZ.Cmd.Cmd_Card_Forge_SC", pb_bool(1, False) + pb_int64_field(2, uid))]
    if int(player.get("coin", 0)) < row["cost"]:
        log.info("    card forge rejected: uid=%d card=%d forge=%d needs coin=%d has=%d",
                 uid, card[1], forge_level, row["cost"], int(player.get("coin", 0)))
        return [("PVZ.Cmd.Cmd_Card_Forge_SC", pb_bool(1, False) + pb_int64_field(2, uid))]
    load_battle_cards()
    star = int(_BATTLE_CARDS.get(card[1], {}).get("star", 1))
    counts = {}
    for item_id in materials:
        counts[item_id] = counts.get(item_id, 0) + 1
    # The client lets the player combine several chlorophyll items to raise the
    # displayed success rate.  consumeItemList is the repeated list of each item
    # consumed, so every entry contributes its own chance (including duplicates).
    # Using only materials[0] made the server roll at e.g. 4% while the client
    # showed 100%, which looked like the card was capped at forge +1.
    chance_table = load_card_forge_chances()
    material_chances = [chance_table.get((star, item_id), 0) for item_id in materials]
    chance = min(10000, sum(material_chances)) if materials else 10000
    log.info("    card forge attempt: uin=%s uid=%d card=%d star=%d forge=%d->%d "
             "coin=%d cost=%d materials=%s materialChances=%s chance=%.2f%%",
             player["uin"], uid, card[1], star, forge_level, row["level"],
             int(player.get("coin", 0)), row["cost"], materials,
             material_chances, chance / 100)
    if any(store.get_item_count(player["uin"], item_id) < count
           for item_id, count in counts.items()):
        log.info("    card forge rejected: uid=%d forge=%d insufficient materials=%s",
                 uid, forge_level, counts)
        return [("PVZ.Cmd.Cmd_Card_Forge_SC", pb_bool(1, False) + pb_int64_field(2, uid))]
    success = chance >= 10000 or random.randint(1, 10000) <= chance
    for item_id, count in counts.items():
        store.add_item(player["uin"], item_id, -count)
    if not success:
        log.info("    card forge failed roll: uid=%d card=%d forge remains %d; consumed=%s",
                 uid, card[1], forge_level, counts)
        item_updates = b""
        for item_id in counts:
            item = build_item_dto(item_id, store.get_item_count(player["uin"], item_id))
            item_updates += pb_tag(1, 2) + uvarint(len(item)) + item
        messages = [("PVZ.Cmd.Cmd_Card_Forge_SC",
                     pb_bool(1, False) + pb_int64_field(2, uid))]
        if item_updates:
            messages.append(("PVZ.Cmd.Cmd_Item_Update_SC", item_updates))
        return messages
    player["coin"] = int(player["coin"]) - row["cost"]
    store.save_player(player["uin"], coin=player["coin"])
    store.set_card_forge_level(player["uin"], uid, row["level"])
    log.info("    card forge success: uid=%d card=%d forge=%d coin=%d",
             uid, card[1], row["level"], player["coin"])
    result = pb_bool(1, True) + pb_int64_field(2, uid)
    # Sync the changed card before the success event: CardProxy resolves its
    # CardItemVO when Forge_SC arrives.  SyncFullInfo updates that object and
    # clears its cached forge template. Rebuilding the entire collection here
    # delayed the animation by several seconds for accounts with many cards.
    messages = []
    sync = build_card_sync_sc(player["uin"], uid, card[1], 28)
    if sync:
        messages.append(sync)
    messages.append(("PVZ.Cmd.Cmd_SyncCoin_SC", pb_varint_field(1, player["coin"])))
    item_updates = b""
    for item_id in counts:
        item = build_item_dto(item_id, store.get_item_count(player["uin"], item_id))
        item_updates += pb_tag(1, 2) + uvarint(len(item)) + item
    if item_updates:
        messages.append(("PVZ.Cmd.Cmd_Item_Update_SC", item_updates))
    messages.append(("PVZ.Cmd.Cmd_Card_Forge_SC", result))
    return messages


_CARD_UPGRADE_RECIPES = None


def load_card_upgrade_recipes():
    """Load CardUpgradeTemplate: cardId -> star-up requirements.

    The table is found in two clientDB revisions.  The current one uses
    ``id, levelNeed, forgeLvNeed, costItemID, costItemNum, costCoinNum,
    newCardId`` where ``id`` is the source card ID; some revisions include a
    separate ``cardId`` column.  Read by header so both remain compatible.
    """
    global _CARD_UPGRADE_RECIPES
    if _CARD_UPGRADE_RECIPES is None:
        _CARD_UPGRADE_RECIPES = {}
        rows = _read_clientdb_table("CardUpgradeTemplate.txt")
        if rows:
            header = [name.lstrip("\ufeff") for name in rows[0]]
            ci = {name: i for i, name in enumerate(header)}

            def col(row, name, pos):
                i = ci.get(name, pos)
                return row[i] if i < len(row) else "0"

            for row in rows[1:]:
                try:
                    source = int(col(row, "cardId", 0)) if "cardId" in ci else int(col(row, "id", 0))
                    _CARD_UPGRADE_RECIPES[source] = (
                        int(col(row, "levelNeed", 2 if "cardId" in ci else 1)),
                        int(col(row, "forgeLvNeed", 3 if "cardId" in ci else 2)),
                        int(col(row, "costItemID", 4 if "cardId" in ci else 3)),
                        int(col(row, "costItemNum", 5 if "cardId" in ci else 4)),
                        int(col(row, "costCoinNum", 6 if "cardId" in ci else 5)),
                        int(col(row, "newCardId", 7 if "cardId" in ci else 6)))
                except (TypeError, ValueError):
                    continue
        log.info("loaded %d card star-up recipes", len(_CARD_UPGRADE_RECIPES))
    return _CARD_UPGRADE_RECIPES


def _logic_error(pos, param=None):
    """PVZ.Cmd.Cmd_LogicError_SC{pos(1), param(2), seqid(3)} — the client looks `pos` up in
    clientDB ErrorInfo.txt and shows the toast (handlerID=0 rows are safe standard toasts;
    isForbidConnectAgain=0 keeps the connection). Used to REPLACE the old silent `[]`
    rejections so the player sees WHY nothing happened (e.g. 1015 该卡牌没有强化满)."""
    body = pb_varint_field(1, int(pos))
    if param is not None:
        body += pb_varint_field(2, int(param))
    return ("PVZ.Cmd.Cmd_LogicError_SC", body)


def _handle_card_star_upgrade(cmd_data, player):
    uid = parse_varint_fields(cmd_data).get(1, 0)
    card = _owned_card(player, uid)
    if not card:
        log.info("    card evolve REJECTED: uin=%s unknown card uid=%s (stale client object?)",
                 player.get("uin"), uid)
        return [_logic_error(1015)]
    recipe = load_card_upgrade_recipes().get(card[1])
    if not recipe:
        # Family has no CardUpgradeTemplate row at all (not star-upgradable).
        log.info("    card evolve REJECTED: uid=%d card=%d has no star-up recipe", uid, card[1])
        return [_logic_error(1016)]
    need_level, need_forge, item_id, item_num, coin_num, new_card_id = recipe
    forge_level = store.get_card_forge_level(player["uin"], uid)
    account_level = int(player.get("level", 1))
    # Per-branch diagnostics + a visible LogicError toast (ErrorInfo.txt ids) instead of
    # the old silent [] — the client UI can be stale (e.g. forge reset by the previous
    # star-up), and silence made the star-up button look dead ("条件满足却升不了星").
    if account_level < need_level:
        log.info("    card evolve REJECTED: uid=%d card=%d accountLv=%d/%d",
                 uid, card[1], account_level, need_level)
        return [_logic_error(8506)]
    if forge_level < need_forge:
        # By far the most common case: star-up reset forge to 0 and the client panel
        # still showed the pre-reset state, or the player skipped re-forging to +5.
        log.info("    card evolve REJECTED: uid=%d card=%d forge=%d/%d (re-forge to +5 first)",
                 uid, card[1], forge_level, need_forge)
        return [_logic_error(1015)]
    if store.get_item_count(player["uin"], item_id) < item_num:
        log.info("    card evolve REJECTED: uid=%d card=%d pieces item=%d short (need %d)",
                 uid, card[1], item_id, item_num)
        return [_logic_error(2417)]
    if int(player.get("coin", 0)) < coin_num:
        log.info("    card evolve REJECTED: uid=%d card=%d coin=%d need=%d",
                 uid, card[1], int(player.get("coin", 0)), coin_num)
        return [_logic_error(202)]
    load_battle_cards()
    # newCardId=0 marks the final star and must never be upgraded further.
    if not new_card_id or new_card_id not in _BATTLE_CARDS:
        log.info("    card evolve REJECTED: uid=%d card=%d is final star (newCardId=%s)",
                 uid, card[1], new_card_id)
        return [_logic_error(1016)]
    # Keep one stable client object.  This Flash build retains the old card
    # object when a different UID is returned, causing duplicate plants and a
    # stale +5 forge state.  Update the existing UID in place and send a full
    # info sync for that same UID.
    new_uid = uid
    store.add_item(player["uin"], item_id, -item_num)
    player["coin"] = int(player.get("coin", 0)) - coin_num
    store.save_player(player["uin"], coin=player["coin"])
    store.replace_card(player["uin"], uid, new_uid, new_card_id)
    # Star-up consumes the current enhancement, while the card's level/exp remain intact.
    store.set_card_forge_level(player["uin"], new_uid, 0)
    level = card[2]
    # Build the normal full-card sync so the client also receives forge=0 and the
    # recalculated post-star attributes/power in the same response.
    sync = build_card_sync_sc(player["uin"], new_uid, new_card_id, 26)
    stats = card_stats_at_level(new_card_id, level)
    player["_last_card_evolve_old_uid"] = uid
    player["_last_card_evolve_new_uid"] = new_uid
    result = pb_int64_field(1, new_uid) + pb_varint_field(2, stats.get("star", 1))
    item = build_item_dto(item_id, store.get_item_count(player["uin"], item_id))
    messages = [("PVZ.Cmd.Cmd_Card_Evolve_SC", result),
                sync,
                ("PVZ.Cmd.Cmd_Item_Update_SC", pb_tag(1, 2) + uvarint(len(item)) + item),
                ("PVZ.Cmd.Cmd_SyncCoin_SC", pb_varint_field(1, player["coin"]))]
    messages += _quest_observe_card_progress(player)
    return messages


def handle_card_usecardupgrade(cmd_data, player):
    """Handle the actual star-up request emitted by the client UI.

    The client does not send Cmd_Card_Evolve_CS when the star-up button is
    pressed; it sends Cmd_Card_UseCardUpgrade_CS{oldUId}.  Keep the existing
    evolve implementation as the single validation/mutation path, but replace
    its response with the protocol that CardProxy listens for.
    """
    uid = parse_varint_fields(cmd_data).get(1, 0)
    messages = _handle_card_star_upgrade(cmd_data, player)
    if not messages:
        return []
    if messages[0][0] == "PVZ.Cmd.Cmd_LogicError_SC":
        # Rejected: forward the error toast untouched (the wrapper below would
        # otherwise rewrite messages[0] into a bogus success event).
        return messages
    # The server keeps the same UID so formations and the selected card remain
    # valid.  The cardId changes inside the full-info sync sent alongside this.
    new_uid = int(player.pop("_last_card_evolve_new_uid", uid))
    player.pop("_last_card_evolve_old_uid", None)
    messages[0] = (
        "PVZ.Cmd.Cmd_Card_UseCardUpgrade_SC",
        pb_int64_field(1, uid) + pb_int64_field(2, new_uid),
    )
    # As with forge, CardProxy handles this event by immediately looking up
    # the card by UID.  Deliver the new full card first so it sees the new
    # star and forgeLevel=0 instead of the pre-upgrade +5 object.
    if len(messages) > 1 and messages[1][0] == "PVZ.Cmd.Cmd_Card_SyncFullInfo_SC":
        messages[0], messages[1] = messages[1], messages[0]
    # SyncFullInfo updates this UID in place and invalidates the client's
    # cached star-specific forge template. A full collection refresh here made
    # the animation wait several seconds on accounts with many cards.
    # The item update fires BagGlobals.BAG_ITEM_CHANGED. CardUpgradeCt handles
    # that by calling setCostItem(), which seeks the same MovieClip back to
    # "add_cost". Deliver all state updates first, then the success event that
    # starts its "upgrade" timeline, or the animation stops immediately.
    success = next(message for message in messages
                   if message[0] == "PVZ.Cmd.Cmd_Card_UseCardUpgrade_SC")
    messages.remove(success)
    messages.append(success)
    return messages


def handle_card_evolve(cmd_data, player):
    """Spend item 43 (威望) on the selected plant's independent 0..200 evolution tree."""
    uid = parse_varint_fields(cmd_data).get(1, 0)
    card = _owned_card(player, uid)
    if not card:
        return []
    current = store.get_card_evolve_level(player["uin"], uid)
    target = current + 1
    row = load_plant_evolution()["levels"].get(target)
    if not row:
        return []
    item_id, amount = row["cost"]
    if amount <= 0 or store.get_item_count(player["uin"], item_id) < amount:
        log.info("    prestige evolve REJECTED: uid=%d level=%d need=%d:%d",
                 uid, target, item_id, amount)
        return []
    store.add_item(player["uin"], item_id, -amount)
    store.set_card_evolve_level(player["uin"], uid, target)
    player["prestige"] = store.get_item_count(player["uin"], 43)
    store.save_player(player["uin"], prestige=player["prestige"])
    sync = build_card_sync_sc(player["uin"], uid, card[1], 30)
    item = build_item_dto(item_id, store.get_item_count(player["uin"], item_id))
    messages = []
    if sync:
        messages.append(sync)
    messages.extend([
        ("PVZ.Cmd.Cmd_Card_Evolve_SC", pb_int64_field(1, uid) + pb_varint_field(2, target)),
        ("PVZ.Cmd.Cmd_Item_Update_SC", pb_tag(1, 2) + uvarint(len(item)) + item),
        ("PVZ.Cmd.Cmd_SyncPrestige_SC", pb_varint_field(1, player["prestige"])),
    ])
    log.info("    prestige evolve: uid=%d level=%d cost=%d:%d", uid, target, item_id, amount)
    return messages


def _armor_dto(state):
    dto = (pb_varint_field(1, state["armor_type"]) + pb_varint_field(2, state["star"])
           + pb_varint_field(3, state["level"]) + pb_varint_field(4, state["exp"])
           + pb_varint_field(6, state["substar"]))
    for gem_type, item_id in sorted(state["gems"].items()):
        gem = pb_varint_field(1, gem_type) + pb_varint_field(2, item_id)
        dto += pb_tag(5, 2) + uvarint(len(gem)) + gem
    return dto


def _armor_card(player, fields):
    uid = int(fields.get(1, 0))
    return uid, _owned_card(player, uid)


def _armor_sync(player, uid, card):
    return build_card_sync_sc(player["uin"], uid, card[1], 31) if card else None


def handle_armor_get_card(cmd_data, player):
    uid, card = _armor_card(player, parse_varint_fields(cmd_data))
    if not card:
        return []
    body = pb_int64_field(1, uid)
    for state in store.get_card_armors(player["uin"], uid).values():
        dto = _armor_dto(state)
        body += pb_tag(2, 2) + uvarint(len(dto)) + dto
    body += pb_varint_field(3, store.get_card_armor_type(player["uin"], uid))
    return body


def handle_armor_get_growth(cmd_data, player):
    body = b""
    for level, (count, sub_id, _percent) in sorted(
            _armor_growth(player["uin"], int(player.get("level", 1))).items()):
        dto = (pb_varint_field(1, level) + pb_varint_field(2, count)
               + pb_varint_field(3, sub_id))
        body += pb_tag(1, 2) + uvarint(len(dto)) + dto
    return body


def handle_armor_set_type(cmd_data, player):
    fields = parse_varint_fields(cmd_data)
    uid, card = _armor_card(player, fields)
    armor_type = int(fields.get(2, 0))
    if not card or armor_type not in (1, 2, 3):
        return []
    store.set_card_armor_type(player["uin"], uid, armor_type)
    response = pb_int64_field(1, uid) + pb_varint_field(2, armor_type)
    sync = _armor_sync(player, uid, card)
    return [("PVZ.Cmd.Cmd_Armor_SetType_SC", response)] + ([sync] if sync else [])


def handle_armor_upgrade_star(cmd_data, player):
    fields = parse_varint_fields(cmd_data)
    uid, card = _armor_card(player, fields)
    armor_type = int(fields.get(2, 0))
    if not card or armor_type not in (1, 2, 3):
        return []
    state = store.get_card_armors(player["uin"], uid)[armor_type]
    need = load_plant_armor()["star_need"].get((armor_type, state["star"], state["substar"]))
    if not need or int(player.get("level", 1)) < need["role"]:
        return []
    item_id, amount = need["cost"]
    if amount <= 0 or store.get_item_count(player["uin"], item_id) < amount:
        return []
    if state["star"] == 0:
        star, substar = 1, 0
    elif state["substar"] < 4:
        star, substar = state["star"], state["substar"] + 1
    else:
        star, substar = state["star"] + 1, 0
    store.add_item(player["uin"], item_id, -amount)
    store.set_card_armor(player["uin"], uid, armor_type, star, substar,
                         state["level"], state["exp"])
    if not store.get_card_armor_type(player["uin"], uid):
        store.set_card_armor_type(player["uin"], uid, armor_type)
    response = (pb_int64_field(1, uid) + pb_varint_field(2, armor_type)
                + pb_varint_field(3, star) + pb_varint_field(4, substar))
    item = build_item_dto(item_id, store.get_item_count(player["uin"], item_id))
    update = ("PVZ.Cmd.Cmd_Item_Update_SC", pb_tag(1, 2) + uvarint(len(item)) + item)
    sync = _armor_sync(player, uid, card)
    return [("PVZ.Cmd.Cmd_Armor_UpgradeStar_SC", response), update] + ([sync] if sync else [])


def handle_armor_upgrade_level(cmd_data, player):
    fields = parse_varint_fields(cmd_data)
    uid, card = _armor_card(player, fields)
    armor_type, item_id, amount = (int(fields.get(2, 0)), int(fields.get(3, 0)),
                                   int(fields.get(4, 0)))
    if not card or armor_type not in (1, 2, 3) or item_id != 98904 or amount <= 0:
        return []
    available = store.get_item_count(player["uin"], item_id)
    used = min(amount, available)
    if used <= 0:
        return []
    state = store.get_card_armors(player["uin"], uid)[armor_type]
    level, exp = state["level"], state["exp"] + used * 500
    levels = load_plant_armor()["levels"]
    while level < max(levels or {1: None}):
        need_exp = levels.get(level, (0, 999))[0]
        need_star = levels.get(level + 1, (0, 999))[1]
        if need_exp <= 0 or exp < need_exp or state["star"] < need_star:
            break
        exp -= need_exp
        level += 1
    store.add_item(player["uin"], item_id, -used)
    store.set_card_armor(player["uin"], uid, armor_type, state["star"], state["substar"], level, exp)
    response = (pb_int64_field(1, uid) + pb_varint_field(2, armor_type)
                + pb_varint_field(3, item_id) + pb_varint_field(4, used)
                + pb_varint_field(5, level) + pb_varint_field(6, exp))
    item = build_item_dto(item_id, store.get_item_count(player["uin"], item_id))
    update = ("PVZ.Cmd.Cmd_Item_Update_SC", pb_tag(1, 2) + uvarint(len(item)) + item)
    sync = _armor_sync(player, uid, card)
    return [("PVZ.Cmd.Cmd_Armor_UpgradeLevel_SC", response), update] + ([sync] if sync else [])


def handle_armor_set_gem(cmd_data, player):
    fields = parse_varint_fields(cmd_data)
    uid, card = _armor_card(player, fields)
    armor_type, item_id = int(fields.get(2, 0)), int(fields.get(3, 0))
    crystal = load_plant_armor()["crystals"].get(item_id)
    if (not card or armor_type not in (1, 2, 3) or not crystal
            or store.get_item_count(player["uin"], item_id) < 1):
        return []
    state = store.get_card_armors(player["uin"], uid)[armor_type]
    old_item = int(state["gems"].get(crystal["hole"], 0))
    changes = [(item_id, -1)] + ([(old_item, 1)] if old_item else [])
    update = grant_items(player, changes)
    store.set_card_armor_gem(player["uin"], uid, armor_type, crystal["hole"], item_id)
    response = (pb_int64_field(1, uid) + pb_varint_field(2, armor_type)
                + pb_varint_field(3, item_id))
    sync = _armor_sync(player, uid, card)
    return [("PVZ.Cmd.Cmd_Armor_SetGem_SC", response)] + ([update] if update else []) + ([sync] if sync else [])


def handle_armor_unset_gem(cmd_data, player):
    fields = parse_varint_fields(cmd_data)
    uid, card = _armor_card(player, fields)
    armor_type, gem_type = int(fields.get(2, 0)), int(fields.get(3, 0))
    if not card or armor_type not in (1, 2, 3) or gem_type not in (1, 2, 3, 4):
        return []
    state = store.get_card_armors(player["uin"], uid)[armor_type]
    item_id = int(state["gems"].get(gem_type, 0))
    if not item_id:
        return []
    store.set_card_armor_gem(player["uin"], uid, armor_type, gem_type, 0)
    update = grant_items(player, [(item_id, 1)])
    response = (pb_int64_field(1, uid) + pb_varint_field(2, armor_type)
                + pb_varint_field(3, gem_type))
    sync = _armor_sync(player, uid, card)
    return [("PVZ.Cmd.Cmd_Armor_UnsetGem_SC", response), update] + ([sync] if sync else [])


def handle_armor_combine_unset(cmd_data, player):
    fields = parse_varint_fields(cmd_data)
    item_id, batches = int(fields.get(1, 0)), int(fields.get(2, 0))
    crystal = load_plant_armor()["crystals"].get(item_id)
    if not crystal or not crystal["next"] or batches <= 0:
        return []
    batches = min(batches, store.get_item_count(player["uin"], item_id) // crystal["need"])
    if batches <= 0:
        return []
    update = grant_items(player, [(item_id, -batches * crystal["need"]),
                                  (crystal["next"], batches)])
    response = (pb_varint_field(1, item_id) + pb_varint_field(2, batches)
                + pb_varint_field(3, crystal["next"]))
    return [("PVZ.Cmd.Cmd_Armor_CombineUnsetGem_SC", response), update]


def handle_armor_combine_set(cmd_data, player):
    fields = parse_varint_fields(cmd_data)
    uid, card = _armor_card(player, fields)
    armor_type, gem_type = int(fields.get(2, 0)), int(fields.get(3, 0))
    if not card or armor_type not in (1, 2, 3):
        return []
    state = store.get_card_armors(player["uin"], uid)[armor_type]
    item_id = int(state["gems"].get(gem_type, 0))
    crystal = load_plant_armor()["crystals"].get(item_id)
    # One copy is already socketed, so only (need-1) additional bag copies are consumed.
    need = crystal["need"] - 1 if crystal else 0
    if not crystal or not crystal["next"] or need <= 0 or store.get_item_count(player["uin"], item_id) < need:
        return []
    update = grant_items(player, [(item_id, -need)])
    store.set_card_armor_gem(player["uin"], uid, armor_type, gem_type, crystal["next"])
    response = (pb_int64_field(1, uid) + pb_varint_field(2, armor_type)
                + pb_varint_field(3, gem_type) + pb_varint_field(4, crystal["next"]))
    sync = _armor_sync(player, uid, card)
    return [("PVZ.Cmd.Cmd_Armor_CombineSetGem_SC", response), update] + ([sync] if sync else [])


_PUZZLE_PRICES = None


def load_puzzle_prices():
    global _PUZZLE_PRICES
    if _PUZZLE_PRICES is None:
        _PUZZLE_PRICES = {}
        rows = _read_clientdb_table("puzzlePrice.txt")
        if rows:
            header = {name: i for i, name in enumerate(rows[0])}
            for row in rows[1:]:
                try:
                    _PUZZLE_PRICES[int(row[header["id"]])] = int(row[header["price"]])
                except (KeyError, IndexError, ValueError):
                    continue
    return _PUZZLE_PRICES


def handle_card_exchangepiece(cmd_data, player):
    fields = parse_varint_fields(cmd_data)
    uid, index, amount = fields.get(3, 0), fields.get(1, -1), fields.get(2, -1)
    if not _owned_card(player, uid) or amount < 0:
        return []
    recipe = _puzzle_piece_recipe(player["uin"], uid, index)
    if not recipe:
        return []
    stage, item_id, required = recipe
    price = load_puzzle_prices().get(item_id, 0)
    if price <= 0:
        return []
    counts = store.purchase_puzzle_piece(player["uin"], uid, stage, index,
                                         item_id, required, amount, price)
    if counts is None:
        log.info("    puzzle purchase rejected: uid=%d index=%d amount=%d", uid, index, amount)
        return []
    updates = b"".join(pb_bytes(1, build_item_dto(item, count)) for item, count in counts.items())
    # The success event immediately asks the client to fill this slot. Its bag
    # must already contain the purchased pieces and the updated point balance.
    return [("PVZ.Cmd.Cmd_Item_Update_SC", updates),
            ("PVZ.Cmd.Cmd_Card_ExchangePiece_SC", pb_varint_field(1, index))]


# ---- card avatars (wardrobe / 时装) --------------------------------------------
_CARD_AVATARS = None  # {tdPlantId(int): [avatarId(int), ...] ascending}
_CARD_AVATAR_TEMPLATES = None  # {avatarId: {plant_id, forge_type, unlock_items, order}}
_CARD_AVATAR_FORGE = None  # {forge_type: {level: {cost_items}}}
_CARD_AVATAR_ASSETS = None  # {avatarId: {pvp: bool, td: bool}}, from ModuleAvatarConfig.swf


def _card_avatar_plant_id(card):
    """Map an owned battle-card id (e.g. 1205) to its TD plant id (1200)."""
    if not card:
        return 0
    load_battle_cards()
    template = _BATTLE_CARDS.get(int(card[1])) or {}
    plant_id = int(template.get("tdId", 0) or 0)
    catalog = load_card_avatars()
    if plant_id in catalog or not template.get("awakeLevel"):
        return plant_id
    # Awakening variants have a distinct tdId but retain the same configured
    # icon and wardrobe. Preserve the selected costume on the existing UID.
    candidates = {int(row["tdId"]) for row in _BATTLE_CARDS.values()
                  if row.get("icon") == template.get("icon") and row.get("tdId") in catalog}
    return next(iter(candidates)) if len(candidates) == 1 else plant_id


def load_card_avatars():
    """Parse cardChestAvatar.txt out of the clientDB archive once; cache it.
    Returns {tdPlantId: [avatarId, ...]} sorted ascending. The client treats the lowest-id
    avatar of a plant as its default 'Using' skin (getPlantAvatarsByPlantId sorts ascending
    and getPlantDefaultAvatarID returns [0])."""
    global _CARD_AVATARS
    if _CARD_AVATARS is not None:
        return _CARD_AVATARS
    _CARD_AVATARS = {}
    if not os.path.isfile(_CLIENTDB_PATH):
        return _CARD_AVATARS
    data = open(_CLIENTDB_PATH, "rb").read()
    pos = 0
    while pos + 4 <= len(data):                       # big-endian [len][name][len][tsv] archive
        nlen = int.from_bytes(data[pos:pos + 4], "big"); pos += 4
        name = data[pos:pos + nlen].decode("utf-8", "replace"); pos += nlen
        dlen = int.from_bytes(data[pos:pos + 4], "big"); pos += 4
        chunk = data[pos:pos + dlen]; pos += dlen
        if name != "cardChestAvatar.txt":
            continue
        rows = [r for r in chunk.decode("utf-8", "replace").replace("\r", "").split("\n") if r.strip()]
        hdr = rows[0].split("\t"); ci = {c: i for i, c in enumerate(hdr)}
        ii, pi = ci.get("id"), ci.get("tdPlantId")
        for r in rows[1:]:
            c = r.split("\t")
            try:
                aid, pid = int(c[ii]), int(c[pi])
            except (ValueError, IndexError):
                continue
            _CARD_AVATARS.setdefault(pid, []).append(aid)
        break
    for pid in _CARD_AVATARS:
        _CARD_AVATARS[pid].sort()
    return _CARD_AVATARS


def load_card_avatar_templates():
    """Load the wardrobe catalog, including unlock materials and forge type."""
    global _CARD_AVATAR_TEMPLATES
    if _CARD_AVATAR_TEMPLATES is not None:
        return _CARD_AVATAR_TEMPLATES
    _CARD_AVATAR_TEMPLATES = {}
    rows = _read_clientdb_table("cardChestAvatar.txt")
    if rows:
        header = {name: i for i, name in enumerate(rows[0])}
        for row in rows[1:]:
            try:
                aid = int(row[header["id"]])
                _CARD_AVATAR_TEMPLATES[aid] = {
                    "plant_id": int(row[header["tdPlantId"]]),
                    "forge_type": int(row[header.get("forgeType", -1)]) if header.get("forgeType") is not None else 0,
                    "catalog": int(row[header.get("avatarCatalog", -1)]) if header.get("avatarCatalog") is not None else 0,
                    "unlock_items": parse_bonus_items(row[header.get("unLockItemStr", -1)]) if header.get("unLockItemStr") is not None else [],
                    "order": int(row[header.get("order", -1)]) if header.get("order") is not None else aid,
                }
            except (KeyError, IndexError, TypeError, ValueError):
                continue
    log.info("loaded %d card avatar templates", len(_CARD_AVATAR_TEMPLATES))
    return _CARD_AVATAR_TEMPLATES


def load_card_avatar_forge():
    """Load avatar forge material costs keyed by forge type and target level."""
    global _CARD_AVATAR_FORGE
    if _CARD_AVATAR_FORGE is not None:
        return _CARD_AVATAR_FORGE
    _CARD_AVATAR_FORGE = {}
    rows = _read_clientdb_table("cardChestForgeAvatar.txt")
    if rows:
        header = {name: i for i, name in enumerate(rows[0])}
        for row in rows[1:]:
            try:
                forge_type = int(row[header["type"]])
                level = int(row[header["level"]])
                costs = parse_bonus_items(row[header["useItemStr"]])
            except (KeyError, IndexError, TypeError, ValueError):
                continue
            _CARD_AVATAR_FORGE.setdefault(forge_type, {})[level] = costs
    log.info("loaded %d card avatar forge types", len(_CARD_AVATAR_FORGE))
    return _CARD_AVATAR_FORGE


def load_card_avatar_assets():
    """Read the embedded avatar binding XML directly from ModuleAvatarConfig.

    The SWF stores the XML as uncompressed DefineBinaryData.  Keeping this
    inventory separate lets us expose every working card costume while not
    selecting one of the entries whose TD bone binding is absent.
    """
    global _CARD_AVATAR_ASSETS
    if _CARD_AVATAR_ASSETS is not None:
        return _CARD_AVATAR_ASSETS
    _CARD_AVATAR_ASSETS = {}
    webroot = os.path.dirname(_CLIENTDB_PATH)
    paths = [os.path.join(webroot, "ModuleAvatarConfig.swf")]
    try:
        paths += [os.path.join(webroot, name) for name in os.listdir(webroot)
                  if name.startswith("ModuleAvatarConfig_") and name.endswith(".swf")]
    except OSError:
        pass
    for path in paths:
        try:
            data = open(path, "rb").read()
        except OSError:
            continue
        # CWS stores every tag after the 8-byte SWF header in one zlib stream.
        if data[:3] == b"CWS":
            try:
                import zlib
                data = data[:8] + zlib.decompress(data[8:])
            except (zlib.error, ValueError):
                continue
        for match in re.finditer(rb"<a\s+([^>]+)/>", data):
            attrs = {key.decode("ascii"): value.decode("utf-8", "ignore")
                     for key, _quote, value in re.findall(
                         rb"([A-Za-z0-9]+)=(['\"])(.*?)\2", match.group(1))}
            try:
                avatar_id = int(attrs.get("id", "0"))
            except ValueError:
                continue
            if avatar_id:
                _CARD_AVATAR_ASSETS[avatar_id] = {
                    "pvp": bool(attrs.get("bbPVP") or attrs.get("hbPVP") or attrs.get("hpCard")),
                    "td": bool(attrs.get("bbTD") or attrs.get("hbTD")),
                }
        if _CARD_AVATAR_ASSETS:
            break
    log.info("loaded %d avatar asset bindings (%d with TD bindings)",
             len(_CARD_AVATAR_ASSETS),
             sum(1 for value in _CARD_AVATAR_ASSETS.values() if value["td"]))
    return _CARD_AVATAR_ASSETS


def _working_card_avatars(plant_id):
    """Catalog entries with a real card/PVP binding; fall back to the table if needed."""
    avatars = list(load_card_avatars().get(int(plant_id), []))
    assets = load_card_avatar_assets()
    return [aid for aid in avatars if not assets or assets.get(aid, {}).get("pvp")]


def _card_avatar_selected(player, uid, card=None, _shared=None):
    card = card or _owned_card(player, uid)
    avatars = _working_card_avatars(_card_avatar_plant_id(card)) if card else []
    if not avatars:
        return 0
    for avatar_id in avatars:
        status, _level = _avatar_default_status(player, uid, card, avatar_id, avatars,
                                                _shared=_shared)
        if status == 4:
            return int(avatar_id)
    return int(min(avatars))


def _card_avatar_total_level(player, uid, card=None, _shared=None):
    """All activated costumes stack their enhancement bonus, as the UI states.

    ``_shared`` lets the card-package loop reuse one DB fetch per card instead of one
    per costume: {"avatars": {uid: {avatar_id: row}}, "fill": {uid: fill_stage}}.
    """
    card = card or _owned_card(player, uid)
    avatars = _working_card_avatars(_card_avatar_plant_id(card)) if card else []
    total = 0
    for avatar_id in avatars:
        status, level = _avatar_default_status(player, uid, card, avatar_id, avatars,
                                               _shared=_shared)
        if status in (3, 4):
            total += max(0, int(level))
    return total


def _apply_card_avatar_bonus(stats, player, uid, card=None, _shared=None):
    level = _card_avatar_total_level(player, uid, card, _shared=_shared)
    if level:
        value = level * 10
        stats["atk"] = stats.get("atk", 0) + value
        stats["def_"] = stats.get("def_", 0) + value
        stats["hp"] = stats.get("hp", 0) + value * 10
        stats["ability"] = stats.get("ability", 0) + value
    return stats


def _encode_avatar_all_attr(level=0):
    """Encode Dto_AvatarAllAttr completely.

    The client treats hp/shield as UInt64 objects and all ten fields are read by
    the wardrobe panel.  Older replies only emitted five fields, which left the
    panel with null nested values.  The exact production attribute table is not
    present in this local package, so use a small deterministic per-level bonus;
    the important part is a stable, complete DTO that the client can render.
    """
    level = max(0, int(level))
    value = level * 10
    return (pb_varint_field(1, value)       # attack
            + pb_varint_field(2, value)     # defense
            + pb_varint_field(3, value * 10)  # hp (UInt64)
            + pb_varint_field(4, value * 10)  # shield (UInt64)
            + pb_varint_field(5, value)     # ability
            + pb_float_field(6, 0.0)        # hit
            + pb_float_field(7, 0.0)        # dodge
            + pb_float_field(8, 0.0)        # critical
            + pb_float_field(9, 0.0)        # tough
            + pb_float_field(10, 0.0))      # immune


def _avatar_info_dto(avatar_id, status, forge_level=0):
    forge_level = max(0, int(forge_level))
    curr_power = forge_level * 50
    next_power = (forge_level + 1) * 50
    curr_attr = _encode_avatar_all_attr(forge_level)
    next_attr = _encode_avatar_all_attr(forge_level + 1)
    return (pb_varint_field(1, int(avatar_id))
            + pb_varint_field(2, int(status))
            + pb_varint_field(3, forge_level)
            + pb_varint_field(4, curr_power)
            + pb_varint_field(5, next_power)
            + pb_tag(6, 2) + uvarint(len(curr_attr)) + curr_attr
            + pb_tag(7, 2) + uvarint(len(next_attr)) + next_attr)


def _avatar_template_for(avatar_id, plant_id=None):
    template = load_card_avatar_templates().get(int(avatar_id))
    if template and (plant_id is None or int(template["plant_id"]) == int(plant_id)):
        return template
    return None


def _avatar_default_status(player, uid, card, avatar_id, avatars, _shared=None):
    """Derive a first-login status without writing synthetic ownership rows.

    ``_shared`` carries the per-card DB state (avatar rows / fill quality) fetched once
    by the caller's loop — without it every costume status check re-queries the store.
    """
    shared = _shared or {}
    avatars_map = shared.get("avatars", {}).get(uid)
    if avatars_map is None:
        avatars_map = store.get_card_avatars(player["uin"], uid)
    saved = avatars_map.get(int(avatar_id))
    if saved:
        return int(saved["status"]), int(saved["forge_level"])
    default_id = min(avatars) if avatars else 0
    if int(avatar_id) == default_id:
        return 4, 0  # E_AvatarStatus_Using
    template = _avatar_template_for(avatar_id, _card_avatar_plant_id(card))
    if template and not template.get("unlock_items"):
        # Quality avatars with an empty unlock cost become usable once the card's
        # quality reaches their catalog number.  The local save may have a higher
        # quality than the original client caps, so compare numerically only.
        try:
            fill = shared.get("fill", {}).get(uid)
            quality = store.get_card_fill_quality(player["uin"], uid) if fill is None else fill
            if int(template.get("catalog") or 0) <= quality:
                return 3, 0  # E_AvatarStatus_CanUse
        except (TypeError, ValueError):
            pass
    if template:
        # The special collection is redeemed for an owned material directly.
        # The ordinary quality outfits use the mall-assisted Buy path.
        return (5 if int(template.get("catalog") or 0) == 101 else 2), 0
    return 1, 0


def _avatar_response_body(uid, info, attr):
    return (pb_int64_field(1, int(uid))
            + pb_tag(2, 2) + uvarint(len(info)) + info
            + pb_tag(3, 2) + uvarint(len(attr)) + attr)


def handle_card_getavatarinfo(cmd_data, player):
    """Cmd_Card_GetAvatarInfo_CS{cardUId(1,I64)} -> Cmd_Card_GetAvatarInfo_SC{avatarList(1)=[Dto_AvatarInfo],
    avatarAllAttr(2)=Dto_AvatarAllAttr}. The wardrobe (时装) screen sends this when it opens.

    The client REQUIRES a non-empty avatarList that contains exactly one avatar in the Using(4) state
    and a present avatarAllAttr.  The old empty command handlers caused the wardrobe mediator to
    dereference null after opening/forging.  Return the real catalog plus persistent state instead.
    """
    uid = parse_varint_fields(cmd_data).get(1, 0)
    uin = player.get("uin")
    card = next((c for c in store.get_cards(uin) if int(c[0]) == int(uid)), None) if uin else None
    avatars = _working_card_avatars(_card_avatar_plant_id(card)) if card else []
    avatar_list = b""
    for aid in avatars:
        status, forge_level = _avatar_default_status(player, uid, card, aid, avatars)
        dto = _avatar_info_dto(aid, status, forge_level)
        avatar_list += pb_tag(1, 2) + uvarint(len(dto)) + dto
    attr = _encode_avatar_all_attr(_card_avatar_total_level(player, uid, card))
    body = avatar_list + pb_tag(2, 2) + uvarint(len(attr)) + attr
    log.info("    CARD AVATAR INFO: uid=%d card=%s -> %d avatars",
             uid, card[1] if card else None, len(avatars))
    return body


def grant_battle_card_exp(player, exp_each):
    """After a win, add `exp_each` plant XP to EVERY card in the player's formation (this is the
    植物经验 the battle rewards, which the client animates onto each card's bar). Returns the
    Cmd_Card_SyncFullInfo_SC messages for the cards that changed."""
    if exp_each <= 0:
        return []
    uin = player["uin"]
    placements = default_formation_placements(player)
    card_by_uid = {uid: cid for uid, cid, _l, _e in store.get_cards(uin)}
    messages = []
    for uid in placements.values():
        cid = card_by_uid.get(uid)
        if cid is None:
            continue
        res = add_card_exp(player, uid, cid, exp_each)
        if res:
            sync = build_card_sync_sc(uin, uid, cid, 20)  # ActionFrom_AddExpLevelUp
            if sync:
                messages.append(sync)
    if messages:
        log.info("    battle exp: +%d to %d formation card(s)", exp_each, len(messages))
    return messages


# --- skill/rage bar --------------------------------------------------------------
# The bar under each unit's HP is the SKILL (rage) bar: the client draws `maxRage` pips and fills
# `rage` of them. Design (from the player): 3 pips, start filled 2/3, +1 each round; at full the unit
# casts its special skill. The fill/reset is driven by per-round buffEffect changeRage ticks in the
# replay (a Dto_FightDamage with changeHp=0 + a non-Dodge damageType -> CostarChangeHP animates only
# the rage bar, no attack anim / no damage number).
RAGE_MAX = 3
RAGE_START = 2
# battleCard.skillId2 = a card's SPECIAL (ability); skillId1 = its basic. A unit casts skillId2 when its
# rage bar is full (any kind), else uses skillId1. Each skill runs its REAL effect (see _SKILL_INFO) so
# the replay matches the client's plan-tree and HP stays in sync.
# CAST damage = basic x this (footage: peashooter basic 270, ability 810 = 3x). AoE abilities hit each
# target for basic x _AOE_MULT. Heals restore a fraction of the ally's max HP.
_SKILL_DMG_MULT = 3
_AOE_MULT = 1.6
_HEAL_FRAC_BASIC = 0.04     # a basic heal restores this fraction of the ally's max HP (kept modest so
_HEAL_FRAC_CAST = 0.08      # flag-mummy healers don't out-sustain the plants and drag the fight out)

# Skill kind + target count, parsed from BattleLineupCardSkillTemplate.txt (name+desc). This is what
# makes every skill actually WORK: the sim executes the real effect and the client's plan-tree matches
# (attack/aoe -> InjuredPlan damage; heal -> CurePlan heal; charge -> self-buff, no enemy damage). Only
# damage skills (attack/aoe) ever deal a KILLING blow (isDead) — heal/charge target allies/self, so the
# client never stalls on a heal/charge death (the old bug). kinds: 'attack'(1 enemy), 'aoe'(N enemies),
# 'heal'(N lowest-HP% allies), 'charge'(self, 0-damage swing).
_SKILL_INFO = None
_SKILL_EFFECTS = None
_SKILL_DESCS = None
_BATTLE_STATES = None


def load_battle_states():
    """The card-battle state IDs and effect parameters shipped with Flash."""
    global _BATTLE_STATES
    if _BATTLE_STATES is None:
        _BATTLE_STATES = {}
        rows = _read_clientdb_table("battleState.txt")
        if rows:
            ci = {c: i for i, c in enumerate(rows[0])}
            for row in rows[1:]:
                try:
                    sid = int(row[ci["id"]])
                    param = tuple(int(x) for x in row[ci["buffParam1"]].split(":"))
                    if len(param) == 4:
                        _BATTLE_STATES[sid] = param
                except (ValueError, IndexError, KeyError):
                    continue
    return _BATTLE_STATES


def _leader_effect(skill_id):
    """Map the stock captain skill series to the matching battleState rows."""
    tier = skill_id % 100
    series = skill_id // 100
    state_group = {100: 2700, 101: 2900, 102: 1400, 103: 2200,
                   104: 1800, 105: 1600, 109: 3100, 110: 2000,
                   111: 2200}
    if 1 <= tier <= 5 and series in state_group:
        effect = {"state": state_group[series] + tier, "side": "allies", "turns": 30}
        # Sunlight/Oxygen captain shields use battleState 2201..2205. Keep the
        # shield magnitude explicit here as well: captain shields must mutate
        # the battle's shield pool, even if a clientDB state row is incomplete.
        if series in (103, 111):
            effect["shield_ratio_bp"] = (tier + 1) * 100
        return effect
    if 10601 <= skill_id <= 10605:
        return {"state": 100, "side": "enemies", "turns": 1, "chance": 10, "targets": 2}
    if skill_id == 11205:
        return {"state": 16101, "side": "self", "turns": 30}
    return {}


def _skill_target_count(desc):
    """Zero means every living target, not an arbitrary three-card cap."""
    if "全体" in desc or re.search(r"所有(?:单位|目标|敌|友|己|我|植物|僵尸)", desc):
        return 0
    if "每一横行的前排" in desc:
        return 3
    energy_targets = re.search(r"(?:随机对)?([1-9])个有能量的敌方", desc)
    if energy_targets:
        return int(energy_targets[1])
    match = re.search(r"(?:治疗|攻击|打击|定身|随机攻击|随机治疗|随机打击)([1-9一二三四五六])(?:个|名|位)", desc)
    if not match:
        match = re.search(r"([1-9一二三四五六])(?:个|名|位)(?:生命|敌|友|目标|单位|前排|后排)", desc)
    if match:
        return {"一": 1, "二": 2, "三": 3, "四": 4, "五": 5, "六": 6}.get(match[1], int(match[1]) if match[1].isdigit() else 1)
    if "周围" in desc or "附近" in desc or "所在竖列" in desc or "所在竖排" in desc:
        return 0
    return 1


def _skill_effect(sid, desc):
    """Only state IDs confirmed in battleState.txt are sent to Flash."""
    tier = sid % 10
    effect = {}
    if 9301 <= sid <= 9305:  # oxygen algae: 2-round regeneration
        effect.update(state=14800 + tier, turns=2, side="allies")
    elif 12451 <= sid <= 12455:  # moonflower basic heal grants reflect
        effect.update(state=19935 + tier, turns=1, side="allies")
    elif 12461 <= sid <= 12465:  # moonflower: 1-round damage increase
        effect.update(state=19600 + sid - 12460, turns=1, side="allies", cleanse=True)
    elif 1001 <= sid <= 1005:  # ice lettuce: 15% freeze for one round
        effect.update(state=100, turns=1, side="enemies", chance=15)
    elif 71 <= sid <= 75:  # five grades of the same charge skill
        effect.update(state=600, turns=2, side="self")
    elif "定身" in desc and "清除" not in desc:
        chance = re.search(r"(\d+)%几率", desc)
        turns = re.search(r"定身(\d+)回合", desc)
        if chance or "有几率" not in desc:
            effect.update(state=100, turns=int(turns[1]) if turns else 1,
                          side="enemies", chance=int(chance[1]) if chance else 100)
    elif "眩晕" in desc and "清除" not in desc:
        chance = re.search(r"(\d+)%几率", desc)
        if chance or "有几率" not in desc:
            effect.update(state=800, turns=2, side="enemies",
                          chance=int(chance[1]) if chance else 100)
    elif "沉默" in desc and "清除" not in desc and 1 <= tier <= 5:
        chance = re.search(r"(\d+)%几率", desc)
        if chance or "有几率" not in desc:
            effect.update(state=17020 + tier, turns=1, side="enemies",
                          chance=int(chance[1]) if chance else 100)
    elif "易伤" in desc and "清除" not in desc:
        percent = re.search(r"(\d+)%易伤", desc)
        if percent:
            ids = [state_id for state_id, param in load_battle_states().items()
                   if param[0] == 13 and param[3] == int(percent[1]) * 100]
            if ids:
                turns = re.search(r"(?:持续|效果持续|效果)(\d+)回合", desc)
                effect.update(state=min(ids), turns=int(turns[1]) if turns else 1,
                              side="enemies")
    if not effect.get("state"):
        # Many skills have no skill->state foreign key.  Match only a percentage
        # and semantic that uniquely identify an existing client state row;
        # unknown mechanics are left unmodelled, never sent as fake buff IDs.
        rules = (
            (r"每回合流血(\d+)%", (4, 3, 206), "enemies"),
            (r"流血(\d+)%", (4, 3, 206), "enemies"),
            (r"每回合回复(\d+)%生命", (3, 3, 206), "allies"),
            (r"防御下降(\d+)%", (4, 2, 202), "enemies"),
            (r"伤害能力削弱(\d+)%", (14, 0, 0), "enemies"),
            (r"伤害和治疗能力削弱(\d+)%", (18, 0, 0), "enemies"),
            (r"获得(\d+)%吸血", (10, 3, 118), "self"),
            (r"获得(\d+)%反伤", (9, 3, 218), "self"),
            (r"(?:获得|提高)(\d+)%攻击加成", (3, 1, 201), "self"),
            (r"获得(\d+)%伤害加成", (15, 0, 0), "allies"),
            (r"获得(\d+)%免伤", (12, 0, 0), "allies"),
            (r"提高自身免伤能力(\d+)%", (12, 0, 0), "self"),
            (r"获得(\d+)%暴击加成", (3, 15, 215), "self"),
            (r"获得(\d+)%生命加成", (3, 6, 206), "allies"),
        )
        state_rows = load_battle_states()
        for pattern, prefix, side in rules:
            match = re.search(pattern, desc)
            if not match:
                continue
            value = int(match[1]) * 100
            ids = [state_id for state_id, param in state_rows.items()
                   if param[:3] == prefix and param[3] == value]
            if ids:
                duration = re.search(r"(?:持续|效果持续|本回合|在)(\d+)回合|(\d+)回合内", desc)
                effect.update(state=min(ids), side=side,
                              turns=int(duration[1] or duration[2]) if duration else 1)
                break
    if "清除队友的定身和沉默" in desc:
        effect["cleanse"] = True
    return effect


def load_skill_info():
    """{skillId: (kind, nTargets)} classified from the skill template's name+desc keywords."""
    global _SKILL_INFO, _SKILL_EFFECTS, _SKILL_DESCS
    if _SKILL_INFO is None:
        _SKILL_INFO = {}
        _SKILL_EFFECTS = {}
        _SKILL_DESCS = {}
        rows = _read_clientdb_table("BattleLineupCardSkillTemplate.txt")
        if rows:
            hdr = rows[0]; ci = {c: i for i, c in enumerate(hdr)}
            for r in rows[1:]:
                def col(k):
                    i = ci.get(k)
                    return r[i] if i is not None and i < len(r) else ""
                try:
                    sid = int(col("id"))
                except ValueError:
                    continue
                text = col("name") + col("desc")
                desc = col("desc")
                _SKILL_DESCS[sid] = desc
                # Secondary clauses often describe a team-wide buff on a
                # single-target attack.  They must not widen the attack.
                primary = re.split(r"，并|,并|并使|并获得", desc, 1)[0]
                n = _skill_target_count(primary)
                _SKILL_EFFECTS[sid] = _skill_effect(sid, desc)
                if re.search(r"(?:治疗|治療)(?:[1-9一二三四五六]个|友方|己方|所有)", primary):
                    _SKILL_INFO[sid] = ("heal", n)
                elif "蓄力" in primary or "攻击加成" in primary:       # self charge/buff
                    _SKILL_INFO[sid] = ("charge", 1)
                elif any(k in primary for k in ("全体增加", "全体攻击", "全体暴击", "全体命中", "全体闪避", "全体普攻", "全体技能", "全体技力", "获得护盾", "提高友方", "为能量未满", "增加当前生命", "自身增加")):
                    _SKILL_INFO[sid] = ("support", n)
                elif any(k in primary for k in ("阵首", "阵中", "阵尾", "周围", "全体", "所有敌")) or n > 1:  # AoE
                    _SKILL_INFO[sid] = ("aoe", n)
                else:                                          # single-target attack
                    _SKILL_INFO[sid] = ("attack", n)
        log.info("loaded skill info for %d skills", len(_SKILL_INFO))
    return _SKILL_INFO


def build_fight_card(pos, card_id, hp, level=1, is_leader=False, max_rage=RAGE_MAX, rage=RAGE_START,
                     power=0, exp=0, speed=0, avatar_id=0, is_help_card=False,
                     power_elements=None, shield=0, max_shield=None, max_hp=None, is_live=True):
    """Dto_FightCardInfo{posIndex(1),cardId(2),hp(3,U64),rage(4),shield(5,U64),maxHp(6,U64),
    maxRage(7),maxShield(8,U64),isLeader(9),level(11),cardPower(16,U64),isLive(17),
    powerEle(18)=[Dto_CardPower{ele(1)=total(0),value(2,I64)=power,speed(3,I64)=先攻}]}.
    maxRage(7) = the number of SEGMENTS the client draws in the skill bar (UnitProgressCtr.changeRageMax
    divides the bar into maxRage pips) -> 3 pips; rage(4) = how many are filled at battle start -> 2/3.
    The replay's per-round changeRage ticks it +1 (see simulate_battle).
    CRITICAL: maxShield(8) and cardPower(16) are U64 OBJECTS. An UNSET U64 reads back as NULL on the
    client, and UnitFactory.updateUnit does `maxShield.toNumber()` (line ~115) -> #1009, plus the report
    coerces cardPower -> #1034. That crash halts the per-unit UpdateUnitPlan, which never setComplete()s,
    so the plan machine stalls on a timeout = the visible battle GAPS. Both MUST be present (0 is fine).
    powerEle(18) is what the battle HUD reads for 先攻 (the "先攻: ???" line next to each side's name is a
    null Int64 -> the client cannot render a number). Like the formation's Dto_CardPosInfo.powerEle it
    must carry BOTH value (战力) and speed (先攻, I64 — same shape build_card_pos uses)."""
    power_ele = (pb_varint_field(1, 0)                       # ele = E_PowerEle_total
                 + pb_int64_field(2, max(0, int(power)))     # value (战力)
                 + pb_int64_field(3, max(0, int(speed))))    # speed (先攻)
    power_fields = pb_tag(18, 2) + uvarint(len(power_ele)) + power_ele
    if power_elements is not None:
        power_fields += _power_element_fields(
            [entry for entry in power_elements if int(entry[0]) != 0], 18)
    if max_shield is None:
        # maxShield = 该单位自己的护盾池（battleCard.initialShield 成长 + 装备加成）。
        # 没有护盾池的单位发 0 —— 客户端对 maxShield=0 的单位不画蓝盾条（原版设计：植物
        # 全员 initialShield=0，只有法老木乃伊 19x/盾卫僵尸 37x 这类带盾僵尸有 3xHP 的盾池）。
        # 若把 maxShield 兜底成 hp//2，客户端会给每个无盾单位画出一条“空盾条”（玩家反馈
        # “植物只有蓝盾条没有盾量”），所以这里绝不能再兜底。
        # simulate_battle 会在战斗结束后把 u["max_shield"] 回写为本场实际达到的盾量峰值，
        # 让队长/傀儡临时盾在无池单位身上也能显示。
        max_shield = max(0, int(shield or 0))
    return (pb_varint_field(1, pos) + pb_varint_field(2, card_id)
            + pb_varint_field(3, hp) + pb_varint_field(4, rage)
            + pb_varint_field(5, max(0, int(shield or 0)))
            + pb_varint_field(6, hp if max_hp is None else max_hp) + pb_varint_field(7, max_rage)
            + pb_varint_field(8, max_shield)
            + pb_varint_field(9, 1 if is_leader else 0)
            + pb_varint_field(10, exp)                                     # exp WITHIN the level (bar fill)
            + pb_varint_field(11, level) + pb_varint_field(15, int(avatar_id))
            + (pb_varint_field(12, 1) if is_help_card else b"")           # borrowed friend, not a result EXP bar
            + pb_varint_field(16, power)      # cardPower
            + pb_varint_field(17, int(is_live))
            + power_fields)                       # powerEle (战力来源 + 先攻)


# Odd posIndex = left/plants, even = right/zombies (BattleConst.isLeft = idx%2==1); 9 slots/side.
_LEFT_POS = [1, 3, 5, 7, 9, 11, 13, 15, 17]
_RIGHT_POS = [2, 4, 6, 8, 10, 12, 14, 16, 18]
# The player's team occupies THESE posIndexes only. The city home-team view (EmbattleCommand.
# addBattleCardViewToCity) creates DragableEmbattlePlant slots at posIndex 3,7,9,11,13,15,17 (7 slots);
# posIndex 1 is reserved for the puppet/dummy and 5 is skipped — a card placed there has no slot and
# the view null-derefs. So formation cardPos MUST use this set (odd = left/plants in the battle too).
_FORMATION_POS = [3, 7, 9, 11, 13, 15, 17]
_FORMATION_MAX = 6                # how many cards we auto-place in the default team
# The ENEMY/zombie side has the SAME reserved-slot rule mirrored: the pre-fight lineup window
# (BattleLineupWindow.initEnemyCardvessel) creates enemy vessels at posIndex 4,8,10,12,14,16,18 only —
# posIndex 2 and 6 are the invisible/reserved slots (like plant 1 and 5). An enemy card at 2/6 has no
# vessel, so lineupUpdateHandler's getCardVesselByPosIndex(false, pos).setData() null-derefs (#1009).
# So zombies MUST use this set (even = right/zombies in the battle too).
_ENEMY_POS = [4, 8, 10, 12, 14, 16, 18]

# REAL per-level enemy composition transcribed from the wiki
# (plantsvszombies.wiki.gg/wiki/Zphinx_-_Day_N). Egypt zombie cards: 111 Mummy, 121 Conehead,
# 131 Buckethead, 141 Flag. Each entry = (cardId, count, wikiHP, power); the FIRST entry's first
# zombie is the leader/boss. Validation: sum of powers == the level's required Fighting Power, and
# wikiHP == power*9 (mummy/flag) or power*10.8 (conehead/buckethead, 1.2x tankier).
_ADVENTURE_LEVELS = {
    1: {   # chapter 1 = Zphinx (Egypt), NORMAL mode. 10 days.
        # 木乃伊一律用法老木乃伊 191（带盾变体，盾=3×HP）：原版埃及关的蓝盾条僵尸。
        # 191 的卡面 EHP(hp 928+盾 2784) 会按比例拆分 wiki HP，总等效血量与原转写一致。
        1:  [(191, 3, 2970, 330)],
        2:  [(191, 3, 2970, 330)],
        3:  [(191, 3, 2970, 330), (141, 1, 2970, 330)],
        4:  [(121, 1, 3888, 360), (141, 2, 3240, 360)],
        5:  [(121, 1, 4212, 390), (191, 2, 3510, 390)],   # conehead leader
        6:  [(121, 2, 3888, 360), (191, 2, 3240, 360)],
        7:  [(121, 2, 4212, 390), (141, 2, 3510, 390)],
        8:  [(121, 1, 4536, 420), (141, 1, 3780, 420), (191, 2, 3780, 420)],
        9:  [(121, 2, 4536, 420), (191, 2, 3780, 420)],
        10: [(131, 1, 5832, 540), (191, 2, 4860, 540)],   # buckethead boss
    },
}
# NOTE: per-stage end-of-battle rewards (Plant EXP item 5 + Coins item 1 every clear; TD Key 4001 + Town
# Prosperity item 2 + plants/items on first clear) come straight from clientDB fuben.txt via
# fuben_stage_reward() — for EVERY chapter, matching the level-select tooltip exactly. (An older
# hand-transcribed ch1-only _ADVENTURE_REWARDS was removed: it duplicated fuben.txt and, merged on top,
# double-granted ch1 loot while giving ch2+ a 0 result-screen exp animation.)


# PACING knob (cosmetic only now): divide the wiki HP by this so the win animation resolves quickly. The
# outcome is decided by POWER (resolve_battle), not by grinding HP, so this only affects how long the
# replay plays. Set to 1 for the real wiki HP.
_ZOMBIE_HP_TEST_DIVISOR = 3
# Enemy atk/def are derived from the zombie's Fighting Power so tougher stages visibly hit harder in the
# replay. These feed the ANIMATION only (win/loss is power-decided), so they're tuned for believable
# on-screen damage, not balance.
_ENEMY_ATK_FROM_POWER = 1.0
_ENEMY_DEF_FROM_POWER = 0.10
# Difficulty (BALANCED): the team WINS when its effective Fighting Power (card levels + Lab + World Tree)
# reaches this fraction of the enemy's total power. 1.0 = you must out-power the enemy; a little under 1
# gives slack so a marginal team can still squeak a win. Raise toward/over 1 for a harder game.
_WIN_POWER_RATIO = 0.95
# Within-chapter Fighting-Power ramp (per stage past 1) for untranscribed chapters. ~0.07 matches the
# spread the wiki shows across chapter 1 (stage1 990 -> stage10 ~1620, ~1.63x over 10 stages).
_FALLBACK_STAGE_SCALE = 0.07


def _chapter_base_power(chapter):
    """Total enemy Fighting Power at STAGE 1 of a chapter, calibrated to the wiki (user-supplied,
    2026-07-14): ch1-4 = 990 / 2550 / 5220 / 9000. Those fit the EXACT quadratic 555*ch^2 - 105*ch + 540
    (constant 2nd difference 1110), which we extrapolate for the deeper untranscribed chapters."""
    return max(1, 555 * chapter * chapter - 105 * chapter + 540)


def _enemy_atk_def(power):
    """(atk, def_) for a zombie of the given Fighting Power — replay-damage only, scaled off power."""
    return max(1, int(power * _ENEMY_ATK_FROM_POWER)), max(0, int(power * _ENEMY_DEF_FROM_POWER))
# Themed zombie families by WORLD (star-1 base cardIds from battleCard.txt), so a chapter's fallback
# enemies fit its setting instead of the generic 小偷僵尸 (thief) placeholder. Chapter->world is from the
# FubenChapterTemplate names: ch1-6 Ancient Egypt / Egyptian Market, 7-8 Great Wall, 9-12 Pirate Seas,
# 13-15 Far Future / Mecha. (Egypt mummies are proven in ch1; the later-world families exist in
# battleCard.txt but their in-battle assets are unverified — swap any that fail to render.)
_WORLD_ZOMBIES = {
    # 埃及：法老木乃伊用带盾变体 191（盾=3×HP，客户端蓝盾条的出处）。190 是无盾基础卡，
    # 场上不显示蓝盾条（玩家反馈“僵尸没有蓝盾条”）。
    "egypt":     [111, 121, 131, 141, 150, 161, 171, 181, 191],  # 木乃伊/路障/铁桶/摇旗/太阳神/骆驼/火炬/造墓/法老(带盾)
    "greatwall": [310, 320, 330, 350, 371, 380, 400, 410],        # 军士/顶碗/铁盔/弓箭/盾卫(带盾)/推车/骑兵/令牌
    "pirate":    [430, 440, 450, 460, 470, 480, 490, 500],        # 醉酒/滚筒/海鸥/海盗巨人/小鬼/杂耍/猴子/摇旗水手
    "future":    [200, 202, 201, 206, 204, 207, 254],             # 喷射器/机甲路障/电磁盾/机甲橄榄球/迪斯科/机甲巨人/喷射器舞者
    "sea":       [771, 781, 791, 801, 817, 818, 820, 841, 851, 861, 871, 881, 891],  # 海带/虾兵/螺兵/海马/蚌仙/龟丞相/河豚/水母/海夜叉/分裂/深海力士
}
_CHAPTER_WORLD = {
    1: "egypt", 2: "egypt", 3: "egypt", 4: "egypt", 5: "egypt", 6: "egypt",
    7: "greatwall", 8: "greatwall",
    9: "pirate", 10: "pirate", 11: "pirate", 12: "pirate",
    13: "future", 14: "future", 15: "future",
    16: "sea", 17: "sea", 18: "sea", 19: "sea", 20: "sea",   # 海底龙宫
}
_DEFAULT_ENEMY_CARDS = [111, 121, 131, 141]   # Egypt mummies — default for deeper/unmapped chapters


def chapter_enemy_cards(chapter):
    """Themed zombie cardIds for a chapter's world (Egypt mummies if the chapter isn't mapped)."""
    return _WORLD_ZOMBIES.get(_CHAPTER_WORLD.get(chapter, "egypt"), _DEFAULT_ENEMY_CARDS)


# --- formation / lineup (the backyard team editor) --------------------------------
def _legacy_formation_placements(player):
    """Return the old insertion-order auto lineup used by early server builds.

    Older saves were initialized with the first six rows in ``cards``.  Those rows
    are usually the starter/white cards, even when the account already owns much
    stronger upgraded cards later in the collection.  Keeping this helper separate
    lets us migrate only that unmistakable generated layout without overwriting a
    lineup the player actually chose.
    """
    return {
        _FORMATION_POS[i]: row[0]
        for i, row in enumerate(store.get_cards(player["uin"])[:_FORMATION_MAX])
    }


def _preferred_formation_placements(player):
    """Choose a useful initial team from the player's real collection.

    This is used only when no explicit lineup exists (or when migrating the old
    first-six auto lineup).  Existing manually saved positions remain untouched.
    Higher card level/star/power wins, so a newly opened adventure no longer
    replaces a developed account with low-level white starter cards.
    """
    load_battle_cards()
    cards = list(store.get_cards(player["uin"]))

    def score(row):
        _uid, cid, level, exp = row
        template = _BATTLE_CARDS.get(cid) or {}
        star = int(template.get("star", 1) or 1)
        try:
            power = card_power(card_stats_at_level(cid, max(1, int(level))))
        except Exception:
            power = 0
        return (int(level), star, power, int(exp), int(cid))

    cards.sort(key=score, reverse=True)
    return {
        _FORMATION_POS[i]: row[0]
        for i, row in enumerate(cards[:_FORMATION_MAX])
    }


def default_formation_placements(player):
    """{posIndex: uid} for the player's battle team (team 1). Their SAVED layout if it uses valid slots,
    else auto-place their collection cards on _FORMATION_POS and persist it, so the backyard lineup +
    adventure battles start with a real team instead of empty.  A legacy insertion-order auto lineup is
    migrated to the strongest cards once; manually chosen layouts are preserved."""
    uin = player["uin"]
    # Adventure stores a borrowed friend in this same table, marked with
    # ownerRoleId.  It is not one of the player's owned card UIDs, so the
    # ordinary/home lineup must ignore that position instead of treating the
    # whole saved formation as corrupt and replacing it with starter cards.
    saved_with_owner = store.get_formation_with_owner(uin, 1)
    saved = {int(pos): int(uid) for pos, (uid, owner) in saved_with_owner.items()
             if not int(owner or 0)}
    owned_uids = {int(uid) for uid, _cid, _lvl, _exp in store.get_cards(uin)}
    # Keep a saved layout only if every slot and UID is valid. Old saves can
    # contain a recycled/migrated card; returning that UID makes the client
    # resolve a null card template and crash in CardItemWithBitmap.
    if saved and all(pos in _FORMATION_POS and int(uid) in owned_uids
                     for pos, uid in saved.items()):
        # This exact shape was generated by the old server, not selected by the
        # player.  Replace it with the strongest owned cards so existing saves are
        # repaired without touching a real custom formation.
        if len(saved) == min(_FORMATION_MAX, len(owned_uids)) \
                and saved == _legacy_formation_placements(player):
            placements = _preferred_formation_placements(player)
            if placements and placements != saved:
                store.set_formation(uin, 1, placements)
                log.info("    migrated legacy battle lineup to developed cards: %s", placements)
                return placements
        return saved
    placements = _preferred_formation_placements(player)
    if placements:
        store.set_formation(uin, 1, placements)
    return placements


def build_card_pos(pos, uid, role_id, hp, power, speed=0, power_elements=None):
    """Dto_CardPosInfo{posIndex(1), uid(2,I64), ownerRoleId(3,I64), curHp(4,U64), maxHp(5,U64),
    powerEle(6)=[Dto_CardPower{ele=total(0), value(2,I64)=power, speed(3,I64)=先攻}]}.
    - ownerRoleId is OMITTED (null): a card with a null owner is treated as the PLAYER'S OWN. Setting it
      (even to the real roleId) risks the client reading the card as a borrowed/help card -> "该植物不在
      家园中，不能移动他" (can't move a plant that isn't in your home). Note Int64(0) would still read as
      "someone else's" (the check is `if(ownerRoleId && ...)` and an Int64 object is truthy), so we must
      truly omit the field, not send 0.
    - powerEle needs BOTH value (totalPower) AND speed (totalSpeed) or BattleCardFormationVO.totalSpeed
      does .toNumber() on a null Int64 and #1009-crashes the backyard every frame.
    - speed = the plant's 先攻 (from 洗炼 — the only 先攻 source this server models). BattleCardFormationVO
      derives the lineup's 总先攻 by summing the cardPos speeds, so 0 made it print 总先攻 0."""
    power_ele = (pb_varint_field(1, 0) + pb_int64_field(2, power)     # Dto_CardPower{ele=total, value}
                 + pb_int64_field(3, max(0, int(speed or 0))))        # speed = 先攻 (present, non-null)
    power_fields = pb_tag(6, 2) + uvarint(len(power_ele)) + power_ele
    if power_elements is not None:
        power_fields += b"".join(
            pb_tag(6, 2) + uvarint(len(body)) + body
            for element, value, source_speed in power_elements if int(element) != 0
            for body in [_dto_card_power_element(element, value, source_speed)])
    return (pb_varint_field(1, pos) + pb_int64_field(2, uid)          # posIndex, uid (NO ownerRoleId)
            + pb_varint_field(4, hp) + pb_varint_field(5, hp)
            + power_fields)


def build_card_pos_fuben(pos, uid, role_id, hp, power, owner_role_id=0,
                         power_elements=None, speed=0):
    """Adventure-lineup variant of Dto_CardPosInfo with borrowed-card ownership."""
    power_ele = (pb_varint_field(1, 0) + pb_int64_field(2, power)
                 + pb_int64_field(3, max(0, int(speed or 0))))
    power_fields = pb_tag(6, 2) + uvarint(len(power_ele)) + power_ele
    if power_elements is not None:
        power_fields += b"".join(
            pb_tag(6, 2) + uvarint(len(body)) + body
            for element, value, source_speed in power_elements if int(element) != 0
            for body in [_dto_card_power_element(element, value, source_speed)])
    d = pb_varint_field(1, pos) + pb_int64_field(2, uid)
    if owner_role_id:
        d += pb_int64_field(3, owner_role_id)
    return (d + pb_varint_field(4, hp) + pb_varint_field(5, hp)
            + power_fields)


def build_formation_info_fuben(player, team_id, placements, owner_roles=None):
    """Build an adventure formation while retaining one friend's ownerRoleId.

    A borrowed card's UID must match ``Dto_FriendInfo.helpPlant.base.uid``.  The
    old response used the friend's role id as the slot UID, so the client could
    not resolve the selected friend card and later passed cardId=0 into its
    lineup renderer.
    """
    load_battle_cards()
    uin = player["uin"]
    role_id = player.get("role_id", uin)
    card_by_uid = {uid: (cid, lvl) for uid, cid, lvl, _exp in store.get_cards(uin)}
    bonus = deployed_stat_bonus(player)
    owner_roles = owner_roles or {}
    cardpos_b, total_power, leader_uid = b"", 0, 0
    for pos in sorted(placements):
        uid = int(placements[pos] or 0)
        owner = int(owner_roles.get(pos, 0) or 0)
        cid, lvl = card_by_uid.get(uid, (0, 1))
        if owner and owner != int(role_id or uin):
            friend = store.get_friend_by_role_id(uin, owner) or {}
            friend_uid, cid, lvl, _friend_stats = _friend_help_card(friend)
            uid = friend_uid
        elif uid not in card_by_uid:
            # Never emit a CardPosInfo for a deleted/stale UID.  The client
            # resolves card details from the package by UID and a missing row
            # becomes a null card template (#1009 in CardItemWithBitmap).
            log.warning("    skipping stale fuben card uid=%d at pos=%d", uid, pos)
            continue
        st = effective_card_stats(player, cid, lvl, bonus, uid=uid) if cid in _BATTLE_CARDS else {}
        power = card_power(st) if st else 0
        total_power += power
        if leader_uid == 0:
            leader_uid = uid
        power_elements = (_card_power_source_elements(
            player, uid, cid, lvl, include_deployed=True) if not owner and cid in _BATTLE_CARDS else None)
        cp = build_card_pos_fuben(
            pos, uid, role_id, st.get("hp", 0), power, owner,
            power_elements=power_elements, speed=st.get("refine_speed", 0))
        cardpos_b += pb_tag(1, 2) + uvarint(len(cp)) + cp
    saved_leader = store.get_formation_leader(uin, team_id)
    if saved_leader in placements.values():
        leader_uid = saved_leader
    return (cardpos_b + pb_varint_field(2, 1) + pb_int64_field(3, leader_uid)
            + pb_varint_field(4, total_power) + pb_varint_field(5, team_id)
            + pb_varint_field(6, 0) + pb_varint_field(8, 0))


def _fuben_formation_entries(player):
    """Return a normalized ``(placements, owner_roles)`` pair for adventure.

    Local cards must exist in the player's collection.  Borrowed cards must
    still point at an existing friend row; their displayed UID is canonicalized
    later by :func:`build_formation_info_fuben` to the friend's helpPlant UID.
    """
    ensure_player_cards(player)
    my_role_id = int(player.get("role_id") or player["uin"])
    saved = store.get_formation_with_owner(player["uin"], 1)
    owned_uids = {int(uid) for uid, _cid, _lvl, _exp in store.get_cards(player["uin"])}
    # The adventure lineup used to be initialized independently from the
    # backyard lineup, using the first six rows in the card table.  That table
    # starts with the white starter cards, so every adventure entry silently
    # reset a developed account back to those cards.  Migrate only that exact
    # legacy shape; a lineup the player explicitly arranged (or one containing
    # a borrowed friend) must remain untouched.
    if saved and all(not int(owner or 0) for _pos, (_uid, owner) in saved.items()):
        raw_saved = {int(pos): int(uid) for pos, (uid, _owner) in saved.items()}
        legacy = _legacy_formation_placements(player)
        if (len(raw_saved) == min(_FORMATION_MAX, len(owned_uids))
                and raw_saved == legacy):
            preferred = default_formation_placements(player)
            if preferred and preferred != raw_saved:
                saved = {pos: (uid, 0) for pos, uid in preferred.items()}
                store.set_formation(player["uin"], 1, preferred)
                log.info("    migrated legacy fuben lineup to developed cards: %s", preferred)
    # Initialize a missing team only. A partial saved lineup is intentional:
    # removing a card or moving the friend must never auto-deploy another card.
    if not saved:
        saved = {pos: (uid, 0) for pos, uid in
                 default_formation_placements(player).items()}
    valid = {}
    seen_owned = set()
    has_friend = False
    for pos, (uid, owner) in sorted(saved.items()):
        if pos not in _FORMATION_POS:
            continue
        uid, owner = int(uid), int(owner or 0)
        if owner and owner != my_role_id:
            if not has_friend and store.get_friend_by_role_id(player["uin"], owner):
                valid[pos] = (uid, owner)
                has_friend = True
        elif uid in owned_uids and uid not in seen_owned and len(seen_owned) < _FORMATION_MAX:
            valid[pos] = (uid, 0)
            seen_owned.add(uid)
    placements = {pos: uid for pos, (uid, _owner) in valid.items()}
    owners = {pos: owner for pos, (_uid, owner) in valid.items()
              if owner and owner != my_role_id}
    # Persist the cleaned layout so the stale UID cannot return on the next
    # request.  This is idempotent for an already valid layout.
    saved_entries = {pos: (int(uid), int(owner or 0)) for pos, (uid, owner) in saved.items()
                     if pos in _FORMATION_POS}
    if valid != saved_entries:
        store.set_formation(player["uin"], 1, placements, owners)
    return placements, owners


def build_formation_info(player, team_id, placements):
    """Dto_FormationInfo{cardPos(1)=[Dto_CardPosInfo], formationId(2), leaderUid(3,I64),
    totalPower(4,U64), teamId(5), status(6)=home(1,editable), isDefend(8)=0}."""
    load_battle_cards()
    uin = player["uin"]; role_id = player.get("role_id", uin)
    card_by_uid = {uid: (cid, lvl) for uid, cid, lvl, _exp in store.get_cards(uin)}
    bonus = deployed_stat_bonus(player)             # Lab + World Tree boost on every deployed plant
    cardpos_b, total_power, leader_uid = b"", 0, 0
    for pos in sorted(placements):
        uid = placements[pos]
        cid, lvl = card_by_uid.get(uid, (uid, 1))
        st = effective_card_stats(player, cid, lvl, bonus, uid=uid) if cid in _BATTLE_CARDS else {}
        power = card_power(st) if st else 0
        total_power += power
        if leader_uid == 0:
            leader_uid = uid
        power_elements = (_card_power_source_elements(
            player, uid, cid, lvl, include_deployed=True) if cid in _BATTLE_CARDS else None)
        cp = build_card_pos(pos, uid, role_id, st.get("hp", 0), power,
                            st.get("refine_speed", 0), power_elements=power_elements)
        cardpos_b += pb_tag(1, 2) + uvarint(len(cp)) + cp
    saved_leader = store.get_formation_leader(uin, team_id)
    if saved_leader in placements.values():
        leader_uid = saved_leader
    return (cardpos_b + pb_varint_field(2, 1)                # formationId
            + pb_int64_field(3, leader_uid)                  # leaderUid
            + pb_varint_field(4, total_power)                # totalPower (U64)
            + pb_varint_field(5, team_id)                    # teamId
            + pb_varint_field(6, 0)      # status = E_TeamStatus_home(0), EDITABLE. status=1 = _out =
                                         # "出征中" -> client blocks moving plants / editing formation.
            + pb_varint_field(8, 0))                         # isDefend = 0 (attack team)


def handle_battle_getformation(cmd_data, player):
    """Cmd_Battle_GetFormation_CS -> Cmd_Battle_GetFormation_SC{formation(1), team(2)=[Dto_FormationInfo],
    teamMaxNum(3), defaultTeamId(4)}. The player's battle team, loaded into battleCardModel at login
    (updateEmbattleCardTeam) and shown/edited in the backyard lineup. Pre-filled with the player's cards
    so the lineup isn't empty and the pre-fight lineup window can render the player side."""
    ensure_player_cards(player)
    placements = default_formation_placements(player)
    formation = build_formation_info(player, 1, placements)
    team = pb_tag(2, 2) + uvarint(len(formation)) + formation        # team (field 2, repeated)
    log.info("    battle GET formation: %d cards %s", len(placements), placements)
    return (pb_tag(1, 2) + uvarint(len(formation)) + formation       # formation (field 1)
            + team + pb_varint_field(3, 1) + pb_varint_field(4, 1))   # teamMaxNum=1, defaultTeamId=1


def handle_battle_setformation(cmd_data, player):
    """Cmd_Battle_SetFormation_CS{formation(1)=Dto_FormationInfo} -> persist the player's chosen team.
    Parse cardPos -> {posIndex: uid}. There's no Cmd_Battle_SetFormation_SC; setLineup does NOT update
    the local formation VO, so the client only refreshes the lineup once the server SENDS the updated
    team back — so we re-push Cmd_Battle_GetFormation_SC (its handler = updateEmbattleCardTeam + dispatch
    LINEUP_UPDATE, which rebuilds the backyard view). Without this the drag appears to do nothing."""
    placements, team_id, leader_uid = {}, 1, 0
    fsub = parse_repeated_submessages(cmd_data, 1)
    if fsub:
        team_id = parse_varint_fields(fsub[0]).get(5, 1) or 1
        leader_uid = parse_varint_fields(fsub[0]).get(3, 0)
        for cp in parse_repeated_submessages(fsub[0], 1):            # cardPos
            c = parse_varint_fields(cp)
            pos, uid = c.get(1, 0), c.get(2, 0)
            if pos and uid:
                placements[pos] = uid
    store.set_formation(player["uin"], team_id, placements)
    if leader_uid in placements.values():
        store.set_formation_leader(player["uin"], team_id, leader_uid)
    log.info("    battle SET formation team=%d: %s", team_id, placements)
    return [("PVZ.Cmd.Cmd_Battle_GetFormation_SC", handle_battle_getformation(b"", player))]


def handle_fuben_getformation(cmd_data, player):
    """Return the adventure formation, including a borrowed friend's ownerRoleId."""
    note_battle_scene(player, "fuben")      # the lineup window will request the authoritative enemy preview
    placements, owners = _fuben_formation_entries(player)
    formation = build_formation_info_fuben(player, 1, placements, owners)
    log.info("    fuben GET formation: %d cards %s owner_roles=%s", len(placements), placements, owners)
    return pb_tag(1, 2) + uvarint(len(formation)) + formation        # formation (field 1)


def handle_fuben_getformation_messages(cmd_data, player):
    """Return friend-card cache before the adventure formation.

    After a friend-card battle the Flash client clears/rebuilds its temporary
    ``helpCardInfo`` list asynchronously.  Sending only the formation leaves a
    borrowed UID with no matching ``Dto_FriendInfo.helpPlant``; the next
    ``CardItemWithBitmap.setData`` then dereferences null and raises #1009.
    Re-send moduleType=5 (FUBEN_PLANT) first whenever this formation contains a
    borrowed friend card, then send the authoritative formation.
    """
    body = handle_fuben_getformation(cmd_data, player)
    _placements, owners = _fuben_formation_entries(player)
    if owners:
        friend_req = (pb_varint_field(1, 5) + pb_varint_field(2, 0)
                      + pb_varint_field(3, 0) + pb_varint_field(4, 8))
        friend_body = handle_friend_getlist(friend_req, player)
        return [("PVZ.Cmd.Cmd_Friend_GetList_SC", friend_body),
                ("PVZ.Cmd.Cmd_Fuben_GetFormation_SC", body)]
    return [("PVZ.Cmd.Cmd_Fuben_GetFormation_SC", body)]


def handle_fuben_setformation(cmd_data, player):
    """Persist an adventure lineup with at most one borrowed friend card."""
    my_role_id = int(player.get("role_id") or player["uin"])
    placements = {}
    owner_roles = {}
    seen_cards = set()
    fsub = parse_repeated_submessages(cmd_data, 1)
    if fsub:
        for cp in parse_repeated_submessages(fsub[0], 1):            # cardPos
            c = parse_varint_fields(cp)
            pos, uid, owner = c.get(1, 0), c.get(2, 0), c.get(3, 0)
            if pos and uid:
                identity = (owner if owner and owner != my_role_id else 0, uid)
                if pos not in _FORMATION_POS or pos in placements or identity in seen_cards:
                    log.warning("    fuben SET formation rejected: duplicate/invalid slot or card")
                    return handle_fuben_getformation_messages(b"", player)
                seen_cards.add(identity)
                placements[pos] = uid
                if owner and owner != my_role_id:
                    owner_roles[pos] = owner
    self_count = sum(1 for pos in placements if pos not in owner_roles)
    if self_count > 6 or len(owner_roles) > 1:
        log.warning("    fuben SET formation rejected: self=%d friend=%d", self_count, len(owner_roles))
        return handle_fuben_getformation_messages(b"", player)
    if placements:
        store.set_formation(player["uin"], 1, placements, owner_roles)
    log.info("    fuben SET formation: %s owner_roles=%s", placements, owner_roles)
    return handle_fuben_getformation_messages(b"", player)


def build_player_units(player, placements=None, owner_roles=None):
    """The player's LINEUP (their saved formation) as battle-card units (first placed = leader), with each
    plant's effective stats (card level + Lab + World Tree). Shared by adventure AND Trial Road, so both
    fight with the same team + investment. `placements` overrides the saved team (the zombie island
    fields the lineup arranged in its own prepare view). Returns [{pos,card_id,hp,atk,def_,skill1,
    skill2,level,is_leader,name,power,speed,uid,exp}] — `speed` is the plant's 先攻 (from 洗炼, the only
    先攻 source this server models) which the battle report sends both per card (powerEle) and per side
    (totalSpeed)."""
    load_battle_cards()
    left = []
    if placements is None:
        placements = default_formation_placements(player)
    owner_roles = owner_roles or {}
    my_role_id = int(player.get("role_id") or player["uin"])
    card_by_uid = {uid: (cid, lvl, exp) for uid, cid, lvl, exp in store.get_cards(player["uin"])}
    bonus = deployed_stat_bonus(player)             # Lab + World Tree boost on every deployed plant
    saved_leader = store.get_formation_leader(player["uin"], 1)
    if saved_leader not in placements.values():
        saved_leader = next(iter(placements.values()), 0)
    for pos in sorted(placements):
        uid = int(placements[pos] or 0)
        owner = int(owner_roles.get(pos, 0) or 0)
        if owner and owner != my_role_id:
            friend = store.get_friend_by_role_id(player["uin"], owner)
            if not friend:
                continue
            uid, card_id, level, st = _friend_help_card(friend)
            exp = 0
            st = dict(st)
            for field in ("atk", "def_", "hp", "ability", "hit", "dodge", "critical", "tough"):
                st[field] = st.get(field, 0) + bonus.get(field, 0)
            avatar_id = 0
            is_help_card = True
        else:
            card_id, level, exp = card_by_uid.get(uid, (uid, 1, 0))
            if card_id not in _BATTLE_CARDS:
                continue
            st = effective_card_stats(player, card_id, level, bonus, uid=uid)
            avatar_id = _card_avatar_selected(player, uid,
                                               (uid, card_id, level, exp))
            is_help_card = False
        if card_id not in _BATTLE_CARDS:
            continue
        power = card_power(st)
        power_elements = (_card_power_source_elements(
            player, uid, card_id, level, include_deployed=True) if not is_help_card else None)
        left.append({"pos": pos, "card_id": card_id, "hp": st["hp"], "atk": st["atk"],
                     "def_": st["def_"], "hit": st.get("hit", 0), "dodge": st.get("dodge", 0),
                     "critical": st.get("critical", 0), "tough": st.get("tough", 0),
                     "shield": max(0, int(st.get("shield", 0) or 0)),   # 蓝盾血池（battleCard + 装备）
                     "skill1": st["skill1"], "skill2": st.get("skill2", 0),
                     "level": level, "is_leader": uid == saved_leader, "name": st["name"],
                     "power": power,                     # effective power (feeds the win/loss decision)
                     "speed": int(st.get("refine_speed", 0) or 0),   # 先攻 -> the battle HUD's 先攻 total
                     "power_elements": power_elements,
                     "uid": uid, "exp": exp,
                     "avatar_id": avatar_id, "is_help_card": is_help_card})
    return left


def build_battle_units(player, chapter, mode, stage):
    """Fabricate the two teams. left = the player's LINEUP; right = a few stage zombies. Returns
    (left_units, right_units). Battle == the backyard lineup."""
    if chapter and mode and stage:
        fuben_placements, fuben_owners = _fuben_formation_entries(player)
        left = build_player_units(player, fuben_placements, fuben_owners)
    else:
        left = build_player_units(player)
    # Right: the stage's zombies. If we have the REAL wiki composition for this (chapter, stage) use it
    # (exact types/counts/HP/power); HP is divided by _ZOMBIE_HP_TEST_DIVISOR for testing. Otherwise
    # fall back to a themed, adaptive-HP squad so un-transcribed chapters still play.
    right = _build_wiki_enemies(chapter, stage) or _build_fallback_enemies(chapter, stage)
    return left, right


def _zombie_hp_shield_split(card_id, zst, ehp):
    """带盾僵尸家族（法老木乃伊 19x / 盾卫僵尸 37x，客户端卡面盾=3×HP，蓝盾条的出处）把该档
    等效总血量 ehp 按卡面原生 hp:shield 比例拆成血池+盾池；无盾卡全部给血池。返回 (hp, shield)。
    总 EHP 不变，所以既有的 power 校验 / 胜负 / 奖励节奏都不受影响，只是战斗表现为先削蓝盾。"""
    native_shield = max(0, int((zst or {}).get("shield", 0) or 0))
    if native_shield <= 0:
        return max(1, int(ehp)), 0
    native_hp = max(1, int((zst or {}).get("hp", 1) or 1))
    total = native_hp + native_shield
    hp = max(1, int(ehp) * native_hp // total)
    return hp, max(1, int(ehp) - hp)


def _build_wiki_enemies(chapter, stage):
    """Real per-level enemies from _ADVENTURE_LEVELS, or None if this level isn't transcribed yet."""
    level = _ADVENTURE_LEVELS.get(chapter, {}).get(stage)
    if not level:
        return None
    right, i = [], 0
    for card_id, count, wiki_hp, power in level:
        zst = _BATTLE_CARDS.get(card_id, {"skill1": 0, "skill2": 0, "name": "Zombie"})
        atk, dfn = _enemy_atk_def(power)
        # 带盾僵尸（法老木乃伊/盾卫僵尸家族）把该档总血量按卡面比例拆成血+盾；
        # 总等效血量(EHP)不变，胜负(power 决定)与奖励节奏都不受影响。
        hp, sh = _zombie_hp_shield_split(card_id, zst, wiki_hp // _ZOMBIE_HP_TEST_DIVISOR)
        for _ in range(count):
            if i >= len(_ENEMY_POS):
                break
            right.append({"pos": _ENEMY_POS[i], "card_id": card_id, "hp": hp, "atk": atk, "def_": dfn,
                          "skill1": zst.get("skill1", 0), "skill2": zst.get("skill2", 0), "level": 1,
                          "shield": sh,
                          "is_leader": i == 0, "power": power, "name": zst.get("name", "Zombie")})
            i += 1
    return right


def _build_fallback_enemies(chapter, stage):
    """Themed zombie squad for a level with no transcribed composition. The picks come from a STAGE
    SEEDED rng (not the global `random`), so the same (chapter, stage) always rolls the same zombies —
    the pre-fight preview and the fight itself must agree on what is standing on the lawn."""
    enemy_cards = [c for c in chapter_enemy_cards(chapter) if c in _BATTLE_CARDS] \
        or [c for c in _DEFAULT_ENEMY_CARDS if c in _BATTLE_CARDS] \
        or [next(iter(_BATTLE_CARDS), 111)]
    total_power = _chapter_base_power(chapter) * (1 + _FALLBACK_STAGE_SCALE * (stage - 1))
    zombie_count = max(1, min(3 + (stage - 1) // 2, len(_ENEMY_POS)))
    z_power = max(1, int(total_power / zombie_count))
    z_hp = max(1, z_power * 9 // _ZOMBIE_HP_TEST_DIVISOR)
    atk, dfn = _enemy_atk_def(z_power)
    rng = _stage_rng("fallback", chapter, stage)
    # 随机抽，同场不重复；卡池不够再从头补
    picks = rng.sample(enemy_cards, min(zombie_count, len(enemy_cards)))
    while len(picks) < zombie_count:
        picks.append(rng.choice(enemy_cards))
    right = []
    for i in range(zombie_count):
        zc = picks[i]
        zst = _BATTLE_CARDS.get(zc, {"skill1": 0, "name": "Zombie"})
        hp, sh = _zombie_hp_shield_split(zc, zst, z_hp)
        right.append({"pos": _ENEMY_POS[i], "card_id": zc, "hp": hp, "atk": atk, "def_": dfn,
                      "skill1": zst.get("skill1", 0), "skill2": zst.get("skill2", 0), "level": 1,
                      "shield": sh,
                      "is_leader": i == 0, "power": z_power, "name": zst.get("name", "Zombie")})
    return right


# --- pre-fight preview == the fight itself ---------------------------------------
# The client ALWAYS shows the enemy squad first: BattleLineupWindow.preFight_PVE asks for
# Cmd_Battle_GetFightInfo_CS (a fight in the activity dungeon uses Cmd_Battle_GetActivityFubenFightInfo_CS)
# and paints the Dto_EnemyCardInfo zombies the SC carries into the lineup window. The fight that follows
# must field EXACTLY those zombies, or the player previews one squad and fights another (the reported
# "僵尸种类不一致" bug). Two things used to break that:
#   1. The preview request only carries ids we can read for an ADVENTURE target: fubenChapterId(2) /
#      fubenModeId(3) / fubenStageId(4). Trial Road / Nightmare / Gene Trial put their own ids
#      (screwUpStageId / geneTestStageId) in the same Dto_BattleTarget and those arrive as 0/0/0 — the
#      preview then fell back to a random themed squad while the fight used the mode's real one.
#   2. The fallback squad used the global `random`, so even two identical requests disagreed.
# Fix: (a) every squad generator is now deterministic for a given stage (_stage_rng), (b) the preview
# resolves a 0/0/0 target through the battle scene the client just opened, so it shows THAT mode's real
# squad, and (c) whatever the preview showed is stamped onto the fight's own units (types only — hp/atk/
# power/balance stay the fight's), which makes the pre-fight lineup authoritative for every mode.

_BATTLE_SCENES = {}      # uin -> (scene, ts): the last battle scene the client opened
_PENDING_PREVIEW = {}    # uin -> {"ts","family","key","label","cards":[(pos, cardId)]}
_PREVIEW_TTL = 600       # seconds a stored preview stays authoritative for the next fight
_SCENE_HINT_TTL = 1800   # a remembered scene older than this is ignored (fresh session)
_SCENE_FAMILY = {"fuben": "fuben", "activity": "activity",
                 "screwup": "screwup", "newscrewup": "screwup", "gene": "gene",
                 "zombieisland": "island", "newzombieisland": "island",
                 "puppetfuben": "puppetfuben"}


def note_battle_scene(player, scene):
    """Record which battle scene the client is in. Every scene calls this from its own GetInfo /
    GetFormation request, i.e. BEFORE its lineup window asks for the enemy preview."""
    uin = player.get("uin")
    if uin:
        _BATTLE_SCENES[uin] = (scene, time.time())
    player["_battle_scene"] = scene


def _battle_scene(player):
    """Scene tag of the most recent battle-scene request ('' when unknown)."""
    scene = player.get("_battle_scene")
    if scene:
        return scene
    entry = _BATTLE_SCENES.get(player.get("uin"))
    if entry and time.time() - entry[1] <= _SCENE_HINT_TTL:
        return entry[0]
    return ""


def _stage_rng(*parts):
    """Stable RNG for one battle's enemy composition (FNV-1a over the parts): the same stage always
    rolls the same zombies, so a preview and the fight that follows can never disagree."""
    seed = 2166136261
    for part in parts:
        if isinstance(part, str):
            part = sum((ord(ch) & 0xFF) << (8 * (i % 4)) for i, ch in enumerate(part)) or 0
        seed = ((seed ^ (int(part) & 0xFFFFFFFF)) * 16777619) & 0xFFFFFFFF
    return random.Random(seed)


def preview_enemy_units(player, chapter, mode, stage, target_type=0, sub=0):
    """The enemy squad the pre-fight lineup window shows for a Cmd_Battle_GetFightInfo_CS target. It is
    built with the SAME builder the matching fight uses and remembered as the authoritative lineup.
    `sub` is the mode-specific wave (傀儡战境's puppetFubenSubStageId)."""
    if target_type == _DUMMY_FUBEN_TARGET:                  # 傀儡战境 (BattleTargetType 22)
        d_mode = int(mode or _DUMMY_MODE_EASY)
        d_chapter, d_stage = int(chapter or 1), int(stage or 1)
        wave = int(sub or 0) or _puppet_fuben_next_wave(player, d_mode, d_chapter, d_stage)
        fp = float((load_dummy_config()["waves"].get((d_mode, d_chapter, d_stage, wave))
                    or {}).get("fp") or 0)
        units = _tr_enemy_squad(max(1, int(fp)), d_chapter * 100 + d_stage * 10 + wave)
        remember_battle_preview(player, units, _DUMMY_FUBEN_SCENE,
                                _puppet_fuben_key(d_mode, d_chapter, d_stage, wave),
                                label="preview:puppetfuben:%d/%d/%d/%d" % (d_mode, d_chapter, d_stage,
                                                                            wave))
        return units
    if target_type == _NOEND_FUBEN_TARGET:                  # 无尽炼狱 (BattleTargetType 26)
        # mode/sub carry noEndFubenModeId / noEndFubenStageId (Dto_BattleTarget 22/23). Without this
        # branch the window fell through to the generic "unknown" squad while the fight built its own.
        stage_no = max(1, int(sub or stage or 1))
        units = _noend_fuben_squad(stage_no)
        remember_battle_preview(player, units, "noend", "noend/%d" % stage_no,
                                label="preview:noend:floor%d" % stage_no)
        return units
    if chapter and stage:                                   # adventure (fuben) target
        units = _build_wiki_enemies(chapter, stage) or _build_fallback_enemies(chapter, stage)
        family, key = "fuben", "%d/%d/%d" % (chapter, mode, stage)
    elif target_type in _ZI_TARGET_MODE:                    # zombie island (target type 9 / 21)
        zi_mode = _ZI_TARGET_MODE[target_type]
        zi_level = _zi_next_level(player, zi_mode)
        units, key = _zi_enemy_units(zi_mode, zi_level), _zi_fight_key(zi_mode, zi_level)
        family = "island"
    else:
        # A 0/0/0 fuben target = one of the modes that carries its own id. Follow the scene the client
        # just opened so the window shows that mode's real squad (see the note above).
        scene = _battle_scene(player)
        family = _SCENE_FAMILY.get(scene, "unknown")
        if scene in ("screwup", "newscrewup"):
            units, key = _screwup_preview_units(player, scene), ""
        elif scene == "gene":
            units, key = _gene_test_preview_units(player), ""
        elif scene in _ZI_SCENE_MODE:
            zi_mode = _ZI_SCENE_MODE[scene]
            zi_level = _zi_next_level(player, zi_mode)
            units, key = _zi_enemy_units(zi_mode, zi_level), _zi_fight_key(zi_mode, zi_level)
        else:
            units, key = _build_fallback_enemies(chapter, stage), ""
    remember_battle_preview(player, units, family, key,
                            label="preview:%s:%s" % (family, key or _battle_scene(player) or "?"))
    return units


def _screwup_preview_units(player, scene):
    """Trial Road's real squad for the stage the client is about to fight (currentStage + 1; the
    Nightmare tab has its own climb and doubles the squad power, exactly like its fight handler)."""
    hard = scene == "newscrewup"
    cur = int(player.get("tr_hard_current" if hard else "tr_current") or 0)
    stage_id = cur + 1
    lvl_data = load_trial_road().get(stage_id)
    if not lvl_data:
        return []
    return _tr_enemy_squad(max(1, int(lvl_data["power"]) * (2 if hard else 1)), stage_id)


def _gene_test_preview_units(player):
    """Gene Trial's real encounter (the same single zombie the fight builds) for the stage/sub the
    client is about to run."""
    stage, mode, sub = _gene_scene_target(player)
    units = _gene_test_enemy_units(player, stage, mode, sub)
    if units:
        return units
    # The exact sub may not be authored yet; every sub of a stage fields the same zombie type, so show
    # the first authored one instead of an empty preview.
    subs = sorted(s for (m, st, s) in load_card_dna()["test"] if m == mode and st == stage)
    return _gene_test_enemy_units(player, stage, mode, subs[0]) if subs else []


def _gene_scene_target(player):
    """(stage, mode, sub) the client is about to fight in the Gene Trial: the stage/mode it last opened
    plus the sub after the one already cleared (the fight_CS confirms it again)."""
    stage = int(player.get("gene_test_last_stage") or 1)
    mode = int(player.get("_gene_mode") or 0)
    sub = max(1, int(store.get_gene_test_stage(player["uin"], mode, stage)["current_sub"] or 0) + 1)
    return stage, mode, sub


def remember_battle_preview(player, units, family, key, label=""):
    """Stamp `units` (the squad the player is looking at RIGHT NOW) as the authoritative enemy lineup."""
    uin = player.get("uin")
    if not uin or not units:
        return
    _PENDING_PREVIEW[uin] = {"ts": time.time(), "family": family, "key": key or "",
                             "label": label or family,
                             "cards": [(u["pos"], u["card_id"]) for u in units]}
    log.info("    enemy preview: %s -> %s", _PENDING_PREVIEW[uin]["label"],
             [(u["pos"], u["card_id"]) for u in units])


def take_previewed_enemy_cards(player, family, key=""):
    """The remembered preview's [(posIndex, cardId)] when it belongs to THIS fight, else None."""
    uin = player.get("uin")
    pending = _PENDING_PREVIEW.get(uin) if uin else None
    if not pending:
        return None
    if time.time() - pending["ts"] > _PREVIEW_TTL:
        _PENDING_PREVIEW.pop(uin, None)         # stale: something else was previewed since
        return None
    if pending["family"] != family:
        return None
    if pending["key"] and key and pending["key"] != key:
        return None
    return pending["cards"]


def apply_previewed_enemy_types(player, units, family, key=""):
    """Field the very zombies the pre-fight window showed: the remembered preview's cardIds are stamped
    onto this fight's units (matched by slot order). hp/atk/def/power/level stay the fight's own, so the
    win/lose decision, the replay pacing, the result screen and the rewards are all untouched."""
    cards = take_previewed_enemy_cards(player, family, key)
    if not cards or not units:
        return units
    load_battle_cards()
    changed = []
    for i, unit in enumerate(units):
        card_id = cards[i % len(cards)][1]
        if card_id == unit["card_id"]:
            continue
        stats = _BATTLE_CARDS.get(card_id)
        if not stats:
            continue
        unit["card_id"] = card_id
        unit["skill1"] = stats.get("skill1", 0)
        unit["skill2"] = stats.get("skill2", 0)
        unit["name"] = stats.get("name", unit.get("name", "Zombie"))
        changed.append((unit["pos"], card_id))
    if changed:
        log.info("    fight zombies follow the pre-fight preview: %s", changed)
    return units


def _col_of_pos(pos):
    """Grid column of a posIndex (1=front .. 3=back), per BattleConst.getColIndexByPosIndex."""
    if pos in (1, 2, 7, 8, 13, 14):
        return 1
    if pos in (3, 4, 9, 10, 15, 16):
        return 2
    return 3


def _depth_of_pos(pos):
    """1=front, 2=middle, 3=back in the client's 3x3 layout."""
    return (int(pos) - 1) // 6 + 1


def _lane_of_pos(pos):
    """1=top, 2=middle, 3=bottom."""
    return ((int(pos) - 1) // 2) % 3 + 1


# Extra rounds appended after the last kill. Each round the client plays a built-in ~1s delay, and
# DiePlanNomal starts a ~2s death fade but completes its plan immediately (doesn't hold the round), so
# without a buffer battleEnd() pops the result while the final zombie is still mid-fade = "zombies left
# when the stage finishes". One buffer round (~1s) still covers most of the fade and settles faster than
# the old 2 rounds. They are NOT empty rounds though — see the filler action at the end of
# simulate_battle (立即结束 needs a round it can walk action-by-action).
_DEATH_FADE_BUFFER_ROUNDS = 1


# 傀儡在战报里的一击：每个回合轮到的那只傀儡打「最前面还活着的僵尸」这一份 maxHP（6%）——胜负与死亡
# 时机仍由上面的脚本决定，所以这一下只是「并肩作战」的观感（对保护方会被夹到只剩 1 HP）。
_PUPPET_FIGHT_CHIP = 0.06


def _combat_proc_chance(source, counter, maximum):
    """Return a bounded basis-point chance after the opposing rate counters it.

    The authored battleCard, gene and nutrition secondary attributes use 10000
    for 100%. Capping avoids a fully unavoidable hit or permanent evasion from
    stacked local bonuses; the original online server's formula is unavailable.
    """
    return max(0, min(int(maximum), int(source or 0) - int(counter or 0)))


def simulate_battle(left_units, right_units, won, max_rounds=60, puppets=None,
                    leader_sides=("left", "right"), stop_on_elimination=False,
                    world_boss_id=0, result_state=None):
    """Deterministic replay the client animates, with REAL per-skill effects (see load_skill_info). The
    OUTCOME is decided upstream by Fighting Power (resolve_battle) and passed in as `won` — this only
    animates it, because the client trusts report.result/winSide and treats the replay as theatre.
    The LOSER's units are mortal and get routed; the WINNER's units are protected (any hit on them is
    clamped to leave >= 1 HP) so the replay always ends with the loser wiped and the winner standing,
    regardless of the raw stat scales. So on a WIN the zombies die and the plants survive (the original,
    confirmed-good animation); on a LOSS the plants are overwhelmed and the zombies survive.
    Each round every living unit casts its ability (skillId2) when its rage bar is full, else its basic
    (skillId1): attack -> the front-most enemy; aoe -> the front-most N; heal -> the N lowest-HP% allies;
    charge -> a 0-damage self swing. The winner FOCUS-fires the loser (kills them one at a time); the
    loser SPREADS a tuned chip onto the healthiest winner unit (so none is pinned at 1 HP = the old
    silent-unit bug). Returns [(actions, buffs), ...]: actions=[{actor,skill,cast,damages:[{target,dmg,
    dead}],puppet}] (dmg>0 damage / dmg<0 heal; a puppet action also carries {index,skill} for
    Dto_FightAction.puppetActor). A fail-safe finishing round guarantees the loser is wiped even if
    healers keep it alive, then _DEATH_FADE_BUFFER_ROUNDS empty rounds let the last death fade play.

    `world_boss_id` opts into actual HP-based combat: neither side is protected,
    the boss's death or player elimination ends combat, and the round limit never
    emits a forced wipe. `result_state` receives final HP/shield for settlement.

    `leader_sides` controls which teams may trigger a captain skill at round zero. Competitive/replay
    callers keep both sides by default; ordinary adventure passes only `("left",)` because the local
    fuben zombies have no player formation/captain and their synthetic first-card leader skill is not
    part of the adventure rules.

    `stop_on_elimination` ends the replay on the lethal action and omits subsequent puppet actions,
    round-end effects, and death-fade charge rounds. Ordinary adventure enables it because the server
    has already decided the result; other modes preserve their existing replay pacing.

    `puppets` = {round: {"actor": 101, "skill":…}} (see _puppet_battle_lineup): the 上阵傀儡 fight
    BESIDE the plants — "傀儡按照首轮至五轮顺序每回合依次轮流出手", so the fight's round N is
    lineup slot (N-1)%5+1, and that puppet strikes the front-most LIVING zombie for a chip of its max HP. The
    Flash client reserves 101,103,105,107,109 for the five left-side dummy slots; puppetActor.actorIndex
    addresses the actual current slot, matching the client's visible dummy. It never decides the fight
    (the script above owns every death; a chip on the protected winner side is clamped to leave 1 HP).
    傀儡战境 and the normal adventure handler pass `puppets`; the latter uses only the player's left-side
    puppet context (sideType 38) and never adds enemy puppets. Activity/trial/island/gene handlers leave
    it empty because those client result windows still crash while preloading puppet resources (#1009,
    see build_fight_report)."""
    # World Boss runs up to its round limit with mortal units on BOTH sides.
    # No power-predetermined winner, cosmetic chip, or forced final wipe.
    load_skill_info()
    states = load_battle_states()
    skill_effects = _SKILL_EFFECTS or {}
    skill_descs = _SKILL_DESCS or {}
    if puppets:                                   # 傀儡出手（第 N 回合 = 上阵第 N 格）
        log.info("    puppets act from rounds %s", sorted(puppets))
    hp = {u["pos"]: u.get("initial_hp", u["hp"]) for u in left_units + right_units}
    maxhp = {u["pos"]: u.get("max_hp", u["hp"]) for u in left_units + right_units}
    base_maxhp = dict(maxhp)
    # 护盾（蓝盾）血池：battleCard.initialShield 成长 + 装备加成的真实数值。
    # 有池的单位开局就是满盾条（maxShield=pool）；没有池的单位 maxShield=0（客户端不画条，
    # 与原版一致）。队长盾系/护盾技能/傀儡给无池单位套盾时把 maxshield 动态扩容到盾量，
    # 战斗结束回写 u["max_shield"]=峰值，客户端的临时盾条因此可见（比例=盾量/峰值）。
    # 伤害先扣盾再扣血（见下方攻击分支）。
    shield, maxshield, peak_shield = {}, {}, {}
    for u in left_units + right_units:
        pool = max(0, int(u.get("shield", 0) or 0))
        shield[u["pos"]] = pool
        maxshield[u["pos"]] = pool
        peak_shield[u["pos"]] = pool
    atk = {u["pos"]: u["atk"] for u in left_units + right_units}
    rates = {u["pos"]: {field: max(0, int(u.get(field, 0) or 0))
                        for field in ("hit", "dodge", "critical", "tough")}
             for u in left_units + right_units}
    # Local, stable random stream: repeated previews and fight reports for the
    # same combatants produce the same replay without perturbing global RNG.
    seed_parts = [int(won)]
    for u in sorted(left_units + right_units, key=lambda unit: unit["pos"]):
        seed_parts.extend([u["pos"], u["card_id"], u["hp"], u["atk"]])
        seed_parts.extend(rates[u["pos"]][field]
                          for field in ("hit", "dodge", "critical", "tough"))
    rng = _stage_rng("combat", *seed_parts)
    skill1 = {u["pos"]: (u.get("skill1") or 0) for u in left_units + right_units}
    skill2 = {u["pos"]: (u.get("skill2") or 0) for u in left_units + right_units}
    rage = {u["pos"]: RAGE_START for u in left_units + right_units}
    statuses = {u["pos"]: {} for u in left_units + right_units}
    left_pos = [u["pos"] for u in left_units]
    right_pos = [u["pos"] for u in right_units]
    # The protected (winner) side never dies in the replay; the loser side is routed. Which side is which
    # is the power-decided outcome, so plants-immortal/zombies-die on a win, and the mirror on a loss.
    winner_pos = [] if world_boss_id else (left_pos if won else right_pos)
    loser_pos = right_pos if won else left_pos
    boss_pos = next((u["pos"] for u in right_units if u["card_id"] == world_boss_id), None)
    summon_pos = [u["pos"] for u in right_units if u.get("is_live") is False]

    def battle_finished():
        if world_boss_id:
            return not alive(left_pos) or hp[boss_pos] <= 0
        return not alive(loser_pos)

    def alive(ps):
        return [p for p in ps if hp[p] > 0]

    def front_n(ps, n):
        targets = sorted(alive(ps), key=lambda p: (_depth_of_pos(p), p))
        return targets if n == 0 else targets[:n]

    def attack_targets(pos, enemies, sid, count, immortal):
        desc = skill_descs.get(sid, "")
        pool = alive(enemies)
        if "有能量的敌方" in desc:
            pool = [p for p in pool if rage[p] > 0]
        if "每一横行的前排" in desc:
            return [min(row, key=lambda p: (_depth_of_pos(p), p))
                    for lane in (1, 2, 3)
                    if (row := [p for p in pool if _lane_of_pos(p) == lane])]
        if "阵首、阵中、阵尾各1个" in desc:
            return [rng.choice(row) for col in (1, 2, 3)
                    if (row := [p for p in pool if _depth_of_pos(p) == col])]
        columns = [c for c, word in ((1, "阵首"), (2, "阵中"), (3, "阵尾"))
                   if word in desc]
        if columns:
            filtered = [p for p in pool if _depth_of_pos(p) in columns]
            pool = filtered
        if "前方横行" in desc:
            same_row = [p for p in pool if _lane_of_pos(p) == _lane_of_pos(pos)]
            pool = same_row
        if "前方横行最后一个" in desc and pool:
            pool = [max(pool, key=lambda p: (_depth_of_pos(p), -p))]
        if "周围" in desc or "附近" in desc:
            center = min(pool, key=lambda p: (_depth_of_pos(p), p)) if pool else None
            if center is not None:
                center_depth = _depth_of_pos(center)
                center_lane = _lane_of_pos(center)
                pool = [p for p in pool if abs(_depth_of_pos(p) - center_depth)
                        + abs(_lane_of_pos(p) - center_lane) <= 1]
        if "所在竖列" in desc or "所在竖排" in desc:
            center = min(pool, key=lambda p: (_depth_of_pos(p), p)) if pool else None
            pool = [p for p in pool if _depth_of_pos(p) == _depth_of_pos(center)] if center else []
        if "后方所有" in desc or "身后所有" in desc:
            center = min(pool, key=lambda p: (_depth_of_pos(p), p)) if pool else None
            if center:
                pool = [p for p in pool if _lane_of_pos(p) == _lane_of_pos(center)
                        and _depth_of_pos(p) >= _depth_of_pos(center)]
        if "随机" in desc:
            return rng.sample(pool, min(len(pool), count or len(pool))) if pool else []
        pool = sorted(pool, key=lambda p: (-hp[p], p) if immortal else (_depth_of_pos(p), p))
        return pool if count == 0 else pool[:count]

    def add_status(target, state_id, turns, damage):
        if state_id not in states:
            return
        statuses[target][state_id] = turns
        damage.update(buff_id=state_id, buff_left_round=turns, is_add_buff=True)
        param = states[state_id]
        if param[0] == 3 and param[1] == 4:
            # 护盾系 buff：按 maxhp 百分比直接套盾。无池单位 maxshield=0，若仍用
            # maxshield-shield 做上限就永远套不上（旧 bug），所以这里动态扩容容量。
            added = max(1, maxhp[target] * param[3] // 10000)
            shield[target] += added
            maxshield[target] = max(maxshield[target], shield[target])
            peak_shield[target] = max(peak_shield[target], shield[target])
            damage["change_shield"] = added
        elif param[0] == 3 and param[1] == 6:
            added = max(1, base_maxhp[target] * param[3] // 10000)
            maxhp[target] += added
            hp[target] += added
            damage["change_max_hp"] = added
            damage["dmg"] = -added

    def apply_leader_effect(target, effect, damage):
        """Apply captain buffs to both status state and live combat attributes.

        Shield captain skills previously depended on interpreting battleState
        rows in add_status(). That made the buff icon/replay event look valid
        while a missing or mismatched row silently skipped the live shield
        mutation. The known sunlight/oxygen shield series carry their own
        client-confirmed basis-point values, so update the shield pool directly
        and emit the same changeShield delta the client animates.
        """
        state_id = effect["state"]
        if effect.get("shield_ratio_bp") is None:
            add_status(target, state_id, effect["turns"], damage)
            return
        turns = effect["turns"]
        statuses[target][state_id] = turns
        damage.update(buff_id=state_id, buff_left_round=turns, is_add_buff=True)
        # 盾量按 maxhp 基点直算，容量(maxshield)动态扩容——无盾池单位（maxShield=0，
        # 客户端平时不画条）也能通过本场峰值拿到可见的蓝盾条。
        requested = max(1, maxhp[target] * int(effect["shield_ratio_bp"]) // 10000)
        shield[target] += requested
        maxshield[target] = max(maxshield[target], shield[target])
        peak_shield[target] = max(peak_shield[target], shield[target])
        damage["change_shield"] = requested

    def remove_status(target, state_id):
        """One removal DTO, including the max-HP change for a dispelled buff."""
        param = states.get(state_id)
        statuses[target].pop(state_id, None)
        removed = {"target": target, "dmg": 0, "dead": False,
                   "buff_id": state_id, "buff_left_round": 0,
                   "is_add_buff": False}
        if param and param[0] == 3 and param[1] == 6:
            amount = max(1, base_maxhp[target] * param[3] // 10000)
            maxhp[target] -= amount
            lost = max(0, hp[target] - maxhp[target])
            hp[target] -= lost
            removed["change_max_hp"] = -amount
            removed["dmg"] = lost
        return removed

    def attack_factor(pos, casting=False):
        factor = 1.0
        for state_id in statuses[pos]:
            param = states.get(state_id)
            if not param:
                continue
            op, stat, _base, value = param
            if op in (3, 15) and (stat == 1 or op == 15):
                factor += value / 10000.0
            elif casting and op == 3 and stat == 5:
                factor += value / 10000.0
            elif (op == 4 and stat == 1) or op in (14, 18):
                factor -= value / 10000.0
        return max(0.1, factor)

    def defense_factor(pos):
        factor = 1.0
        for state_id in statuses[pos]:
            param = states.get(state_id)
            if param and param[0] == 3 and param[1] == 2:
                factor -= param[3] / 10000.0
            elif param and param[0] == 4 and param[1] == 2:
                factor += param[3] / 10000.0
            elif param and param[0] == 12:
                factor -= param[3] / 10000.0
            elif param and param[0] == 13:
                factor += param[3] / 10000.0
        return max(0.1, factor)

    def proc_rate(pos, stat_name):
        value = rates[pos][stat_name]
        stat_code = {"hit": 13, "dodge": 14, "critical": 15, "tough": 16}[stat_name]
        for state_id in statuses[pos]:
            param = states.get(state_id)
            if param and param[1] == stat_code:
                value += param[3] if param[0] in (1, 3) else -param[3]
        return max(0, value)

    def apply_configured_effect(sid, target, damage, is_enemy, rng):
        effect = skill_effects.get(sid, {})
        if not effect.get("state") or (effect["side"] == "enemies") != is_enemy:
            return
        if effect.get("chance", 100) < 100 and rng.randrange(100) >= effect["chance"]:
            return
        add_status(target, effect["state"], effect["turns"], damage)

    def kind_of(pos, casting):
        sid = skill2[pos] if casting else skill1[pos]
        return sid, _SKILL_INFO.get(sid, ("attack", 1))

    def is_damager(pos):
        return kind_of(pos, False)[1][0] in ("attack", "aoe")

    # Loser chip tuned so the immortal winner sheds ~40% of its combined HP over the fight (cosmetic).
    # Based on the winner's DPS vs the loser's total HP (how long the rout takes).
    winner_dps = sum(atk[p] for p in winner_pos if is_damager(p)) or 1
    loser_total_hp = sum(hp[z] for z in loser_pos)
    est_rounds = max(1, -(-loser_total_hp // winner_dps))
    winner_total_hp = sum(hp[p] for p in winner_pos) or 1
    per_hit = max(1, int(0.4 * winner_total_hp / max(1, len(loser_pos) * est_rounds)))
    pending_rage = []

    def act(pos, allies, enemies):
        if any(states.get(state_id, ())[0:1] == (7,) for state_id in statuses[pos]):
            return None, False  # frozen this round
        silenced = any(states.get(state_id, ())[0:1] == (8,) for state_id in statuses[pos])
        casting = rage[pos] >= RAGE_MAX and skill2[pos] != 0 and not silenced
        sid, (kind, ntgt) = kind_of(pos, casting)
        desc = skill_descs.get(sid, "")
        damages = []
        if world_boss_id == 998 and pos == boss_pos and casting:
            # The shipped skill-2 tree calls RelivePlan. Hidden beforeCardList
            # entries supply the four models; positive HP deltas reveal them.
            healed = min(maxhp[pos] - hp[pos], max(1, maxhp[pos] // 8))
            hp[pos] += healed
            damages.append({"target": pos, "dmg": -healed, "dead": False})
            for t in summon_pos:
                gained = maxhp[t] - hp[t]
                hp[t] = maxhp[t]
                rage_delta = RAGE_START - rage[t]
                rage[t] = RAGE_START
                statuses[t].clear()
                damages.append({"target": t, "dmg": -gained, "dead": False,
                                "is_relive": True, "change_rage": rage_delta})
        elif kind == "heal":
            frac = (_HEAL_FRAC_CAST if casting else _HEAL_FRAC_BASIC) * attack_factor(pos)
            heal_targets = sorted(alive(allies), key=lambda a: (hp[a] / maxhp[a], a))
            if ntgt:
                heal_targets = heal_targets[:ntgt]
            for t in heal_targets:
                h = min(int(maxhp[t] * frac), maxhp[t] - hp[t])
                hp[t] += h
                damage = {"target": t, "dmg": -h, "dead": False}
                apply_configured_effect(sid, t, damage, False, rng)
                if h or "buff_id" in damage:
                    damages.append(damage)
                if skill_effects.get(sid, {}).get("cleanse"):
                    for state_id in list(statuses[t]):
                        param = states.get(state_id)
                        if param and param[0] in (7, 8):
                            del statuses[t][state_id]
                            damages.append({"target": t, "dmg": 0, "dead": False,
                                            "buff_id": state_id, "buff_left_round": 0,
                                            "is_add_buff": False})
        elif kind in ("charge", "support"):
            targets = [pos] if kind == "charge" else front_n(allies, ntgt)
            energy_grant = re.search(r"增加(\d+)点能量，成功率为(\d+)%", desc)
            if energy_grant and "随机友方" in desc:
                eligible = [t for t in alive(allies) if rage[t] < RAGE_MAX]
                count = int(re.search(r"(\d+)个随机友方", desc)[1])
                targets = rng.sample(eligible, min(count, len(eligible)))
            for t in targets:
                damage = {"target": t, "dmg": 0, "dead": False}
                apply_configured_effect(sid, t, damage, False, rng)
                if energy_grant and rng.randrange(100) < int(energy_grant[2]):
                    gain = min(RAGE_MAX - rage[t], int(energy_grant[1]))
                    rage[t] += gain
                    damage["change_rage"] = gain
                if "增加当前生命50%的护盾" in desc:
                    gained = max(1, hp[t] // 2)
                    shield[t] += gained
                    maxshield[t] = max(maxshield[t], shield[t])
                    peak_shield[t] = max(peak_shield[t], shield[t])
                    damage["change_shield"] = gained
                damages.append(damage)
        else:                                                # attack / aoe -> damage
            effect = skill_effects.get(sid, {})
            self_buff = None
            if effect.get("state") and effect.get("side") == "self":
                self_buff = {"target": pos, "dmg": 0, "dead": False}
                apply_configured_effect(sid, pos, self_buff, False, rng)
            immortal = enemies is winner_pos                                  # a hit on the protected side
            n = ntgt
            if immortal:                                # the loser spreads its chip onto the healthiest
                targets = attack_targets(pos, enemies, sid, n, True)
                per = per_hit
            else:                                       # the winner focus-fires the front-most loser unit
                dmg_mult = _AOE_MULT if kind == "aoe" else _SKILL_DMG_MULT
                targets = attack_targets(pos, enemies, sid, n, False)
                per = int(atk[pos] * dmg_mult) if casting else atk[pos]
            per = int(per * attack_factor(pos, casting))
            per = max(1, per)
            for t in targets:
                dodge = _combat_proc_chance(proc_rate(t, "dodge"), proc_rate(pos, "hit"), 6000)
                if rng.randrange(10000) < dodge:
                    damages.append({"target": t, "dmg": 0, "dead": False,
                                    "damage_type": 3})  # E_DamageType_Dodge
                    continue
                critical = _combat_proc_chance(proc_rate(pos, "critical"), proc_rate(t, "tough"), 7500)
                crit_hit = rng.randrange(10000) < critical
                dealt = max(1, per * 3 // 2) if crit_hit else per
                dealt = max(1, int(dealt * defense_factor(t)))
                absorbed = min(shield[t], dealt)
                shield[t] -= absorbed
                d = min(dealt - absorbed, (hp[t] - 1) if immortal else hp[t])
                if d <= 0 and absorbed <= 0:
                    continue
                hp[t] -= d
                damage = {"target": t, "dmg": d, "dead": (not immortal) and hp[t] <= 0,
                          "damage_type": 2 if crit_hit else 1}
                if absorbed:
                    damage["change_shield"] = -absorbed
                if hp[t] > 0:
                    apply_configured_effect(sid, t, damage, True, rng)
                drain = re.search(r"减少其(\d+)格能量", desc)
                if drain and hp[t] > 0:
                    lost = min(rage[t], int(drain[1]))
                    rage[t] -= lost
                    damage["change_rage"] = -lost
                damages.append(damage)
                if "清除目标的所有增益效果" in desc and hp[t] > 0:
                    for state_id in list(statuses[t]):
                        param = states.get(state_id)
                        if param and param[0] in (1, 3, 9, 10, 12, 15):
                            if param[0] == 3 and param[1] == 4:  # shield excluded by description
                                continue
                            damages.append(remove_status(t, state_id))
                # Ongoing lifesteal/reflect are state effects, not just icons.
                for state_id in list(statuses[pos]):
                    param = states.get(state_id)
                    if param and param[0] == 10 and d > 0:
                        healed = min(maxhp[pos] - hp[pos], d * param[3] // 10000)
                        if healed:
                            hp[pos] += healed
                            damages.append({"target": pos, "dmg": -healed, "dead": False})
                for state_id in list(statuses[t]):
                    param = states.get(state_id)
                    if param and param[0] == 9 and d > 0 and hp[pos] > 1:
                        reflected = min(hp[pos] - 1, d * param[3] // 10000)
                        if reflected:
                            hp[pos] -= reflected
                            damages.append({"target": pos, "dmg": reflected, "dead": False})
            if self_buff and "buff_id" in self_buff:
                damages.append(self_buff)
            if effect.get("state") and effect.get("side") == "allies":
                buff_targets = front_n(allies, 0)
                for target in buff_targets:
                    damage = {"target": target, "dmg": 0, "dead": False}
                    apply_configured_effect(sid, target, damage, False, rng)
                    if "buff_id" in damage:
                        damages.append(damage)
        if not damages:
            if kind in ("heal", "charge", "support"):    # a support with nothing to do
                damages = [{"target": pos, "dmg": 0, "dead": False}]
            else:                             # an attacker with no living enemy: don't swing at nothing
                return None, casting
        # Skill-bar (rage) change for THIS action, applied by the tree's ActorChangeHP node so it
        # animates AS the unit acts: a cast drains to 0, any other action fills +1 (capped). This is
        # the actor's own changeRage (Dto_FightActor field 5) — no round-end buffEffect, so the bar
        # drains exactly when the skill fires instead of a round late.
        rage_delta = (0 if "发动技能不消耗能量" in desc else -rage[pos]) if casting \
            else (1 if rage[pos] < RAGE_MAX else 0)
        rage[pos] += rage_delta
        end_gain = re.search(r"回合结束时回复(\d+)点能量", desc)
        if end_gain:
            pending_rage.append((pos, int(end_gain[1])))
        full_gain = re.search(r"(\d+)%几率完全回复能量", desc)
        if full_gain and rng.randrange(100) < int(full_gain[1]):
            pending_rage.append((pos, RAGE_MAX))
        return {"actor": pos, "skill": sid, "cast": casting, "rage": rage_delta,
                "damages": damages}, casting

    # The client's round zero selects its dedicated captain-skill animation.
    # Earlier reports had no such action, so every captain skill was inert.
    leader_actions = []
    for side, own, opposing in (("left", left_units, right_units),
                                ("right", right_units, left_units)):
        if side not in leader_sides:
            continue
        leader = next((u for u in own if u.get("is_leader")), None)
        if not leader:
            continue
        sid = int(_BATTLE_CARDS.get(leader["card_id"], {}).get("leader_skill", 0))
        effect = _leader_effect(sid)
        if not effect:
            continue
        if effect["side"] == "self":
            targets = [leader["pos"]]
        elif effect["side"] == "enemies":
            targets = front_n([u["pos"] for u in opposing], effect.get("targets", 0))
        else:
            targets = front_n([u["pos"] for u in own], 0)
        leader_damages = []
        for target in targets:
            damage = {"target": target, "dmg": 0, "dead": False}
            if effect.get("chance", 100) == 100 or rng.randrange(100) < effect["chance"]:
                apply_leader_effect(target, effect, damage)
            leader_damages.append(damage)
        if leader_damages:
            leader_actions.append({"actor": leader["pos"], "skill": sid,
                                   "cast": True, "leader": True, "rage": 0,
                                   "damages": leader_damages})
    rounds = [(leader_actions, [])] if leader_actions else []
    for _ in range(max_rounds):
        if battle_finished():
            break
        actions = []
        pending_rage.clear()
        # Left side acts first; STOP the moment the loser is wiped so no later unit swings at an empty
        # field (the "repeater attacks a target that just died" bug).
        for pos in alive(left_pos):
            if battle_finished():
                break
            a, _casting = act(pos, left_pos, right_pos)
            if a is not None:
                actions.append(a)
        # Right side retaliates (only those still alive, and only if the loser isn't already wiped).
        for pos in alive(right_pos):
            if battle_finished():
                break
            a, _casting = act(pos, right_pos, left_pos)
            if a is not None:
                actions.append(a)
        # 傀儡 (puppet): the lineup's slots act in round order ("傀儡按照首轮至五轮顺序每回合依次轮流出手",
        # 没有傀儡时该回合傀儡轮空). It hits the front-most LIVING zombie for a chip of that zombie's max
        # HP — the plants' script above still owns every death, so the puppet can only finish a loser off
        # (never one of the protected winners, whose chip is clamped to 1 HP). `puppet` is what
        # encode_fight_replay turns into Dto_FightAction.puppetActor(6), which is how the client's battle
        # knows WHICH dummy unit acts; the ordinary actor+damage pair plays the hit and the HP change.
        # 护盾技能（酒气冲云/铜皮铁骨“为…队友增加最大生命N的护盾”）例外：不造成伤害，改为给
        # 生命百分比最少的至多 3 个存活队友套盾（changeShield 正值 = 蓝盾条回复），这就是
        # “有的傀儡专门回复蓝盾条值”的出处。
        puppet = (puppets or {}).get((_ % _DUMMY_MAX_LINEUP) + 1)
        can_act = bool(puppet) and (not stop_on_elimination or not battle_finished())
        shield_bp = None
        if can_act:
            shield_cfg = (load_dummy_config().get("shield_skills") or {}).get(
                int(puppet.get("skill") or 0))
            if shield_cfg:
                lv = max(1, int(puppet.get("skill_lv") or 1))
                shield_bp = shield_cfg[0] + shield_cfg[1] * (lv - 1)
        if can_act and shield_bp:
            shield_targets = sorted(alive(left_pos),
                                    key=lambda p: (hp[p] / maxhp[p], p))[:3]
            damages = []
            for t in shield_targets:
                # "为生命百分比最少的3个队友增加最大生命N的护盾"——是叠加一层新盾。
                # 容量(maxshield)随盾量动态扩容并记入峰值：无池单位(maxShield=0)的
                # 傀儡盾条因此可见（DTO maxShield=本场峰值，比例=盾量/峰值）。
                gained = max(1, maxhp[t] * int(shield_bp) // 10000)
                shield[t] += gained
                maxshield[t] = max(maxshield[t], shield[t])
                peak_shield[t] = max(peak_shield[t], shield[t])
                damages.append({"target": t, "dmg": 0, "dead": False,
                                "change_shield": gained})
            if damages:
                actions.append({"actor": puppet.get("actor", 101), "skill": puppet.get("skill") or 0,
                                "cast": True, "rage": 0, "damages": damages,
                                "puppet": {"index": puppet.get("actor", 101),
                                            "skill": puppet.get("skill") or 0}})
        elif can_act:
            puppet_targets = front_n(right_pos, 1)
            if puppet_targets:
                tgt = puppet_targets[0]
                immortal = right_pos is winner_pos
                chip = max(1, int(maxhp[tgt] * _PUPPET_FIGHT_CHIP))
                if immortal:
                    chip = min(chip, hp[tgt] - 1)
                if chip > 0:
                    hp[tgt] -= chip
                    actions.append({"actor": puppet.get("actor", 101), "skill": puppet.get("skill") or 0, "cast": True, "rage": 0,
                                    "damages": [{"target": tgt, "dmg": chip, "dead": hp[tgt] <= 0}],
                                    "puppet": {"index": puppet.get("actor", 101),
                                                "skill": puppet.get("skill") or 0}})
        # End-of-round state effects. Oxygen algae's regeneration is a real HP
        # update in the replay, and each expiring icon is explicitly removed.
        round_buffs = []
        if stop_on_elimination and battle_finished():
            # Keep the killing action as the final replay event. Do not make the client wait through
            # leftover puppet, status, or fade animations after the server's outcome is settled.
            rounds.append((actions, round_buffs))
            break
        for target, requested in pending_rage:
            if hp[target] <= 0:
                continue
            gained = min(RAGE_MAX - rage[target], requested)
            if gained > 0:
                rage[target] += gained
                round_buffs.append({"target": target, "dmg": 0, "dead": False,
                                    "change_rage": gained})
        for target in list(hp):
            if hp[target] <= 0:
                continue
            for state_id, turns in list(statuses[target].items()):
                param = states.get(state_id)
                if param and param[2] == 206 and param[0] == 3 and param[1] == 3:
                    amount = min(maxhp[target] - hp[target], int(maxhp[target] * param[3] / 10000))
                    if amount > 0:
                        hp[target] += amount
                        round_buffs.append({"target": target, "dmg": -amount, "dead": False})
                elif param and param[2] == 206 and param[0] == 4 and param[1] == 3:
                    immortal = target in winner_pos
                    amount = min(hp[target] - (1 if immortal else 0),
                                 max(1, maxhp[target] * param[3] // 10000))
                    if amount > 0:
                        hp[target] -= amount
                        round_buffs.append({"target": target, "dmg": amount,
                                            "dead": hp[target] <= 0})
                if turns < 30:
                    turns -= 1
                    if turns <= 0:
                        del statuses[target][state_id]
                        expiry = {"target": target, "dmg": 0, "dead": False,
                                  "buff_id": state_id, "buff_left_round": 0,
                                  "is_add_buff": False}
                        if param and param[0] == 3 and param[1] == 6:
                            removed = max(1, base_maxhp[target] * param[3] // 10000)
                            maxhp[target] -= removed
                            lost = max(0, hp[target] - maxhp[target])
                            hp[target] -= lost
                            expiry["change_max_hp"] = -removed
                            expiry["dmg"] = lost
                        round_buffs.append(expiry)
                    else:
                        statuses[target][state_id] = turns
        rounds.append((actions, round_buffs))
    # Fail-safe: healers can keep a survivor alive — finish any surviving loser with a winner attacker's
    # basic (a damage skill, safe for the death handling) so the replay always resolves to the outcome.
    survivors = alive(loser_pos)
    if survivors and not world_boss_id:
        killer = next((p for p in alive(winner_pos) if is_damager(p)), None)
        if killer:
            fk = [{"target": z, "dmg": hp[z], "dead": True} for z in survivors]
            for z in survivors:
                hp[z] = 0
            rounds.append(([{"actor": killer, "skill": skill1[killer], "cast": False, "rage": 0,
                             "damages": fk}], []))
    # Trailing buffer rounds so the final unit's death fade finishes before battleEnd. CRITICAL: they
    # are NOT action-less. 立即结束 (the client's fast-forward) cancels the current plan and jumps to the
    # END of the replay, and the round it lands on is inspected (the round-state command walks
    # round.action[...]) — an action-less round there throws #1009 and wedges the round state machine
    # ("立即结束 -> ActionScript 错误 + 卡死"). So every buffer round carries ONE harmless "charge"
    # action from a surviving winner unit: a 0-damage self swing, exactly the shape act() already emits
    # for a support with nothing to do (no damage number, ~1s animation, same pace as before).
    filler_actor = next((p for p in alive(winner_pos) if is_damager(p)), None) \
        or next((p for p in alive(winner_pos)), None)
    for _ in range(0 if stop_on_elimination else _DEATH_FADE_BUFFER_ROUNDS):
        if filler_actor is None:                      # winner side always has someone standing
            rounds.append(([], []))
            continue
        # actionType=Update (see encode_fight_replay): the client's actionReady branches on
        # E_FightActionType — Attack(0) plays the swing animation, Update(1) only refreshes the
        # unit's HP/rage data. A 0-damage self swing as Update = the round still has ONE walkable
        # action (立即结束 needs it, round.action.length #1009) but NO "plant attacks the empty
        # field" animation after the last zombie died (the 攻击空气 complaint).
        rounds.append(([{"actor": filler_actor, "skill": skill1[filler_actor], "cast": False,
                         "rage": 0, "update": True,
                         "damages": [{"target": filler_actor, "dmg": 0, "dead": False}]}], []))
    # 盾量峰值回写：报告的 beforeCardList/afterCardList 编码（encode_left_card_lists /
    # encode_before_card_list）读 u["max_shield"]。无池且从未获得盾的单位峰值=0 ->
    # DTO maxShield=0 -> 客户端不画空盾条；获得过临时盾的单位 maxShield=峰值 -> 盾条可见。
    for u in left_units + right_units:
        u["max_shield"] = max(0, int(peak_shield.get(u["pos"], 0)))
    if result_state is not None:
        result_state.update(hp=dict(hp), shield=dict(shield))
    return rounds


def resolve_battle(left_units, right_units):
    """Compare combat power after the same crit/dodge counters used in the replay.

    The local server decides the result before building its theatrical replay.
    Expected damage therefore influences the result, while actual deterministic
    proc rolls and HP changes are represented in the replay that follows.
    """
    def effective_power(attackers, defenders):
        base = sum(max(0, int(u.get("power", 0))) for u in attackers)
        if not defenders:
            return base
        # Average over the opposing squad. A unit with a higher critical rate
        # therefore increases its team's chance to win, while dodge and tough
        # reduce the opposing team's effective damage using the same counters.
        total = 0.0
        for attacker in attackers:
            power = max(0, int(attacker.get("power", 0)))
            if not power:
                continue
            factor = 0.0
            for defender in defenders:
                dodge = _combat_proc_chance(defender.get("dodge", 0),
                                             attacker.get("hit", 0), 6000) / 10000.0
                critical = _combat_proc_chance(attacker.get("critical", 0),
                                                defender.get("tough", 0), 7500) / 10000.0
                factor += (1.0 - dodge) * (1.0 + 0.5 * critical)
            total += power * factor / len(defenders)
        return round(total)

    left_power = effective_power(left_units, right_units)
    right_power = effective_power(right_units, left_units)
    if not left_units:
        return False, left_power, right_power       # no plants deployed -> can't win
    if right_power <= 0:
        return True, left_power, right_power
    won = left_power >= right_power * _WIN_POWER_RATIO
    return won, left_power, right_power


def encode_fight_replay(rounds):
    """Repeated Dto_FightRound (report field 4) from simulate_battle output (list of (actions, buffs)).
    Dto_FightRound{round(1), action(2)=[Dto_FightAction]}. Dto_FightAction{actor(1)=Dto_FightActor,
    damage(2)=[Dto_FightDamage], actionType(5)=Attack(0), puppetActor(6)=Dto_FightPuppetActor}. Dto_FightActor
    {actorIndex(1),targetIndex(2),skillId(3),changeRage(5,int32)}. Dto_FightPuppetActor{actorIndex(1),
    targetIndex(2),skillId(3)} — an action carrying it is a 傀儡 (puppet) acting that round: actorIndex is
    the puppet's posIndex from Dto_FightSide.puppetList (its lineup slot), targetIndex the victim.
    Dto_FightDamage{targetIndex(1),changeHp(2,int64),damageType(3),isDead(7)}. skillId picks basic vs cast;
    actor.changeRage = the unit's OWN skill-bar change, applied by the tree's ActorChangeHP node so the bar
    fills/drains AS the unit acts (drain on cast, +1 else).
    A damage's dmg>0 -> changeHp NEGATIVE (damage); dmg<0 -> POSITIVE (heal)."""
    d = b""
    has_leader_round = bool(rounds and rounds[0][0] and rounds[0][0][0].get("leader"))
    for i, (actions, buffs) in enumerate(rounds, 0 if has_leader_round else 1):
        round_b = pb_varint_field(1, i)
        for a in actions:
            dmgs = a["damages"]
            primary = dmgs[0]["target"] if dmgs else a["actor"]
            rd = a.get("rage", 0)                                    # actor's own skill-bar change
            actor = (pb_varint_field(1, a["actor"]) + pb_varint_field(2, primary)
                     + pb_varint_field(3, a["skill"])                # skillId picks basic vs special
                     + (pb_varint_field(5, rd) if rd >= 0 else pb_int64_field(5, rd)))  # changeRage
            dmg_bytes = b""
            for dd in dmgs:      # dmg>0 -> changeHp NEGATIVE (damage); dmg<0 -> POSITIVE (heal)
                one = (pb_varint_field(1, dd["target"]) + pb_int64_field(2, -dd["dmg"])
                       + pb_varint_field(3, dd.get("damage_type", 1))
                       + pb_bool(7, dd["dead"]))
                if dd.get("is_relive"):
                    one += pb_bool(10, True)
                if dd.get("change_shield"):
                    one += pb_int64_field(6, dd["change_shield"])
                if dd.get("change_rage"):
                    one += (pb_varint_field(4, dd["change_rage"]) if dd["change_rage"] > 0
                            else pb_int64_field(4, dd["change_rage"]))
                if dd.get("change_max_hp"):
                    one += pb_int64_field(11, dd["change_max_hp"])
                if dd.get("buff_id"):
                    one += (pb_varint_field(5, dd["buff_id"])
                            + pb_varint_field(8, dd.get("buff_left_round", 0))
                            + pb_bool(9, dd.get("is_add_buff", False)))
                dmg_bytes += pb_tag(2, 2) + uvarint(len(one)) + one           # damage[] (repeated)
            puppet_bytes = b""
            is_puppet = bool(a.get("puppet"))
            if is_puppet:                                        # this round's 傀儡 acts (field 6)
                pu = a["puppet"]
                pa = (pb_varint_field(1, pu["index"]) + pb_varint_field(2, primary)
                      + pb_varint_field(3, pu.get("skill") or 0))
                puppet_bytes = pb_tag(6, 2) + uvarint(len(pa)) + pa
            # BattleActionStateCommand creates the ordinary actor from puppetActor when actor is null.
            # Sending both fields makes PlanFactory treat the dummy marker as a normal plant position and
            # call getPlanSettingByCardId(null), which is the entry #1009 shown by Flash.
            actor_field = b"" if is_puppet else (pb_tag(1, 2) + uvarint(len(actor)) + actor)
            # actionType: Attack(0) plays the skill/swing animation; Update(1) is the data-refresh
            # branch (E_FightActionType_Update) the client walks without any attack animation —
            # used by the post-elimination filler rounds so 立即结束 can still walk an action but
            # surviving plants don't visibly swing at the empty field.
            action_b = (actor_field                                             # actor (normal only)
                        + dmg_bytes                                          # damage[] (1..N targets)
                        + puppet_bytes                                       # puppetActor (field 6)
                        + pb_varint_field(5, 1 if a.get("update") else 0))    # actionType
            round_b += pb_tag(2, 2) + uvarint(len(action_b)) + action_b       # action[]
        for dd in buffs:
            one = (pb_varint_field(1, dd["target"]) + pb_int64_field(2, -dd["dmg"])
                   + pb_varint_field(3, dd.get("damage_type", 1))
                   + pb_bool(7, dd.get("dead", False)))
            if dd.get("change_shield"):
                one += pb_int64_field(6, dd["change_shield"])
            if dd.get("change_rage"):
                one += (pb_varint_field(4, dd["change_rage"]) if dd["change_rage"] > 0
                        else pb_int64_field(4, dd["change_rage"]))
            if dd.get("change_max_hp"):
                one += pb_int64_field(11, dd["change_max_hp"])
            if dd.get("buff_id"):
                one += (pb_varint_field(5, dd["buff_id"])
                        + pb_varint_field(8, dd.get("buff_left_round", 0))
                        + pb_bool(9, dd.get("is_add_buff", False)))
            round_b += pb_tag(3, 2) + uvarint(len(one)) + one
        d += pb_tag(4, 2) + uvarint(len(round_b)) + round_b              # fightReplay[] (report field 4)
    return d


def encode_before_card_list(units):
    """Repeated Dto_FightCardInfo (field 2) bytes for one side, from build_battle_units dicts."""
    d = b""
    for u in units:
        power = u.get("power") or card_power({
            field: u.get(field, 0)
            for field in ("atk", "def_", "hp", "ability", "hit", "dodge", "critical", "tough")
        })
        card = build_fight_card(u["pos"], u["card_id"], u.get("initial_hp", u["hp"]), u["level"], u["is_leader"],
                                power=power, speed=u.get("speed", 0),
                                avatar_id=u.get("avatar_id", 0),
                                power_elements=u.get("power_elements"),
                                shield=u.get("shield", 0), max_shield=u.get("max_shield"),
                                max_hp=u.get("max_hp", u["hp"]), is_live=u.get("is_live", True))
        d += pb_tag(2, 2) + uvarint(len(card)) + card
    return d


def encode_left_card_lists(player, units, card_exp_gain):
    """Build the SELF side's beforeCardList (field 2) AND afterCardList (field 4). The result screen
    (FightResultWDMediator.update_res_bar) animates each plant's exp bar from before[i].exp/level to
    after[i].exp/level. before = the plant's CURRENT level + within-level exp; after = after adding
    `card_exp_gain` (capped by the account level). Same order both lists so the client pairs them."""
    acct = int(player.get("level", 1))
    before = after = b""
    # FightResultWDMediator has six resBar slots. It removes exactly one
    # isHelpCard entry from beforeCardList, but leaves afterCardList untouched
    # and pairs both arrays by index. Put the friend last in BOTH lists, so
    # the first six owned cards keep their matching EXP values regardless of
    # the friend's battle position. Battle positions remain in each DTO.
    ordered_units = sorted(units, key=lambda u: bool(u.get("is_help_card")))
    for u in ordered_units:
        power = u.get("power") or card_power({
            field: u.get(field, 0)
            for field in ("atk", "def_", "hp", "ability", "hit", "dodge", "critical", "tough")
        })
        old_total = int(u.get("exp", 0))
        old_lv = int(u.get("level", 1))
        old_within = card_exp_within_level(old_total, old_lv)
        new_lv, new_total = card_level_from_exp(old_total + max(0, card_exp_gain), u["card_id"], acct)
        new_within = card_exp_within_level(new_total, new_lv)
        bc = build_fight_card(u["pos"], u["card_id"], u["hp"], old_lv, u["is_leader"],
                              power=power, exp=old_within, speed=u.get("speed", 0),
                              avatar_id=u.get("avatar_id", 0),
                              is_help_card=u.get("is_help_card", False),
                              power_elements=u.get("power_elements"),
                              shield=u.get("shield", 0), max_shield=u.get("max_shield"))
        ac = build_fight_card(u["pos"], u["card_id"], u["hp"], new_lv, u["is_leader"],
                              power=power, exp=new_within, speed=u.get("speed", 0),
                              avatar_id=u.get("avatar_id", 0),
                              is_help_card=u.get("is_help_card", False),
                              power_elements=u.get("power_elements"),
                              shield=u.get("shield", 0), max_shield=u.get("max_shield"))
        before += pb_tag(2, 2) + uvarint(len(bc)) + bc
        after += pb_tag(4, 2) + uvarint(len(ac)) + ac
    return before, after


def build_fight_report(player, chapter, mode, stage, won=True, reward_items=None, is_first=False,
                       left_units=None, right_units=None, replay_bytes=b"", card_exp_gain=0,
                       fight_type=1, puppet_bytes=None, side_types=None):
    """A Dto_FightReport that resolves to a WIN or a LOSS (`won`). left_units/right_units populate each
    side's beforeCardList (the plants/zombies on the field + result screen). replay_bytes = the encoded
    fightReplay (report field 4): non-empty -> the units play out the fight round-by-round; empty ->
    isOver() is true immediately. On a LOSS: result=Loss, winSide=Right (the client's isRoleWin() is then
    false, so FightChestsWDMedator routes to showLoseWD() instead of the win chest), and NO reward block.
    Dto_FightReport{result(1),leftSide(2),rightSide(3),fightReplay(4),fightType(5),winSide(7)}.
    Dto_FightSide{sideType(1),beforeCardList(2),reward(3),roleName(6),totalPower(7),roleLevel(8),
    totalSpeed(15),puppetList(16)}.

    `puppet_bytes` = an encoded puppetList (the 上阵傀儡 that fight BESIDE the plants). `None` (the
    default) means no puppetList; ordinary modes other than the explicit adventure path omit it. The
    normal adventure handler passes the player's list with sideType=38 after clientDB plan rows are
    present, while activity/trial/island/gene modes keep it empty to avoid a null plan in closeBattle()
    (ActionScript #1009). The dedicated 傀儡战境 caller also passes its list explicitly; `b""` means no
    puppetList."""
    # fight_type = BattleTargetType (routing): 1=Fuben (adventure), 11=ScrewUp (Trial Road) — decides
    # which result window FightChestsWDMedator opens for this report.
    E_FIGHTRESULT_WIN, E_FIGHTRESULT_LOSS = 0, 1
    E_WINSIDE_LEFT, E_WINSIDE_RIGHT = 1, 2
    if not won:                                       # a loss grants nothing + no card XP
        reward_items, card_exp_gain = None, 0
    lvl = int(player.get("level", 1))
    # The win/result window (FightResultWDMediator) reads the self side's role-exp + card-exp;
    # nulls crash it. Dto_RoleAttr{oldRoleLevel(1),oldExpPercent(2),newRoleLevel(3),newExpPercent(4)}
    # (old==new -> no bar animation). Dto_CardExp{oldCardExp(1),oldExpBeanNum(2),expOverflow(3)}.
    role_attr = (pb_varint_field(1, lvl) + pb_varint_field(2, 0)
                 + pb_varint_field(3, lvl) + pb_varint_field(4, 0))
    card_exp = pb_varint_field(1, 0) + pb_varint_field(2, 0) + pb_varint_field(3, 0)
    # reward (field 3, repeated Dto_FightReward): the win chest reads getSelfSide().reward ->
    # rewardItem (Dto_ItemInfo{uid,id,num}). One Add block holds the whole stage's loot. Exp-type
    # items (2/5) are auto-hidden from the chest grid by the client; the rest show as icons.
    reward_block = b""
    if reward_items:
        items_b = b""
        for iid, num in reward_items:
            dto = build_item_dto(iid, num)
            items_b += pb_tag(4, 2) + uvarint(len(dto)) + dto           # rewardItem (field 4)
        fr = (pb_varint_field(1, 0)                                     # changeType = Add
              + pb_varint_field(2, 1 if is_first else 0)                # isFirstFullStar
              + items_b)
        reward_block = pb_tag(3, 2) + uvarint(len(fr)) + fr            # reward (field 3)
    # Real per-side totals so the result screen's 战斗力 matches the lineup + enemy preview (not a
    # placeholder 100). Each unit's power = its carried power, else derived from its scaled stats.
    def _side_power(units):
        return sum((u.get("power") or card_power({
            field: u.get(field, 0)
            for field in ("atk", "def_", "hp", "ability", "hit", "dodge", "critical", "tough")
        })) for u in (units or []))
    left_power = _side_power(left_units)
    right_power = _side_power(right_units)
    # 先攻 (initiative): the battle HUD prints ONE number per side, next to the side's name ("Zombies
    # 先攻: ???" = the client had no totalSpeed to print). It is the sum of the units' speed, so send the
    # real total — the per-unit powerEle speed above and this total must agree.
    def _side_speed(units):
        return sum(max(0, int(u.get("speed", 0) or 0)) for u in (units or []))
    left_speed = _side_speed(left_units)
    right_speed = _side_speed(right_units)
    # beforeCardList (field 2) + afterCardList (field 4): the result screen fills each plant's exp bar
    # from before -> after. card_exp_gain = the 植物经验 (Plant EXP) this level awards each plant.
    before_cards, after_cards = encode_left_card_lists(player, left_units or [], card_exp_gain)
    # 普通冒险/活动/试炼结果不发送傀儡字段。客户端在这些战斗的结算模型中没有完整的
    # 傀儡上下文，即使 battleCard 表存在傀儡卡行，也会在 closeBattle() 阶段尝试访问空对象
    # 并触发 ActionScript #1009。只有专用的傀儡战境调用方显式传入 puppet_bytes，才发送傀儡。
    if puppet_bytes is None:
        puppet_bytes = b""
    if puppet_bytes and replay_bytes:
        # UnitFactory.updateDummy starts every puppet at alpha=0. Round zero
        # reveals the first one before any action, including a captain skill.
        # A captain skill has its own round zero; preserve it after this empty
        # setup round. Later rounds switch to the next puppet slot after attack.
        replay_bytes = pb_bytes(4, pb_varint_field(1, 0)) + replay_bytes
    left = (pb_varint_field(1, side_types[0] if side_types else 0)   # sideType = Self (38 in 傀儡战境)
            + before_cards                              # beforeCardList (field 2)
            + reward_block                              # reward (field 3)
            + after_cards                               # afterCardList (field 4)
            + pb_varint_field(5, int(player.get("face_id") or 1))   # roleFaceId
            + pb_string(6, player.get("name", "Player"))   # roleName
            + pb_varint_field(7, left_power)            # totalPower
            + pb_varint_field(8, lvl)                   # roleLevel
            + pb_tag(9, 2) + uvarint(len(card_exp)) + card_exp    # cardExp
            + pb_tag(10, 2) + uvarint(len(role_attr)) + role_attr  # roleAttr
            + pb_string(13, player_face_url(player))  # roleQQFaceURL ← 左边头像
            + pb_varint_field(15, left_speed)           # totalSpeed ← 先攻
            + puppet_bytes)                             # puppetList (field 16, repeated)
    right = (pb_varint_field(1, side_types[1] if side_types else (mode or 1))   # sideType
             + encode_before_card_list(right_units or [])  # beforeCardList (field 2)
             + pb_varint_field(5, 0)                    # roleFaceId = 0
             + pb_string(6, "Zombies")                  # roleName
             + pb_varint_field(7, right_power)          # totalPower
            + pb_string(13, "http://127.0.0.1:8080/image/head/zombie.png")  # roleQQFaceURL ← 指向僵尸图
            + pb_varint_field(15, right_speed))         # totalSpeed ← 先攻
    return (pb_varint_field(1, E_FIGHTRESULT_WIN if won else E_FIGHTRESULT_LOSS)    # result
            + pb_tag(2, 2) + uvarint(len(left)) + left                # leftSide
            + pb_tag(3, 2) + uvarint(len(right)) + right              # rightSide
            + replay_bytes                                            # fightReplay (field 4, repeated)
            + pb_varint_field(5, fight_type)                          # fightType -> routing
            + pb_varint_field(7, E_WINSIDE_LEFT if won else E_WINSIDE_RIGHT))   # winSide


def build_enemy_card(pos, card_id, hp, level=1, is_leader=False, power=0):
    """Dto_EnemyCardInfo{posIndex(1),cardId(2),level(3),isLeader(4),power(5),hp(7,U64),maxhp(8,U64)}.
    The pre-fight enemy preview reads these to SHOW + PRELOAD the zombie assets before the fight."""
    return (pb_varint_field(1, pos) + pb_varint_field(2, card_id) + pb_varint_field(3, level)
            + pb_varint_field(4, 1 if is_leader else 0) + pb_varint_field(5, power)
            + pb_varint_field(7, hp) + pb_varint_field(8, hp))


# --- zombie island / 勇闯僵尸岛 ------------------------------------------------------
# The island is a 12-stage ladder (clientDB ZombieIslandTemplate.txt = 关卡1..关卡12) whose every stage
# is guarded by zombies; beating a stage opens that island's chest(s) and pays 冒险勋章 (item 2013), the
# island shop's currency (ExchangeStore type 2). The client ships TWO copies of the feature and switches
# between them with the island panel's 普通/进阶 buttons:
#
#   normal (普通) : Cmd_ZombieIsland_*      battle target 9  (BattleTargetType_ZombieIsland)
#                  Dto_CardBaseInfo.zombieIslandHp, Cmd_ZombieIsland_Sweep_CS
#   adv    (进阶) : Cmd_NewZombieIsland_*   battle target 21 (BattleTargetType_NewZombieIsland)
#                  Dto_CardBaseInfo.newZombieIslandHp, TakeAllReward (no sweep)
#
# Each mode keeps its own climb/chests (store.island_progress / store.island_boxes), so switching tabs
# never loses progress. The per-island ZOMBIE COMPOSITION was configured server-side in the original
# game (it is in no clientDB table), so it is generated here from ZombieIslandLevel.txt (island ->
# zombie level, used as the enemies' displayed level) plus a themed family per island and a
# deterministic, power-ramped squad — the SAME builder answers the pre-fight preview and the fight, so
# the window can never show a squad other than the one fielded (see the preview note above).
_ZI_NORMAL, _ZI_ADV = 0, 1
_ZI_TARGET_MODE = {9: _ZI_NORMAL, 21: _ZI_ADV}          # BattleTargetType 9 / 21
_ZI_SCENE_NAMES = {_ZI_NORMAL: "zombieisland", _ZI_ADV: "newzombieisland"}
_ZI_SCENE_MODE = {v: k for k, v in _ZI_SCENE_NAMES.items()}
_ZI_BOXES = 3                    # chests per island (IslandView draws box1..box3)
_ZI_DAILY_REFRESH = 1            # 重新开始 restarts per day (the panel's "今日剩余")
# How many plants the island fields. The prepare view lets you arrange more than this (a live save had
# 16), but the island RESULT window (FightResultZombieIslandMediator.update_card, ModuleBattle.swf) has a
# fixed 6-slot card Vector and throws `RangeError #1125: 索引 6 超出范围 6` on a 7th card, so the battle
# must field at most 6 — see _zi_player_placements.
_ZI_LINEUP_MAX = 6
_ZI_BASE_POWER = 1200            # total enemy power guarding island 1
_ZI_POWER_STEP = 0.30            # each island ~30% stronger than the previous one
_ZI_ADV_POWER_MULT = 1.5         # the 进阶 climb is the harder duplicate of the same ladder
_ZI_MEDAL_ITEM = 2013            # 冒险勋章 — the island shop's currency
_ZI_CHEST_ITEM = 4071            # 僵尸岛宝箱 — the island's guard-chest reward
_ZI_BEAN_ITEM = 2002             # 小经验豆
_ZI_PAPER_ITEM = 2006            # 废报纸
_ZI_ISLAND_WORLD = {             # island -> zombie family (matches the ladder's rising difficulty)
    1: "egypt", 2: "egypt", 3: "egypt", 4: "egypt",
    5: "greatwall", 6: "greatwall", 7: "greatwall", 8: "greatwall",
    9: "pirate", 10: "pirate", 11: "future", 12: "future",
}
# The island shop (道具兑换) — the six entries the in-game panel shows:
# (entryId, pos, itemId, itemNum, consumeItemId, consumeItemNum).
_ZI_SHOP = [
    (1, 1, 53900, 10, _ZI_MEDAL_ITEM, 100),   # 碎片-火龙草 x10
    (2, 2, 54900, 10, _ZI_MEDAL_ITEM, 100),   # 碎片-椰子加农炮 x10
    (3, 3, 54400, 15, _ZI_MEDAL_ITEM, 50),    # 碎片-地刺 x15
    (4, 4, _ZI_BEAN_ITEM, 1, _ZI_MEDAL_ITEM, 10),
    (5, 5, _ZI_PAPER_ITEM, 1, _ZI_MEDAL_ITEM, 20),
    (6, 6, 2104, 1, _ZI_MEDAL_ITEM, 60),      # 四星叶绿素
]
_ZI_SHOP_REFRESH_HOUR = 21       # 下次刷新时间：今日21:00 (the panel's own caption)


# --- 联盟商店 (ExchangeStoreType_GuildFuben = storeId 4) -------------------------------
# The 联盟 NPC window opens the shared ExchangeStore with ExchangeStoreType_GuildFuben
# (ModuleUnion.swf UnionNPCViewMediator.onClick -> openExchangeWithType), and the runtime log
# confirms the requests arrive as storeId 4. The wares live server-side (no clientDB table), and
# the currency is 联盟勋章 (item 2028, "联盟副本的荣誉证明，可在联盟商店中兑换奖励") — the same
# token guild_modes_local's 联盟副本日奖励 hands out, so the loop is: fight 联盟副本 -> earn
# 联盟勋章 -> spend it here. entryIds 401..406: they must not collide with the island shop's
# 1..6 or 神奇兑换's 5001+ (Cmd_ExchangeStore_Exchange_CS carries ONLY entryId — the server
# tells the stores apart by their entryId ranges).
_GUILD_MEDAL_ITEM = 2028         # 联盟勋章
_GUILD_SHOP = [
    (401, 1, 53900, 10, _GUILD_MEDAL_ITEM, 100),   # 碎片-火龙草 x10
    (402, 2, 54900, 10, _GUILD_MEDAL_ITEM, 100),   # 碎片-椰子加农炮 x10
    (403, 3, 54400, 15, _GUILD_MEDAL_ITEM, 50),    # 碎片-地刺 x15
    (404, 4, 2104, 1, _GUILD_MEDAL_ITEM, 60),      # 四星叶绿素
    (405, 5, 3430, 1, _GUILD_MEDAL_ITEM, 40),      # 南瓜小巫宝箱
    (406, 6, 2021, 1, _GUILD_MEDAL_ITEM, 150),     # 稀有时装
]
_GUILD_SHOP_STORE = 4            # ExchangeStoreType_GuildFuben


def _guild_shop_state(player):
    """{entryId,...} already exchanged today in the guild shop (rolled over on a new day)."""
    if (player.get("guild_shop_day") or "") != _zi_today():
        player["guild_shop_day"] = _zi_today()
        player["guild_shop_bought"] = ""
        store.save_player(player["uin"], guild_shop_day=player["guild_shop_day"],
                          guild_shop_bought="")
    raw = player.get("guild_shop_bought") or ""
    return {int(x) for x in raw.split(",") if x.strip().isdigit()}


_ZI_LEVELS = None
_ZI_TEMPLATE = None


def load_zombie_island_levels():
    """{islandLevel: zombieLevel} from clientDB ZombieIslandLevel.txt."""
    global _ZI_LEVELS
    if _ZI_LEVELS is None:
        _ZI_LEVELS = {}
        rows = _read_clientdb_table("ZombieIslandLevel.txt")
        if rows:
            hdr = rows[0]; ci = {c: i for i, c in enumerate(hdr)}
            for r in rows[1:]:
                try:
                    _ZI_LEVELS[int(r[ci["id"]])] = int(r[ci["zombieLevel"]])
                except (ValueError, KeyError, IndexError):
                    continue
        log.info("loaded %d zombie-island levels", len(_ZI_LEVELS))
    return _ZI_LEVELS


def load_zombie_island_template():
    """[islandId,...] from clientDB ZombieIslandTemplate.txt (the islands the panel draws)."""
    global _ZI_TEMPLATE
    if _ZI_TEMPLATE is None:
        _ZI_TEMPLATE = []
        rows = _read_clientdb_table("ZombieIslandTemplate.txt")
        if rows:
            hdr = rows[0]; ci = {c: i for i, c in enumerate(hdr)}
            for r in rows[1:]:
                try:
                    _ZI_TEMPLATE.append(int(r[ci["id"]]))
                except (ValueError, KeyError, IndexError):
                    continue
        log.info("loaded %d zombie-island stages", len(_ZI_TEMPLATE))
    return _ZI_TEMPLATE


def zi_island_count():
    """How many islands the ladder has (12 in the shipped data)."""
    return len(load_zombie_island_template()) or 12


def _zi_clamp_level(level):
    return max(1, min(int(level or 1), zi_island_count()))


def _zi_enemy_units(mode, level):
    """The squad guarding `level` — deterministic per (mode, level) so the pre-fight preview and the
    fight agree. The zombies' displayed LEVEL comes from ZombieIslandLevel.txt and the total power ramps
    ~30% per island (x1.5 for the 进阶 climb); the family changes as the ladder climbs."""
    level = _zi_clamp_level(level)
    z_level = max(1, int(load_zombie_island_levels().get(level, level)))
    total_power = _ZI_BASE_POWER * (1.0 + _ZI_POWER_STEP) ** (level - 1)
    if int(mode) == _ZI_ADV:
        total_power *= _ZI_ADV_POWER_MULT
    count = max(3, min(2 + (level + 1) // 2, _ZI_LINEUP_MAX, len(_ENEMY_POS)))
    pool = [c for c in _WORLD_ZOMBIES.get(_ZI_ISLAND_WORLD.get(level, "egypt"),
                                          _DEFAULT_ENEMY_CARDS) if c in _BATTLE_CARDS] \
        or [c for c in _DEFAULT_ENEMY_CARDS if c in _BATTLE_CARDS] or [111]
    rng = _stage_rng("island", int(mode), level)
    picks = [pool[-1]]                                 # the family's strongest = the island's leader
    rest = [c for c in pool if c not in picks]
    if rest:
        picks += rng.sample(rest, min(count - 1, len(rest)))
    while len(picks) < count:
        picks.append(rng.choice(pool))
    per_power = max(1, int(total_power / count))
    hp = max(1, per_power * 9 // _ZOMBIE_HP_TEST_DIVISOR)
    atk, dfn = _enemy_atk_def(per_power)
    right = []
    for i, card_id in enumerate(picks[:count]):
        zst = _BATTLE_CARDS.get(card_id, {"skill1": 0, "skill2": 0, "name": "Zombie"})
        right.append({"pos": _ENEMY_POS[i], "card_id": card_id, "hp": hp, "atk": atk, "def_": dfn,
                      "skill1": zst.get("skill1", 0), "skill2": zst.get("skill2", 0),
                      "level": z_level, "is_leader": i == 0, "power": per_power,
                      "name": zst.get("name", "Zombie")})
    return right


def _zi_fight_key(mode, level):
    """The preview/fight identity of one island battle (mode + island)."""
    return "%d/%d" % (int(mode), _zi_clamp_level(level))


# --- island state (progress / daily restarts / chests) ------------------------------
def _zi_today():
    return time.strftime("%Y%m%d")


def _zi_state(player, mode):
    """{'level','max','refresh_used','remain','last_role_level'} with the daily restart counter already
    rolled over for a new day."""
    uin = player["uin"]
    level, mx, used, day, _boxes, _pre, role_lvl = store.island_progress(uin, mode)
    if day != _zi_today():
        used, day = 0, _zi_today()
        store.save_island_progress(uin, mode, refresh_used=0, day=day)
    return {"level": _zi_clamp_level(level), "max": int(mx), "refresh_used": int(used),
            "remain": max(0, _ZI_DAILY_REFRESH - int(used)), "last_role_level": int(role_lvl)}


def _zi_next_level(player, mode):
    """The island this mode fights next (1..zi_island_count())."""
    return _zi_state(player, mode)["level"]


def _zi_boxes(player, mode):
    """[(levelId, boxId, taken, unlocked)] for every chest of the ladder, in panel order. A chest is
    unlocked once its island has been CLEARED (max = highest island ever cleared), so the chest of the
    final island opens too — island 12 keeps `level` at 12 for a replay."""
    taken = store.island_boxes(player["uin"], mode)
    cleared = _zi_state(player, mode)["max"]
    out = []
    for lvl in sorted(load_zombie_island_template() or list(range(1, zi_island_count() + 1))):
        for box in range(1, _ZI_BOXES + 1):
            out.append((lvl, box, (lvl, box) in taken, lvl <= cleared))
    return out


def _zi_box_rewards(mode, level, box_id):
    """What one chest holds: box 1 = the guard chest (僵尸岛宝箱), 2/3 = the smaller caches."""
    lvl = _zi_clamp_level(level)
    boost = 2 if int(mode) == _ZI_ADV else 1
    if int(box_id) == 1:
        return [(_ZI_MEDAL_ITEM, (20 + 5 * lvl) * boost), (_ZI_CHEST_ITEM, 1)]
    if int(box_id) == 2:
        return [(_ZI_MEDAL_ITEM, (10 + 3 * lvl) * boost), (_ZI_BEAN_ITEM, 1 + lvl // 3)]
    return [(_ZI_MEDAL_ITEM, (5 + 2 * lvl) * boost), (_ZI_PAPER_ITEM, 2)]


def _zi_win_rewards(mode, level):
    """The per-win loot the fight report's chest shows (the island chests are claimed separately)."""
    boost = 2 if int(mode) == _ZI_ADV else 1
    return [(_ZI_MEDAL_ITEM, (8 + 2 * _zi_clamp_level(level)) * boost)]


def _zi_player_placements(player, mode):
    """{posIndex: uid} the player fields in the island: the lineup arranged in the island's own prepare
    view (SetPreCard), else the normal backyard team.

    CAPPED AT _ZI_LINEUP_MAX (6). The island prepare view happily sends more (a live save had 16 uids
    arranged), but the island RESULT window — FightResultZombieIslandMediator.update_card() in
    ModuleBattle.swf — indexes a fixed 6-slot client Vector with the report's card index, so a 7th plant
    throws `RangeError: Error #1125: 索引 6 超出范围 6` the moment the battle ends (battleEndHandler ->
    FightChestsWDMedator -> FightResultZombieIslandMediator.reset -> update_card) and the result screen
    never opens. The lawn/beforeCardList and that window must therefore agree on 6."""
    uids = store.island_precards(player["uin"], mode) or \
        [uid for _pos, uid in sorted(default_formation_placements(player).items())]
    owned = {uid for uid, _cid, _lvl, _exp in store.get_cards(player["uin"])}
    uids = [uid for uid in uids if uid in owned][:_ZI_LINEUP_MAX]
    return {_FORMATION_POS[i]: uid for i, uid in enumerate(uids)}


def _zi_fight_units(player, mode, level):
    """(left, right) for one island battle: the player's island lineup vs the island's guards. The guard
    squad is the same object the pre-fight preview showed (types only — see apply_previewed_enemy_types)."""
    left = build_player_units(player, _zi_player_placements(player, mode))
    right = _zi_enemy_units(mode, level)
    right = apply_previewed_enemy_types(player, right, "island", _zi_fight_key(mode, level))
    return left, right


def _zi_reward_box_body(level_id, box_id, taken):
    """Dto_RewardBox{levelId(1), boxId(2), hasTaken(3)} — one entry of rewardBox/rewardState."""
    return (pb_varint_field(1, int(level_id)) + pb_varint_field(2, int(box_id))
            + pb_varint_field(3, 1 if taken else 0))


def _zi_boxes_body(player, mode):
    """repeated Dto_RewardBox for every chest of the ladder (field 1 of both GetIslandInfo_SCs)."""
    body = b""
    for lvl, box, taken, _unlocked in _zi_boxes(player, mode):
        dto = _zi_reward_box_body(lvl, box, taken)
        body += pb_tag(1, 2) + uvarint(len(dto)) + dto
    return body


def _zi_precard_body(player, mode):
    """Cmd_(New)ZombieIsland_GetPreCard_SC{cardList(1, repeated int64), hasSet(2)}. The uids are written
    UNPACKED (one varint per tag), which the client's reader accepts for repeated int64."""
    uids = store.island_precards(player["uin"], mode)
    body = b"".join(pb_varint_field(1, uid) for uid in uids)
    return body + pb_varint_field(2, 1 if uids else 0)


def _zi_sync_formation(player, mode, sc_name):
    """[(sc_name, body)] pushing the island's own lineup as Dto_FormationInfo (field 1)."""
    formation = build_formation_info(player, 1, _zi_player_placements(player, mode))
    return [(sc_name, pb_tag(1, 2) + uvarint(len(formation)) + formation)]


def handle_battle_getfightinfo(cmd_data, player):
    """Cmd_Battle_GetFightInfo_CS{target(1)=Dto_BattleTarget} -> Cmd_Battle_GetFightInfo_SC
    {formation(1), enemyCard(4)=[Dto_EnemyCardInfo], enemyTotalPower(5)}. preFight_PVE sends this
    to fetch the ENEMY lineup so it can preview + PRELOAD the zombie assets BEFORE the fight — without
    it enemyCards is empty, the zombies aren't preloaded, and the replay cold-loads them mid-fight and
    crashes on the first play. The squad comes from preview_enemy_units, which builds it with the SAME
    builder (and the same ids) the fight will use and remembers it as the authoritative lineup, so the
    window can never show different zombies than the battle fields."""
    targets = parse_repeated_submessages(cmd_data, 1)
    target = parse_varint_fields(targets[0]) if targets else {}
    if target.get(1) == 16:
        data = _plant_test_state(player)
        sid, sub = target.get(12, 0), target.get(13, 0)
        right = _plant_test_enemies(player, sid, sub)
        formation = build_formation_info(player, 1, _plant_test_placements(player, data))
        body = pb_bytes(1, formation)
        for unit in right:
            body += pb_bytes(4, build_enemy_card(unit["pos"], unit["card_id"], unit["hp"],
                             unit["level"], unit["is_leader"], power=unit["power"]))
        return body + pb_varint_field(5, sum(unit["power"] for unit in right))
    tgt = parse_repeated_submessages(cmd_data, 1)
    chapter = mode = stage = ttype = wave = 0
    if tgt:
        t = parse_varint_fields(tgt[0])
        ttype = t.get(1, 0)
        chapter, mode, stage = t.get(2, 0), t.get(3, 0), t.get(4, 0)
        if ttype == _DUMMY_FUBEN_TARGET:
            # 傀儡战境 carries its own ids (Dto_BattleTarget 18..21) and leaves fuben* at 0 — the same
            # shape Trial Road / Gene Trial use (see the "preview == the fight" note above).
            chapter, mode = t.get(18, 0), t.get(19, 0)
            stage, wave = t.get(20, 0), t.get(21, 0)
        if ttype == _NOEND_FUBEN_TARGET:
            # 无尽炼狱 carries its own ids in Dto_BattleTarget 22/23 (noEndFubenModeId/StageId).
            mode, stage, wave = t.get(22, 0), t.get(23, 0), t.get(23, 0)
        if ttype == 8:  # World Boss also uses the shared pre-fight lineup request.
            boss_id = t.get(11, 0)
            if boss_id not in _WORLD_BOSS_IDS:
                return b""
            state = _worldboss_state(player)
            e = _worldboss_entry(state, boss_id)
            enemy = _worldboss_enemy(boss_id, e)
            formation = build_formation_info(player, 1, _worldboss_placements(player))
            # Preview contains the boss only; Qin summons stay hidden until casting.
            return (pb_bytes(1, formation)
                    + pb_bytes(4, build_enemy_card(enemy["pos"], boss_id, enemy["hp"], 1, False, enemy["power"]))
                    + pb_varint_field(5, enemy["power"]))
        if ttype == _RANK_ARENA_TARGET:
            # 巅峰竞技场: the enemy is the opponent the player challenged — Dto_BattleTarget.roleId
            # carries them (doChallengeEmbattle sets target.roleId = _opponentId). Without this the
            # target is 0/0/0 and the window falls back to the shared "unknown" squad, so every
            # arena preview showed the same two Egypt zombies.
            right = _arena_opponent_units(t.get(8, 0))
            if right:
                note_battle_scene(player, "arena")
                formation = build_formation_info(player, 1, default_formation_placements(player))
                d = pb_bytes(1, formation)
                for u in right:
                    d += pb_bytes(4, build_enemy_card(u["pos"], u["card_id"], u["hp"],
                                                      u.get("level", 1), u.get("is_leader", False),
                                                      power=u.get("power", 0)))
                log.info("    RankArena preview: opponent=%s -> %d units (%d power)",
                         t.get(8, 0), len(right), sum(u.get("power", 0) for u in right))
                return d + pb_varint_field(5, sum(u.get("power", 0) for u in right))
        if ttype == _GUARD_ROB_TARGET:           # 密藏掠夺(Guard)：敌方=刷新出来的目标，己方=出征阵容
            formation, cards, total_power = guard_local.rob_fight_preview(
                _activity_server_api(), player, int(t.get(14, 0) or 0))
            d = pb_bytes(1, formation)
            for ec in cards:
                d += pb_bytes(4, ec)
            log.info("    GuardRob preview: index=%s -> %d enemy cards (%d power)",
                     t.get(14, 0), len(cards), total_power)
            return d + pb_varint_field(5, total_power)

    if ttype in _ZI_TARGET_MODE:                 # the island window: mark the scene + use the island team
        zi_mode = _ZI_TARGET_MODE[ttype]
        note_battle_scene(player, _ZI_SCENE_NAMES[zi_mode])
    elif ttype == _DUMMY_FUBEN_TARGET:
        note_battle_scene(player, _DUMMY_FUBEN_SCENE)
    # The squad comes from preview_enemy_units — the SAME builder the matching fight uses, remembered as
    # the authoritative pre-fight lineup (see the "pre-fight preview == the fight itself" note).
    right = preview_enemy_units(player, chapter, mode, stage, ttype, wave)
    log.info("    battle fight-info (preload): type=%d chapter=%d mode=%d stage=%d scene=%s "
             "-> %d enemy cards %s",
             ttype, chapter, mode, stage, _battle_scene(player), len(right),
             [(u["pos"], u["card_id"]) for u in right])
    # formation (field 1) = the player's OWN plants. The pre-fight preview preloads BOTH sides' unit
    # bone-animations from the fight info; without our own formation here only the ENEMY assets get
    # preloaded, so on first play the player's plants cold-load mid-spawn and UnitFactory.updateUnit
    # crashes (#1009) partway through -> only the first few plants spawn and the rest + all zombies never do.
    if ttype in _ZI_TARGET_MODE:
        placements = _zi_player_placements(player, _ZI_TARGET_MODE[ttype])
        formation = build_formation_info(player, 1, placements)
    elif ttype == _DUMMY_FUBEN_TARGET:
        placements = _puppet_fuben_placements(player)
        formation = build_formation_info(player, 1, placements)
    elif chapter and mode and stage:
        placements, owners = _fuben_formation_entries(player)
        formation = build_formation_info_fuben(player, 1, placements, owners)
    else:
        placements = default_formation_placements(player)
        formation = build_formation_info(player, 1, placements)
    d = pb_tag(1, 2) + uvarint(len(formation)) + formation  # formation (field 1) — preload our plants
    for u in right:
        ec = build_enemy_card(u["pos"], u["card_id"], u["hp"], u["level"], u["is_leader"],
                              power=u.get("power", 0))
        d += pb_tag(4, 2) + uvarint(len(ec)) + ec           # enemyCard (field 4, repeated)
    d += pb_varint_field(5, sum(u.get("power", 0) for u in right))   # enemyTotalPower (战力)
    # puppetformation (field 6) is only part of the 傀儡战境 pre-fight contract.  In ordinary
    # adventure/activity previews the client treats this field as the *opponent*'s puppet formation;
    # echoing the player's lineup here makes zombies appear to have our puppets.  The actual battle
    # report carries the player's lineup on leftSide.puppetList when the clientDB has the puppet card
    # rows, so leave field 6 absent for every non-傀儡战境 target.
    if ttype == _DUMMY_FUBEN_TARGET:
        puppet_side = b""
        owned_puppets = store.get_puppets(player["uin"])
        for base_id in puppet_lineup(player):
            row = owned_puppets.get(base_id)
            if not row:
                continue
            dto = puppet_info_dto(base_id, row)
            puppet_side += pb_tag(1, 2) + uvarint(len(dto)) + dto
        d += pb_tag(6, 2) + uvarint(len(puppet_side)) + puppet_side
    return d


def handle_battle_fight(cmd_data, player):
    """Cmd_Battle_Fight_CS{target(1)=Dto_BattleTarget, isTryAgain(2)} -> Cmd_Battle_Fight_SC
    {report(1)=Dto_FightReport, type(2)}. Fuben target carries fubenChapterId(2)/fubenModeId(3)/
    fubenStageId(4). The outcome is decided by Fighting Power (resolve_battle): a WIN grants the loot +
    marks the stage cleared; a LOSS grants NOTHING, does NOT clear the stage, and the client shows a
    defeat screen the player can retry from. So Lab/World-Tree/card-level investment decides progress."""
    chapter = mode = stage = ttype = 0
    tgt = parse_repeated_submessages(cmd_data, 1)
    if tgt:
        t = parse_varint_fields(tgt[0])
        ttype = t.get(1, 0)
        chapter, mode, stage = t.get(2, 0), t.get(3, 0), t.get(4, 0)
    if ttype in _ZI_TARGET_MODE:
        # 勇闯僵尸岛 can also be fought through the generic battle entry: its Dto_BattleTarget only carries
        # the type (9 / 21), so the island climb drives the stage. Route it to the island fight.
        zi_mode = _ZI_TARGET_MODE[ttype]
        return _zi_run_fight(player, zi_mode, _zi_next_level(player, zi_mode))
    if ttype == _DUMMY_FUBEN_TARGET:
        # 傀儡战境 has the same shape: type 22 plus its own ids in Dto_BattleTarget 18..21. The mode's own
        # window sends Cmd_PuppetFuben_Fight_CS, but the generic entry must land on the same fight.
        wave = t.get(21, 0) or _puppet_fuben_next_wave(player, t.get(19, 0), t.get(18, 0), t.get(20, 0))
        return _puppet_fuben_run_fight(player, t.get(19, 0), t.get(18, 0), t.get(20, 0), wave)
    if ttype == _NOEND_FUBEN_TARGET:
        # 无尽炼狱：type 26，Dto_BattleTarget 用 noEndFubenModeId(22) / noEndFubenStageId(23) 承载层号。
        # 报告必须带 fight_type=26：否则客户端 BattleServiceCommand.getResourceList 会走 Fuben 分支，
        # 用 battleChapterId(此时为 0) 去 getFubenChapterTemplateById(0)，返回 null -> #1009。
        return _noend_fuben_run_fight(player, t.get(22, 0), t.get(23, 0))
    uin = player["uin"]
    # Energy: the client already gates the fight on currEnergy >= energyCost, so spend it (win or lose —
    # you used stamina attempting). fuben.txt energyCost (5 for ch1). We sync the new value below.
    energy_cost = fuben_energy_cost(chapter, mode, stage) if (chapter and stage) else 0
    if energy_cost:
        consume_energy(player, energy_cost)
    # First clear? (bonusFirst is granted once.) Check BEFORE we record this win. The whole reward —
    # every-clear Plant EXP(5) + Coins(1) + first-clear TD Key(4001)/Town Prosperity(2)/plants/items —
    # comes straight from clientDB fuben.txt (fuben_stage_reward), so the granted amounts EXACTLY match
    # the level-select tooltip, for every chapter (not just hand-transcribed ch1).
    is_first = bool(chapter and stage) and stage not in store.get_fuben_passed(uin, chapter, mode)
    reward_items = list(fuben_stage_reward(chapter, mode, stage, is_first)) if (chapter and stage) else []
    # 植物经验 (item 5) is the plant/card XP: it's what each formation plant gains AND the amount the
    # result screen animates onto their bars, so both must read from the SAME reward (matches the tooltip).
    battle_exp = sum(num for iid, num in reward_items if iid == 5)
    # Real units: player's plants (left) vs stage zombies (right), placed on the field + result screen.
    left_units, right_units = build_battle_units(player, chapter, mode, stage)
    # The pre-fight lineup window is authoritative: field the zombies the player was shown there (same
    # slots/stats, only the types are taken over — see apply_previewed_enemy_types).
    right_units = apply_previewed_enemy_types(player, right_units, "fuben",
                                             "%d/%d/%d" % (chapter, mode, stage))
    # Decide the outcome by effective Fighting Power, then animate the replay to match it.
    won, left_power, right_power = resolve_battle(left_units, right_units)
    if won and chapter and stage:
        reward_items.append((hotspot_events.SHELL, 1))
    adventure_puppet_bytes = _auto_puppet_list(player)
    adventure_side_types = (38, 1) if adventure_puppet_bytes else None
    # 普通冒险只让我方上阵傀儡出手；僵尸侧没有 puppetList，也不会生成敌方傀儡。
    # clientDB 已补齐傀儡 battleCard 行时，回放使用 puppetActor(6) 指向左侧傀儡槽位。
    rounds = simulate_battle(left_units, right_units, won, puppets=_auto_puppets(player),
                             leader_sides=("left",), stop_on_elimination=True) \
        if (left_units and right_units) else []
    replay_bytes = encode_fight_replay(rounds)
    log.info("    battle: %d plants (%d 战力) vs %d zombies (%d 战力) -> %s, %d rounds (left=%s right=%s)",
             len(left_units), left_power, len(right_units), right_power, "WIN" if won else "LOSS",
             len(rounds), [(u["pos"], u["card_id"], u["name"]) for u in left_units],
             [(u["pos"], u["card_id"]) for u in right_units])
    report = build_fight_report(player, chapter, mode, stage, won, reward_items, is_first,
                                left_units, right_units, replay_bytes, card_exp_gain=battle_exp,
                                # 只把我方傀儡挂在左侧；右侧僵尸始终没有傀儡字段。
                                puppet_bytes=adventure_puppet_bytes, side_types=adventure_side_types)
    fight_sc = (pb_tag(1, 2) + uvarint(len(report)) + report   # report (field 1)
                + pb_varint_field(2, 1))                        # type = Fuben (field 2)
    messages = [("PVZ.Cmd.Cmd_Battle_Fight_SC", fight_sc)]
    if energy_cost:
        messages.append(energy_sync_msg(player))   # HUD 体力 bar reflects the spend
    if not (chapter and stage):
        log.info("    BATTLE fight (fuben): chapter=%d mode=%d stage=%d (not saved)", chapter, mode, stage)
        return messages
    if not won:
        # A defeat: no clear, no rewards, no exp. The client shows the lose screen; retrying re-fights.
        # Earlier stages stay winnable, so the player grinds those for card/role XP, then comes back.
        log.info("    BATTLE LOSS: fuben chapter=%d mode=%d stage=%d (%d < %d*%.2f 战力) — no reward, retry",
                 chapter, mode, stage, left_power, right_power, _WIN_POWER_RATIO)
        return messages
    # A win: record it + tell the client (Cmd_Fuben_SyncStageInfo_SC): star>0 marks the stage cleared and
    # unlocks the next. Client caches it during battle, applies it on return.
    star = 3
    store.pass_fuben_stage(uin, chapter, mode, stage, star)
    si = _fuben_stage_info_dto(player, chapter, mode, stage, star)  # Dto_Fuben_StageInfo
    sync = pb_tag(1, 2) + uvarint(len(si)) + si                     # stageinfo (field 1)
    messages.append(("PVZ.Cmd.Cmd_Fuben_SyncStageInfo_SC", sync))
    # Grant the loot server-side (currencies -> HUD sync, everything else -> bag) so the
    # win chest's display matches the player's real balances/bag.
    messages += grant_fuben_reward(player, reward_items)
    # 植物经验 (item 5, computed above) is CARD XP, not a bag item — feed it to each formation plant so
    # they level up (the client animates the SAME amount onto their bars). grant_fuben_reward skips item 5.
    messages += grant_battle_card_exp(player, battle_exp)
    # ROLE exp: every adventure stage clear levels the ACCOUNT too (first-clear full, replay
    # reduced), scaled by chapter -> unlocks town buildings by playing. Pushes SyncExp/SyncLevel
    # + live building unlocks on level-up.
    role_exp = role_exp_for_clear(chapter, is_first)
    messages += grant_role_exp(player, role_exp)
    _daily_quest_touch(player, "fuben", 1)
    quest_rows = _main_quest_rows()
    messages += _quest_sync_messages(main_quest_local.record_fuben_clear(
        uin, quest_rows, chapter, mode, stage))
    messages += _quest_record_condition(player, 22, 0, int(player.get("level", 1)), quest_rows)
    messages += _quest_observe_card_progress(player, quest_rows)
    log.info("    BATTLE WIN & SAVED: fuben chapter=%d mode=%d stage=%d star=%d first=%s "
             "reward=%s cardXP=%d roleXP=%d", chapter, mode, stage, star, is_first,
             reward_items, battle_exp, role_exp)
    return messages


# --- zombie island request handlers ------------------------------------------------
# Every handler below has a "normal" (Cmd_ZombieIsland_*) and an "adv" (Cmd_NewZombieIsland_*) flavour;
# they share the state helpers above and differ only in the wire shape, so the panel's two tabs behave
# identically. Both GetInfo replies carry EVERY chest of the ladder (field 1) — the panel draws one
# IslandView per level with its box1..box3 chests — plus the island to fight next.
def handle_zi_getinfo(cmd_data, player, mode=_ZI_NORMAL):
    """Cmd_(New)ZombieIsland_GetIslandInfo_CS -> Cmd_(New)ZombieIsland_GetIslandInfo_SC.

    normal: rewardBox(1) + nextLevel(2) + lastPassRoleLevel(3)
    adv:    rewardState(1) + nextLevel(2) + refreshTimes(3) + remainTimes(4)"""
    ensure_player_cards(player)
    note_battle_scene(player, _ZI_SCENE_NAMES[mode])
    st = _zi_state(player, mode)
    body = _zi_boxes_body(player, mode) + pb_varint_field(2, st["level"])
    if mode == _ZI_ADV:
        body += pb_varint_field(3, st["refresh_used"]) + pb_varint_field(4, st["remain"])
    else:
        # lastPassRoleLevel = the role level at the last pass; before any pass the client shows the
        # player's CURRENT level, which is also what the original server reported.
        passed_level = st["last_role_level"] if st["max"] else int(player.get("level", 1))
        body += pb_varint_field(3, passed_level)
    log.info("    zombie island%s info: next=%d cleared=%d boxesTaken=%d restarts=%d/%d",
             " adv" if mode == _ZI_ADV else "", st["level"], st["max"],
             len(store.island_boxes(player["uin"], mode)), st["refresh_used"], _ZI_DAILY_REFRESH)
    return body


def handle_zi_getrefreshinfo(cmd_data, player):
    """Cmd_ZombieIsland_GetRefreshInfo_CS -> refreshTimes(1) + remainTimes(2) (the 刷新 button's data)."""
    st = _zi_state(player, _ZI_NORMAL)
    return pb_varint_field(1, st["refresh_used"]) + pb_varint_field(2, st["remain"])


def _zi_restart(player, mode):
    """重新开始: back to island 1, consuming one of the daily restarts. Returns whether it happened."""
    st = _zi_state(player, mode)
    if st["remain"] > 0:
        store.save_island_progress(player["uin"], mode, level=1,
                                   refresh_used=st["refresh_used"] + 1)
        log.info("    zombie island%s restart: climb reset to island 1 (%d/%d used today)",
                 " adv" if mode == _ZI_ADV else "", st["refresh_used"] + 1, _ZI_DAILY_REFRESH)
        return True
    log.info("    zombie island%s restart refused: no restarts left today",
             " adv" if mode == _ZI_ADV else "")
    return False


def handle_zi_refreshchallenge(cmd_data, player, mode=_ZI_NORMAL):
    """Cmd_(New)ZombieIsland_RefreshChallenge_CS -> result(1) + refreshTimes(2) + remainTimes(3)."""
    ok = _zi_restart(player, mode)
    st = _zi_state(player, mode)
    return (pb_varint_field(1, 1 if ok else 0) + pb_varint_field(2, st["refresh_used"])
            + pb_varint_field(3, st["remain"]))


def _zi_idnum_body(rewards, field=1):
    """repeated Dto_IdNum{id(1), num(2)} — the reward list of both TakeReward SCs (field 1) and of
    Dto_ZombieIsland_LevelReward (field 2)."""
    body = b""
    for item_id, num in rewards:
        dto = pb_varint_field(1, int(item_id)) + pb_varint_field(2, int(num))
        body += pb_tag(field, 2) + uvarint(len(dto)) + dto
    return body


def _zi_claim_box(player, mode, level, box_id):
    """Claim one chest: (RewardStatus, rewards). 1 = Succ, 2 = Already (claimed twice), 3 = NotQualified
    (the island isn't cleared yet / no such chest) — the client turns these into the matching tip."""
    lvl = _zi_clamp_level(level)
    box = int(box_id or 1)
    if not 1 <= box <= _ZI_BOXES or lvl > _zi_state(player, mode)["max"]:
        return 3, []
    if not store.take_island_box(player["uin"], mode, lvl, box):
        return 2, []
    return 1, _zi_box_rewards(mode, lvl, box)


def handle_zi_takereward(cmd_data, player, mode=_ZI_NORMAL):
    """Cmd_(New)ZombieIsland_TakeReward_CS{levelId(1)[, boxId(2)]}.

    normal -> {levelId(1), boxId(2), rewardStatus(3)=RewardStatus, rewardList(4)=[Dto_IdNum]}
    adv    -> {levelId(1), reward(2)=[Dto_IdNum]}"""
    f = parse_varint_fields(cmd_data)
    level, box = f.get(1, 0), f.get(2, 1)
    status, rewards = _zi_claim_box(player, mode, level, box)
    ok = status == 1
    messages = grant_fuben_reward(player, rewards) if ok else []
    if mode == _ZI_ADV:
        list_b = b""
        for item_id, num in rewards:
            dto = pb_varint_field(1, int(item_id)) + pb_varint_field(2, int(num))
            list_b += pb_tag(2, 2) + uvarint(len(dto)) + dto
        log.info("    zombie island adv chest: level=%d -> %s", level, rewards if ok else "refused")
        return [("PVZ.Cmd.Cmd_NewZombieIsland_TakeReward_SC",
                 pb_varint_field(1, _zi_clamp_level(level)) + list_b)] + messages
    # normal: rewardStatus says whether it worked (1=Succ, 2=Again, 3=NotQualified).
    list_b = b""
    for item_id, num in rewards:
        dto = pb_varint_field(1, int(item_id)) + pb_varint_field(2, int(num))
        list_b += pb_tag(4, 2) + uvarint(len(dto)) + dto
    log.info("    zombie island chest: level=%d box=%d -> status=%d %s", level, box, status,
             rewards if ok else "refused")
    return [("PVZ.Cmd.Cmd_ZombieIsland_TakeReward_SC",
             pb_varint_field(1, _zi_clamp_level(level)) + pb_varint_field(2, int(box))
             + pb_varint_field(3, status) + list_b)] + messages


def handle_newzi_takeallreward(cmd_data, player):
    """Cmd_NewZombieIsland_TakeAllReward_CS -> reward(1)=[Dto_IdNum]: open every unopened chest of a
    cleared island (the adv panel's 一键领取)."""
    total, messages = [], []
    for lvl, box, taken, unlocked in _zi_boxes(player, _ZI_ADV):
        if taken or not unlocked:
            continue
        status, rewards = _zi_claim_box(player, _ZI_ADV, lvl, box)
        if status == 1:
            total += rewards
    if total:
        messages = grant_fuben_reward(player, total)
    log.info("    zombie island adv take-all: %d stack(s) %s", len(total), total)
    return [("PVZ.Cmd.Cmd_NewZombieIsland_TakeAllReward_SC", _zi_idnum_body(total))] + messages


def handle_zi_sweep(cmd_data, player):
    """Cmd_ZombieIsland_Sweep_CS -> levelReward(1)=[Dto_ZombieIsland_LevelReward{levelId(1),
    reward(2)=[Dto_IdNum]}]: the daily sweep of every CLEARED island (normal tab only — the adv tab has
    no sweep command). One sweep per day, like the other modes' sweeps."""
    uin, today = player["uin"], _zi_today()
    _level, cleared, _used, _day, _boxes, _pre, _rl = store.island_progress(uin, _ZI_NORMAL)
    cleared = min(int(cleared), zi_island_count())
    if player.get("zi_sweep_day") == today:
        log.info("    zombie island sweep refused: already swept today")
        return [("PVZ.Cmd.Cmd_ZombieIsland_Sweep_SC", b"")]
    player["zi_sweep_day"] = today
    store.save_player(uin, zi_sweep_day=today)
    body, total = b"", []
    for lvl in range(1, cleared + 1):
        rewards = [(_ZI_MEDAL_ITEM, 4 + lvl)]
        total += rewards
        dto = pb_varint_field(1, lvl) + _zi_idnum_body(rewards, field=2)
        body += pb_tag(1, 2) + uvarint(len(dto)) + dto
    log.info("    zombie island sweep: %d island(s) -> %s", cleared, total)
    return [("PVZ.Cmd.Cmd_ZombieIsland_Sweep_SC", body)] + grant_fuben_reward(player, total)


def _zi_target_type(mode):
    """BattleTargetType of a mode (9 = ZombieIsland, 21 = NewZombieIsland) — also the fight report's
    fightType, which is what routes the client to the island's own result window."""
    return 21 if int(mode) == _ZI_ADV else 9


def _parse_repeated_varints(data, field_num):
    """Every value of a repeated varint field, in order (the client writes int64 lists UNPACKED; the
    packed form is accepted too). `parse_varint_fields` can't be used: it keeps the LAST occurrence."""
    out, pos = [], 0
    try:
        while pos < len(data):
            key, pos = read_uvarint(data, pos)
            num, wire = key >> 3, key & 7
            if wire == 0:
                value, pos = read_uvarint(data, pos)
                if num == field_num:
                    out.append(value)
            elif wire == 2:
                ln, pos = read_uvarint(data, pos)
                if num == field_num:
                    end = pos + ln
                    while pos < end:
                        value, pos = read_uvarint(data, pos)
                        out.append(value)
                else:
                    pos += ln
            elif wire == 5:
                pos += 4
            elif wire == 1:
                pos += 8
            else:
                break
    except (IndexError, ValueError):
        pass
    return out


def _zi_run_fight(player, mode, level):
    """Shared body of both island fights: field the island lineup against the island's guards, decide the
    outcome by Fighting Power and write the climb forward on a win. The reply is
    Cmd_(New)ZombieIsland_Fight_SC{levelId(1), report(2)} — the same shape for both tabs."""
    level = _zi_clamp_level(level)
    note_battle_scene(player, _ZI_SCENE_NAMES[mode])
    left, right = _zi_fight_units(player, mode, level)
    won, left_power, right_power = resolve_battle(left, right)
    rounds = simulate_battle(left, right, won) \
        if (left and right) else []
    rewards = _zi_win_rewards(mode, level) if won else None
    report = build_fight_report(player, 0, mode, level, won, rewards, False, left, right,
                                encode_fight_replay(rounds), fight_type=_zi_target_type(mode))
    sc_name = ("PVZ.Cmd.Cmd_NewZombieIsland_Fight_SC" if mode == _ZI_ADV
               else "PVZ.Cmd.Cmd_ZombieIsland_Fight_SC")
    messages = [(sc_name,
                 pb_varint_field(1, level) + pb_tag(2, 2) + uvarint(len(report)) + report)]
    log.info("    zombie island%s fight: island=%d %d plants (%d 战力) vs %d zombies (%d 战力) -> %s",
             " adv" if mode == _ZI_ADV else "", level, len(left), left_power, len(right),
             right_power, "WIN" if won else "LOSS")
    if won:
        st = _zi_state(player, mode)
        nxt = level + 1 if level < zi_island_count() else level
        store.save_island_progress(player["uin"], mode, level=nxt, max=max(st["max"], level),
                                   last_role_level=int(player.get("level", 1)))
        log.info("    zombie island%s cleared island %d: its chests are open, next=%d, loot %s",
                 " adv" if mode == _ZI_ADV else "", level, nxt, rewards)
        messages += grant_fuben_reward(player, rewards)
        messages += _quest_record_condition(player, 34, 0, 1)
        # The island panel does not reliably request GetIslandInfo again after the
        # fight result closes. Push its refreshed model now so the next island and
        # newly-opened chests are visible without leaving and re-entering the panel.
        info_sc = ("PVZ.Cmd.Cmd_NewZombieIsland_GetIslandInfo_SC" if mode == _ZI_ADV
                   else "PVZ.Cmd.Cmd_ZombieIsland_GetIslandInfo_SC")
        messages.append((info_sc, handle_zi_getinfo(b"", player, mode)))
    return messages


def _noend_fuben_squad(stage):
    """The zombie squad for one 无尽炼狱 floor.

    The lineup window and the fight MUST both come from here — the preview used to fall through to
    the generic "unknown" squad (no preview branch for BattleTargetType 26) while the fight built its
    own, so the player saw different zombies before and after the battle."""
    stage = max(1, int(stage or 1))
    # 用层号推导一个"章节档位"来缩放敌人战力：每 5 层升一档、封顶 15 章，避免高层瞬间爆炸或前期过弱。
    synthetic_chapter = min(15, max(1, (stage + 4) // 5))
    return (_build_wiki_enemies(synthetic_chapter, stage)
            or _build_fallback_enemies(synthetic_chapter, stage))


def _noend_fuben_run_fight(player, mode, stage):
    """无尽炼狱战斗：玩家已布阵植物 vs 按层号缩放的僵尸。

    关键：报告的 ``fight_type`` 必须是 ``_NOEND_FUBEN_TARGET``(26)，这样客户端
    ``BattleServiceCommand.getResourceList`` 才不会误入 Fuben 分支去查关卡模板
    （NoEndFuben 走 ``BattleServiceCmd.setData(report)`` 只传报告，battleChapterId 为 0，
    ``getFubenChapterTemplateById(0)`` 返回 null -> #1009）。26 会让客户端走默认（friend）
    资源分支，正常加载战斗并读取 ``cacheReport.leftSide/rightSide``。

    返回的仍是 ``Cmd_Battle_Fight_SC{report(1)}``，与 ``missing_features_local.noend_fight``
    的提取逻辑（抽 field 1）保持一致。
    """
    stage = max(1, int(stage or 1))
    # 左侧 = 玩家在无尽炼狱选中的出战植物（local_noend_fuben.pre_card）；未选则退回常规阵容。
    # 这样与客户端 ConfirmFight 回的 cardHpRatio 保持一致：选谁就打谁。
    left = build_player_units(player, placements=_noend_fuben_placements(player["uin"]))
    right = _noend_fuben_squad(stage)
    # 与预览用同一套：布阵窗看到谁，开打就 field 谁（只接管类型，数值仍由本层决定）。
    right = apply_previewed_enemy_types(player, right, "noend", "noend/%d" % stage)
    won, left_power, right_power = resolve_battle(left, right)
    rounds = simulate_battle(left, right, won) if (left and right) else []
    report = build_fight_report(player, min(15, max(1, (stage + 4) // 5)), 0, stage, won, [], False,
                                left, right, encode_fight_replay(rounds),
                                fight_type=_NOEND_FUBEN_TARGET)
    sc = pb_tag(1, 2) + uvarint(len(report)) + report   # report (field 1)
    log.info("    noend fuben fight: floor=%d %d plants (%d 战力) vs %d zombies (%d 战力) -> %s",
             stage, len(left), left_power, len(right), right_power, "WIN" if won else "LOSS")
    return [("PVZ.Cmd.Cmd_Battle_Fight_SC", sc)]


def _noend_fuben_placements(uin):
    """无尽炼狱出战阵容：``{posIndex: uid}``，无记录/解析失败返回 None（走常规阵容）。

    ``local_noend_fuben.pre_card`` 只是一串 uid（客户端按玩家点选顺序排布，没有位置），
    所以这里必须把它们映射到 **``_FORMATION_POS``（3,7,9,11,13,15,17）** —— 与
    ``_zi_player_placements`` 同一套规则。绝不能简单地 ``{i+1: uid}``：

      * posIndex 1 是傀儡/假人保留位、5 被跳过，客户端没有对应槽位（视图空指针 #1009）；
      * ``BattleConst.isLeft = posIndex % 2 == 1``：偶数 posIndex 会被判定成"右侧/僵尸"，
        玩家的植物直接被画到敌方半场（"对面还有植物"）；
      * 低位偶数还与 ``_ENEMY_POS`` 的僵尸位重合（pos 4 = 第一只僵尸），同一个 posIndex
        出现植物 + 僵尸两个单位，``BattleCommand.createUnitList`` 会对同一 ``UnitBase``
        跑两次 ``UpdateUnitPlan`` -> ``UnitFactory.updateUnit`` -> ``UnitBase.addControl``
        抛 "相同类型控制器只能添加一次!"。
    """
    uids = None
    try:
        con = sqlite3.connect(store.DB_PATH)
        try:
            row = con.execute("SELECT pre_card FROM local_noend_fuben WHERE uin=?",
                              (uin,)).fetchone()
        finally:
            con.close()
        if row and row[0]:
            uids = [int(x) for x in str(row[0]).split(",")
                    if x.strip().lstrip("-").isdigit()]
            uids = [u for u in uids if u > 0]
    except Exception:
        uids = None
    if not uids:
        return None
    owned = {uid for uid, _cid, _lvl, _exp in store.get_cards(uin)}
    uids = [uid for uid in uids if uid in owned][:_FORMATION_MAX]
    if not uids:
        return None
    return {_FORMATION_POS[i]: uid for i, uid in enumerate(uids)}



def handle_zi_fight(cmd_data, player, mode=_ZI_NORMAL):
    """Cmd_(New)ZombieIsland_Fight_CS{levelId(1)}. The client fights the island it shows as next; we fall
    back to the stored climb position when the field is missing."""
    level = parse_varint_fields(cmd_data).get(1, 0) or _zi_next_level(player, mode)
    return _zi_run_fight(player, mode, level)


def handle_zi_getprecard(cmd_data, player, mode=_ZI_NORMAL):
    """Cmd_(New)ZombieIsland_GetPreCard_CS -> cardList(1) + hasSet(2): the lineup arranged for the island
    (the prepare view's right-hand list). Empty + hasSet=0 until the player arranges one, in which case
    the island fields the normal backyard team."""
    ensure_player_cards(player)
    uids = store.island_precards(player["uin"], mode)
    if not uids:
        log.info("    zombie island%s pre-cards: none set (the backyard team is used)",
                 " adv" if mode == _ZI_ADV else "")
    return _zi_precard_body(player, mode)


def handle_zi_setprecard(cmd_data, player, mode=_ZI_NORMAL):
    """Cmd_(New)ZombieIsland_SetPreCard_CS{cardList(1, repeated int64)} -> remember the island lineup and
    acknowledge it (SetPreCard_SC carries no fields). The arranged list is kept as the client sent it (it
    is the prepare view's own state, echoed by GetPreCard), but only the first _ZI_LINEUP_MAX entries are
    fielded — see _zi_player_placements (the result window has 6 card slots)."""
    uids = [u for u in _parse_repeated_varints(cmd_data, 1) if u]
    if len(uids) > _ZI_LINEUP_MAX:
        log.info("    zombie island%s pre-cards: %d arranged -> only the first %d fight",
                 " adv" if mode == _ZI_ADV else "", len(uids), _ZI_LINEUP_MAX)
    store.set_island_precards(player["uin"], mode, uids)
    log.info("    zombie island%s pre-cards set: %s", " adv" if mode == _ZI_ADV else "", uids)
    sc_name = ("PVZ.Cmd.Cmd_NewZombieIsland_SetPreCard_SC" if mode == _ZI_ADV
               else "PVZ.Cmd.Cmd_ZombieIsland_SetPreCard_SC")
    return [(sc_name, b"")]


def _zi_sync_sc_name(mode):
    return ("PVZ.Cmd.Cmd_NewZombieIsland_SyncFormation_SC" if mode == _ZI_ADV
            else "PVZ.Cmd.Cmd_ZombieIsland_SyncFormation_SC")


def handle_zi_getformation(cmd_data, player, mode=_ZI_NORMAL):
    """Cmd_(New)ZombieIsland_GetFormation_CS -> Cmd_(New)ZombieIsland_SyncFormation_SC{formation(1)=
    Dto_FormationInfo}: the island's own team (the arranged list, else the backyard team)."""
    ensure_player_cards(player)
    note_battle_scene(player, _ZI_SCENE_NAMES[mode])
    return _zi_sync_formation(player, mode, _zi_sync_sc_name(mode))


def handle_zi_setformation(cmd_data, player, mode=_ZI_NORMAL):
    """Cmd_(New)ZombieIsland_SetFormation_CS{formation(1)/plantFormation(1)} -> persist the arranged team
    as the island's pre-card list and echo SyncFormation_SC (the client only refreshes once we push it)."""
    fsub = parse_repeated_submessages(cmd_data, 1)
    placed = []
    if fsub:
        for cp in parse_repeated_submessages(fsub[0], 1):        # cardPos
            c = parse_varint_fields(cp)
            pos, uid = c.get(1, 0), c.get(2, 0)
            if pos and uid:
                placed.append((pos, uid))
    if placed:
        store.set_island_precards(player["uin"], mode, [uid for _pos, uid in sorted(placed)])
    log.info("    zombie island%s formation set: %s", " adv" if mode == _ZI_ADV else "", sorted(placed))
    return _zi_sync_formation(player, mode, _zi_sync_sc_name(mode))

# --- 傀儡 (puppets — the "Dummy" module, town button Name_Dummy, opens at role level 55) -----------
# A 傀儡 is a TAMED ZOMBIE that fights beside the player's plants: the lineup's 5 slots act one per
# round ("傀儡按照首轮至五轮顺序每回合依次轮流出手") and every deployed puppet also hands the plants a
# stat bonus. Two command families serve the whole feature:
#
#   Cmd_Puppet_*        the puppet itself: GetInfo (the owned list — puppetInfo is REPEATED),
#                       Recruit (合成 from 碎片), UpgradeLevel/Star/Quality,
#                       UpgradeSkillLevel/Quality, UpgradeSparLevel/Quality (the 6 equipment parts),
#                       Swap, RecycleSparDraw (拆解图纸), Get/SetFormation (the lineup),
#                       GetExtractInfo/Extract (捕捉: 普通捕捉/高级捕捉) + Cmd_Market_BuyPuppet*.
#   Cmd_PuppetFuben_*   傀儡战境: 2 modes (1 普通 / 2 精英) x 10 chapters x 6 stages x 5 waves.
#
# Everything the client shows comes from clientDB's `dummy*` tables (傀儡 = "dummy" in the original
# code); see load_dummy_config for the list. Persistence: one row per puppet in `puppets` (its six
# equipment parts as "part:level:quality;..." in `spars`), dungeon progress in `puppet_fuben`, and the
# scalars (能量/技能点/编队/捕捉计数) in the players row — see player_store.
_DUMMY_ITEM_ENERGY = 42            # 能量 — one 傀儡战境 attempt
_DUMMY_ITEM_SKILL = 41             # 技能点 — one 傀儡技能 level
_DUMMY_ITEM_EQUIP_FRAG = 95531     # 装备碎片
_DUMMY_ITEM_FORGE = 95539          # 傀儡原石 (substitutes the equipment cost when 晋品)
_DUMMY_ITEM_SKILL_DISC = 95540     # 技能磁碟 (activates a higher 主动技能 tier)
_DUMMY_ITEM_SKILL_SHARD = 95541    # 技能残片 (skill levels past 150)
_DUMMY_ITEM_SWAP_CARD = 95542      # 傀儡交换卡 (the cost of Swap)
_DUMMY_CATCHERS = (95537, 95538)   # 普通捕捉器 / 高级捕捉器 (the two 捕捉 groups)
_DUMMY_EXP_ITEMS = (95533, 95534, 95535, 95536)      # 培养液: 10/50/250/2500 puppet exp
_DUMMY_MAX_LINEUP = 5              # 上阵傀儡: five rounds, one puppet each
_DUMMY_EQUIP_PARTS = 6             # 头盔/夹克/武器/皮靴/手套/短裤
_DUMMY_MODE_EASY, _DUMMY_MODE_ELITE = 1, 2
_DUMMY_FUBEN_TARGET = 22           # BattleTargetType_PuppetFuben (pre-fight preview routing)
_NOEND_FUBEN_TARGET = 26            # BattleTargetType_NoEndFuben (无尽炼狱) — Dto_BattleTarget 用
                                     #   noEndFubenModeId(22) / noEndFubenStageId(23) 承载层号
_DUMMY_STAR_MAX = 9                # dummyZombieStarInfo tops out at 9 stars
_DUMMY_STARTER = [(95537, 5), (95538, 5), (95533, 20), (95534, 20), (95535, 10), (95539, 20),
                  (95540, 10), (95542, 10), (95501, 1), (95506, 1), (95511, 1), (95516, 1),
                  (95521, 1), (95526, 1),
                  (95601, 100), (95602, 100), (95606, 100), (95608, 100), (95612, 100)]
# ^ one-time stash so the feature can be tried out. The last five are the 碎片 of the five 1★/白 puppets
#   (武僧/炸弹/大刀/火炬/铜锣僵尸): 100 碎片 = one 合成 each, so a fresh account owns a puppet to 上阵 /
#   升星 / 交换 / 带进傀儡战境 straight away instead of grinding 捕捉 (1 free capture per 22h) for weeks.
#   More 碎片 can be handed out any time with `python gm.py <uin> puppetpieces [count]` or the
#   启动器's 发傀儡碎片 button.

_DUMMY = None

def _dummy_cols(name):
    """(rows, {column: index}) of a clientDB table ([] when the table is missing)."""
    rows = _read_clientdb_table(name)
    if not rows:
        return [], {}
    return rows[1:], {c: i for i, c in enumerate(rows[0])}


def _dummy_int(text, default=0):
    try:
        return int(str(text).strip() or default)
    except ValueError:
        return default


def _dummy_items(text):
    """\"95540:50;1:5000000\" -> [(95540, 50), (1, 5000000)] (blank / 0-count entries dropped)."""
    out = []
    for part in str(text or "").split(";"):
        if ":" not in part:
            continue
        iid, num = part.split(":", 1)
        iid, num = _dummy_int(iid), _dummy_int(num)
        if iid > 0 and num > 0:
            out.append((iid, num))
    return out


def load_dummy_config():
    """Every 傀儡 config table, parsed once (the client's own numbers drive every action below)."""
    global _DUMMY
    if _DUMMY is not None:
        return _DUMMY
    cfg = {"zombies": {}, "levels": {}, "stars": {}, "quality": {}, "equip": {}, "equip_level": {},
           "equip_quality": {}, "skills": {}, "skill_up": {}, "active_skill": {}, "call": {},
           "stages": {}, "waves": {}, "combine": {}}
    rows, c = _dummy_cols("dummyZombieInfo.txt")
    for r in rows:
        cfg["zombies"][_dummy_int(r[c["id"]])] = {
            "name": r[c["name"]], "res": r[c["resName"]], "type": _dummy_int(r[c["type"]]),
            "enemy": _dummy_int(r[c["isEnemy"]]), "rarity": _dummy_int(r[c["rarity"]]),
            "active": _dummy_int(r[c["activeSkillId"]]), "passive": _dummy_int(r[c["passiveSkillId"]]),
            "piece": _dummy_int(r[c["pieceID"]]), "show": _dummy_int(r[c["isShow"]]),
            "composite": _dummy_int(r[c["isComposite"]]),
            "star": _dummy_int(r[c["compositeStar"]]), "quilty": _dummy_int(r[c["compositeQuilty"]]),
            "icon": _dummy_int(r[c["iconID"]]),
        }
    rows, c = _dummy_cols("dummyLevelInfo.txt")
    for r in rows:
        cfg["levels"][_dummy_int(r[c["id"]])] = {"exp": _dummy_int(r[c["exp"]]),
                                                 "role_lv": _dummy_int(r[c["needRoleLevel"]], 1)}
    rows, c = _dummy_cols("dummyZombieStarInfo.txt")
    for r in rows:
        cfg["stars"][_dummy_int(r[c["id"]])] = {"pieces": _dummy_int(r[c["needPieces"]]),
                                                "buff": _dummy_int(r[c["percentBuff"]] or 10000)}
    rows, c = _dummy_cols("dummyZombieQuiltyInfo.txt")
    for r in rows:
        needs = []
        for part in str(r[c["needEquipmentStr"]] or "").split(";"):     # "part:quilty:level"
            bits = part.split(":")
            if len(bits) == 3:
                needs.append((_dummy_int(bits[0]), _dummy_int(bits[1]), _dummy_int(bits[2])))
        cfg["quality"][_dummy_int(r[c["id"]])] = {
            "name": r[c["name"]], "max_lv": _dummy_int(r[c["maxLV"]], 1), "equip_need": needs,
            "lossless": _dummy_items(r[c["losslessItemStr"]]),
            "next": _dummy_int(r[c["nextQuiltyID"]]),
            "swap_cost": _dummy_items(r[c["exchangeNeedItemStr"]]),
        }
    rows, c = _dummy_cols("dummyEquipmentInfo.txt")
    for r in rows:
        cfg["equip"][(_dummy_int(r[c["type"]]), _dummy_int(r[c["quilty"]]))] = {
            "name": r[c["name"]], "need": _dummy_items(r[c["needItems"]]),
            "atk": _dummy_int(r[c["baseAttack"]]), "def": _dummy_int(r[c["baseDefense"]]),
            "hp": _dummy_int(r[c["baseHp"]]), "ab": _dummy_int(r[c["baseAbilty"]]),
            "g_atk": _dummy_int(r[c["growAttack"]]), "g_def": _dummy_int(r[c["growDefense"]]),
            "g_hp": _dummy_int(r[c["growHp"]]), "g_ab": _dummy_int(r[c["growAbilty"]]),
        }
    rows, c = _dummy_cols("dummyEquipmentLevelInfo.txt")
    for r in rows:
        cfg["equip_level"][_dummy_int(r[c["id"]])] = _dummy_items(r[c["needItems"]])
    rows, c = _dummy_cols("dummyEquipmentQuiltyInfo.txt")
    for r in rows:
        cfg["equip_quality"][_dummy_int(r[c["id"]])] = {
            "name": r[c["name"]], "max_lv": _dummy_int(r[c["maxLV"]], 1),
            "coins": _dummy_items(r[c["compositeDrawingCostParam"]]),
            "frags": _dummy_items(r[c["compositeDrawingGenerateParam"]]),
            "exchange": _dummy_items(r[c["exchangeNeedItemStr"]]),
        }
    cfg["skills"], cfg["skill_up"] = {}, {}
    cfg["shield_skills"] = {}        # {skillId: (percentBase_bp, percentGrow_bp)} 护盾技能（傀儡回复蓝盾）
    rows, c = _dummy_cols("dummyZombieSkillInfo.txt")
    for r in rows:
        sid = _dummy_int(r[c["id"]])
        cfg["skills"][sid] = {
            "name": r[c["name"]], "desc": r[c["desc"]], "next": _dummy_int(r[c["activeSkillId"]]),
            "base": _dummy_int(r[c["baseSkillID"]]), "info": _dummy_int(r[c["activeSkillInfoID"]]),
            "rarity": _dummy_int(r[c["rarity"]], 1), "buff": r[c["buffParam"]],
        }
        # “为…队友增加最大生命{1}的护盾”（酒气冲云/铜皮铁骨等）：傀儡出手改为给
        # 生命百分比最少的队友套盾，盾量 = percentBase + percentGrow*(lv-1) 基点。
        desc = str(r[c["desc"]] or "")
        if "的护盾" in desc and "增加" in desc:
            base_bp, grow_bp = _dummy_int(r[c["percentBaseValue"]]), _dummy_int(r[c["percentGrowValue"]])
            if base_bp > 0:
                cfg["shield_skills"][sid] = (base_bp, grow_bp)
    rows, c = _dummy_cols("dummySkillUpdateInfo.txt")
    for r in rows:
        cfg["skill_up"][_dummy_int(r[c["id"]])] = _dummy_items(r[c["needItemStr"]])
    rows, c = _dummy_cols("dummyActiveSkillInfo.txt")
    for r in rows:
        cfg["active_skill"][_dummy_int(r[c["id"]])] = {
            "need": _dummy_items(r[c["needItems"]]), "star": _dummy_int(r[c["needDummyStar"]]),
            "skill_lv": _dummy_int(r[c["needSkillLv"]]), "max": _dummy_int(r[c["maxSkill"]], 1),
        }
    rows, c = _dummy_cols("dummyZombieCallInfo.txt")
    for r in rows:
        drops = []
        for part in str(r[c["dropItemStr"]] or "").split(";"):            # "itemId:weight"
            if ":" in part:
                iid, weight = part.split(":", 1)
                drops.append((_dummy_int(iid), _dummy_int(weight)))
        cfg["call"][_dummy_int(r[c["id"]])] = {
            "need": _dummy_items(r[c["needItemStr"]]),
            "diamond": _dummy_items(r[c["needDiamondStr"]]),
            "get": _dummy_items(r[c["getItemStr"]]), "drops": drops,
            "free_cd": _dummy_int(r[c["freeCD"]]), "max": _dummy_int(r[c["maxExtractCount"]], 10),
            "desc": r[c["desc"]],
        }
    rows, c = _dummy_cols("dummyFubenStageInfo.txt")
    for r in rows:
        key = (_dummy_int(r[c["mode"]]), _dummy_int(r[c["chaperID"]]), _dummy_int(r[c["stageID"]]))
        cfg["stages"][key] = {
            "name": r[c["name"]], "min_lv": _dummy_int(r[c["openMinLv"]], 1),
            "energy": _dummy_int(r[c["needEnergy"]], 5),
            "loot": [i for i in str(r[c["lootItemStr"]] or "").split(",") if i.strip().isdigit()],
            "limit": _dummy_int(r[c["fightLimit"]]), "icon": _dummy_int(r[c["icon"]], 0),
        }
    rows, c = _dummy_cols("dummyFubenLevelInfo.txt")
    for r in rows:
        key = (_dummy_int(r[c["mode"]]), _dummy_int(r[c["chapterID"]]), _dummy_int(r[c["stageID"]]),
               _dummy_int(r[c["levelID"]]))
        cfg["waves"][key] = {"fp": float(r[c["recommandFP"]] or 0), "name": r[c["name"]]}
    rows, c = _dummy_cols("dummyCombineTemplate.txt")
    for r in rows:
        cfg["combine"][_dummy_int(r[c["id"]])] = {
            "name": r[c["name"]],
            "puppets": [_dummy_int(x) for x in str(r[c["combineStr"]] or "").split(",") if x.strip()],
        }
    _DUMMY = cfg
    log.info("loaded 傀儡 config: %d puppets, %d stages, %d skill levels",
             len(cfg["zombies"]), len(cfg["stages"]), len(cfg["skill_up"]))
    return _DUMMY


def dummy_stage_waves(mode, chapter, stage):
    """The subStageIds dummyFubenLevelInfo gives one stage (1..N)."""
    cfg = load_dummy_config()
    return sorted(k[3] for k in cfg["waves"] if k[0] == int(mode) and k[1] == int(chapter)
                  and k[2] == int(stage))


def dummy_stage_keys(mode=None, chapter=None):
    """Sorted (mode, chapter, stage) of every 傀儡战境 stage (optionally filtered)."""
    return sorted(k for k in load_dummy_config()["stages"]
                  if (mode is None or k[0] == int(mode)) and (chapter is None or k[1] == int(chapter)))
# Energy / skill points: the client's own config keys (iMaxPuppetEnergy, iRecoverPuppetEnergy*,
# iMaxPuppetSkillVal, iRecoverPuppetSkillVal*, iPuppetEnergyBuyTimes, iPuppetSkillValBuyTimes) are
# mirrored here — and echoed to the client via SERVER_CONFIG_OVERRIDES so the panel's caps agree.
_DUMMY_ENERGY_MAX = 200
_DUMMY_ENERGY_REGEN = (600, 1)          # (seconds between ticks, 能量 per tick)
_DUMMY_SKILL_MAX = 300
_DUMMY_SKILL_REGEN = (600, 1)           # (seconds between ticks, 技能点 per tick)
_DUMMY_BUY_TIMES = 5                    # purchases per day, of either currency
_DUMMY_SWAP_MIN_QUALITY = 300           # 蓝色品质及以上傀儡可交换
_DUMMY_BUY_TABLES = None
# Currencies the client keeps in the players row rather than in the bag: used by every 傀儡 price below.
_PUPPET_CURRENCIES = dict(_CURRENCY_SYNC)
_PUPPET_CURRENCIES[37] = ("ticket", "PVZ.Cmd.Cmd_SyncTicket_SC")     # 金钻 (gold diamond)


def puppet_state(player, key, cap, regen):
    """The player's CURRENT amount of a regenerating puppet currency (能量 / 技能点).

    The stored value is topped up by the elapsed ticks and both the value and the timestamp are kept
    in the players row, so closing the game never loses accumulated regen."""
    uin = player["uin"]
    now = int(time.time())
    amount = int(player.get(key) or 0)
    stamp = int(player.get(key + "_ts") or 0)
    step, per = regen
    if not stamp:
        stamp = now
    elif amount < cap:
        ticks = (now - stamp) // step
        if ticks > 0:
            amount = min(cap, amount + ticks * per)
            stamp += ticks * step
    if amount != int(player.get(key) or 0) or stamp != int(player.get(key + "_ts") or 0):
        player[key] = amount
        player[key + "_ts"] = stamp
        store.save_player(uin, **{key: amount, key + "_ts": stamp})
    return amount


def puppet_energy(player):
    """Current 能量 (a fresh account is filled when its one-time starter stash is handed out)."""
    puppet_starter_grant(player)
    return puppet_state(player, "puppet_energy", _DUMMY_ENERGY_MAX, _DUMMY_ENERGY_REGEN)


def puppet_skill_val(player):
    """Current 技能点."""
    puppet_starter_grant(player)
    return puppet_state(player, "puppet_skill_val", _DUMMY_SKILL_MAX, _DUMMY_SKILL_REGEN)


def puppet_starter_grant(player):
    """The one-time stash (捕捉器 / 培养液 / 装备图纸 / 能量 / 技能点) handed out the first time any 傀儡
    command arrives on a fresh account: the live game fed these through events this PoC never runs, and
    without them the panels are all dead ends. The flag column makes it strictly once."""
    if int(player.get("puppet_granted") or 0):
        return
    uin = player["uin"]
    for item_id, num in _DUMMY_STARTER:
        store.add_item(uin, item_id, num)
    now = int(time.time())
    player.update({"puppet_granted": 1, "puppet_energy": _DUMMY_ENERGY_MAX, "puppet_energy_ts": now,
                   "puppet_skill_val": _DUMMY_SKILL_MAX, "puppet_skill_val_ts": now})
    store.save_player(uin, puppet_granted=1, puppet_energy=_DUMMY_ENERGY_MAX, puppet_energy_ts=now,
                      puppet_skill_val=_DUMMY_SKILL_MAX, puppet_skill_val_ts=now)
    log.info("    granted one-time 傀儡 starter stash (uin=%d)", uin)


def puppet_sync_messages(player):
    """Cmd_SyncPuppetEnergy_SC{1} + Cmd_SyncPuppetSkillVal_SC{1} — pushed whenever either changes."""
    return [("PVZ.Cmd.Cmd_SyncPuppetEnergy_SC", pb_varint_field(1, puppet_energy(player))),
            ("PVZ.Cmd.Cmd_SyncPuppetSkillVal_SC", pb_varint_field(1, puppet_skill_val(player)))]


def puppet_spend(player, key, amount):
    """Spend from a regenerating pool. False (and nothing changes) when there is not enough."""
    have = puppet_energy(player) if key == "puppet_energy" else puppet_skill_val(player)
    if amount > have:
        return False
    player[key] = have - amount
    player[key + "_ts"] = int(time.time())
    store.save_player(player["uin"], **{key: player[key], key + "_ts": player[key + "_ts"]})
    return True


# ---- 拒绝时的提示 (Cmd_LogicError_SC.pos) ---------------------------------------------------
# clientDB `ErrorInfo.txt` 12200..12218 就是傀儡那一串文案，原版服务器在"这次操作不成立"时推
# `Cmd_LogicError_SC{pos=错误ID}`，客户端 ErrorHanderManager 查表弹提示。只回一个空的 _SC 会让面板
# 拿到 null(puppetInfo 缺失)，所以每个拒绝分支都要带上原因：
#   12200 你的背包已经满了      12201 无法找到指定傀儡     12202 你已经获得过该种傀儡了
#   12203 小镇等级限制傀儡升级   12204 已达到最高品质       12205 条件不足，无法晋品
#   12206 傀儡装备等级不足       12207 技能点不足           12208 技能点数量已达上限
#   12209 能量不足，需要补充一下 12210 能量已达上限         12211 傀儡等级不足
#   12212 傀儡等级限制           12213 不能合成该傀儡       12214 傀儡品质限制傀儡升级
#   12215 傀儡星级不够           12216 技能等级不够         12217 已经是最高品阶技能
#   12218 已经是该品阶最大等级    204 需求道具不足 (通用：碎片/图纸/培养液/交换卡…)
_PUPPET_ERR_BAG_FULL = 12200
_PUPPET_ERR_NO_PUPPET = 12201
_PUPPET_ERR_OWNED = 12202
_PUPPET_ERR_ROLE_LV = 12203
_PUPPET_ERR_MAX_QUALITY = 12204
_PUPPET_ERR_QUALITY_COND = 12205
_PUPPET_ERR_SPAR_LV = 12206
_PUPPET_ERR_NO_SKILL_VAL = 12207
_PUPPET_ERR_SKILL_VAL_FULL = 12208
_PUPPET_ERR_NO_ENERGY = 12209
_PUPPET_ERR_ENERGY_FULL = 12210
_PUPPET_ERR_LOW_LV = 12211
_PUPPET_ERR_LV_LIMIT = 12212
_PUPPET_ERR_CANNOT_RECRUIT = 12213
_PUPPET_ERR_QUALITY_UP = 12214
_PUPPET_ERR_STAR = 12215
_PUPPET_ERR_SKILL_LV = 12216
_PUPPET_ERR_SKILL_MAX = 12217
_PUPPET_ERR_SKILL_LV_MAX = 12218
_PUPPET_ERR_NO_ITEM = 204


def puppet_error(err_id):
    """拒绝一次傀儡操作时给客户端的提示：Cmd_LogicError_SC{pos = ErrorInfo id}。"""
    return ("PVZ.Cmd.Cmd_LogicError_SC", pb_varint_field(1, int(err_id)))


def puppet_spars(row):
    """{part: (level, quality)} — the six equipment parts of one puppet row."""
    out = {}
    for part in str(row.get("spars") or "").split(";"):
        bits = part.split(":")
        if len(bits) == 3 and _dummy_int(bits[0]) > 0:
            out[_dummy_int(bits[0])] = (_dummy_int(bits[1]), _dummy_int(bits[2]))
    return out


def puppet_spars_text(spars):
    """\"part:level:quality;...\" (the `puppets.spars` column format)."""
    return ";".join("%d:%d:%d" % (p, lv, q) for p, (lv, q) in sorted(spars.items()))


def _puppet_skill_dto(skill_id, level):
    """Dto_PuppetSkillInfo{id(1),level(2)} (empty when the slot has no skill yet)."""
    if not int(skill_id or 0):
        return b""
    return pb_varint_field(1, int(skill_id)) + pb_varint_field(2, int(level or 1))


def puppet_skills_bytes(row):
    """active(6) + passive(7) sub-messages of Dto_PuppetFullInfo / Dto_PuppetInfo."""
    out = b""
    for num, sid, lv in ((6, row.get("active_skill"), row.get("active_level")),
                         (7, row.get("passive_skill"), row.get("passive_level"))):
        sk = _puppet_skill_dto(sid, lv)
        if sk:
            out += pb_tag(num, 2) + uvarint(len(sk)) + sk
    return out


def puppet_full_dto(base_id, row):
    """Dto_PuppetFullInfo{baseId(1),exp(2),level(3),star(4),quality(5),activeSkill(6),passiveSkill(7),
    spar(8, repeated Dto_PuppetSparInfo{level(1),quality(2)})}. The spar list always carries all six
    parts in part order: the panel renders one equipment tile per index."""
    d = (pb_varint_field(1, int(base_id)) + pb_varint_field(2, int(row.get("exp") or 0))
         + pb_varint_field(3, int(row.get("level") or 1))
         + pb_varint_field(4, int(row.get("star") or 1))
         + pb_varint_field(5, int(row.get("quality") or 0)) + puppet_skills_bytes(row))
    spars = puppet_spars(row)
    for part in range(1, _DUMMY_EQUIP_PARTS + 1):
        lv, quality = spars.get(part, (0, 0))
        sp = pb_varint_field(1, lv) + pb_varint_field(2, quality)
        d += pb_tag(8, 2) + uvarint(len(sp)) + sp
    return d


def puppet_info_dto(base_id, row):
    """Dto_PuppetInfo — one lineup entry (equipment is not part of the lineup DTO)."""
    return (pb_varint_field(1, int(base_id)) + pb_varint_field(2, int(row.get("exp") or 0))
            + pb_varint_field(3, int(row.get("level") or 1))
            + pb_varint_field(4, int(row.get("star") or 1))
            + pb_varint_field(5, int(row.get("quality") or 0)) + puppet_skills_bytes(row))


def puppet_lineup(player):
    """[baseId,...] the lineup in ROUND order (round 1..5) — owned puppets only, CAPPED at 5: the
    lineup panel's five slots are what the battle lets act, one per round."""
    owned = store.get_puppets(player["uin"])
    out = []
    for raw in str(player.get("puppet_lineup") or "").split(","):
        base_id = _dummy_int(raw)
        if base_id and base_id in owned and base_id not in out:
            out.append(base_id)
    return out[:_DUMMY_MAX_LINEUP]


def save_puppet_lineup(player, base_ids):
    player["puppet_lineup"] = ",".join(str(b) for b in base_ids)
    store.save_player(player["uin"], puppet_lineup=player["puppet_lineup"])


def puppet_power(base_id, row):
    """The puppet's fighting power: its six equipment parts (dummyEquipmentInfo base + per-level grow,
    scaled by the puppet's level) and the star bonus (dummyZombieStarInfo.percentBuff). The CLIENT shows
    its own number computed from the same tables — this one drives the lineup bonus and the fight."""
    cfg = load_dummy_config()
    level = max(1, int(row.get("level") or 1))
    spars = puppet_spars(row)
    atk = def_ = hp = 0
    for part, (part_lv, part_q) in spars.items():
        e = cfg["equip"].get((part, max(1, part_q)))
        if not e:
            continue
        atk += e["atk"] + e["g_atk"] * part_lv
        def_ += e["def"] + e["g_def"] * part_lv
        hp += e["hp"] + e["g_hp"] * part_lv
    star = cfg["stars"].get(max(1, int(row.get("star") or 1)), {})
    scale = (level / 10.0) * (star.get("buff", 10000) / 10000.0)
    return int(card_power({"atk": atk, "def_": def_, "hp": hp}) * scale)


def puppet_plant_bonus(player):
    """Per-mille bonus the deployed puppets hand to EVERY plant of the lineup ("每个上阵植物获得属性
    加成"): the star buff (dummyZombieStarInfo.percentBuff - 10000) plus 10 per-mille per passive-skill
    level. Used by the 傀儡战境 battle, which is the mode the client advertises it for."""
    puppets = store.get_puppets(player["uin"])
    cfg = load_dummy_config()
    bonus = 0
    for base_id in puppet_lineup(player):
        row = puppets.get(base_id)
        if not row:
            continue
        star = cfg["stars"].get(max(1, int(row.get("star") or 1)), {})
        bonus += max(0, int(star.get("buff", 10000)) - 10000)
        bonus += 10 * max(0, int(row.get("passive_level") or 1))
    return bonus


def puppet_add_exp(player, base_id, row, exp_gain):
    """Feed `exp_gain` puppet experience: levels up while the table allows it AND the ROLE level is
    high enough (dummyLevelInfo.needRoleLevel — "小镇等级限制傀儡升级"). Returns (level, exp)."""
    cfg = load_dummy_config()
    role_lv = int(player.get("level", 1))
    level = max(1, int(row.get("level") or 1))
    exp = max(0, int(row.get("exp") or 0)) + int(exp_gain)
    while True:
        need = cfg["levels"].get(level, {}).get("exp")
        nxt_role = cfg["levels"].get(level + 1, {}).get("role_lv")
        if not need or exp < need or nxt_role is None or role_lv < int(nxt_role):
            break
        exp -= need
        level += 1
    row["level"], row["exp"] = level, exp
    store.save_puppet(player["uin"], base_id, level=level, exp=exp)
    return level, exp


