def _puppet_extract_state(player):
    """{groupId: [freeUsedAtUnix, extractCount, pity]} — the persisted 捕捉 counters."""
    out = {}
    for part in str(player.get("puppet_extract") or "").split(";"):
        bits = part.split(":")
        if len(bits) == 4:
            out[_dummy_int(bits[0])] = [_dummy_int(bits[1]), _dummy_int(bits[2]), _dummy_int(bits[3])]
    return out


def _puppet_save_extract(player, state):
    player["puppet_extract"] = ";".join("%d:%d:%d:%d" % (g, v[0], v[1], v[2])
                                        for g, v in sorted(state.items()))
    store.save_player(player["uin"], puppet_extract=player["puppet_extract"])


def puppet_extract_group(player, group_id):
    """(hasFree, freeCd, extractCount, pity) of one 捕捉 group RIGHT NOW.

    freeCd counts down to the next FREE capture (dummyZombieCallInfo.freeCD = 22h; the panel prints
    "免费捕获次数每天0点刷新"), extractCount is the group's lifetime capture count and pity the number
    of captures since the last guaranteed drop (a 高级/稀有 碎片 every maxExtractCount captures)."""
    info = load_dummy_config()["call"].get(int(group_id)) or {}
    cd = int(info.get("free_cd") or 0)
    state = _puppet_extract_state(player).get(int(group_id), [0, 0, 0])
    now = int(time.time())
    has_free = not state[0] or (cd > 0 and now - state[0] >= cd)
    free_cd = 0 if has_free else max(0, cd - (now - state[0]))
    return (1 if has_free else 0), free_cd, state[1], state[2]


def _puppet_extract_group_dto(group_id, has_free, free_cd, count):
    """Dto_Puppet_ExtractGroupInfo{groupId(1),hasFree(2),freeCd(3),extractCount(4)}."""
    return (pb_varint_field(1, int(group_id)) + pb_varint_field(2, 1 if has_free else 0)
            + pb_varint_field(3, int(free_cd)) + pb_varint_field(4, int(count)))


def handle_puppet_getextractinfo(cmd_data, player):
    """Cmd_Puppet_GetExtractInfo_CS{} -> Cmd_Puppet_GetExtractInfo_SC{groupInfo(2)} — field 2, not 1
    (Dto_Puppet_ExtractGroupInfo per 捕捉 group: 1 普通捕捉 / 2 高级捕捉)."""
    groups = sorted(load_dummy_config()["call"])
    body = b""
    for group_id in groups:
        has_free, free_cd, count, _pity = puppet_extract_group(player, group_id)
        dto = _puppet_extract_group_dto(group_id, has_free, free_cd, count)
        body += pb_tag(2, 2) + uvarint(len(dto)) + dto
    log.info("    傀儡捕捉: %d group(s), free=%s", len(groups),
             [puppet_extract_group(player, g)[0] for g in groups])
    return body


def handle_puppet_extract(cmd_data, player):
    """Cmd_Puppet_Extract_CS{groupId(1),count(2),useItem(3)} -> Cmd_Puppet_Extract_SC{groupInfo(1),
    item(2, repeated Dto_IdNum)}. 捕捉 spends the group's 捕捉器 (useItem) or 金钻, rolls that group's
    drop pool and guarantees a 高级/稀有 碎片 on every maxExtractCount-th capture (10次必出)."""
    f = parse_varint_fields(cmd_data)
    group_id = int(f.get(1, 0) or 1)
    count = max(1, min(10, int(f.get(2, 0) or 1)))
    use_item = bool(f.get(3, 0))
    info = load_dummy_config()["call"].get(group_id)
    has_free, _cd, done, _pity = puppet_extract_group(player, group_id)
    if info is None:
        log.info("    傀儡捕捉: unknown group %d", group_id)
        return [("PVZ.Cmd.Cmd_Puppet_Extract_SC", b""), puppet_error(_PUPPET_ERR_NO_PUPPET)]
    paid = max(0, count - (1 if has_free else 0))
    cost = [(i, n * paid) for i, n in (info["need"] if use_item else info["diamond"])]
    paid_msgs = _puppet_pay(player, cost)
    if paid_msgs is None:
        log.info("    傀儡捕捉: group %d x%d refused, missing %s", group_id, count, cost)
        dto = _puppet_extract_group_dto(group_id, has_free, 0, done)
        return [("PVZ.Cmd.Cmd_Puppet_Extract_SC", pb_tag(1, 2) + uvarint(len(dto)) + dto),
                puppet_error(_PUPPET_ERR_NO_ITEM if use_item else 208)]     # 208 = 钻石不足
    state = _puppet_extract_state(player)
    st = state.setdefault(group_id, [0, 0, 0])
    pool = _DUMMY_CALL_DROPS.get(group_id, _DUMMY_CALL_DROPS[1])
    gains = {}
    for _step in range(count):
        st[1] += 1
        st[2] += 1
        rng = _stage_rng("puppet-call", player["uin"], group_id, st[1])
        if st[2] >= int(info["max"]):                # the 10th capture always drops a 高级/稀有 碎片
            drop = pool["pity"][rng.randrange(len(pool["pity"]))]
            st[2] = 0
        else:
            roll = rng.randrange(sum(w for _i, w in pool["drops"]))
            drop = pool["drops"][-1][0]
            for iid, weight in pool["drops"]:
                if roll < weight:
                    drop = iid
                    break
                roll -= weight
        gains[drop] = gains.get(drop, 0) + 1
    if has_free:
        st[0] = int(time.time())
    _puppet_save_extract(player, state)
    item_upd = grant_items(player, sorted(gains.items()))
    has_free, free_cd, done, _pity = puppet_extract_group(player, group_id)
    dto = _puppet_extract_group_dto(group_id, has_free, free_cd, done)
    items = b""
    for iid, num in sorted(gains.items()):
        num_dto = pb_varint_field(1, iid) + pb_varint_field(2, num)
        items += pb_tag(2, 2) + uvarint(len(num_dto)) + num_dto
    log.info("    傀儡捕捉: group %d x%d (free=%d) cost=%s -> %s", group_id, count,
             1 if has_free else 0, cost, sorted(gains.items()))
    messages = [("PVZ.Cmd.Cmd_Puppet_Extract_SC", pb_tag(1, 2) + uvarint(len(dto)) + dto + items)]
    messages += paid_msgs
    if item_upd:
        messages.append(item_upd)
    messages += puppet_sync_messages(player)
    return messages


def _puppet_can_pay(player, costs):
    """True when [(itemId, num)] is affordable. Currencies the client keeps in the players row (see
    _PUPPET_CURRENCIES: 金币 1 / 金钻 37 / 钻石 4) are checked there, everything else in the bag."""
    for item_id, num in costs:
        if num <= 0:
            continue
        column = _PUPPET_CURRENCIES.get(item_id)
        if column:
            if int(player.get(column[0]) or 0) < num:
                return False
        elif store.get_item_count(player["uin"], item_id) < num:
            return False
    return True


def _puppet_pay(player, costs):
    """Charge [(itemId, num)] for one 傀儡 action.

    Currencies the client keeps in the players row (金币 / 金钻 / 钻石 — see _PUPPET_CURRENCIES) are
    deducted and pushed with their Sync_SC; everything else comes out of the bag. Returns the messages
    the client needs, or None when anything is missing — in which case NOTHING is charged."""
    if not _puppet_can_pay(player, costs):
        return None
    messages, bag = [], []
    for item_id, num in costs:
        if num <= 0:
            continue
        column = _PUPPET_CURRENCIES.get(item_id)
        if column:
            player[column[0]] = int(player.get(column[0]) or 0) - num
            store.save_player(player["uin"], **{column[0]: player[column[0]]})
            messages.append((column[1], pb_varint_field(1, player[column[0]])))
        else:
            bag.append((item_id, -num))
    upd = grant_items(player, bag) if bag else None
    if upd:
        messages.append(upd)
    return messages


def handle_puppet_getinfo(cmd_data, player):
    """Cmd_Puppet_GetInfo_CS{baseId(1, repeated)} -> Cmd_Puppet_GetInfo_SC{puppetInfo(1, repeated
    Dto_PuppetFullInfo)}. This IS the puppet list: an empty request means "everything I own" (how the
    panel opens), explicit ids answer just those (the detail window asks for one)."""
    puppet_starter_grant(player)
    wanted = [b for b in _parse_repeated_varints(cmd_data, 1) if b]
    puppets = store.get_puppets(player["uin"])
    ids = [b for b in wanted if b in puppets] if wanted else sorted(puppets)
    body = b""
    for base_id in ids:
        dto = puppet_full_dto(base_id, puppets[base_id])
        body += pb_tag(1, 2) + uvarint(len(dto)) + dto
    log.info("    傀儡: %d owned, answering %s", len(puppets), ids or "(none)")
    return body


def puppet_lineup_slots(player):
    """[baseId or 0] x _DUMMY_MAX_LINEUP — the lineup BY ROUND (index 0 = 首轮, 0 = that round is empty).

    `puppet_lineup` stores the puppets positionally ("0,0,1000003,0,0" = round 3), because the client's
    panel keeps its five slots keyed by position (`DummyModel.dummyZombieLineupMapByPos`,
    `getLineupZombieInfoByPos`) while Dto_PuppetInfo itself carries no position at all."""
    owned = store.get_puppets(player["uin"])
    out = []
    for raw in str(player.get("puppet_lineup") or "").split(",")[:_DUMMY_MAX_LINEUP]:
        base_id = _dummy_int(raw)
        out.append(base_id if base_id in owned and base_id not in out else 0)
    return out + [0] * (_DUMMY_MAX_LINEUP - len(out))


def puppet_formation_body(player):
    """Cmd_Puppet_GetFormation_SC body: Dto_PuppetFormation{formation(1){puppetInfo(1) x 5}}.

    The list is ALWAYS five entries long, one per ROUND (array index = round - 1) and an unused round is
    an EMPTY Dto_PuppetInfo. Sending only the deployed puppets (or nothing at all when the lineup is
    empty) leaves the client's panel without positional slots — the pods then have no drop target and
    上阵 can never be saved (the panel answers with an empty formation of its own)."""
    puppets = store.get_puppets(player["uin"])
    body = b""
    for base_id in puppet_lineup_slots(player):
        dto = puppet_info_dto(base_id, puppets[base_id]) if base_id else b""
        body += pb_tag(1, 2) + uvarint(len(dto)) + dto      # Dto_PuppetFormation.puppetInfo
    return pb_tag(1, 2) + uvarint(len(body)) + body


def handle_puppet_getformation(cmd_data, player):
    """Cmd_Puppet_GetFormation_CS -> Cmd_Puppet_GetFormation_SC{formation(1)=Dto_PuppetFormation{
    puppetInfo(1, repeated Dto_PuppetInfo x 5)}} — the 上阵傀儡 lineup in ROUND order (see
    puppet_formation_body)."""
    puppet_starter_grant(player)
    log.info("    傀儡上阵: %s", puppet_lineup(player) or "(empty)")
    return puppet_formation_body(player)


def handle_puppet_setformation(cmd_data, player):
    """Cmd_Puppet_SetFormation_CS{formation(1)=Dto_PuppetFormation{puppetInfo(1, repeated Dto_PuppetInfo)}}
    -> the saved lineup, echoed as Cmd_Puppet_GetFormation_SC.

    The request is POSITIONAL (five entries, empty ones for unused rounds — see
    puppet_formation_body), so the round of each puppet is kept. Only owned puppets are stored and at
    most _DUMMY_MAX_LINEUP of them (the five rounds a battle lets act).

    Note the reply: the client has NO Cmd_Puppet_SetFormation_SC class (check Assets/src/PVZ/Cmd), its
    lineup only refreshes on the GetFormation_SC push — the same handshake 傀儡战境 and 僵尸岛 use. An
    empty SetFormation_SC alone leaves the panel showing nothing."""
    puppets = store.get_puppets(player["uin"])
    formations = parse_repeated_submessages(cmd_data, 1)
    slots = []
    for info in (parse_repeated_submessages(formations[0], 1) if formations else []):
        base_id = parse_varint_fields(info).get(1, 0)
        slots.append(base_id if base_id and base_id in puppets and base_id not in slots else 0)
    slots = slots[:_DUMMY_MAX_LINEUP]
    slots += [0] * (_DUMMY_MAX_LINEUP - len(slots))
    save_puppet_lineup(player, slots)
    log.info("    傀儡上阵 set: %s (rounds %s)", puppet_lineup(player) or "(empty)",
             [i + 1 for i, b in enumerate(slots) if b])
    return [("PVZ.Cmd.Cmd_Puppet_SetFormation_SC", b""),
            ("PVZ.Cmd.Cmd_Puppet_GetFormation_SC", puppet_formation_body(player))]


def handle_puppet_recruit(cmd_data, player):
    """Cmd_Puppet_Recruit_CS{baseId(1)} -> Cmd_Puppet_Recruit_SC{puppetInfo(1)=Dto_PuppetFullInfo}:
    合成 a puppet out of its 碎片 — dummyZombieStarInfo[compositeStar].needPieces of
    dummyZombieInfo.pieceID, handed over at that star/quality with both skills at level 1.

    A request the server will not honour is answered with the puppet's CURRENT DTO whenever the
    player owns it (合成 on a puppet you already have is the panel's most common misclick: the
    client dereferences puppetInfo, so an empty SC leaves it with null data)."""
    base_id = int(parse_varint_fields(cmd_data).get(1, 0))
    cfg = load_dummy_config()
    info = cfg["zombies"].get(base_id)
    if not info or not info["composite"] or not info["piece"]:
        log.info("    傀儡合成: %d is not a composable puppet", base_id)
        return [("PVZ.Cmd.Cmd_Puppet_Recruit_SC", b""), puppet_error(_PUPPET_ERR_CANNOT_RECRUIT)]
    owned = store.get_puppet(player["uin"], base_id)
    if owned:                                       # already recruited -> re-send it + explain
        log.info("    傀儡合成: %d (%s) is already owned (star=%s) — echoing it back",
                 base_id, info["name"], owned.get("star"))
        sc = puppet_full_dto(base_id, owned)
        return [("PVZ.Cmd.Cmd_Puppet_Recruit_SC", pb_tag(1, 2) + uvarint(len(sc)) + sc),
                puppet_error(_PUPPET_ERR_OWNED)]
    star = max(1, int(info["star"] or 1))
    need = int(cfg["stars"].get(star, {}).get("pieces") or 100)
    have = store.get_item_count(player["uin"], info["piece"])
    if have < need:
        log.info("    傀儡合成: %d needs x%d of %d (has %d)", base_id, need, info["piece"], have)
        return [("PVZ.Cmd.Cmd_Puppet_Recruit_SC", b""), puppet_error(_PUPPET_ERR_NO_ITEM)]
    row = {"exp": 0, "level": 1, "star": star, "quality": int(info["quilty"] or 100),
           "active_skill": int(info["active"] or 0), "active_level": 1,
           "passive_skill": int(info["passive"] or 0), "passive_level": 1, "spars": ""}
    store.save_puppet(player["uin"], base_id, **row)
    upd = grant_items(player, [(info["piece"], -need)])
    log.info("    傀儡合成: %s (baseId=%d) for x%d of %d", info["name"], base_id, need, info["piece"])
    sc = puppet_full_dto(base_id, row)
    messages = [("PVZ.Cmd.Cmd_Puppet_Recruit_SC", pb_tag(1, 2) + uvarint(len(sc)) + sc)]
    if upd:
        messages.append(upd)
    return messages


_DUMMY_EXP_PER_ITEM = {95533: 10, 95534: 50, 95535: 250, 95536: 2500}   # 培养液 (ItemInfo useEffect)


def _puppet_upgrade_refused(sc_name, base_id, extra=b"", err=_PUPPET_ERR_NO_PUPPET):
    """The refused-upgrade ACK: the request's own _SC (the panel simply keeps its old values) PLUS the
    ErrorInfo 提示 the live game pops for that reason (see the _PUPPET_ERR_* table)."""
    log.info("    傀儡拒绝: %s baseId=%s err=%d", sc_name.rsplit(".", 1)[-1], base_id, err)
    return [(sc_name, pb_varint_field(1, base_id) + extra), puppet_error(err)]


def handle_puppet_upgradelevel(cmd_data, player):
    """Cmd_Puppet_UpgradeLevel_CS{baseId(1),itemId(2),num(3)} -> _SC{baseId,itemId,num,level(4),exp(5)}:
    feed 培养液 — dummyLevelInfo keeps the exp per level and the ROLE level each puppet level needs."""
    f = parse_varint_fields(cmd_data)
    base_id, item_id = int(f.get(1, 0)), int(f.get(2, 0))
    num = int(f.get(3, 0) or 1)
    row = store.get_puppet(player["uin"], base_id)
    per = _DUMMY_EXP_PER_ITEM.get(item_id)
    if not row:
        return _puppet_upgrade_refused("PVZ.Cmd.Cmd_Puppet_UpgradeLevel_SC", base_id)
    if not per or num <= 0:
        return _puppet_upgrade_refused("PVZ.Cmd.Cmd_Puppet_UpgradeLevel_SC", base_id,
                                       err=_PUPPET_ERR_NO_ITEM)
    num = min(num, store.get_item_count(player["uin"], item_id))
    if num <= 0:                                     # no 培养液 left in the bag
        return _puppet_upgrade_refused("PVZ.Cmd.Cmd_Puppet_UpgradeLevel_SC", base_id,
                                       err=_PUPPET_ERR_NO_ITEM)
    level, exp = puppet_add_exp(player, base_id, row, per * num)
    upd = grant_items(player, [(item_id, -num)])
    body = (pb_varint_field(1, base_id) + pb_varint_field(2, item_id) + pb_varint_field(3, num)
            + pb_varint_field(4, level) + pb_varint_field(5, exp))
    log.info("    傀儡升级: baseId=%d -> lv%d exp%d (%d x%d)", base_id, level, exp, item_id, num)
    messages = [("PVZ.Cmd.Cmd_Puppet_UpgradeLevel_SC", body)]
    if upd:
        messages.append(upd)
    return messages


def handle_puppet_upgradestar(cmd_data, player):
    """Cmd_Puppet_UpgradeStar_CS{baseId(1)} -> _SC{baseId(1),star(2)}: 升星 spends
    dummyZombieStarInfo[star+1].needPieces of the puppet's 碎片 (top star = _DUMMY_STAR_MAX)."""
    base_id = int(parse_varint_fields(cmd_data).get(1, 0))
    row = store.get_puppet(player["uin"], base_id)
    info = load_dummy_config()["zombies"].get(base_id)
    if not row or not info:
        return _puppet_upgrade_refused("PVZ.Cmd.Cmd_Puppet_UpgradeStar_SC", base_id,
                                       pb_varint_field(2, 1))
    star = max(1, int(row.get("star") or 1))
    nxt = star + 1
    need = int(load_dummy_config()["stars"].get(nxt, {}).get("pieces") or 0)
    if not need or star >= _DUMMY_STAR_MAX:
        log.info("    傀儡升星: baseId=%d already at %d★ (top %d)", base_id, star, _DUMMY_STAR_MAX)
        return _puppet_upgrade_refused("PVZ.Cmd.Cmd_Puppet_UpgradeStar_SC", base_id,
                                       pb_varint_field(2, star), err=_PUPPET_ERR_STAR)
    if store.get_item_count(player["uin"], info["piece"]) < need:
        log.info("    傀儡升星: baseId=%d star %d refused (need %d of %d)", base_id, nxt, need,
                 info["piece"])
        return _puppet_upgrade_refused("PVZ.Cmd.Cmd_Puppet_UpgradeStar_SC", base_id,
                                       pb_varint_field(2, star), err=_PUPPET_ERR_NO_ITEM)
    row["star"] = nxt
    store.save_puppet(player["uin"], base_id, star=nxt)
    upd = grant_items(player, [(info["piece"], -need)])
    log.info("    傀儡升星: baseId=%d -> %d星 (x%d of %d)", base_id, nxt, need, info["piece"])
    messages = [("PVZ.Cmd.Cmd_Puppet_UpgradeStar_SC",
                 pb_varint_field(1, base_id) + pb_varint_field(2, nxt))]
    if upd:
        messages.append(upd)
    return messages


def _puppet_equip_gaps(row, quality):
    """[part] of the six equipment parts that are BEHIND dummyZombieQuiltyInfo[quality].needEquipmentStr
    ("part:quilty:level"): that is exactly what 傀儡晋品 asks for ("请提升全部装备再晋品傀儡")."""
    need = load_dummy_config()["quality"].get(int(quality), {}).get("equip_need") or []
    spars = puppet_spars(row)
    gaps = []
    for part, part_q, part_lv in need:
        have_lv, have_q = spars.get(part, (0, 0))
        if have_q != part_q or have_lv < part_lv:
            gaps.append(part)
    return gaps


def handle_puppet_upgradequality(cmd_data, player):
    """Cmd_Puppet_UpgradeQuality_CS{baseId(1),useItem(2)} -> _SC{baseId,useItem,quality(3)} — 傀儡晋品.

    Needs every part of dummyZombieQuiltyInfo[target].needEquipmentStr at its quality+level. `useItem`
    spends the CURRENT quality's losslessItemStr (傀儡原石 — "在傀儡晋品时使用可以替代装备消耗") so a
    player who cannot raise the gear can still promote."""
    f = parse_varint_fields(cmd_data)
    base_id, use_item = int(f.get(1, 0)), bool(f.get(2, 0))
    row = store.get_puppet(player["uin"], base_id)
    cfg = load_dummy_config()
    if not row:
        return _puppet_upgrade_refused("PVZ.Cmd.Cmd_Puppet_UpgradeQuality_SC", base_id,
                                       pb_varint_field(2, 1 if use_item else 0)
                                       + pb_varint_field(3, 0))
    quality = int(row.get("quality") or 0)
    target = int(cfg["quality"].get(quality, {}).get("next") or 0)

    def refuse(err=_PUPPET_ERR_QUALITY_COND):
        return _puppet_upgrade_refused("PVZ.Cmd.Cmd_Puppet_UpgradeQuality_SC", base_id,
                                       pb_varint_field(2, 1 if use_item else 0)
                                       + pb_varint_field(3, quality), err=err)

    if not target or target not in cfg["quality"]:
        return refuse(_PUPPET_ERR_MAX_QUALITY)          # 已达到最高品质
    gaps = _puppet_equip_gaps(row, target)
    cost = list(cfg["quality"][quality]["lossless"]) if (gaps and use_item) else []
    if gaps and not use_item:
        log.info("    傀儡晋品: baseId=%d refused, parts %s are behind", base_id, gaps)
        return refuse(_PUPPET_ERR_SPAR_LV)              # 请提升全部装备再晋品傀儡
    paid = _puppet_pay(player, cost)
    if paid is None:
        log.info("    傀儡晋品: baseId=%d refused, missing %s", base_id, cost)
        return refuse(_PUPPET_ERR_NO_ITEM)
    row["quality"] = target
    store.save_puppet(player["uin"], base_id, quality=target)
    log.info("    傀儡晋品: baseId=%d %s -> %s (gaps=%s cost=%s)", base_id,
             cfg["quality"].get(quality, {}).get("name", quality),
             cfg["quality"][target]["name"], gaps, cost)
    messages = [("PVZ.Cmd.Cmd_Puppet_UpgradeQuality_SC",
                 pb_varint_field(1, base_id) + pb_varint_field(2, 1 if use_item else 0)
                 + pb_varint_field(3, target))]
    messages += paid
    return messages


def _puppet_skill_cap(base_id, row, passive):
    """The level cap of one skill: dummyActiveSkillInfo[skill.infoInfo].maxSkill, and never above the
    puppet's own level ("技能等级不能超过傀儡等级")."""
    cfg = load_dummy_config()
    skill_id = int(row.get("passive_skill" if passive else "active_skill") or 0)
    skill = cfg["skills"].get(skill_id) or {}
    info = cfg["active_skill"].get(int(skill.get("info") or 0)) or {}
    return min(int(info.get("max") or 1), max(1, int(row.get("level") or 1)))


def _puppet_pay_skill_cost(player, costs):
    """技能点 (item 41) is spent from the REGENERATING pool (Cmd_SyncPuppetSkillVal_SC), 金币 from the coin
    column and everything else from the bag. Returns the client messages, or False when unaffordable
    (nothing is spent in that case)."""
    pool_cost = sum(n for i, n in costs if i == _DUMMY_ITEM_SKILL)
    rest = [(i, n) for i, n in costs if i != _DUMMY_ITEM_SKILL]
    if not _puppet_can_pay(player, rest) or puppet_skill_val(player) < pool_cost:
        return False
    if pool_cost and not puppet_spend(player, "puppet_skill_val", pool_cost):
        return False
    paid = _puppet_pay(player, rest)
    return False if paid is None else paid


def handle_puppet_upgradeskilllevel(cmd_data, player):
    """Cmd_Puppet_UpgradeSkillLevel_CS{baseId(1),passiveSkill(2)} -> _SC{baseId,passiveSkill,level(3)}:
    one level for dummySkillUpdateInfo[level+1]'s price (金币 + 技能点, plus 技能残片 95541 past 150)."""
    f = parse_varint_fields(cmd_data)
    base_id, passive = int(f.get(1, 0)), bool(f.get(2, 0))
    key = "passive_level" if passive else "active_level"
    row = store.get_puppet(player["uin"], base_id)

    def refuse(err=_PUPPET_ERR_NO_PUPPET):
        return _puppet_upgrade_refused("PVZ.Cmd.Cmd_Puppet_UpgradeSkillLevel_SC", base_id,
                                       pb_varint_field(2, 1 if passive else 0)
                                       + pb_varint_field(3, 1), err=err)

    if not row:
        return refuse()
    level = max(1, int(row.get(key) or 1))
    cap = _puppet_skill_cap(base_id, row, passive)
    cost = load_dummy_config()["skill_up"].get(level + 1)
    if level >= cap or not cost:
        log.info("    傀儡技能: baseId=%d %s lv%d refused (cap %d)", base_id,
                 "passive" if passive else "active", level, cap)
        return refuse(_PUPPET_ERR_SKILL_LV_MAX)       # 已经是该品阶最大等级
    paid = _puppet_pay_skill_cost(player, cost)
    if paid is False:
        log.info("    傀儡技能: baseId=%d lv%d refused, cost %s", base_id, level + 1, cost)
        return refuse(_PUPPET_ERR_NO_SKILL_VAL)       # 技能点不足
    row[key] = level + 1
    store.save_puppet(player["uin"], base_id, **{key: level + 1})
    log.info("    傀儡技能: baseId=%d %s -> lv%d (cost %s)", base_id,
             "passive" if passive else "active", level + 1, cost)
    messages = [("PVZ.Cmd.Cmd_Puppet_UpgradeSkillLevel_SC",
                 pb_varint_field(1, base_id) + pb_varint_field(2, 1 if passive else 0)
                 + pb_varint_field(3, level + 1))]
    messages += paid
    messages += puppet_sync_messages(player)
    return messages


def handle_puppet_upgradeskillquality(cmd_data, player):
    """Cmd_Puppet_UpgradeSkillQuality_CS{baseId(1),passiveSkill(2)} -> _SC{baseId,passiveSkill,skillId(3)}
    — 技能晋品: once the skill reached dummyActiveSkillInfo.needSkillLv (and the puppet has needDummyStar
    stars) it promotes to dummyZombieSkillInfo[skill].activeSkillId for that row's needItems (技能磁碟)."""
    f = parse_varint_fields(cmd_data)
    base_id, passive = int(f.get(1, 0)), bool(f.get(2, 0))
    key = "passive_skill" if passive else "active_skill"
    lv_key = "passive_level" if passive else "active_level"
    row = store.get_puppet(player["uin"], base_id)
    cfg = load_dummy_config()
    skill_id = int((row or {}).get(key) or 0)
    skill = cfg["skills"].get(skill_id) or {}

    def refuse(err=_PUPPET_ERR_NO_PUPPET):
        return _puppet_upgrade_refused("PVZ.Cmd.Cmd_Puppet_UpgradeSkillQuality_SC", base_id,
                                       pb_varint_field(2, 1 if passive else 0)
                                       + pb_varint_field(3, skill_id), err=err)

    if not row or not skill:
        return refuse()
    target = int(skill.get("next") or 0)
    info = cfg["active_skill"].get(int(skill.get("info") or 0)) or {}
    level = max(1, int(row.get(lv_key) or 1))
    if not target or target not in cfg["skills"]:
        return refuse(_PUPPET_ERR_SKILL_MAX)          # 已经是最高品阶技能
    if int(row.get("star") or 1) < int(info.get("star") or 0):
        return refuse(_PUPPET_ERR_STAR)               # 傀儡星级不够
    if level < int(info.get("skill_lv") or 0):
        log.info("    傀儡技能晋品: baseId=%d skill=%d refused (lv%d/%s star%d/%s)",
                 base_id, skill_id, level, info.get("skill_lv"), int(row.get("star") or 1),
                 info.get("star"))
        return refuse(_PUPPET_ERR_SKILL_LV)           # 技能等级不够
    paid = _puppet_pay(player, info.get("need") or [])
    if paid is None:
        log.info("    傀儡技能晋品: baseId=%d refused, missing %s", base_id, info.get("need"))
        return refuse(_PUPPET_ERR_NO_ITEM)
    row[key] = target
    store.save_puppet(player["uin"], base_id, **{key: target})
    log.info("    傀儡技能晋品: baseId=%d %s %d -> %d", base_id, "passive" if passive else "active",
             skill_id, target)
    messages = [("PVZ.Cmd.Cmd_Puppet_UpgradeSkillQuality_SC",
                 pb_varint_field(1, base_id) + pb_varint_field(2, 1 if passive else 0)
                 + pb_varint_field(3, target))]
    messages += paid
    return messages


def _puppet_spar_build_cost(part, quality):
    """The price of BUILDING one equipment part at `quality`: dummyEquipmentInfo's needItems
    (the part's 图纸 + 装备碎片 95531)."""
    return list(load_dummy_config()["equip"].get((part, max(1, quality)), {}).get("need") or [])


def handle_puppet_upgradesparlevel(cmd_data, player):
    """Cmd_Puppet_UpgradeSparLevel_CS{baseId(1),sparType(2),maxUpgradeCount(3)} -> _SC{baseId,sparType,
    maxUpgradeCount,level(4)} — 升级装备 / 一键升级.

    Level 0 -> 1 BUILDS the part; every further level costs dummyEquipmentLevelInfo[level] (装备碎片 +
    金币). maxUpgradeCount is the panel's budget: the loop repeats while the bag allows (0 = one level),
    and dummyEquipmentQuiltyInfo caps the level per quality."""
    f = parse_varint_fields(cmd_data)
    base_id, part = int(f.get(1, 0)), int(f.get(2, 0))
    want = max(1, int(f.get(3, 0) or 1))
    row = store.get_puppet(player["uin"], base_id)
    cfg = load_dummy_config()
    spars = puppet_spars(row or {})
    level, quality = spars.get(part, (0, 0))
    cap = int(cfg["equip_quality"].get(max(1, quality), {}).get("max_lv") or 0)
    messages = []
    for _step in range(want):
        if level and cap and level >= cap:
            break
        if level == 0:
            cost, nxt_quality = _puppet_spar_build_cost(part, 1), max(1, quality)
        else:
            cost, nxt_quality = list(cfg["equip_level"].get(level, [])), quality
        if not cost:
            break
        paid = _puppet_pay(player, cost)
        if paid is None:
            break
        messages += paid
        level += 1
        quality = nxt_quality
        spars[part] = (level, quality)
        store.save_puppet(player["uin"], base_id, spars=puppet_spars_text(spars))
        log.info("    傀儡装备升级: baseId=%d part %d -> q%d lv%d (cost %s)", base_id, part, quality,
                 level, cost)
    if not messages:                 # nothing was built/levelled: say why (the panel would just
        # keep showing the old level and the click would look dead)
        messages.append(puppet_error(_PUPPET_ERR_SPAR_LV if level >= max(1, cap)
                                     else _PUPPET_ERR_NO_ITEM))
    body = (pb_varint_field(1, base_id) + pb_varint_field(2, part) + pb_varint_field(3, want)
            + pb_varint_field(4, level))
    return [("PVZ.Cmd.Cmd_Puppet_UpgradeSparLevel_SC", body)] + messages


def handle_puppet_upgradesparquality(cmd_data, player):
    """Cmd_Puppet_UpgradeSparQuality_CS{baseId(1),sparType(2)} -> _SC{baseId,sparType,quality(3),level(4)}
    — 晋级装备: the part must sit at its current dummyEquipmentQuiltyInfo.maxLV, and promoting pays the
    NEXT quality's 图纸 (dummyEquipmentInfo[(part, q+1)].needItems) plus that quality's 装备碎片/金币
    (dummyEquipmentQuiltyInfo.compositeDrawingGenerateParam / compositeDrawingCostParam). The level is
    kept — the new quality simply raises the cap (10/40/80/130/200)."""
    f = parse_varint_fields(cmd_data)
    base_id, part = int(f.get(1, 0)), int(f.get(2, 0))
    row = store.get_puppet(player["uin"], base_id)
    cfg = load_dummy_config()
    spars = puppet_spars(row or {})
    level, quality = spars.get(part, (0, 0))
    if quality <= 0:                                   # not built yet: build it at quality 1
        target, cost, level = 1, _puppet_spar_build_cost(part, 1), 1
    else:
        cur = cfg["equip_quality"].get(quality) or {}
        target = quality + 1
        if target not in cfg["equip_quality"] or level < int(cur.get("max_lv") or 0):
            log.info("    傀儡装备晋品: baseId=%d part %d refused (q%d lv%d, needs lv%s)", base_id,
                     part, quality, level, cur.get("max_lv"))
            return _puppet_upgrade_refused("PVZ.Cmd.Cmd_Puppet_UpgradeSparQuality_SC", base_id,
                                           pb_varint_field(2, part) + pb_varint_field(3, quality)
                                           + pb_varint_field(4, level), err=_PUPPET_ERR_SPAR_LV)
        nxt = cfg["equip_quality"][target]
        cost = (_puppet_spar_build_cost(part, target) + list(nxt.get("frags") or [])
                + list(nxt.get("coins") or []))
    paid = _puppet_pay(player, cost)
    if paid is None:
        log.info("    傀儡装备晋品: baseId=%d part %d refused, missing %s", base_id, part, cost)
        return _puppet_upgrade_refused("PVZ.Cmd.Cmd_Puppet_UpgradeSparQuality_SC", base_id,
                                       pb_varint_field(2, part) + pb_varint_field(3, quality)
                                       + pb_varint_field(4, level), err=_PUPPET_ERR_NO_ITEM)
    spars[part] = (level, target)
    store.save_puppet(player["uin"], base_id, spars=puppet_spars_text(spars))
    log.info("    傀儡装备晋品: baseId=%d part %d -> q%d lv%d (cost %s)", base_id, part, target, level,
             cost)
    messages = [("PVZ.Cmd.Cmd_Puppet_UpgradeSparQuality_SC",
                 pb_varint_field(1, base_id) + pb_varint_field(2, part) + pb_varint_field(3, target)
                 + pb_varint_field(4, level))]
    messages += paid
    return messages


def handle_puppet_recyclespardraw(cmd_data, player):
    """Cmd_Puppet_RecycleSparDraw_CS{id(1),num(2)} -> _SC{item(1, repeated Dto_IdNum)} — 拆解图纸: a 装备
    图纸 (95501..95530 = 6 parts x 5 qualities) breaks down into that quality's
    dummyEquipmentQuiltyInfo.compositeDrawingGenerateParam (装备碎片 95531)."""
    f = parse_varint_fields(cmd_data)
    item_id = int(f.get(1, 0))
    num = max(1, int(f.get(2, 0) or 1))
    quality = (item_id - 95501) // 5 + 1 if 95501 <= item_id <= 95530 else 0
    if not quality:
        log.info("    傀儡图纸拆解: %d is not an equipment drawing", item_id)
        return [("PVZ.Cmd.Cmd_Puppet_RecycleSparDraw_SC", b"")]
    num = min(num, store.get_item_count(player["uin"], item_id))
    if num <= 0:
        return [("PVZ.Cmd.Cmd_Puppet_RecycleSparDraw_SC", b"")]
    gains = [(i, n * num) for i, n in
             (load_dummy_config()["equip_quality"].get(quality, {}).get("frags") or [(95531, 30)])]
    upd = grant_items(player, [(item_id, -num)] + gains)
    items = b""
    for iid, count in gains:
        dto = pb_varint_field(1, iid) + pb_varint_field(2, count)
        items += pb_tag(1, 2) + uvarint(len(dto)) + dto
    log.info("    傀儡图纸拆解: %d x%d -> %s", item_id, num, gains)
    messages = [("PVZ.Cmd.Cmd_Puppet_RecycleSparDraw_SC", items)]
    if upd:
        messages.append(upd)
    return messages


def handle_puppet_swap(cmd_data, player):
    """Cmd_Puppet_Swap_CS{srcBaseId(1),dstBaseId(2)} -> _SC{srcBaseId,dstBaseId} — 傀儡交换: LEVEL, exp,
    QUALITY and the six equipment parts move between two puppets (the panel's own note: "傀儡品质，等级交换
    / 装备品质，等级互换", while "傀儡星级不交换 / 傀儡技能不交换"). Only 蓝色品质及以上 puppets may be
    swapped and the price is the higher quality's exchangeNeedItemStr (傀儡交换卡 95542)."""
    f = parse_varint_fields(cmd_data)
    src, dst = int(f.get(1, 0)), int(f.get(2, 0))
    puppets = store.get_puppets(player["uin"])
    a, b = puppets.get(src), puppets.get(dst)
    if not a or not b or src == dst:
        log.info("    傀儡交换: %d <-> %d refused (own=%s,%s same=%s)", src, dst,
                 bool(a), bool(b), src == dst)
        return [("PVZ.Cmd.Cmd_Puppet_Swap_SC", b""), puppet_error(_PUPPET_ERR_NO_PUPPET)]
    cfg = load_dummy_config()
    quality = max(int(a.get("quality") or 0), int(b.get("quality") or 0))
    if quality < _DUMMY_SWAP_MIN_QUALITY:       # 蓝色品质及以上傀儡可交换
        log.info("    傀儡交换: %d <-> %d refused, quality %d < %d", src, dst, quality,
                 _DUMMY_SWAP_MIN_QUALITY)
        return [("PVZ.Cmd.Cmd_Puppet_Swap_SC", b""), puppet_error(_PUPPET_ERR_QUALITY_UP)]
    cost = list(cfg["quality"].get(quality, {}).get("swap_cost") or [])
    if _puppet_pay(player, cost) is None:
        log.info("    傀儡交换: %d <-> %d refused, missing %s", src, dst, cost)
        return [("PVZ.Cmd.Cmd_Puppet_Swap_SC", b""), puppet_error(_PUPPET_ERR_NO_ITEM)]
    fields = ("level", "exp", "quality", "spars")
    swap = {k: a.get(k) for k in fields}
    store.save_puppet(player["uin"], src, **{k: b.get(k) for k in fields})
    store.save_puppet(player["uin"], dst, **swap)
    log.info("    傀儡交换: %d lv%s q%s spars=%s <-> %d lv%s q%s spars=%s (cost %s)", src, a.get("level"),
             a.get("quality"), a.get("spars"), dst, b.get("level"), b.get("quality"), b.get("spars"), cost)
    body = pb_varint_field(1, src) + pb_varint_field(2, dst)
    return [("PVZ.Cmd.Cmd_Puppet_Swap_SC", body)]


def _dummy_buy_tables():
    """{'energy'|'skill': [(buyNumber, diamondPrice, amount)]} — the two 傀儡 market tables."""
    global _DUMMY_BUY_TABLES
    if _DUMMY_BUY_TABLES is None:
        tables = {}
        for key, table in (("energy", "dummyBuyFubenEnemgyInfo.txt"),
                           ("skill", "dummyBuySkillPointInfo.txt")):
            rows, cols = _dummy_cols(table)
            tables[key] = sorted((_dummy_int(r[cols["id"]]), _dummy_int(r[cols["price"]]),
                                  _dummy_int(r[cols["itemNum"]])) for r in rows)
        _DUMMY_BUY_TABLES = tables
        log.info("loaded 傀儡 market tables: %s",
                 {k: len(v) for k, v in tables.items()})
    return _DUMMY_BUY_TABLES


def _puppet_buy(player, table_key, pool_key, count_key, cap):
    """One 傀儡 market purchase. Returns (diamondSyncMessages, buyNumber) — buyNumber counts today's
    purchases (0 = refused: out of the daily allowance, pool already full, or too few diamonds).

    dummyBuyFubenEnemgyInfo / dummyBuySkillPointInfo give the price of the Nth purchase of the day and
    the amount it hands over; iPuppetEnergyBuyTimes / iPuppetSkillValBuyTimes cap the day."""
    if (player.get("puppet_buy_day") or "") != _zi_today():
        player.update({"puppet_buy_day": _zi_today(), "puppet_energy_buy": 0, "puppet_skill_buy": 0})
        store.save_player(player["uin"], puppet_buy_day=player["puppet_buy_day"],
                          puppet_energy_buy=0, puppet_skill_buy=0)
    n = int(player.get(count_key) or 0) + 1
    rows = _dummy_buy_tables().get(table_key) or []
    have = puppet_energy(player) if pool_key == "puppet_energy" else puppet_skill_val(player)
    if n > len(rows) or n > _DUMMY_BUY_TIMES or have >= cap:
        return None, n
    price, amount = rows[n - 1][1], rows[n - 1][2]
    syncs = _spend_diamonds(player, price)
    if syncs is None:
        return None, n
    player[count_key] = n
    player[pool_key] = min(cap, have + amount)
    store.save_player(player["uin"], **{count_key: n, pool_key: player[pool_key]})
    log.info("    傀儡商城: %s 第%d次 -%d钻石 +%d (uin=%d)", table_key, n, price, amount, player["uin"])
    return syncs, n


def handle_market_buypuppetenergy(cmd_data, player):
    """Cmd_Market_BuyPuppetEnergy_CS{} -> _SC{buyNum(1)} + SyncPuppetEnergy_SC (+ the diamond sync)."""
    syncs, n = _puppet_buy(player, "energy", "puppet_energy", "puppet_energy_buy", _DUMMY_ENERGY_MAX)
    messages = [("PVZ.Cmd.Cmd_Market_BuyPuppetEnergy_SC", pb_varint_field(1, n))]
    if syncs:
        messages += syncs
        messages.append(("PVZ.Cmd.Cmd_SyncPuppetEnergy_SC", pb_varint_field(1, puppet_energy(player))))
    return messages


def handle_market_buypuppetskillval(cmd_data, player):
    """Cmd_Market_BuyPuppetSkillVal_CS{} -> _SC{buyNum(1)} + SyncPuppetSkillVal_SC."""
    syncs, n = _puppet_buy(player, "skill", "puppet_skill_val", "puppet_skill_buy", _DUMMY_SKILL_MAX)
    messages = [("PVZ.Cmd.Cmd_Market_BuyPuppetSkillVal_SC", pb_varint_field(1, n))]
    if syncs:
        messages += syncs
        messages.append(("PVZ.Cmd.Cmd_SyncPuppetSkillVal_SC", pb_varint_field(1, puppet_skill_val(player))))
    return messages


# --- 傀儡战境 (Cmd_PuppetFuben_*) -------------------------------------------------------
def _dummy_fuben_progress(player, mode, chapter):
    """{stage_id: (wave, timesToday)} for one chapter; elite counters roll over daily."""
    today = _zi_today()
    return {stage: (wave, times if day == today else 0)
            for stage, (wave, times, day) in store.puppet_fuben_progress(
                player["uin"], mode, chapter).items()}


def _dummy_chapter_passed(player, mode, chapter):
    """True when the chapter's LAST stage is fully cleared (every wave) — that is what opens the next
    chapter ("上一章普通关还未通过") and the elite tab of this chapter ("本章普通关还未通过")."""
    stages = [s for (_m, _c, s) in dummy_stage_keys(mode, chapter)]
    if not stages:
        return False
    last = max(stages)
    wave, _times = _dummy_fuben_progress(player, mode, chapter).get(last, (0, 0))
    return wave >= len(dummy_stage_waves(mode, chapter, last))


def _dummy_chapter_open(player, mode, chapter):
    """A chapter opens once the PREVIOUS one is passed; 精英 additionally needs its own 普通 clear."""
    chapters = sorted({c for (_m, c, _s) in dummy_stage_keys(mode)})
    if chapter not in chapters:
        return False
    index = chapters.index(chapter)
    if index and not _dummy_chapter_passed(player, mode, chapters[index - 1]):
        return False
    if int(mode) == _DUMMY_MODE_ELITE and not _dummy_chapter_passed(player, _DUMMY_MODE_EASY, chapter):
        return False
    return True


def _puppet_fuben_next_wave(player, mode, chapter, stage):
    """The wave a stage would fight next: the first uncleared one (used when the client's target does not
    carry a puppetFubenSubStageId)."""
    wave, _times, _sweep, _unlocked = _dummy_stage_state(player, mode, chapter, stage)
    waves = dummy_stage_waves(mode, chapter, stage)
    return min([w for w in waves if w > wave] or waves or [1])


def _dummy_stage_state(player, mode, chapter, stage):
    """(wave, timesToday, canSweep, unlocked) of one stage. Stage N+1 needs stage N fully cleared
    ("前一关还未通过"), which is also the sweep condition the panel shows."""
    key = (int(mode), int(chapter), int(stage))
    if key not in load_dummy_config()["stages"]:
        return 0, 0, False, False
    progress = _dummy_fuben_progress(player, mode, chapter)
    total = len(dummy_stage_waves(mode, chapter, stage))
    wave, times = progress.get(int(stage), (0, 0))
    unlocked = True
    if int(stage) > 1:
        prev = max(0, int(stage) - 1)
        unlocked = progress.get(prev, (0, 0))[0] >= len(dummy_stage_waves(mode, chapter, prev))
    if not _dummy_chapter_open(player, mode, chapter):
        unlocked = False
    return wave, times, total > 0 and wave >= total, unlocked


def _puppet_fuben_chapter_fight_count(player, mode, chapter):
    """Attempts made today across the chapter, matching GetStageInfo_SC.fightTimes."""
    stages = (stage for (_mode, ch, stage) in dummy_stage_keys(mode, chapter) if ch == int(chapter))
    progress = _dummy_fuben_progress(player, mode, chapter)
    return sum(progress.get(stage, (0, 0))[1] for stage in stages)


def _puppet_fuben_stage_sync(player, mode, chapter, stage):
    """Build the same refreshed stage DTO and chapter attempt count returned by GetStageInfo_SC."""
    done, times, can_sweep, _unlocked = _dummy_stage_state(player, mode, chapter, stage)
    info = load_dummy_config()["stages"].get((int(mode), int(chapter), int(stage))) or {}
    has_limit = 1 if (int(mode) == _DUMMY_MODE_ELITE and int(info.get("limit") or 0)) else 0
    stage_dto = (pb_varint_field(1, stage) + pb_varint_field(2, done)
                 + pb_varint_field(3, has_limit) + pb_varint_field(4, times)
                 + pb_varint_field(5, 1 if can_sweep else 0))
    body = (pb_varint_field(1, chapter) + pb_varint_field(2, mode)
            + pb_tag(3, 2) + uvarint(len(stage_dto)) + stage_dto
            + pb_varint_field(4, _puppet_fuben_chapter_fight_count(player, mode, chapter)))
    return ("PVZ.Cmd.Cmd_PuppetFuben_SyncStageInfo_SC", body)


def handle_puppetfuben_getchapterinfo(cmd_data, player):
    """Cmd_PuppetFuben_GetChapterInfo_CS{} -> _SC{lastPassEasyChapterId(1),lastPassHardChapterId(2)}:
    the highest FULLY cleared chapter of each tab — the chapter list unlocks everything up to the next
    one (see _dummy_chapter_open)."""
    puppet_starter_grant(player)
    easy = hard = 0
    for mode, field in ((_DUMMY_MODE_EASY, "easy"), (_DUMMY_MODE_ELITE, "hard")):
        for chapter in sorted({c for (_m, c, _s) in dummy_stage_keys(mode)}):
            if _dummy_chapter_passed(player, mode, chapter):
                if field == "easy":
                    easy = chapter
                else:
                    hard = chapter
    if int(player.get("puppet_easy_chapter") or 0) != easy:
        player["puppet_easy_chapter"] = easy
        store.save_player(player["uin"], puppet_easy_chapter=easy)
    if int(player.get("puppet_hard_chapter") or 0) != hard:
        player["puppet_hard_chapter"] = hard
        store.save_player(player["uin"], puppet_hard_chapter=hard)
    log.info("    傀儡战境: chapters passed 普通=%d 精英=%d", easy, hard)
    return pb_varint_field(1, easy) + pb_varint_field(2, hard)


def handle_puppetfuben_getstageinfo(cmd_data, player):
    """Cmd_PuppetFuben_GetStageInfo_CS{chapterId(1),modeId(2)} -> _SC{chapterId,modeId,
    stageInfo(3, repeated Dto_PuppetFuben_StageInfo), fightTimes(4)}.

    Dto_PuppetFuben_StageInfo{stageId(1), star(2), hasLimit(3), times(4), canSweep(5)}: `star` is how
    many of the stage's waves are cleared (dummyFubenLevelInfo gives one sub-level per wave),
    `hasLimit`/`times` are the elite tab's daily attempts (fightLimit) and `canSweep` the full clear
    that unlocks 扫荡."""
    f = parse_varint_fields(cmd_data)
    chapter, mode = int(f.get(1, 1) or 1), int(f.get(2, _DUMMY_MODE_EASY) or _DUMMY_MODE_EASY)
    body = pb_varint_field(1, chapter) + pb_varint_field(2, mode)
    fights = 0
    for stage in sorted(s for (_m, c, s) in dummy_stage_keys(mode, chapter) if c == chapter):
        wave, times, can_sweep, unlocked = _dummy_stage_state(player, mode, chapter, stage)
        key = (mode, chapter, stage)
        has_limit = 1 if (int(mode) == _DUMMY_MODE_ELITE
                          and int(load_dummy_config()["stages"][key]["limit"] or 0)) else 0
        fights += times
        dto = (pb_varint_field(1, stage) + pb_varint_field(2, wave if unlocked else 0)
               + pb_varint_field(3, has_limit) + pb_varint_field(4, times)
               + pb_varint_field(5, 1 if can_sweep else 0))
        body += pb_tag(3, 2) + uvarint(len(dto)) + dto
    body += pb_varint_field(4, fights)
    log.info("    傀儡战境 stage info: mode=%d chapter=%d -> %d stage(s), %d fight(s) today", mode,
             chapter, len(dummy_stage_keys(mode, chapter)), fights)
    return body


_DUMMY_FUBEN_TEAM = 3                  # the 傀儡战境 lineup owns formation team 3
_DUMMY_FUBEN_SCENE = "puppetfuben"     # battle-scene tag (see _BATTLE_SCENES/_SCENE_FAMILY)


def _puppet_fuben_key(mode, chapter, stage, wave):
    return "%d/%d/%d/%d" % (int(mode), int(chapter), int(stage), int(wave))


def _puppet_fuben_placements(player):
    """{posIndex: uid} of the plant team the 傀儡战境 fields: the lineup arranged in the mode's own window
    (formation team 3) or, when none was arranged, the player's backyard team. Capped at _ZI_LINEUP_MAX
    like every other mode — the result window's card Vector holds six."""
    ensure_player_cards(player)
    owned = {uid for uid, _c, _l, _e in store.get_cards(player["uin"])}
    saved = {p: u for p, u in store.get_formation(player["uin"], _DUMMY_FUBEN_TEAM).items()
             if u in owned and p in _FORMATION_POS}
    placements = (saved if int(player.get("puppet_fuben_formation_set") or 0)
                  else saved or default_formation_placements(player))
    return dict(sorted(placements.items())[:_ZI_LINEUP_MAX])


def _puppet_fuben_formation_body(player):
    """Cmd_PuppetFuben_GetFormation_SC body: formation(1) = Dto_FormationInfo."""
    formation = build_formation_info(player, 1, _puppet_fuben_placements(player))
    return pb_tag(1, 2) + uvarint(len(formation)) + formation


def handle_puppetfuben_getformation(cmd_data, player):
    """Cmd_PuppetFuben_GetFormation_CS -> Cmd_PuppetFuben_GetFormation_SC{formation(1)}: the plant team
    of the mode's own lineup window."""
    note_battle_scene(player, _DUMMY_FUBEN_SCENE)
    log.info("    傀儡战境 formation: %s", sorted(_puppet_fuben_placements(player)))
    return _puppet_fuben_formation_body(player)


def handle_puppetfuben_setformation(cmd_data, player):
    """Cmd_PuppetFuben_SetFormation_CS{formation(1)} -> persist team 3 and ECHO GetFormation_SC (the
    client only refreshes once that push arrives — the same handshake the zombie island uses)."""
    placements = []
    for sub in parse_repeated_submessages(cmd_data, 1):        # cardPos of Dto_FormationInfo
        fields = parse_varint_fields(sub)
        pos, uid = fields.get(1, 0), fields.get(2, 0)
        if pos and uid:
            placements.append((pos, uid))
    store.set_formation(player["uin"], _DUMMY_FUBEN_TEAM, placements)
    player["puppet_fuben_formation_set"] = 1
    store.save_player(player["uin"], puppet_fuben_formation_set=1)
    log.info("    傀儡战境 formation set: %s", sorted(placements))
    return [("PVZ.Cmd.Cmd_PuppetFuben_GetFormation_SC", _puppet_fuben_formation_body(player))]


# --- 傀儡 as battle cards: what the CLIENT must know before a report may carry them -----------------
# A side's `puppetList` (Dto_FightSide field 16) is resolved by the client through
# PlanFactory.getPlanSettingByCardId -> SettingsModel.battleCardSettings, and the 傀儡 baseIds exist only
# in the client's `dummyZombieInfo`, NOT in `battleCard` — so a 傀儡 baseId in a battle whose side is not
# a 傀儡 side (sideType 38/39) resolves to a null plan -> #1009 in BattleServiceCommand.getResourceList
# and the battle module never finishes loading ("进冒险就卡死"). tools_puppet_battle_cards.py patches the
# served webroot\clientDB.txt with one battleCard row per 傀儡 (planClassName = dummyZombieInfo.resName,
# which is exactly the cardId of the client's battle cartoon/plan XML inside Game.swf, e.g.
# <node cardId="PVP_zombie_kongfu_basic"><assetsTree><assetUnit assetName="PVP_zombie_kongfu_basic"/>
# + its data-driven <attackTree>) — that is what lets the client build AND animate the 傀儡 in any battle.
# Until the patch is in place the server keeps 傀儡 out of every non-傀儡战境 report.
_BATTLECARD_IDS = None


def battlecard_ids():
    """{id (str)} of the served clientDB's battleCard table: the ids the client can build a plan for.
    Cached for the process lifetime — restart the server after patching clientDB.txt."""
    global _BATTLECARD_IDS
    if _BATTLECARD_IDS is None:
        rows = _read_clientdb_table("battleCard.txt")
        _BATTLECARD_IDS = {r[0] for r in rows[1:]} if rows else set()
    return _BATTLECARD_IDS


def client_knows_puppet_cards(player):
    """True when the client's battleCard table has a row for EVERY 上阵傀儡 of `player`, i.e. the 傀儡 can
    ride along in any battle report because `Dto_FightSide.puppetList` resolves to a real plan (no #1009).
    False = only 傀儡战境 may carry them (its sideType 38/39 takes the dummy path, which always works)."""
    ids = battlecard_ids()
    if not ids:
        return False
    return all(str(pid) in ids for pid in puppet_lineup(player) if pid)


def _auto_puppet_list(player):
    """Return the player's puppetList only when every lineup card has a client battleCard plan."""
    return _puppet_fight_list(player) if client_knows_puppet_cards(player) else b""


def _auto_puppets(player):
    """Return the player's replay puppet slots only when the client can resolve their plans."""
    return _puppet_battle_lineup(player) if client_knows_puppet_cards(player) else None


def _puppet_fight_list(player):
    """repeated Dto_FightPuppetInfo{posIndex(1),baseId(2),level(3),star(4),quality(5),activeSkill(6),
    passiveSkill(7)} (Dto_FightSide field 16) — the 上阵傀儡 of the report.

    `posIndex` is 101/103/105/107/109 for 首轮..五轮, matching
    Dto_FightPuppetActor.actorIndex in the replay, so the client can match the dummy unit that acts
    each round. Only the slots that hold a puppet are listed (the battle has no empty-slot concept)."""
    puppets = store.get_puppets(player["uin"])
    body = b""
    for index, base_id in enumerate(puppet_lineup_slots(player), 1):
        if not base_id:
            continue
        row = puppets[base_id]
        dummy_pos = 101 + (index - 1) * 2
        dto = (pb_varint_field(1, dummy_pos) + pb_varint_field(2, base_id)
               + pb_varint_field(3, row.get("level") or 1) + pb_varint_field(4, row.get("star") or 1)
               + pb_varint_field(5, row.get("quality") or 0) + puppet_skills_bytes(row))
        body += pb_tag(16, 2) + uvarint(len(dto)) + dto
    return body


def _puppet_battle_lineup(player):
    """{slot: {"actor":…, "skill":…}} — what simulate_battle needs to let the 上阵傀儡 act: round N is the
    puppet in lineup slot N ("傀儡按照首轮至五轮顺序每回合依次轮流出手，没有傀儡时该回合傀儡轮空").
    `actor` is the dummy position (101/103/105/107/109), which the report puts in Dto_FightPuppetInfo.posIndex and
    Dto_FightPuppetActor.actorIndex."""
    puppets = store.get_puppets(player["uin"])
    out = {}
    for index, base_id in enumerate(puppet_lineup_slots(player), 1):
        if base_id:
            out[index] = {"actor": 101 + (index - 1) * 2,
                          "skill": int(puppets[base_id].get("active_skill") or 0),
                          "skill_lv": int(puppets[base_id].get("active_level") or 1)}
    return out


_DUMMY_LOOT_AMOUNT = {95501: 1, 95502: 1, 95503: 1, 95504: 1, 95505: 1,
                      95506: 1, 95507: 1, 95508: 1, 95509: 1, 95510: 1,
                      95511: 1, 95512: 1, 95513: 1, 95514: 1, 95515: 1,
                      95516: 1, 95517: 1, 95518: 1, 95519: 1, 95520: 1,
                      95521: 1, 95522: 1, 95523: 1, 95524: 1, 95525: 1,
                      95526: 1, 95527: 1, 95528: 1, 95529: 1, 95530: 1,
                      95531: 20, 95533: 3, 95534: 2, 95535: 1, 95539: 1}


def _puppet_fuben_loot(player, mode, chapter, stage, wave):
    """The loot of one cleared wave: 3 items rolled from the stage's dummyFubenStageInfo.lootItemStr with
    a stable RNG, and the 精英 tab always includes 傀儡原石 95539 ("精英关卡必掉傀儡原石")."""
    info = load_dummy_config()["stages"].get((int(mode), int(chapter), int(stage))) or {}
    pool = [int(i) for i in info.get("loot") or []]
    if not pool:
        return []
    rng = _stage_rng("puppet-loot", player["uin"], mode, chapter, stage, wave)
    picks = rng.sample(pool, min(3, len(pool)))
    if int(mode) == _DUMMY_MODE_ELITE and _DUMMY_ITEM_FORGE not in picks:
        picks[-1] = _DUMMY_ITEM_FORGE
    out = {}
    for item_id in picks:
        amount = _DUMMY_LOOT_AMOUNT.get(item_id, 1)
        if item_id >= 95601:                                    # 傀儡碎片: 1..2 per clear
            amount = rng.randint(1, 2)
        out[item_id] = out.get(item_id, 0) + amount
    return sorted(out.items())


def _puppet_fuben_bonus(units, per_mille):
    """Apply the 上阵傀儡 bonus (per-mille, see puppet_plant_bonus) to the player's units — the panel's
    "每个上阵植物获得属性加成". A copy is returned so callers keep their own unit dicts untouched."""
    if not per_mille:
        return units
    factor = 1.0 + per_mille / 10000.0
    out = []
    for unit in units:
        clone = dict(unit)
        for key in ("atk", "def_", "hp", "ability"):
            if clone.get(key):
                clone[key] = max(1, int(clone[key] * factor))
        if clone.get("power"):
            clone["power"] = int(clone["power"] * factor)
        out.append(clone)
    return out


def _puppet_fuben_units(player, mode, chapter, stage, wave):
    """(left, right) of one 傀儡战境 wave: the player's plants (with the puppet bonus) against the squad
    whose power is dummyFubenLevelInfo's recommandFP for that wave."""
    cfg = load_dummy_config()
    fp = float((cfg["waves"].get((int(mode), int(chapter), int(stage), int(wave))) or {}).get("fp") or 0)
    left = _puppet_fuben_bonus(build_player_units(player, _puppet_fuben_placements(player)),
                               puppet_plant_bonus(player))
    right = _tr_enemy_squad(max(1, int(fp)), int(chapter) * 100 + int(stage) * 10 + int(wave))
    right = apply_previewed_enemy_types(player, right, _DUMMY_FUBEN_SCENE,
                                        _puppet_fuben_key(mode, chapter, stage, wave))
    return left, right


def _puppet_fuben_run_fight(player, mode, chapter, stage, wave):
    """One 傀儡战境 wave.

    Gates: the chapter/stage must be open, the role level must reach dummyFubenStageInfo.openMinLv, the
    wave must be reached or the next uncleared one, and the 精英 tab has fightLimit attempts per day.
    Cleared waves may be replayed without reducing stage progress. The fight spends the
    stage's 能量 (item 42 pool), decides the outcome by 战力 like every other mode, and on a win records
    the wave + pays that wave's loot. fightType = BattleTargetType_PuppetFuben (22) so the client opens
    THIS mode's result window, and the two sides carry E_FightSide 38/39 with the 上阵傀儡 in
    leftSide.puppetList (field 16)."""
    cfg = load_dummy_config()
    info = cfg["stages"].get((int(mode), int(chapter), int(stage)))
    waves = dummy_stage_waves(mode, chapter, stage)
    done, times, _can_sweep, unlocked = _dummy_stage_state(player, mode, chapter, stage)
    remaining_waves = [w for w in waves if w > done]
    next_wave = min(remaining_waves) if remaining_waves else 0
    if not info or int(wave) not in waves:
        log.info("    傀儡战境: invalid stage/wave (mode=%d chapter=%d stage=%d wave=%s)",
                 mode, chapter, stage, wave)
        return [puppet_error(12600)]                 # 未开启; never send Fight_SC without a report
    if not unlocked or (next_wave and int(wave) > next_wave):
        log.info("    傀儡战境: stage/wave locked (mode=%d chapter=%d stage=%d wave=%s next=%s opened=%s)",
                 mode, chapter, stage, wave, next_wave, unlocked)
        return [puppet_error(6100)]                  # 未通过指定关卡
    if int(player.get("level", 1)) < int(info["min_lv"]):
        log.info("    傀儡战境: fight refused, needs role level %d", info["min_lv"])
        return [puppet_error(6105)]                  # 小镇等级不足
    limit = int(info["limit"] or 0)
    if int(mode) == _DUMMY_MODE_ELITE and limit and times >= limit:
        log.info("    傀儡战境: 精英 attempts used up today (%d/%d)", times, limit)
        return [puppet_error(312)]                   # 剩余挑战次数不足
    cost = int(info["energy"] or 0)
    if cost and not puppet_spend(player, "puppet_energy", cost):
        log.info("    傀儡战境: fight refused, needs %d 能量", cost)
        return [puppet_error(_PUPPET_ERR_NO_ENERGY)]
    store.save_puppet_stage(player["uin"], mode, chapter, stage, times=times + 1, day=_zi_today())
    left, right = _puppet_fuben_units(player, mode, chapter, stage, wave)
    won, left_power, right_power = resolve_battle(left, right)
    rounds = simulate_battle(left, right, won, puppets=_puppet_battle_lineup(player)) \
        if (left and right) else []
    log.info("    傀儡战境: mode=%d chapter=%d stage=%d wave=%d -> %s (plants %d vs zombies %d 战力), "
             "%d plants + %d 傀儡", mode, chapter, stage, wave, "WIN" if won else "LOSS", left_power,
             right_power, len(left), len(puppet_lineup(player)))
    loot = _puppet_fuben_loot(player, mode, chapter, stage, wave) if won else []
    report = build_fight_report(player, chapter, mode, stage, won, loot, done == 0 and int(wave) == 1,
                                left, right, encode_fight_replay(rounds),
                                fight_type=_DUMMY_FUBEN_TARGET, puppet_bytes=_puppet_fight_list(player),
                                side_types=(38, 39))
    body = (pb_varint_field(1, chapter) + pb_varint_field(2, mode) + pb_varint_field(3, stage)
            + pb_varint_field(4, wave) + pb_tag(5, 2) + uvarint(len(report)) + report)
    messages = [("PVZ.Cmd.Cmd_PuppetFuben_Fight_SC", body)]
    if cost:
        messages += puppet_sync_messages(player)
    if not won:
        messages.append(_puppet_fuben_stage_sync(player, mode, chapter, stage))
        return messages
    store.save_puppet_stage(player["uin"], mode, chapter, stage, wave=max(done, int(wave)), times=times + 1,
                            day=_zi_today())
    messages.append(_puppet_fuben_stage_sync(player, mode, chapter, stage))
    messages += grant_fuben_reward(player, loot)
    return messages


def handle_puppetfuben_fight(cmd_data, player):
    """Cmd_PuppetFuben_Fight_CS{chapterId(1),modeId(2),stageId(3),subStageId(4)} -> Fight_SC with the
    report. subStageId is the WAVE (dummyFubenLevelInfo.levelID, 1..N); omitted means next wave."""
    f = parse_varint_fields(cmd_data)
    puppet_starter_grant(player)
    mode, chapter, stage = int(f.get(2, 0)), int(f.get(1, 0)), int(f.get(3, 0))
    wave = int(f.get(4, 0)) or _puppet_fuben_next_wave(player, mode, chapter, stage)
    return _puppet_fuben_run_fight(player, mode, chapter, stage, wave)


def handle_puppetfuben_sweep(cmd_data, player):
    """Cmd_PuppetFuben_Sweep_CS{chapterId(1),modeId(2),stageId(3),times(4)} -> _SC{chapterId,modeId,
    stageId,times(4),reward(5, repeated Dto_IdNum)}: 扫荡 a fully cleared stage — each sweep burns the
    stage's 能量 and rolls its loot again (the 精英 daily limit caps the sweeps too)."""
    f = parse_varint_fields(cmd_data)
    chapter, mode = int(f.get(1, 0)), int(f.get(2, 0))
    stage, times = int(f.get(3, 0)), max(1, int(f.get(4, 0) or 1))
    info = load_dummy_config()["stages"].get((mode, chapter, stage))
    done, used, can_sweep, _unlocked = _dummy_stage_state(player, mode, chapter, stage)
    empty = ("PVZ.Cmd.Cmd_PuppetFuben_Sweep_SC",
             pb_varint_field(1, chapter) + pb_varint_field(2, mode) + pb_varint_field(3, stage)
             + pb_varint_field(4, 0))
    if not info or not can_sweep:
        log.info("    傀儡战境扫荡: mode=%d chapter=%d stage=%d refused (cleared=%s)", mode, chapter,
                 stage, can_sweep)
        return [empty]
    energy = int(info["energy"] or 0)
    if energy:
        times = min(times, puppet_energy(player) // energy)
    limit = int(info["limit"] or 0)
    if int(mode) == _DUMMY_MODE_ELITE and limit:
        times = min(times, max(0, limit - used))
    if times <= 0 or (energy and not puppet_spend(player, "puppet_energy", energy * times)):
        return [empty]
    gains = {}
    for step in range(times):
        for item_id, num in _puppet_fuben_loot(player, mode, chapter, stage, done + step + 1):
            gains[item_id] = gains.get(item_id, 0) + num
    store.save_puppet_stage(player["uin"], mode, chapter, stage, times=used + times, day=_zi_today())
    rewards = b""
    for item_id, num in sorted(gains.items()):
        dto = pb_varint_field(1, item_id) + pb_varint_field(2, num)
        rewards += pb_tag(5, 2) + uvarint(len(dto)) + dto
    log.info("    傀儡战境扫荡: mode=%d chapter=%d stage=%d x%d -> %s", mode, chapter, stage, times,
             sorted(gains.items()))
    body = (pb_varint_field(1, chapter) + pb_varint_field(2, mode) + pb_varint_field(3, stage)
            + pb_varint_field(4, times) + rewards)
    messages = [("PVZ.Cmd.Cmd_PuppetFuben_Sweep_SC", body)]
    messages += grant_fuben_reward(player, sorted(gains.items()))
    messages += puppet_sync_messages(player)
    messages.append(_puppet_fuben_stage_sync(player, mode, chapter, stage))
    return messages

# the 冒险勋章 prices live in _ZI_SHOP above (the original config was server-side). Purchases are one per
# entry per shop day — the window's 刷新 button (and the 21:00 caption) rerolls those flags.
def _zi_shop_state(player):
    """{entryId,...} already exchanged today (rolled over on a new day)."""
    if (player.get("zi_shop_day") or "") != _zi_today():
        player["zi_shop_day"] = _zi_today()
        player["zi_shop_bought"] = ""
        store.save_player(player["uin"], zi_shop_day=player["zi_shop_day"], zi_shop_bought="")
    raw = player.get("zi_shop_bought") or ""
    return {int(x) for x in raw.split(",") if x.strip().isdigit()}


def _zi_shop_next_refresh():
    """unix ts of the next 今日21:00 boundary (the window's 下次刷新时间 caption)."""
    now = time.time()
    local = time.localtime(now)
    reset = time.mktime((local.tm_year, local.tm_mon, local.tm_mday, _ZI_SHOP_REFRESH_HOUR,
                         0, 0, 0, 0, -1))
    if reset <= now:
        reset += 86400
    return int(reset)


def _zi_shop_entry_body(entry, bought):
    """Dto_ExchangeStore_Entry{entryId(1),pos(2),itemId(3),itemNum(4),consumeItemId(5),consumeItemNum(6),
    hasExchanged(7)}."""
    entry_id, pos, item_id, item_num, cost_id, cost_num = entry
    return (pb_varint_field(1, entry_id) + pb_varint_field(2, pos) + pb_varint_field(3, item_id)
            + pb_varint_field(4, item_num) + pb_varint_field(5, cost_id)
            + pb_varint_field(6, cost_num) + pb_varint_field(7, 1 if entry_id in bought else 0))


# --- 每日碎片轮换 -------------------------------------------------------------------
# 商店/活动/宝箱不再天天发那三样（火龙草 53900 / 椰子加农炮 54900 / 地刺 54400）：
# 每天 0 点从高稀有碎片池里确定性换一批 —— 同一天内稳定、跨天不同。`salt` 让不同入口
# （僵尸岛商店 / 联盟商店 / 宝箱 / 活动）同一天各拿不同的一批。
_DAILY_FRAGMENT_ROTATE = (
    54900,  # 椰子加农炮 q4
    55800,  # 火爆辣椒 q4
    56000,  # 食人花 q4
    56300,  # 香蒲 q4
    56400,  # 海星果 q4
    56500,  # 硝化菇 q4
    56600,  # 钻地荔枝果 q4
    56700,  # 海葵花 q4
    56800,  # 电海松 q4
    56900,  # 灵芝 q4
    57000,  # 氧气藻 q4
    57100,  # 芭蕉 q5
    57300,  # 榴莲 q5
    57400,  # 脉冲黄桃 q4
)
_DAILY_FRAGMENT_REPLACED = (53900, 54900, 54400)     # 原来那三样的占位


def daily_fragments(count=3, salt=0, date_key=None):
    """`count` 个高稀有植物碎片 id —— 今天这一批（同日稳定、跨日不同、可按入口错开）。"""
    pool = _DAILY_FRAGMENT_ROTATE
    try:
        day = int(date_key or time.strftime("%Y%m%d"))
    except (TypeError, ValueError):
        day = 0
    offset = (day * 7 + salt * 5) % len(pool)
    return [pool[(offset + k * 5) % len(pool)] for k in range(min(count, len(pool)))]


def _daily_shop_entries(entries, salt):
    """`entries` with the three fixed fragment slots swapped for TODAY's high-rarity picks."""
    picks = daily_fragments(len(_DAILY_FRAGMENT_REPLACED), salt)
    out = []
    for entry in entries:
        if entry[2] in _DAILY_FRAGMENT_REPLACED:
            idx = _DAILY_FRAGMENT_REPLACED.index(entry[2])
            out.append(entry[:2] + (picks[idx],) + entry[3:])
        else:
            out.append(entry)
    return out


def zi_shop_itemlist(player):
    """Cmd_ExchangeStore_ItemList_SC body for the ISLAND shop (storeId 2)."""
    return _exchange_itemlist_body(_daily_shop_entries(_ZI_SHOP, 1), _zi_shop_state(player))


def _exchange_itemlist_body(entries, bought, refresh_max=1):
    """Cmd_ExchangeStore_ItemList_SC{entrylist(1), refreshTime(2), refreshMaxTimes(3), refreshItem(4),
    refreshTimes(5), refreshNum(6)} for one shop's entries. `bought` = the entry ids already exchanged
    today (empty for an unlimited shop). `refreshMax` = refreshMaxTimes: the client answers
    EXCHANGE_STORE_REFRESH_MAX ("今日刷新已达上限!") once refreshTimes reaches it, so a shop that WANTS
    free unlimited rerolls (神奇兑换) advertises a roomy cap."""
    body = b""
    for entry in entries:
        dto = _zi_shop_entry_body(entry, bought)
        body += pb_tag(1, 2) + uvarint(len(dto)) + dto
    return (body + pb_varint_field(2, _zi_shop_next_refresh()) + pb_varint_field(3, int(refresh_max))
            + pb_varint_field(4, 0) + pb_varint_field(5, 0) + pb_varint_field(6, 0))


def exchange_store_entries(store_id):
    """The wares of an ExchangeStore window: the island shop (2), 联盟商店 (4 = GuildFuben),
    or 神奇兑换 (5 = PlantTicket). For 神奇兑换 this is the WHOLE pool (what an exchange resolves
    entryIds against); the window's list is one page of it — see exchange_store_itemlist /
    plant_coin_shop_page."""
    store_id = int(store_id or 0)
    if store_id == 2:
        return _daily_shop_entries(_ZI_SHOP, 1)
    if store_id == _GUILD_SHOP_STORE:
        return _daily_shop_entries(_GUILD_SHOP, 2)
    if store_id == _PLANT_TICKET_STORE:
        return plant_coin_shop_entries()
    return []


def exchange_store_itemlist(store_id, player):
    """The ItemList body for any stocked store."""
    if int(store_id or 0) == _PLANT_TICKET_STORE:
        # ONE PAGE of six wares (the panel cannot hold more) and no daily purchase limit — see
        # plant_coin_shop_page; 刷新 advances the page instead of clearing purchase flags.
        return _exchange_itemlist_body(plant_coin_shop_page(player), set(),
                                       refresh_max=_PLANT_COIN_SHOP_REFRESH_MAX)
    if int(store_id or 0) == _GUILD_SHOP_STORE:
        # One purchase per entry per shop day, same pacing as the island shop.
        return _exchange_itemlist_body(_daily_shop_entries(_GUILD_SHOP, 2), _guild_shop_state(player))
    return zi_shop_itemlist(player)


def handle_exchangestore_itemlist(cmd_data, player):
    """Cmd_ExchangeStore_ItemList_CS{storeId(1)}. Three stores are stocked: the island shop (2,
    冒险勋章), the guild shop (4 = ExchangeStoreType_GuildFuben, 联盟勋章) and 神奇兑换
    (5 = ExchangeStoreType_PlantTicket, 植物币/神奇植物币). Any other store answers with an
    empty body instead of leaving the window stuck on a generic reply."""
    store_id = parse_varint_fields(cmd_data).get(1, 0)
    entries = exchange_store_entries(store_id)
    if not entries:
        log.info("    exchange store %d: not stocked (island 2 / 联盟 4 / 神奇兑换 5 are)", store_id)
        return b""
    if int(store_id or 0) == _PLANT_TICKET_STORE:
        pages = plant_coin_shop_page_count()
        page = int(player.get("plant_shop_page") or 0) % pages + 1
        log.info("    exchange store %d: page %d/%d of %d wares", store_id, page, pages, len(entries))
    else:
        log.info("    exchange store %d: %d entries", store_id, len(entries))
    return exchange_store_itemlist(store_id, player)


def handle_exchangestore_exchange(cmd_data, player):
    """Cmd_ExchangeStore_Exchange_CS{entryId(1)} -> spend the entry's currency and hand the item over.
    Island entries (1..6) and guild-shop entries (401..406) are limited to one purchase per shop day;
    the 神奇兑换 entries are not limited. The reply re-sends that store's list so 兑换用掉的那一条
    correctly shows as used."""
    entry_id = parse_varint_fields(cmd_data).get(1, 0)
    store_id = 2 if any(e[0] == entry_id for e in _ZI_SHOP) else (
        _GUILD_SHOP_STORE if any(e[0] == entry_id for e in _GUILD_SHOP) else _PLANT_TICKET_STORE)
    entry = next((e for e in exchange_store_entries(store_id) if e[0] == entry_id), None)
    if entry is None:
        log.info("    exchange store: unknown entry %d", entry_id)
        return [("PVZ.Cmd.Cmd_ExchangeStore_Exchange_SC", b"")]
    _eid, _pos, item_id, item_num, cost_id, cost_num = entry
    uin = player["uin"]
    if store_id == 2:
        bought = _zi_shop_state(player)
    elif store_id == _GUILD_SHOP_STORE:
        bought = _guild_shop_state(player)
    else:
        bought = set()
    owned = store.get_item_count(uin, cost_id)
    if entry_id in bought or owned < cost_num:
        log.info("    exchange store %d: entry %d refused (already=%s, %d/%d item %s)",
                 store_id, entry_id, entry_id in bought, owned, cost_num, cost_id)
        return [("PVZ.Cmd.Cmd_ExchangeStore_Exchange_SC", b""),
                ("PVZ.Cmd.Cmd_ExchangeStore_ItemList_SC", exchange_store_itemlist(store_id, player))]
    upd = grant_items(player, [(cost_id, -cost_num), (item_id, item_num)])
    if store_id == 2:
        bought.add(entry_id)
        player["zi_shop_bought"] = ",".join(str(x) for x in sorted(bought))
        store.save_player(uin, zi_shop_bought=player["zi_shop_bought"])
    elif store_id == _GUILD_SHOP_STORE:
        bought.add(entry_id)
        player["guild_shop_bought"] = ",".join(str(x) for x in sorted(bought))
        store.save_player(uin, guild_shop_bought=player["guild_shop_bought"])
    log.info("    exchange store %d: exchanged entry %d -> %d x%d for %d item %d",
             store_id, entry_id, item_id, item_num, cost_num, cost_id)
    messages = [("PVZ.Cmd.Cmd_ExchangeStore_Exchange_SC", b"")]
    if upd:
        messages.append(upd)
    messages.append(("PVZ.Cmd.Cmd_ExchangeStore_ItemList_SC", exchange_store_itemlist(store_id, player)))
    return messages


def handle_exchangestore_refresh(cmd_data, player):
    """Cmd_ExchangeStore_Refresh_CS{storeId(1)} -> reroll the island shop's / guild shop's daily
    purchase flags, or page 神奇兑换's wares (its list is longer than the window, so 刷新 walks the
    pool and wraps)."""
    store_id = parse_varint_fields(cmd_data).get(1, 0)
    if store_id == 2:
        player["zi_shop_day"] = _zi_today()
        player["zi_shop_bought"] = ""
        store.save_player(player["uin"], zi_shop_day=player["zi_shop_day"], zi_shop_bought="")
        log.info("    island shop refreshed: purchase flags cleared")
    elif store_id == _GUILD_SHOP_STORE:
        player["guild_shop_day"] = _zi_today()
        player["guild_shop_bought"] = ""
        store.save_player(player["uin"], guild_shop_day=player["guild_shop_day"],
                          guild_shop_bought="")
        log.info("    guild shop refreshed: purchase flags cleared")
    elif store_id == _PLANT_TICKET_STORE:
        pages = plant_coin_shop_page_count()
        page = (int(player.get("plant_shop_page") or 0) + 1) % pages
        player["plant_shop_page"] = page
        store.save_player(player["uin"], plant_shop_page=page)
        log.info("    神奇兑换 refreshed: page %d/%d", page + 1, pages)
    return [("PVZ.Cmd.Cmd_ExchangeStore_Refresh_SC", b""),
            ("PVZ.Cmd.Cmd_ExchangeStore_ItemList_SC", exchange_store_itemlist(store_id, player))]


# --- 碎片回收 + 神奇兑换 (植物币 210 / 神奇植物币 211) ---------------------------------
# 植物币's own item text: "用于在'神奇兑换'中换取植物碎片。可通过参加'每日答题'活动以及回收已有植物碎片
# 获得" — so the two halves of this feature are:
#   * Cmd_Item_RecycleDebris_CS (the 碎片回收 window, ModuleDebris.swf) destroys 碎片 and pays 植物币;
#   * Cmd_ExchangeStore_* with storeId 5 (ExchangeStoreType_PlantTicket = 神奇兑换) spends them again.
# Every 碎片's ItemInfo row carries its payoff in `useEffect` ("4:20" == 回收为20个植物币, exactly what the
# item description says), so both the recycle rate and the shop prices come straight from client data.
_PLANT_COIN_ITEM = 210            # 植物币 — the normal 神奇兑换 currency
_MYSTERY_COIN_ITEM = 211          # 神奇植物币 — buys the high-rarity 碎片
_PLANT_TICKET_STORE = 5           # ExchangeStoreType_PlantTicket (the 神奇兑换 window)
_FRAGMENT_ID_MIN, _FRAGMENT_ID_MAX = 50000, 60000
_PLANT_COIN_PER_BUY = 5           # fragments handed over per purchase
# The 道具兑换 window (com.qq.modules.exchange.view.components.ExchangePanel in ModuleExchange.swf)
# holds its rows in a FIXED-length Vector — `exchangeListItems:Vector.<ExchangeListItem>`, six slots
# for the 3x2 grid of the art (UI_Exchange_bk). ExchangePanelMediator.onGetExchangeList() indexes that
# Vector with the entry list, so a SEVENTH entry throws
#     RangeError: Error #1125: 索引 6 超出范围 6。
# at com.qq.modules.exchange.view.components::ExchangePanelMediator/onGetExchangeList
# (raised on open AND on every 刷新, because both re-send the list). NEVER send more than this many
# entries for one store; 神奇兑换 keeps its wares reachable by paging six at a time.
_EXCHANGE_PANEL_SLOTS = 6
# refreshMaxTimes for 神奇兑换. The client refuses a refresh once refreshTimes (field 5) reaches it
# (EXCHANGE_STORE_REFRESH_MAX = "今日刷新已达上限!") and our list always answers refreshTimes=0, so a
# roomy cap just means "the 刷新 button keeps working": it is how the pool is browsed.
_PLANT_COIN_SHOP_REFRESH_MAX = 999

_FRAGMENTS = None


def load_fragments():
    """{itemId: {'coin','quality','name','gain'}} for every 碎片 (ItemInfo type 5, id 51xxx..59xxx)."""
    global _FRAGMENTS
    if _FRAGMENTS is not None:
        return _FRAGMENTS
    _FRAGMENTS = {}
    rows = _read_clientdb_table("ItemInfo.txt")
    if rows:
        ci = {c: i for i, c in enumerate(rows[0])}

        def col(r, key, d=""):
            i = ci.get(key)
            return r[i] if i is not None and i < len(r) else d

        for r in rows[1:]:
            try:
                iid, typ = int(col(r, "id") or 0), int(col(r, "type") or 0)
            except ValueError:
                continue
            if typ != 5 or not (_FRAGMENT_ID_MIN <= iid < _FRAGMENT_ID_MAX):
                continue
            coin = 0
            for part in str(col(r, "useEffect")).split(";"):     # "4:20" -> 20 植物币
                if ":" in part and part.split(":", 1)[1].strip().isdigit():
                    coin = max(coin, int(part.split(":", 1)[1]))
            try:
                quality = int(col(r, "quality", "1") or 1)
            except ValueError:
                quality = 1
            _FRAGMENTS[iid] = {"coin": coin, "quality": quality, "name": col(r, "name"),
                               "gain": col(r, "gainWay")}
    log.info("loaded %d plant fragments (碎片回收 / 神奇兑换)", len(_FRAGMENTS))
    return _FRAGMENTS


def frag_coin_value(item_id):
    """How many 植物币 one 碎片 of this item is worth when recycled (0 = not a fragment)."""
    return int((load_fragments().get(int(item_id or 0)) or {}).get("coin") or 0)


def plant_coin_shop_entries():
    """The WHOLE 神奇兑换 pool as Dto_ExchangeStore_Entry tuples (entryId, pos, itemId, itemNum, costId,
    costNum), ranked by fragment id.

    The wares are the 碎片 whose ItemInfo `gainWay` names 神奇兑换 (that is literally what the game says
    they come from); the 5-quality ones cost 神奇植物币 211 ("换取高稀有植物碎片"), the rest 植物币 210.
    Price = 5x (2x for the 稀有 ones) the fragment's own recycle value, so 回收 -> 兑换 can never be
    farmed for a profit. Unlike the island shop these entries are NOT limited to one per day.

    This is the list an exchange resolves `entryId` against (stable: 5001 + the ware's rank) and the
    source the window's pages are cut from — the window itself only ever sees plant_coin_shop_page()."""
    frags = load_fragments()
    picks = [(iid, d) for iid, d in sorted(frags.items()) if "神奇兑换" in (d.get("gain") or "")]
    if not picks:
        picks = sorted((iid, d) for iid, d in frags.items() if d["coin"] > 0)
    entries = []
    for i, (iid, d) in enumerate(picks):
        rare = d["quality"] >= 5
        per_frag = max(10, d["coin"] * (2 if rare else 5))       # cost of ONE fragment
        entries.append((5001 + i, i + 1, iid, _PLANT_COIN_PER_BUY,
                        _MYSTERY_COIN_ITEM if rare else _PLANT_COIN_ITEM,
                        per_frag * _PLANT_COIN_PER_BUY))
    return entries


def plant_coin_shop_page_count():
    """How many pages of _EXCHANGE_PANEL_SLOTS the 神奇兑换 pool makes up (>= 1)."""
    total = len(plant_coin_shop_entries())
    return max(1, (total + _EXCHANGE_PANEL_SLOTS - 1) // _EXCHANGE_PANEL_SLOTS)


def plant_coin_shop_page(player):
    """The 神奇兑换 wares the 道具兑换 window shows RIGHT NOW: one page of at most _EXCHANGE_PANEL_SLOTS
    entries, renumbered so `pos` runs 1..slots (that is the numbering the island shop uses and the grid
    lays out). The client's item Vector is fixed, so this must never return more than the panel holds.

    The page comes from the player's saved `plant_shop_page` (see handle_exchangestore_refresh: 刷新
    walks the pool) and the pool is walked with a wrap-around, so every ware stays reachable even when
    the pool is not a whole number of pages."""
    pool = plant_coin_shop_entries()
    if not pool:
        return []
    slots = min(_EXCHANGE_PANEL_SLOTS, len(pool))
    page = int(player.get("plant_shop_page") or 0) % plant_coin_shop_page_count()
    start = page * _EXCHANGE_PANEL_SLOTS
    page_entries = []
    for pos in range(1, slots + 1):
        entry_id, _rank, item_id, item_num, cost_id, cost_num = pool[(start + pos - 1) % len(pool)]
        page_entries.append((entry_id, pos, item_id, item_num, cost_id, cost_num))
    return page_entries


def handle_item_recycledebris(cmd_data, player):
    """Cmd_Item_RecycleDebris_CS{itemBaseId(1), num(2), pwdtag(3)} -> destroy `num` of that 碎片 and pay
    植物币 (item 210) at the fragment's own rate. Replies Cmd_Item_RecycleDebris_SC{} + the bag sync —
    this is the source of the 神奇兑换 currency (the item description also lists 每日答题)."""
    f = parse_varint_fields(cmd_data)
    item_id, num = int(f.get(1, 0)), int(f.get(2, 0))
    uin = player["uin"]
    owned = store.get_item_count(uin, item_id)
    rate = frag_coin_value(item_id)
    if num <= 0 or owned <= 0 or rate <= 0:
        log.info("    debris recycle REJECTED: item=%d num=%d owned=%d rate=%d", item_id, num, owned, rate)
        return [("PVZ.Cmd.Cmd_Item_RecycleDebris_SC", b"")]
    num = min(num, owned)                                        # never destroy more than we hold
    coin = rate * num
    upd = grant_items(player, [(item_id, -num), (_PLANT_COIN_ITEM, coin)])
    log.info("    debris recycle: %d x 碎片 %d -> %d 植物币", num, item_id, coin)
    messages = [("PVZ.Cmd.Cmd_Item_RecycleDebris_SC", b"")]
    if upd:
        messages.append(upd)
    return messages


def gate_template(stage, gate_id):
    """{'needStars': int, 'needItems': 'id:num;...'} for a gate, or {}."""
    global _GATE_TEMPLATES
    if _GATE_TEMPLATES is None:
        _GATE_TEMPLATES = {}
        rows = _read_clientdb_table("levelselectGateInfo.txt")
        if rows:
            hdr = rows[0]; ci = {c: i for i, c in enumerate(hdr)}

            def col(c, k, d=""):
                i = ci.get(k)
                return c[i] if i is not None and i < len(c) else d
            for c in rows[1:]:
                try:
                    key = (int(col(c, "stageId", "0")), int(col(c, "gateId", "0")))
                except ValueError:
                    continue
                _GATE_TEMPLATES[key] = {
                    "needStars": int(col(c, "needStars", "0") or 0),
                    "needItems": col(c, "needItems", ""),
                }
        log.info("loaded %d gate templates", len(_GATE_TEMPLATES))
    return _GATE_TEMPLATES.get((stage, gate_id), {})


# --- request-driven handlers: read the request, respond with real data -----------
def handle_td_request_tdinfo(cmd_data, player):
    """Cmd_TD_RequestTDInfo_CS -> Cmd_TD_RequestTDInfo_SC. Echo the requested level and
    hand back the player's plants as unlockPlantList so startTD can build the lawn."""
    f = parse_varint_fields(cmd_data)
    # Stage 0 is the client's real tutorial map (conf/td/map/0-1-1.bl). Do not
    # use `or 1` here: it converts the explicit tutorial request into stage 1
    # and silently sends the player to the normal TD flow.
    stage = f[1] if 1 in f else 1
    level = f[2] if 2 in f else 1
    sub = f[3] if 3 in f else 1
    chal = f.get(4, 0)
    log.info("    TD enter: stage=%d level=%d sub=%d plants=%s",
             stage, level, sub, player.get("plants", []))
    d = pb_varint_field(1, stage) + pb_varint_field(2, level) + pb_varint_field(3, sub)
    # Only real TD plants go in the lawn chooser — a non-TD (adventure-only) plant here #1009s
    # TDBasicChooseCard. player['plants'] is cleaned at login, but guard here too.
    for pid in player.get("plants", []):
        if pid not in valid_td_plants():
            continue
        pl = pb_varint_field(1, pid) + pb_varint_field(2, 0)   # Dto_PlantInfo{plantId, isNew}
        d += pb_tag(4, 2) + uvarint(len(pl)) + pl               # unlockPlantList (field 4)
    # field 6: talentIdList (repeated UINT32) — the player's studied Greenhouse talents.
    # TDLoadMediator copies this into TDGameInfo.talentList, then startBackToWarfield calls
    # TalentManager.createTalentEffect(id) for each, so the talents actually APPLY in the level.
    talents = store.get_talents(player["uin"])
    for tid in talents:
        d += pb_varint_field(6, tid)
    if talents:
        log.info("    TD talents applied: %s", talents)
    d += pb_varint_field(7, chal)                               # challengeLevelId
    return d


def handle_td_report_result(cmd_data, player):
    """Cmd_TD_ReportLevelResult_CS -> save the passed level + grant rewards, persist, reply.
    CS: stageId(1) levelId(2) subLevelId(3) passResult(4). SC: level echo + expReward(5)
    star(6) firstPassCoinReward(7) (must be !=0 on first pass for the client to advance)."""
    f = parse_varint_fields(cmd_data)
    stage, level, sub, pass_result = f.get(1, 0), f.get(2, 0), f.get(3, 1), f.get(4, 0)
    # field 5 = achievementList: the achievement ids the client says you earned this run.
    achievements = parse_repeated_varint(cmd_data, 5)
    uin = player["uin"]
    # The tutorial is the distinct stage 0 map. It is not normal TD progress, but
    # completing it is the authoritative hand-off from the new-player flow to town.
    if pass_result != 0 and stage == 0 and player.get("tutorial_active"):
        player["tutorial_active"] = 0
        player["td_stage"], player["td_level"], player["td_sub"] = 1, 1, 1
        store.save_player(uin, tutorial_active=0, td_stage=1, td_level=1, td_sub=1)
        log.info("    tutorial completed for uin=%d", uin)
    elif pass_result != 0 and stage > 0 and player.get("tutorial_active"):
        # Defensive repair: reaching and clearing any ordinary stage means the
        # tutorial has already handed control to the normal campaign.
        player["tutorial_active"] = 0
        store.save_player(uin, tutorial_active=0)
    if pass_result != 0 and stage and level:
        first = not store.is_level_passed(uin, stage, level, sub)
        store.pass_level(uin, stage, level, sub, achievements)
        # Real per-level rewards from clientDB: firstCoin + bonusExp (+ plant) on first clear,
        # bonusCoin on a repeat. Fall back to a small amount if the template is missing.
        rw = level_reward(stage, level, sub)
        # Role exp is server-computed (clientDB bonusExp is empty for ~all levels). Every clear
        # grants it — first clears full, replays reduced — so you keep leveling by playing.
        if first:
            coin_reward = rw.get("firstCoin") or 100
        else:
            coin_reward = rw.get("bonusCoin") or 0
        exp_reward = role_exp_for_clear(stage, first)
        new_stage = max(stage, player.get("td_stage", 1))
        new_level = max(level, player.get("td_level", 1)) if stage == player.get("td_stage", 1) else level
        player["coin"] += coin_reward
        player["exp"] += exp_reward
        player["td_stage"], player["td_level"] = new_stage, new_level
        # Apply role leveling: fold the gained exp into level-ups (exp becomes in-level progress).
        old_level = int(player.get("level", 1))
        leveled = normalize_level(player)
        store.save_player(uin, td_stage=new_stage, td_level=new_level, td_sub=sub,
                          coin=player["coin"], exp=player["exp"], level=player["level"])
        total = store.total_stars(uin, stage)   # star field is the running TOTAL, not the +3

        messages = []
        d = pb_varint_field(1, stage) + pb_varint_field(2, level) + pb_varint_field(3, sub)
        # field 6 `star` = the player's NEW TOTAL stage stars (client shows the delta vs its
        # cached total and updates the map HUD). Sending a constant 3 froze the HUD at 3.
        d += pb_varint_field(5, exp_reward) + pb_varint_field(6, total)  # expReward, totalStars
        d += pb_varint_field(7, coin_reward)                          # firstPassCoinReward
        messages.append(("PVZ.Cmd.Cmd_TD_ReportLevelResult_SC", d))
        messages += _quest_sync_messages(main_quest_local.record_td_clear(
            uin, _main_quest_rows(), stage, level, sub))
        messages += _quest_record_condition(
            player, 22, 0, int(player.get("level", 1)))

        # bonusItems (card fragments etc.) — granted every clear (farmable). Also grant one
        # deterministic Lab reagent on a normal TD win; the reagent addition supplements the
        # authored reward instead of replacing it. Push a single absolute-count bag update.
        gained = {}
        for item_id, amount in (parse_bonus_items(rw.get("bonusItems", ""))
                                + td_lab_material_reward(stage, level, sub)):
            gained[item_id] = gained.get(item_id, 0) + amount
        gained_items = sorted(gained.items())
        if gained_items:
            upd = grant_items(player, gained_items)
            if upd:
                messages.append(upd)

        # First-clear plant unlock (bonusPlant): add to the save + push the sync so the client
        # adds it to the actor's unlockPlantList (actorModel.updateUnlockPlant).
        plant = rw.get("bonusPlant") if first else 0
        if plant:
            store.unlock_plant(uin, plant)
            if plant not in player.setdefault("plants", []):
                player["plants"].append(plant)
            dto = pb_varint_field(1, plant) + pb_varint_field(2, 1)   # Dto_PlantInfo{plantId, isNew=1}
            body = pb_tag(1, 2) + uvarint(len(dto)) + dto             # unlockPlant (field 1)
            messages.append(("PVZ.Cmd.Cmd_SyncUnlockPlant_SC", body))

        # Live HUD updates (the report handler doesn't apply coin/exp itself). On a level-up
        # push Cmd_SyncLevel_SC too (client updates actorLevel, shows the level-up, and
        # re-evaluates feature/town locks — the town opens at level 2).
        messages.append(("PVZ.Cmd.Cmd_SyncCoin_SC", pb_varint_field(1, player["coin"])))
        messages.append(("PVZ.Cmd.Cmd_SyncExp_SC", pb_varint_field(1, player["exp"])))
        if leveled:
            messages.append(("PVZ.Cmd.Cmd_SyncLevel_SC", pb_varint_field(1, player["level"])))
            # Reveal any buildings the new level unlocks, LIVE (no restart needed).
            messages += building_unlock_messages(old_level, player["level"])
        log.info("    LEVEL PASSED & SAVED: stage=%d level=%d sub=%d (first=%s) stars=%d %s"
                 " +%dcoin +%dexp%s%s -> coin=%d exp=%d lvl=%d%s totalStars=%d", stage, level, sub,
                 first, len(set(achievements)), sorted(set(achievements)), coin_reward, exp_reward,
                 (" +plant %d" % plant) if plant else "",
                 (" +items %s" % gained_items) if gained_items else "", player["coin"],
                 player["exp"], player["level"], " LEVEL UP!" if leveled else "", total)
        return messages
    log.info("    level result NOT saved: stage=%d level=%d passResult=%d", stage, level, pass_result)
    d = pb_varint_field(1, stage) + pb_varint_field(2, level) + pb_varint_field(3, sub)
    return [("PVZ.Cmd.Cmd_TD_ReportLevelResult_SC", d)]


def handle_td_getstageinfo(cmd_data, player):
    """Cmd_TD_GetStageInfo_CS -> Cmd_TD_GetStageInfo_SC.

    stageId (so the client builds the stage's levels) + levelInfoList of PASSED levels
    (unlocks the next) + gateList of UNLOCKED gates (field 3) + star = the stage's TOTAL
    star count (field 4, drives the map HUD star number and the gate needStars checks)."""
    f = parse_varint_fields(cmd_data)
    # Preserve an explicit stageId=0 for the new-player tutorial. For requests
    # without a stage id, continue to use the account's normal TD position.
    stage = f[1] if 1 in f else player.get("td_stage", 1)
    uin = player["uin"]
    passed = store.get_passed_levels(uin, stage)
    gates = store.get_unlocked_gates(uin, stage)
    total = store.total_stars(uin, stage)
    log.info("    TD stage info: stage=%d passed=%s gates=%s totalStars=%d",
             stage, passed, gates, total)
    d = pb_varint_field(1, stage)  # stageId
    for level, sub, star, ach in passed:
        li = pb_varint_field(1, level) + pb_varint_field(2, sub)  # Dto_TD_LevelInfo{levelId, subLevelId}
        # starsGot = achievementList.length -> send the ACTUAL earned achievement ids.
        for a in ach:
            li += pb_varint_field(3, a)                           # achievementList (repeated)
        d += pb_tag(2, 2) + uvarint(len(li)) + li                 # levelInfoList (field 2)
    for gid in gates:
        d += pb_varint_field(3, gid)          # gateList (field 3, repeated uint) — unlocked gates
    d += pb_varint_field(4, total)            # star (field 4) — total stage stars for the HUD
    return d


def handle_card_rawattribute(cmd_data, player):
    """Cmd_Card_RawAttribute_CS -> Cmd_Card_RawAttribute_SC.

    The plant almanac (图鉴) asks for the full stats of EVERY plant card in one batch
    (allCard = repeated Dto_CardIdLevel{baseId, level}). It expects one Dto_CardFullInfo
    back per requested card to fill its display cache. An empty allCardInfo leaves that
    cache empty, so the almanac re-fires the whole batch every frame -> flood + freeze.
    We return the card's REAL stats from battleCard.txt (baseId = cardId) so the almanac shows
    true attack/defense/hp/power instead of placeholders."""
    load_battle_cards()
    cards = parse_repeated_submessages(cmd_data, 1)  # repeated Dto_CardIdLevel
    out = b""
    n = 0
    for raw in cards:
        f = parse_varint_fields(raw)
        base_id = f.get(1, 0)
        level = f.get(2, 1)
        if not base_id:
            continue
        known = base_id in _BATTLE_CARDS
        st = card_stats_at_level(base_id, level) if known else None  # almanac shows stats at that level
        # Dto_CardBaseInfo: uid(1,Int64), cardId(2), exp(3), level(4), quality(10). A non-null uid
        # keeps the uid-keyed lookups in CardItemVO (isEmbattle/teamId) from dereferencing null.
        base = (pb_int64_field(1, base_id)       # uid (Int64) — reuse baseId, unique+nonzero
                + pb_varint_field(2, base_id)    # cardId -> looks up the plant template
                + pb_varint_field(4, level)      # level
                + pb_varint_field(10, st["quality"] if st else 1))   # quality (rarity colour)
        # Dto_CardFullInfo: base(1) + REAL scalar stats (from battleCard.txt). hp(5)/shield(6) are
        # UInt64 objects that null-crash when a tooltip calls .toNumber(), so always set them present.
        if st:
            info = (pb_tag(1, 2) + uvarint(len(base)) + base
                    + pb_varint_field(2, card_power(st))    # power
                    + pb_varint_field(3, st["atk"])         # attack
                    + pb_varint_field(4, st["def_"])        # defense
                    + pb_varint_field(5, st["hp"])          # hp   (UInt64)
                    + pb_varint_field(6, 0)                 # shield (UInt64)
                    + pb_varint_field(7, st["ability"])     # ability
                    + pb_float_field(8, st.get("hit", 0))
                    + pb_float_field(9, st.get("dodge", 0))
                    + pb_float_field(10, st.get("critical", 0))
                    + pb_float_field(11, st.get("tough", 0)))
        else:
            info = (pb_tag(1, 2) + uvarint(len(base)) + base
                    + pb_varint_field(2, 0) + pb_varint_field(3, 0) + pb_varint_field(4, 0)
                    + pb_varint_field(5, 0) + pb_varint_field(6, 0) + pb_varint_field(7, 0)
                    + pb_float_field(8, 0) + pb_float_field(9, 0)
                    + pb_float_field(10, 0) + pb_float_field(11, 0))
        out += pb_tag(1, 2) + uvarint(len(info)) + info  # allCardInfo (field 1)
        n += 1
    log.info("    almanac raw-attr: %d cards requested -> %d returned (real stats)", len(cards), n)
    return out


def handle_unlock_gate(cmd_data, player):
    """Cmd_TD_UnlockLevelGate_CS -> Cmd_TD_UnlockLevelGate_SC. The player clicked a locked
    map gate; the client already checked the star/item requirement (checkUnlockable) before
    sending, so we record the gate as unlocked and reply. The SC's `star` is the (unchanged)
    total — gates are a star THRESHOLD, not a cost. onCmd_TD_UnlockLevelGate_SC then flips the
    gate + the level behind it to unlocked and re-syncs the HUD."""
    f = parse_varint_fields(cmd_data)
    stage, gate_id = f.get(1, 0), f.get(2, 0)
    uin = player["uin"]
    store.unlock_gate(uin, stage, gate_id)
    total = store.total_stars(uin, stage)
    messages = [("PVZ.Cmd.Cmd_TD_UnlockLevelGate_SC",
                 pb_varint_field(1, stage) + pb_varint_field(2, gate_id)
                 + pb_varint_field(3, total))]   # stageId, gateId, star(total)
    # Item-gates cost keys/items (e.g. 4001:10). The client already verified the player has
    # them before sending; deduct here and sync the new bag counts.
    need = parse_bonus_items(gate_template(stage, gate_id).get("needItems", ""))
    if need:
        upd = grant_items(player, [(iid, -n) for iid, n in need])
        if upd:
            messages.append(upd)
    log.info("    GATE UNLOCKED & SAVED: stage=%d gate=%d (totalStars=%d, spent %s)",
             stage, gate_id, total, need or "no items")
    return messages


def handle_friend_getlist(cmd_data, player):
    """Cmd_Friend_GetList_CS -> Cmd_Friend_GetList_SC.

    The choose-seeds flow, after you confirm your own plants, loads the 'friend plant
    card' screen (TDChooseCardPanelMediator -> loadFriendCardInfo). Its response handler
    TDProxy.onCmd_TD_RequestFriendCard_SC EARLY-RETURNS unless moduleType matches the
    request, and only past that check does it call enterChooseFriendCardScreen() +
    unlockScreen(). An empty SC has moduleType=0 -> the handler bails -> the screen never
    unlocks -> the level freezes. Echo moduleType/friendType/page/pageSize back with an
    empty friends list (you have no friends yet) and totalCount=0 so it proceeds.

    With GM-added friends (store.get_friends), each friend is sent as a Dto_FriendInfo
    carrying a helpPlant (Dto_CardFullInfo built from the friend's plant_id+level) so the
    TD choose-seeds screen shows the friend-card chooser, and a diamond (Dto_DiamondInfo)
    so each friend's 钻石卡 shows in the friend list / world map."""
    f = parse_varint_fields(cmd_data)
    module_type = f.get(1, 0)
    friend_type = f.get(2, 0)
    page = max(0, int(f.get(3, 0) or 0))
    # 好友列表必须分页返回。小镇左侧 FriendIMWd 控件只有 ITEMS_PER_PAGE=6 个固定格子，
    # 它的 update() 会对响应里每一个好友调用 view.list.getChildAt(i)；一旦返回的好友数 >
    # 格子数就抛 RangeError #2006（"提供的索引超出范围"）。原腾讯服是分页的——这里也必须
    # 分页，并把每页大小钳制在控件容量内，绝不超过 6（返回更少是安全的，返回更多会崩）。
    FRIEND_WIDGET_MAX = 6
    raw_page_size = int(f.get(4) or 0)
    page_size = raw_page_size if 0 < raw_page_size <= FRIEND_WIDGET_MAX else FRIEND_WIDGET_MAX
    friends = list(store.get_friends(player["uin"]))
    # 注入人机好友：让每位玩家的好友列表里都出现 AI 同伴（永远在线、可借卡）。
    try:
        for _b in bots_local.bots():
            friends.append({
                "friend_role_id": _b["uin"],
                "friend_name": _b["name"],
                "help_plant_id": 1200,           # 豌豆射手（TD 植物），保证借卡位非空
                "help_plant_level": 1,
                "diamond_flag": 1,
                "diamond_blue_lvl": 0,
                "diamond_yellow_lvl": 0,
                "diamond_xinyue_lvl": 0,
            })
    except Exception:
        log.exception("injecting bot friends failed")
    total = len(friends)
    start = page * page_size
    page_friends = friends[start:start + page_size]
    d = (pb_varint_field(1, module_type) + pb_varint_field(2, friend_type)
         + pb_varint_field(3, page) + pb_varint_field(4, page_size)
         + pb_varint_field(5, total))              # totalCount = 全部好友数（含人机）
    for idx, fr in enumerate(page_friends, start=1):
        dto = build_friend_info_dto(fr, idx)
        d += pb_tag(7, 2) + uvarint(len(dto)) + dto
    log.info("    friend list: moduleType=%d friendType=%d page=%d (size=%d) -> %d/%d friend(s)",
             module_type, friend_type, page, page_size, len(page_friends), total)
    return d


# --- Dto_DiamondInfo (钻石卡 / QQ 蓝钻) --------------------------------------
# E_DiamondType (Assets/src/PVZ/Cmd/E_DiamondType.as): Blue=1, Yellow=3, XinYue=4.
_DIAMOND_TYPES = (1, 3, 4)


def build_diamond_info(flag, blue_lvl, yellow_lvl, xinyue_lvl):
    """Dto_DiamondInfo{flag(1), diamondLevel(2)=[Dto_DiamondLevel{type(1), level(2)}]}.
    A 0 level omits that diamond entirely (the client reads an absent entry as 'not granted')."""
    levels = {1: blue_lvl, 3: yellow_lvl, 4: xinyue_lvl}
    d = pb_varint_field(1, int(flag))                      # flag (1 = show the card)
    for t in _DIAMOND_TYPES:
        lv = int(levels.get(t, 0) or 0)
        if lv > 0:
            sub = pb_varint_field(1, t) + pb_varint_field(2, lv)   # type, level
            d += pb_tag(2, 2) + uvarint(len(sub)) + sub
    return d


def build_player_diamond(player):
    """The player's OWN Dto_DiamondInfo (read from the save's diamond_* columns)."""
    return build_diamond_info(player.get("diamond_flag", 1),
                              player.get("diamond_blue_lvl", 0),
                              player.get("diamond_yellow_lvl", 0),
                              player.get("diamond_xinyue_lvl", 0))


def build_friend_diamond(fr):
    """A friend's Dto_DiamondInfo (read from the friend row's diamond_* columns)."""
    return build_diamond_info(fr.get("diamond_flag", 1),
                              fr.get("diamond_blue_lvl", 0),
                              fr.get("diamond_yellow_lvl", 0),
                              fr.get("diamond_xinyue_lvl", 0))


def _friend_help_card(fr):
    """Resolve a persisted friend row to one stable borrowed-card identity.

    The friend table stores a TD plant id, while the adventure client matches a
    borrowed slot by ``helpPlant.base.uid``.  Keeping this conversion shared by
    the friend list and formation response prevents the client from creating a
    CardItemVO with cardId=0.
    """
    role_id = int(fr.get("friend_role_id") or fr.get("role_id") or 0)
    plant_id = int(fr.get("help_plant_id") or 0)
    level = max(1, int(fr.get("help_plant_level") or 1))
    cid, _ = td_plant_to_card(plant_id) if plant_id else (None, None)
    if not cid:
        # A stale friend row must still produce a valid, non-null card DTO.
        load_battle_cards()
        cid = min(_BATTLE_CARDS) if _BATTLE_CARDS else 1201
    uid = _friend_help_uid(role_id, cid)
    return uid, cid, level, card_stats_at_level(cid, level)


def build_friend_info_dto(fr, index=1):
    """Dto_FriendInfo{type(1), roleId(2,I64), zoneId(3), name(4), faceId(5), rank(6),
    roleLevel(7), plantInfo(8), passTDNum(9), status(10), helpPlant(11)=Dto_CardFullInfo,
    isFree(13), diamond(15)=Dto_DiamondInfo, isQQFriend(16), qqName(17)}.

    helpPlant is built from the friend row's help_plant_id (a tdPlantId) via td_plant_to_card;
    if unmapped we still send a minimal card so the friend-card slot stays non-null (the client
    null-derefs otherwise). diamond is the friend's 钻石卡 from the friend row."""
    role_id = int(fr.get("friend_role_id") or fr.get("role_id") or 0)
    name = fr.get("friend_name") or ("Player%d" % (role_id % 100000))
    plant_id = int(fr.get("help_plant_id") or 0)
    help_uid, cid, plant_level, st = _friend_help_card(fr)
    # The same help_uid is echoed by Cmd_Fuben_GetFormation_SC for a borrowed
    # position; BattleLineupModel indexes friends by helpPlant.base.uid.
    help_plant = build_card_full_info(help_uid, cid, plant_level, st)
    diamond = build_friend_diamond(fr)
    avatar_id = ((index - 1) % 2) + 1
    plant_info = (
        pb_varint_field(1, plant_id)         # plantId
        + pb_varint_field(2, 0)              # isNew = false
        + pb_varint_field(3, avatar_id)      # avatarId ← 新增，客户端读这个
        + pb_varint_field(4, 0)              # strengthLevel = 0
    )   # Dto_PlantInfo{plantId, isNew}
    return (pb_varint_field(1, 1)                          # type = 1 (FRIEND_TYPE_SNS)
            + pb_int64_field(2, role_id)                  # roleId
            + pb_varint_field(3, 0)                       # zoneId
            + pb_string(4, name)                          # name
            + pb_varint_field(5, (int(role_id) % 3) + 1)   # faceId: 1/2/3 轮换，让好友头像不全是 unknow
            + pb_varint_field(6, 0)                       # rank
            + pb_varint_field(7, plant_level)             # roleLevel (cosmetic)
            + pb_tag(8, 2) + uvarint(len(plant_info)) + plant_info    # plantInfo
            + pb_varint_field(9, 0)                       # passTDNum
            + pb_varint_field(10, 3)                      # status = E_FriendStatus_Friend
            + pb_tag(11, 2) + uvarint(len(help_plant)) + help_plant  # helpPlant (Dto_CardFullInfo)
            + pb_bool(13, True)                           # isFree (free to borrow)
            + pb_tag(15, 2) + uvarint(len(diamond)) + diamond        # diamond (Dto_DiamondInfo)
            + pb_bool(16, False)                          # isQQFriend
            + pb_string(17, name)                        # qqName
            + pb_string(14, "http://127.0.0.1:8080/image/head/%d.png" % index))   # qqFaceURL 放最后


# --- TD privilege (塔防特权) --------------------------------------------------
_TD_PRIV_ENDTIME = 4102444800     # 2100-01-01 UTC — far future, so the privilege never reads as expired


def td_privilege_active(player):
    """True if the player's TD privilege is currently on (and not expired)."""
    if not int(player.get("td_privilege") or 0):
        return False
    end = int(player.get("td_privilege_endtime") or 0)
    return end == 0 or end > int(time.time())


_DIAMOND_CARD_TD_PLANTS = (
    3900,  # Fire Snapdragon / 火龙草
    4100,  # Spikeweed / 地刺
    4200,  # Spikerock / 地刺王
    4500,  # Threepeater / 三发豌豆
    4600,  # Coconut Cannon / 椰子加农炮
    6300,  # Laser Bean / 激光豆子
    6400,  # Citron / 充能柚子
    6500,  # Infi-nut / 全息坚果
    6600,  # Prism Grass / 棱镜草
)


def td_privilege_plants(player):
    """The fixed plantId list supplied by the Diamond Card TD privilege.

    This entitlement is separate from the player's owned plants: synchronizing the
    account roster here exposes every earned plant through the Diamond Card.
    """
    return _DIAMOND_CARD_TD_PLANTS


def build_td_open_privilege_sc(player):
    """Cmd_TD_OpenPrivilege_SC{hasPrivilege(1), remainTime(2)} — the login push that tells the
    client the TD privilege is active. remainTime = seconds remaining (far-future when on)."""
    if not td_privilege_active(player):
        return pb_bool(1, False) + pb_varint_field(2, 0)
    end = int(player.get("td_privilege_endtime") or 0) or _TD_PRIV_ENDTIME
    remain = max(0, end - int(time.time()))
    return pb_bool(1, True) + pb_varint_field(2, remain)


def handle_td_privilege_info(cmd_data, player):
    """Cmd_TD_PrivilegeInfo_CS{stageId(1), levelId(2), subLevelId(3), challengeLevelId(4)} ->
    Cmd_TD_PrivilegeInfo_SC{stageId(1), levelId(2), subLevelId(3), hasPrivilege(4),
    plantId(5)=[...], remainTime(6), challengeLevelId(7)}. Sent on entry to a TD level — the
    client unlocks the listed plants for that level when hasPrivilege=true."""
    f = parse_varint_fields(cmd_data)
    stage = f.get(1, 0); level = f.get(2, 0); sub = f.get(3, 0); chl = f.get(4, 0)
    active = td_privilege_active(player)
    end = int(player.get("td_privilege_endtime") or 0) or _TD_PRIV_ENDTIME
    remain = max(0, end - int(time.time())) if active else 0
    d = (pb_varint_field(1, stage) + pb_varint_field(2, level) + pb_varint_field(3, sub)
         + pb_bool(4, active))
    for pid in td_privilege_plants(player):
        d += pb_varint_field(5, pid)                      # plantId (repeated)
    d += pb_varint_field(6, remain)                       # remainTime
    d += pb_varint_field(7, chl)                          # challengeLevelId
    log.info("    TD privilege info: stage=%d-%d-%d hasPrivilege=%s plants=%d",
             stage, level, sub, active, len(td_privilege_plants(player)))
    return d


def td_privilege_login_messages(player):
    """Pushed right after Cmd_Init_SC when the player's TD privilege is on: the
    Cmd_TD_OpenPrivilege_SC notification populates the client's TD-privilege state for every
    TD activity (Daily / Endless / SnowMan / per-level query) at once."""
    if not td_privilege_active(player):
        return []
    return [("PVZ.Cmd.Cmd_TD_OpenPrivilege_SC", build_td_open_privilege_sc(player))]


def build_vip_syncvipinfo_sc(player):
    """Cmd_Vip_SyncVipInfo_SC{diamond(1)=Dto_DiamondInfo} — the player's OWN diamond card.
    ModuleBlueDiamond.swf listens for this and renders the 钻石卡 UI from it."""
    return pb_tag(1, 2) + uvarint(len(build_player_diamond(player))) + build_player_diamond(player)


def diamond_login_messages(player):
    """Push the player's own diamond card right after Cmd_Init_SC so ModuleBlueDiamond has its
    state from the very start. Always sent (even all-zero) so a previously-shown card clears
    when the GM turns it off."""
    return [("PVZ.Cmd.Cmd_Vip_SyncVipInfo_SC", build_vip_syncvipinfo_sc(player))]


# --- Daily Sign-in (Welfare Hall "签到" tab) ----------------------------------
# The sign-in tab is a monthly reward calendar: one claimable cell per day. The reward
# list is server-defined (no clientDB table backs it), so we fabricate a sensible
# escalating calendar. Rewards are granted FOR REAL via grant_fuben_reward (same
# currency/bag routing as fuben loot) — the client only animates the item-fly.
# Dto_Reward_Info{date=day#, itemId, itemNum, vipLevel}; vipLevel=0 => no VIP doubling.
# Item ids route through _CURRENCY_SYNC/bag: 1=coin 3=sun 4=gift diamond,
# 2002/2003/2004=exp beans, 4001=TD key.  30 entries = a full month calendar.
_SIGN_IN_REWARDS = [
    (1, 2000, 0),  (3, 20, 0),    (2002, 2, 0),  (1, 3000, 0),  (4001, 1, 0),
    (3, 30, 0),    (4, 5, 0),     (1, 4000, 0),  (2003, 1, 0),  (1, 5000, 0),
    (3, 40, 0),    (4001, 2, 0),  (1, 5000, 0),  (4, 10, 0),    (2003, 2, 0),
    (1, 6000, 0),  (3, 50, 0),    (4001, 2, 0),  (1, 6000, 0),  (2004, 1, 0),
    (4, 15, 0),    (1, 8000, 0),  (3, 60, 0),    (4001, 3, 0),  (1, 8000, 0),
    (2003, 3, 0),  (3, 60, 0),    (4, 20, 0),    (1, 10000, 0), (2004, 2, 0),
]


def _sign_today():
    t = time.localtime()
    return t.tm_year * 10000 + t.tm_mon * 100 + t.tm_mday


def _sign_month():
    t = time.localtime()
    return t.tm_year * 100 + t.tm_mon


def _signin_rollover(player):
    """Reset the month's sign count when the calendar month changes; persist."""
    m = _sign_month()
    if int(player.get("sign_month") or 0) != m:
        player["sign_month"] = m
        player["sign_total"] = 0
        store.save_player(player["uin"], sign_month=m, sign_total=0)


def _encode_signin_info(total, signed_today, remain=0, used_free=0, used_vip=0):
    """Dto_SignIn_Info{totalSignNum(1), remainSignNum(2), usedfreeTimes(3),
    usedVipFreeTimes(4), bIsSigned(5)}."""
    return (pb_varint_field(1, total) + pb_varint_field(2, remain)
            + pb_varint_field(3, used_free) + pb_varint_field(4, used_vip)
            + pb_bool(5, signed_today))


def handle_signin_getrewardlist(cmd_data, player):
    """Cmd_SignIn_GetRewardList_CS -> the monthly reward calendar (per-day rewards)."""
    d = b""
    for day, (iid, num, vip) in enumerate(_SIGN_IN_REWARDS, start=1):
        dto = (pb_varint_field(1, day) + pb_varint_field(2, iid)
               + pb_varint_field(3, num) + pb_varint_field(4, vip))
        d += pb_tag(1, 2) + uvarint(len(dto)) + dto      # rewardList (repeated Dto_Reward_Info)
    return d


def handle_signin_getinfo(cmd_data, player):
    """Cmd_SignIn_GetInfo_CS -> the player's current sign-in state (days signed, signed-today)."""
    _signin_rollover(player)
    total = int(player.get("sign_total") or 0)
    signed = int(player.get("sign_last") or 0) == _sign_today()
    info = _encode_signin_info(total, signed)
    return pb_tag(1, 2) + uvarint(len(info)) + info      # signInInfo (field 1, Dto_SignIn_Info)


def handle_signin_setinfo(cmd_data, player):
    """Cmd_SignIn_SetInfo_CS (doSignIn) -> claim today's sign-in: bump the day count, grant
    that day's reward, persist, reply with the updated info. Idempotent per calendar day
    (a second sign-in the same day just re-sends state, no double grant). The client flies
    rewardList[total-1] == the same item we grant here."""
    _signin_rollover(player)
    today = _sign_today()
    uin = player["uin"]
    if int(player.get("sign_last") or 0) == today:
        total = int(player.get("sign_total") or 0)
        log.info("    sign-in: uin=%s already signed today (day %d)", uin, total)
        info = _encode_signin_info(total, True)
        return pb_tag(1, 2) + uvarint(len(info)) + info
    total = min(int(player.get("sign_total") or 0) + 1, len(_SIGN_IN_REWARDS))
    player["sign_total"] = total
    player["sign_last"] = today
    store.save_player(uin, sign_total=total, sign_last=today, sign_month=_sign_month())
    iid, num, vip = _SIGN_IN_REWARDS[total - 1]
    log.info("    sign-in: uin=%s -> day %d, reward item %d x%d", uin, total, iid, num)
    grant_msgs = grant_fuben_reward(player, [(iid, num)])   # actually grants (coin/bag) + syncs
    info = _encode_signin_info(total, True)
    body = pb_tag(1, 2) + uvarint(len(info)) + info
    return [("PVZ.Cmd.Cmd_SignIn_SetInfo_SC", body)] + grant_msgs


# --- FlexibleActivity list (limited-time events framework) --------------------
# The Welfare Hall's "Daily Activity" tab loads ModuleDodgeAndCat, whose
# DodgeAndCatService.initActivity() does getGroupByViewType(v)[0] (NO null check) for
# view types DODGE(2)/CAT(3)/CARD_PLANT_ARMOR(62)/CARD_FRUIT_ADV(63). On an empty
# activity list that throws #1125 "index 0 out of range 0", which aborts the whole
# Welfare Hall window (registerPanel) — so the sign-in tab is unreachable. Fix: feed one
# minimal activity per needed view type so those [0] lookups resolve. viewType ==
# Dto_FlexibleActivityCommon.activityPanelId (field 4); the client requests this list at
# login (InitActivityTask) so m_vecActivity is populated before the window ever opens.
# Activities carry no icon (iconId=0) / no time window, so they add no HUD icon and stay
# inert (a closed event). Add more view types here if other event modules #1125 the same way.
_FLEX_ACTIVITY_VIEWTYPES = [2, 3, 62, 63]   # DODGE, CAT, CARD_PLANT_ARMOR, CARD_FRUIT_ADV


def _activity_fuben_limit(activity_id):
    """Encode the legacy activity-fuben limit used by DodgeAndCatService.

    The level list itself is client data (hdfuben.txt).  The server still has to identify the
    activity as FlexibleActivity type 1 and provide the six stage ids; without this payload the
    client opens ActFubenWindow with an empty `fuben` vector, which is the blank panel users see.
    Activity 1 is catch-thief (1..6), activity 2 is protect-farm (7..12),
    activity 3 is the armor/alloy mine (18..22), and activity 4 is the fruit
    deep-sea dungeon (13..17; its rewards are energy stones).
    """
    stage_ids = {
        1: range(1, 7),       # 捉小偷
        2: range(7, 13),      # 护农田
        3: range(18, 23),     # 植物装甲 / 合金矿场
        4: range(13, 18),     # 果实 / 深渊海域（能量石）
    }
    ids = list(stage_ids.get(int(activity_id), ()))
    if not ids:
        return b""
    limit = (pb_varint_field(3, 6) + pb_varint_field(4, 6)
             + pb_varint_field(5, 0) + b"".join(pb_varint_field(6, i) for i in ids)
             + pb_varint_field(7, 0))
    # FlexibleActivity_1{activityId(1), limit(2)=Dto_FlexibleActivityLimitFuben}.
    nested = (pb_varint_field(1, int(activity_id))
              + pb_tag(2, 2) + uvarint(len(limit)) + limit)
    return nested


def _activity_common(activity_id, panel_id):
    nested = _activity_fuben_limit(activity_id)
    # Dto_FlexibleActivityCommon: activityType=1 selects FlexibleActivity_1; serverParams is the
    # serialized FlexibleActivity_1 payload. The fuben ids and daily limit live in that payload.
    # Explicitly bound the event lifetime too: the Flash ActivityProxy filters expired/unbounded
    # records before DodgeAndCatService builds its tab's stage list.
    now = int(time.time())
    dto = (pb_varint_field(1, int(activity_id)) + pb_varint_field(2, 1)
           + pb_varint_field(4, int(panel_id))
           + pb_varint_field(5, max(1, now - 86400))
           + pb_varint_field(6, 2145916800)  # 2038-01-01 UTC; within protobuf uint32
           + pb_bytes(10, nested))
    return pb_tag(1, 2) + uvarint(len(dto)) + dto


def handle_flexactivity_getlist(cmd_data, player):
    """Cmd_FlexibleActivity_GetActivityList_CS -> a minimal activity list whose entries
    cover the view types the event services index [0] of, so the town/Welfare Hall don't
    #1125. Dto_FlexibleActivityCommon{activityId(1), activityPanelId(4)=viewType}."""
    d = (_activity_common(1, 2) + _activity_common(2, 3)
         + _activity_common(3, 62) + _activity_common(4, 63))
    login_entry = town_login_rewards.common_entry(_activity_server_api(), player)
    d += pb_tag(1, 2) + uvarint(len(login_entry)) + login_entry
    # The limited-time login activity counts a distinct login day even when
    # the player does not open its window during that session.
    hotspot_events.activity_stat(hotspot_events.TIME_ID, player)
    d += hotspot_events.activity_list_entries()
    d += pb_bytes(1, treasure_local.children_common_entry(_activity_server_api(), player))
    d += pb_bytes(1, jar_local.common_entry(_activity_server_api(), player))
    # Do not publish archived promotional icons unless a complete local server adapter
    # exists; those client panels crash when they receive a synthetic empty activity.
    d += historical_activities.common_entries(_activity_server_api())
    return d


def handle_flexactivity_getstat(cmd_data, player):
    """Cmd_FlexibleActivity_GetActivityStat_CS -> FlexibleActivity_1.

    DodgeAndCatService requests the per-activity stat after the activity list arrives. Its
    ActivityProxy parses FlexibleActivity_1.limit into ActivityModuleInfo.openList; without this
    response openList remains null and ActFubenWindowMediator.refreshList crashes with #1009.
    """
    activity_id = parse_varint_fields(cmd_data).get(1, 0)
    archived = historical_activities.empty_stat(_activity_server_api(), activity_id)
    if archived is not None:
        return archived
    if activity_id == town_login_rewards.ACTIVITY_ID:
        return town_login_rewards.get_stat(_activity_server_api(), player)
    if activity_id == treasure_local.CHILDREN_ACTIVITY_ID:
        return treasure_local.children_get_stat(_activity_server_api(), player)
    if activity_id == jar_local.ACTIVITY_ID:
        return jar_local.get_stat(_activity_server_api(), player)
    hotspot_stat = hotspot_events.activity_stat(activity_id, player)
    if hotspot_stat is not None:
        return [hotspot_stat]
    response = _activity_fuben_limit(activity_id)
    if not response:
        log.warning("    activity stat: unsupported activity id=%d", activity_id)
        return []
    log.info("    activity stat: activity=%d -> hdfubenIds=%s", activity_id,
             [fid for fid in range(1, 23) if _activity_id_for_fuben(fid) == activity_id])
    return [("PVZ.Cmd.FlexibleActivity_1", response)]


def handle_flexactivity_take_reward(cmd_data, player):
    activity_id = parse_varint_fields(cmd_data).get(1, 0)
    if activity_id == town_login_rewards.ACTIVITY_ID:
        return town_login_rewards.take_reward(_activity_server_api(), cmd_data, player)
    if activity_id == treasure_local.CHILDREN_ACTIVITY_ID:
        return treasure_local.children_take_reward(_activity_server_api(), cmd_data, player)
    if activity_id == hotspot_events.TIME_ID:
        return hotspot_events.handle_time_reward(cmd_data, player)
    if activity_id in historical_activities.archived_activity_ids(_activity_server_api()):
        # The historic campaign definitions/reward tables are not in this local pack.
        # Acknowledge safely without minting a guessed reward or leaving the client pending.
        return [("PVZ.Cmd.Cmd_FlexibleActivity_TakeReward_SC", b"")]
    return []


def _activity_id_for_fuben(fuben_id):
    """Translate the authoritative hdfuben id ranges to their FlexibleActivity panel."""
    fuben_id = int(fuben_id)
    if 1 <= fuben_id <= 6:
        return 1
    if 7 <= fuben_id <= 12:
        return 2
    if 13 <= fuben_id <= 17:
        return 4
    if 18 <= fuben_id <= 22:
        return 3
    return 0


def _activity_enemy_units(fuben_id):
    """Build an activity lineup from the faction assigned to this hdfuben id.

    hdfuben.txt groups the stages as 1-6 (thief), 7-12 (cart peddler),
    13-17 (sea/Dragon Palace), and 18-22 (Future World/alloy mine). The
    table's headIcon and battleMapId confirm the last two groups' worlds.
    11-15 are only five star variants of the same thief card, not five
    different zombies; the old implementation made every event look like
    the thief event regardless of its map.
    """
    load_battle_cards()
    try:
        fuben_id = int(fuben_id)
    except (TypeError, ValueError):
        fuben_id = 1

    if 1 <= fuben_id <= 6:
        stage, roster = fuben_id, [11]
    elif 7 <= fuben_id <= 12:
        stage, roster = fuben_id - 6, [381, 389]  # 推车小贩 / 推车小贩首领
    elif 13 <= fuben_id <= 17:
        # hdfuben headIcon=809 is 海马僵尸首领 and map 190011 is the sea dungeon.
        stage, roster = fuben_id - 12, [771, 781, 791, 801, 817, 818, 820, 841, 851, 861, 871, 881, 891]
    elif 18 <= fuben_id <= 22:
        # hdfuben headIcon=1041 is 机甲路障僵尸首领 and map 290011 is Future World.
        stage, roster = fuben_id - 17, [250, 252, 200, 202, 201, 204, 206, 207, 254]
    else:
        # Keep unknown/legacy ids safe and visibly distinct from the other factions.
        stage, roster = max(1, min(6, fuben_id)), [11]

    # Progressively introduce more enemy slots as the activity difficulty rises.
    count = min(len(_ENEMY_POS), 2 + (stage - 1) // 2)
    cards = [roster[i % len(roster)] for i in range(count)]
    cards = [cid if cid in _BATTLE_CARDS else roster[0] for cid in cards]
    units = []
    for pos, cid in zip(_ENEMY_POS, cards):
        st = card_stats_at_level(cid, max(1, stage)) or _BATTLE_CARDS.get(cid, {})
        power = card_power(st)
        units.append({"pos": pos, "card_id": cid, "hp": max(1, int(st.get("hp", 1000))),
                      "maxhp": max(1, int(st.get("hp", 1000))), "atk": max(1, int(st.get("atk", 1))),
                      "def_": int(st.get("def_", 0)), "skill1": int(st.get("skill1", 0)),
                      "skill2": int(st.get("skill2", 0)), "level": stage,
                      "is_leader": pos == _ENEMY_POS[0], "name": st.get("name", "小偷僵尸"),
                      "power": power})
    return units


def handle_activity_getformation(cmd_data, player):
    ensure_player_cards(player)
    note_battle_scene(player, "activity")     # its lineup window is about to ask for the enemy preview
    formation = build_formation_info(player, 1, default_formation_placements(player))
    return pb_tag(1, 2) + uvarint(len(formation)) + formation


def handle_activity_setformation(cmd_data, player):
    # Activity formation uses the same team as the normal battle lineup.  Echoing it is important:
    # the activity window waits for this SC before enabling its challenge button.
    return [("PVZ.Cmd.Cmd_Battle_GetActivityFubenFormation_SC",
             handle_activity_getformation(cmd_data, player))]


def _activity_cs_fuben_id(cmd_data):
    """The hdfuben id of an activity fight request. BOTH Cmd_Battle_GetActivityFubenFightInfo_CS (the
    pre-fight preview) and Cmd_Battle_StartActivityFubenFight_CS are {activityId(1), fubenId(2)}; the
    single-id shape is tolerated too. Sharing this parse is what keeps the previewed faction and the
    fought faction identical."""
    fields = parse_varint_fields(cmd_data)
    return fields.get(2) or fields.get(1, 1)


def handle_activity_getfightinfo(cmd_data, player):
    # Resolve the id with the SAME helper the fight uses, so the preview can never resolve a different
    # hdfuben (a different zombie faction) than Cmd_Battle_StartActivityFubenFight_CS will.
    fuben_id = _activity_cs_fuben_id(cmd_data)
    note_battle_scene(player, "activity")
    formation = build_formation_info(player, 1, default_formation_placements(player))
    d = pb_tag(1, 2) + uvarint(len(formation)) + formation
    enemies = _activity_enemy_units(fuben_id)
    remember_battle_preview(player, enemies, "activity", str(fuben_id),
                            label="preview:activity:%s" % fuben_id)
    for unit in enemies:
        ec = build_enemy_card(unit["pos"], unit["card_id"], unit["hp"], unit["level"],
                              unit["is_leader"], unit["power"])
        d += pb_tag(4, 2) + uvarint(len(ec)) + ec
    return d + pb_varint_field(5, sum(u["power"] for u in enemies))


_HDFUBEN_CONFIG = None


def load_hdfuben_config():
    """Read the activity fight/reward setup directly from hdfuben.txt."""
    global _HDFUBEN_CONFIG
    if _HDFUBEN_CONFIG is None:
        _HDFUBEN_CONFIG = {}
        rows = _read_clientdb_table("hdfuben.txt")
        if rows:
            hdr = rows[0]; ci = {c: i for i, c in enumerate(hdr)}
            for row in rows[1:]:
                try:
                    fid = int(row[ci["id"]])
                    _HDFUBEN_CONFIG[fid] = {
                        "level": int(row[ci["level"]]),
                        "headIcon": int(row[ci["headIcon"]]),
                        "bonusRequired": row[ci["bonusRequired"]],
                        "bonusOptional": row[ci["bonusOptional"]],
                        "battleMapId": int(row[ci["battleMapId"]]),
                    }
                except (KeyError, IndexError, TypeError, ValueError):
                    continue
        log.info("loaded %d activity-fuben templates", len(_HDFUBEN_CONFIG))
    return _HDFUBEN_CONFIG


def _activity_fuben_rewards(fuben_id):
    """Return guaranteed activity rewards and enabled bonusOptional items.

    In hdfuben.txt the third component is an enable flag (1=drop this item), unlike
    the regular fuben.txt table where the third component is a 0..10000 probability.
    """
    config = load_hdfuben_config().get(int(fuben_id))
    if not config:
        stage = max(0, min(5, (int(fuben_id) - 1) % 6))
        return [(5, 88 + stage * 78)]
    rewards = parse_bonus_items(config["bonusRequired"])
    for entry in (config["bonusOptional"] or "").split(";"):
        parts = entry.split(":")
        try:
            item_id, amount = int(parts[0]), int(parts[1])
            enabled = int(parts[2]) if len(parts) > 2 else 1
        except (IndexError, TypeError, ValueError):
            continue
        if amount > 0 and enabled:
            rewards.append((item_id, amount))
    return rewards


def handle_activity_startfight(cmd_data, player):
    fields = parse_varint_fields(cmd_data)
    activity_id, fuben_id = fields.get(1, 1), _activity_cs_fuben_id(cmd_data)
    expected_activity_id = _activity_id_for_fuben(fuben_id)
    if expected_activity_id and activity_id != expected_activity_id:
        log.warning("    activity/fuben mismatch: got activity=%d fuben=%d; config expects activity=%d",
                    activity_id, fuben_id, expected_activity_id)
    left = build_player_units(player)
    right = _activity_enemy_units(fuben_id)
    # Fight the squad the activity lineup window previewed (see apply_previewed_enemy_types).
    right = apply_previewed_enemy_types(player, right, "activity", str(fuben_id))
    won, _, _ = resolve_battle(left, right)
    replay = encode_fight_replay(simulate_battle(left, right, won)) \
        if left and right else b""
    reward = _activity_fuben_rewards(fuben_id)
    card_exp_gain = next((amount for item_id, amount in reward if item_id == 5), 0)
    report = build_fight_report(player, 0, activity_id, fuben_id, won, reward, False, left, right,
                                replay, card_exp_gain=card_exp_gain, fight_type=5)
    body = pb_tag(1, 2) + uvarint(len(report)) + report
    log.info("    activity fuben: activity=%d fuben=%d -> %s", activity_id, fuben_id,
             "WIN" if won else "LOSS")
    messages = [("PVZ.Cmd.Cmd_Battle_StartActivityFubenFight_SC", body)]
    if won:
        messages += grant_fuben_reward(player, reward)
        if card_exp_gain:
            messages += grant_battle_card_exp(player, card_exp_gain)
        messages += _quest_observe_card_progress(player)
    return messages


# --- Greenhouse / Plant Talent (植物研究所, Building_Reasearch) ----------------
# A per-plant talent CHAIN (plantTalentInfo.txt): 112 talents in 4 stages, each plant has a
# linear chain (talentIndex 1..5, parentTalentId links them). Studying a talent boosts that
# plant in normal-mode TD. The greenhouse requests one STAGE at a time; the plant cards come
# from the client's own plantTalentInfo, the SC's talentList just flags each talent
# studied/available. We let talents be freely studiable (satisfyPower/satisfyCondition=true)
# but the client still enforces the parent-chain order; studied talents persist.
# CRASH NOTE: PlantTalentModel.setUnlockPlantList does getPlantTalentSetById(talentId).plantId
# with no null check -> every talentId we send MUST exist in plantTalentInfo.txt (they do).
_PLANT_TALENTS = None


def load_plant_talents():
    """{'by_stage': {stageId: [talentId,...]}, 'talent': {talentId: {plantId, stage, parent}}}."""
    global _PLANT_TALENTS
    if _PLANT_TALENTS is None:
        by_stage, talent = {}, {}
        rows = _read_clientdb_table("plantTalentInfo.txt")
        if rows:
            hdr = rows[0]; ci = {c: i for i, c in enumerate(hdr)}

            def col(c, k):
                i = ci.get(k)
                return c[i] if i is not None and i < len(c) else ""
            for c in rows[1:]:
                try:
                    tid = int(col(c, "id")); stage = int(col(c, "stageId"))
                    pid = int(col(c, "plantId")); parent = int(col(c, "parentTalentId") or 0)
                except ValueError:
                    continue
                talent[tid] = {"plantId": pid, "stage": stage, "parent": parent,
                               "power": int(col(c, "power") or 0),
                               "cond": col(c, "advancedCond")}
                by_stage.setdefault(stage, []).append(tid)
        _PLANT_TALENTS = {"by_stage": by_stage, "talent": talent}
        log.info("loaded %d plant talents across %d stages",
                 len(talent), len(by_stage))
    return _PLANT_TALENTS


def plant_card_power(player, plant_id):
    """The player's current 战力 (battle power) for a TD plant = the strongest owned card whose
    tdId == plant_id, at its card level (0 if the plant isn't owned)."""
    load_battle_cards()
    best = 0
    for _uid, card_id, level, _exp in store.get_cards(player["uin"]):
        b = _BATTLE_CARDS.get(card_id)
        if b and b.get("tdId") == int(plant_id):
            best = max(best, card_power(card_stats_at_level(card_id, level)))
    return best


def _eval_talent_condition(player, advanced_cond):
    """True if a talent's advancedCond ('type:params:value') is met. We check the systems that
    exist (TOWN_LEVEL(2)->role level, beat-adventure(14), PLANT_LEVEL(5), PLANT_STAR(8)); every
    other condition is tied to a building we haven't built yet (trial road, nutrition, world tree,
    zen garden, equipment, zombie island, arena, union, mines, awaken, avatar, quest...) and
    returns True so the tree stays completable — wire real checks in here as those come online.
    Types = TalentAdvancedConditionType."""
    parts = (advanced_cond or "").split(":")
    if not parts or not parts[0].isdigit():
        return True
    ctype = int(parts[0])
    params = parts[1] if len(parts) > 1 else ""
    value = parts[2] if len(parts) > 2 else ""
    uin = player["uin"]
    try:
        if ctype == 2:                    # TOWN_LEVEL -> role level (our progression metric)
            return int(player.get("level", 1)) >= int(value or 0)
        if ctype == 14:                   # beat an adventure stage: params = chapter,stage,mode
            ch, st, md = [int(x) for x in (params.split(",") + ["1", "1", "1"])[:3]]
            return st in store.get_fuben_passed(uin, ch, md)
        if ctype == 5:                    # PLANT_LEVEL: params=targetLevel, value=count
            target, count = int(params), int(value)
            return sum(1 for _u, _c, lv, _e in store.get_cards(uin) if int(lv) >= target) >= count
        if ctype == 8:                    # PLANT_STAR: params=star, value=count
            load_battle_cards()
            target, count = int(params), int(value)
            return sum(1 for _u, cid, _lv, _e in store.get_cards(uin)
                       if (_BATTLE_CARDS.get(cid) or {}).get("star", 1) >= target) >= count
    except (ValueError, IndexError):
        return True
    return True                           # unbuilt-system condition -> allow (keep tree completable)


def _talent_gates(player, info, power_cache):
    """The local repair build has no complete authoritative state for all talent gates.

    Keep the greenhouse usable by reporting power and task requirements as satisfied;
    the plant's parent-talent chain is still enforced by the client and study handler.
    """
    return True, True


def handle_talent_getlist(cmd_data, player):
    """Cmd_Talent_GetList_CS{stageId} -> Cmd_Talent_GetList_SC{stageId(1),
    unlockPlantList(3)=[Dto_PlantInfo], talentList(4)=[Dto_TalentInfo]}. satisfyPower/Condition
    are true in this local build so study dialogs can be opened; parent order remains enforced."""
    stage = parse_varint_fields(cmd_data).get(1, 0)
    tal = load_plant_talents()
    studied = set(store.get_talents(player["uin"]))
    if stage == 0:
        # Login (InitTalentTask) requests stage 0. Respond AS stage 1 (a REAL stage): the client
        # sets curStageId from our echoed stageId, and the greenhouse's onRegister immediately runs
        # updateCardBox -> getPlantByStageId(curStageId) + PTBar updates against m_talentDic. Echoing
        # stageId=0 makes those empty/inconsistent and PTBarMediator.updateHandler #1009s on
        # getTalentInfoById(id).hasStudy (null). Studied talents apply in TD via
        # Cmd_TD_RequestTDInfo_SC field 6 (not this model), so we don't need to seed them here.
        stage = 1
        stage_talents = tal["by_stage"].get(1, [])
    else:
        stage_talents = tal["by_stage"].get(stage, [])
    out = pb_varint_field(1, stage)
    # unlockPlantList (field 3) = distinct plants that have talents in this stage
    seen = set()
    for tid in stage_talents:
        pid = tal["talent"][tid]["plantId"]
        if pid in seen:
            continue
        seen.add(pid)
        dto = pb_varint_field(1, pid) + pb_varint_field(2, 0)   # Dto_PlantInfo{plantId, isNew}
        out += pb_tag(3, 2) + uvarint(len(dto)) + dto
    # talentList (field 4) — report gates as satisfied so the talent study button is enabled.
    power_cache = {}
    n_ready = 0
    for tid in stage_talents:
        info = tal["talent"][tid]
        if tid in studied:
            sat_power = sat_cond = True
        else:
            sat_power, sat_cond = _talent_gates(player, info, power_cache)
            if sat_power and sat_cond:
                n_ready += 1
        dto = (pb_varint_field(1, tid)          # talentId
               + pb_bool(2, tid in studied)     # hasStudy
               + pb_bool(3, sat_power)          # satisfyPower
               + pb_bool(4, sat_cond))          # satisfyCondition
        out += pb_tag(4, 2) + uvarint(len(dto)) + dto
    log.info("    talent list stage %d: %d talents, %d plants, %d studied, %d studiable-now",
             stage, len(stage_talents), len(seen),
             len(studied & set(stage_talents)), n_ready)
    return out


def handle_talent_study(cmd_data, player):
    """Cmd_Talent_Study_CS{talentId} -> study it (persist) + Cmd_Talent_Study_SC{talentId}.
    Enforces: real talent, parent studied, and not already studied. The local build reports
    power/task gates satisfied so the client does not silently disable the study button."""
    tid = parse_varint_fields(cmd_data).get(1) or 0
    tal = load_plant_talents()
    info = tal["talent"].get(tid)
    if not info:
        log.info("    talent study: unknown talent %s -> ignored", tid)
        return []
    studied = set(store.get_talents(player["uin"]))
    if tid in studied:
        return []                                    # already studied
    if info["parent"] and info["parent"] not in studied:
        log.info("    talent study: talent %d parent %d not studied -> deny", tid, info["parent"])
        return []                                    # must study the chain in order
    store.study_talent(player["uin"], tid)
    log.info("    talent study: uin=%s studied talent %d (plant %d)",
             player["uin"], tid, info["plantId"])
    return ([ ("PVZ.Cmd.Cmd_Talent_Study_SC", pb_varint_field(1, tid)) ]
            + _quest_observe_talent_progress(player))


# --- Ranking (排行榜, Building_Rank) — leaderboards -----------------------------
# A defunct MMO leaderboard: offline there are no other players, so we show the PLAYER at
# rank #1 in the tabs we can compute (fight power / achievement / trial-stage / plant-star)
# and leave guild/arena/all-server tabs empty. CRITICAL: the SC MUST echo the requested
# `ranktype` (field 1) — RankProxy switches on it, and a mismatched/absent type (the generic
# empty reply sends 0) never fires EVENT_RANK_LIST_UPDATE, so the window stays blank.
def _player_fight_power(player):
    """The player's 战力 = sum of card power over their whole collection (>=100)."""
    load_battle_cards()
    total = sum(card_power(card_stats_at_level(cid, lv))
                for _u, cid, lv, _e in store.get_cards(player["uin"]))
    return total or 100


def _player_plant_stars(player):
    """Total plant stars across owned cards (Dto_RolePlantStar.starnum)."""
    load_battle_cards()
    return sum((_BATTLE_CARDS.get(cid) or {}).get("star", 1)
               for _u, cid, _l, _e in store.get_cards(player["uin"]))


def _rank_dto_fightpower(player, rank):   # Dto_RoleFightPower
    return (pb_varint_field(1, rank) + pb_string(2, player["name"]) + pb_varint_field(3, player["level"])
            + pb_string(4, "") + pb_varint_field(5, _player_fight_power(player))
            + pb_varint_field(6, player["role_id"]))


def _rank_dto_achievement(player, rank):  # Dto_RoleAchievement
    return (pb_varint_field(1, rank) + pb_string(2, player["name"]) + pb_varint_field(3, player["level"])
            + pb_varint_field(4, 0) + pb_varint_field(5, 0) + pb_varint_field(6, player["role_id"]))


def _rank_dto_screwup(player, rank):      # Dto_ScrewUpStage / NewScrewUpStage
    return (pb_varint_field(1, rank) + pb_string(2, player["name"]) + pb_varint_field(3, player["level"])
            + pb_varint_field(4, _player_fight_power(player)) + pb_varint_field(5, 0)
            + pb_varint_field(6, player["role_id"]))


def _rank_dto_plantstar(player, rank):    # Dto_RolePlantStar
    return (pb_varint_field(1, rank) + pb_string(2, player["name"]) + pb_varint_field(3, player["level"])
            + pb_varint_field(4, _player_plant_stars(player)) + pb_varint_field(5, player["role_id"]))


# ranktype -> (GetRankList_SC list field, GetSelfRank_SC self field, dto builder). Types not
# here (guild/arena/all-server) still echo ranktype -> the tab opens, just empty.
_RANK_TYPES = {
    1:  (4, 2, _rank_dto_fightpower),    # RoleFightPower
    2:  (5, 3, _rank_dto_achievement),   # RoleAchievement
    4:  (7, 5, _rank_dto_screwup),       # ScrewUpStage
    6:  (9, 7, _rank_dto_plantstar),     # PlantStar
    12: (15, 11, _rank_dto_screwup),     # NewScrewUpStage
}


def handle_getranklist(cmd_data, player):
    """Cmd_GetRankList_CS{ranktype, page} -> Cmd_GetRankList_SC{ranktype(1), ranknum(3),
    <typefield>=[Dto]}. Player at rank #1 for computable tabs; empty otherwise."""
    ranktype = parse_varint_fields(cmd_data).get(1, 1)
    out = pb_varint_field(1, ranktype)
    entry = _RANK_TYPES.get(ranktype)
    if entry:
        list_field, _self, builder = entry
        dto = builder(player, 1)
        out += pb_varint_field(3, 1)                          # ranknum = 1 (just you)
        out += pb_tag(list_field, 2) + uvarint(len(dto)) + dto
    else:
        out += pb_varint_field(3, 0)                          # no offline data for this board
    return out


def handle_getselfrank(cmd_data, player):
    """Cmd_GetSelfRank_CS{ranktype} -> Cmd_GetSelfRank_SC{ranktype(1), <typefield>=Dto}."""
    ranktype = parse_varint_fields(cmd_data).get(1, 1)
    out = pb_varint_field(1, ranktype)
    entry = _RANK_TYPES.get(ranktype)
    if entry:
        _list, self_field, builder = entry
        dto = builder(player, 1)
        out += pb_tag(self_field, 2) + uvarint(len(dto)) + dto
    return out


# --- King of the Hill (巅峰王者 / TopFight, Building_TopKing) — multiplayer-only stub -----
# A cross-zone PvP betting tournament with no offline equivalent. The window (TopKingWindowMediator)
# early-returns cleanly when the model is "not_inited" (getStageState). The model is inited only if
# curStageInfo != null = getStageInfoByID(stageId) resolves (valid ids are 100..900; stageId==0 gets
# remapped to 900). So we reply with an INVALID non-zero stageId (1) -> curStageInfo=null ->
# not_inited -> onInfoUpdate returns early -> a clean empty tournament (no crash on the empty roster).
def handle_topfight_info(cmd_data, player):
    """Cmd_TopFight_Info_CS -> Cmd_TopFight_Info_SC forced to the uninitialised state so the
    King-of-the-Hill window opens empty instead of trying to render a live tournament."""
    return pb_varint_field(5, 1)          # stageId = 1 (not a real stage) -> model stays not_inited


# --- Zen Garden (阳光房 / Building_GARDEN) — plant/grow/harvest idle-farm -------------
# 16 pots. GardenSeed.txt: type1 = sunflower (produces exp over time -> garden exp -> beans),
# type2 = crop (grows over `time` sec -> one harvest of coins/items). We persist each unlocked
# pot's seed + plant_time, compute yields server-side on harvest, and grant them for real.
_GARDEN_SEEDS = None
_GARDEN_UNLOCK = None
_GARDEN_FERTILIZERS = None
_GARDEN_UPGRADES = None
_GARDEN_SUNFLOWER_EXP = 12          # base exp per production cycle (desc: "12点基础经验/20秒")
_GARDEN_MAX_IDLE_CYCLES = 4320      # cap idle accrual at ~24h (24*3600/20) so it can't runaway
_GARDEN_BEAN_EXP = 10000            # exp per 小经验豆 (item 2002 use-effect) -> bean conversion
_GARDEN_EXP_BEAN_ITEM = 2002
_GARDEN_FERTILIZER_TIME = 4 * 3600
_GARDEN_DEFAULT_FERTILIZER = 1025   # 普通化肥; one-timeslot baseline for legacy pots
_GARDEN_KETTLE_ITEM = 1009          # 金水壶 (ItemID.GOLDEN_WATERING_CANS)
_GARDEN_KETTLE_SHOP_ID = 210        # MallItemTemplate.id; ShopCmd sends this, not itemID
_GARDEN_KETTLE_MAX = 10
_GARDEN_WATER_SECONDS = 3600


def load_garden_upgrades():
    """Return the client-configured pot levels keyed by target level.

    GardenUpgrade.txt uses one row for each level (row 1 is the level-1 base
    value).  The row's ``levelRequired`` and cost apply when upgrading *to*
    that level, while ``expBonus`` is the percentage multiplier used by the
    garden client when calculating hourly experience.
    """
    global _GARDEN_UPGRADES
    if _GARDEN_UPGRADES is None:
        _GARDEN_UPGRADES = {}
        rows = _read_clientdb_table("GardenUpgrade.txt")
        if rows:
            hdr = rows[0]; ci = {c: i for i, c in enumerate(hdr)}

            def col(row, key):
                i = ci.get(key)
                value = row[i] if i is not None and i < len(row) else "0"
                try:
                    return int(value)
                except (TypeError, ValueError):
                    return 0

            for row in rows[1:]:
                level = col(row, "id")
                if level > 0:
                    _GARDEN_UPGRADES[level] = {
                        "levelRequired": col(row, "levelRequired"),
                        "coin": max(0, col(row, "coin")),
                        "diamond": max(0, col(row, "diamond")),
                        "expBonus": max(10000, col(row, "expBonus") or 10000),
                        "needVIP": max(0, col(row, "needVIP")),
                    }
        log.info("loaded %d garden pot upgrade templates", len(_GARDEN_UPGRADES))
    return _GARDEN_UPGRADES


def load_garden_seeds():
    """{seedId: {type, itemid, time, plantid, desc}} from GardenSeed.txt."""
    global _GARDEN_SEEDS
    if _GARDEN_SEEDS is None:
        _GARDEN_SEEDS = {}
        rows = _read_clientdb_table("GardenSeed.txt")
        if rows:
            hdr = rows[0]; ci = {c: i for i, c in enumerate(hdr)}

            def col(c, k):
                i = ci.get(k)
                return c[i] if i is not None and i < len(c) else ""
            for c in rows[1:]:
                try:
                    sid = int(col(c, "id"))
                except ValueError:
                    continue
                _GARDEN_SEEDS[sid] = {
                    "type": int(col(c, "type") or 1), "itemid": int(col(c, "itemID") or 0),
                    "time": int(col(c, "time") or 60), "plantid": int(col(c, "plantID") or 0),
                    "desc": col(c, "desc")}
        log.info("loaded %d garden seeds", len(_GARDEN_SEEDS))
    return _GARDEN_SEEDS


def load_garden_fertilizers():
    """{fertilizerId: {expBuff, coin, diamond, itemID, needVIP}} from GardenFertilizer.txt.

    The Flash purchase dialog uses this exact table: ordinary fertilizer (1025) costs
    1000 coins, while the higher tiers use diamonds and/or VIP gating.
    """
    global _GARDEN_FERTILIZERS
    if _GARDEN_FERTILIZERS is None:
        _GARDEN_FERTILIZERS = {}
        rows = _read_clientdb_table("GardenFertilizer.txt")
        if rows:
            hdr = rows[0]; ci = {c: i for i, c in enumerate(hdr)}

            def col(row, key):
                i = ci.get(key)
                return int(row[i]) if i is not None and i < len(row) and str(row[i]).lstrip("-").isdigit() else 0

            for row in rows[1:]:
                try:
                    fid = int(row[ci["id"]])
                except (ValueError, KeyError, IndexError):
                    continue
                _GARDEN_FERTILIZERS[fid] = {
                    "expBuff": col(row, "expBuff"), "coin": col(row, "coin"),
                    "diamond": col(row, "diamond"), "itemID": col(row, "itemID") or fid,
                    "needVIP": col(row, "needVIP"),
                }
        log.info("loaded %d garden fertilizer templates", len(_GARDEN_FERTILIZERS))
    return _GARDEN_FERTILIZERS


_GARDEN_PETS = None
_GARDEN_ALL_PET_IDS = (1, 2, 3, 4, 5)
_GARDEN_PET_IDS = (2, 3, 4, 5)      # the 4 buyable pets shown in the pet house (id 1 = free base)


def load_garden_pets():
    """{petId: {trial, forever, unlock}} from GardenPet.txt (prices + 好感度 unlock threshold)."""
    global _GARDEN_PETS
    if _GARDEN_PETS is None:
        _GARDEN_PETS = {}
        rows = _read_clientdb_table("GardenPet.txt")
        if rows:
            hdr = rows[0]; ci = {c: i for i, c in enumerate(hdr)}

            def col(c, k):
                i = ci.get(k)
                return int(c[i]) if i is not None and i < len(c) and c[i].isdigit() else 0
            for c in rows[1:]:
                try:
                    pid = int(c[ci["id"]])
                except (ValueError, KeyError, IndexError):
                    continue
                _GARDEN_PETS[pid] = {
                    "trial": col(c, "priceTrial"), "forever": col(c, "priceForever"),
                    "unlock": col(c, "unlockExp"), "addExp": col(c, "addExp"),
                    "averagePercent": col(c, "averagePercent") or 100,
                }
    return _GARDEN_PETS


def _encode_garden_pet(pid, owned=False, used=False, forever=False, expire=0, start=0):
    """Dto_Pet{petid(1), owned(2), forever(3), expiretime(4), startworktime(5), inuse(6),
    dayprice(7), foreverprice(8)}. Prices come from GardenPet.txt so the shop renders real costs."""
    p = load_garden_pets().get(pid, {"trial": 0, "forever": 0})
    return (pb_varint_field(1, pid) + pb_varint_field(2, 1 if owned else 0)
            + pb_varint_field(3, 1 if forever else 0) + pb_varint_field(4, int(expire))
            + pb_varint_field(5, int(start)) + pb_varint_field(6, 1 if used else 0)
            + pb_varint_field(7, p["trial"]) + pb_varint_field(8, p["forever"]))


def _garden_pet_states(player, now=None):
    """Load the persisted pet ownership map and discard expired one-day pets.

    The original client keeps these values in its GardenProxy model, while the PoC
    previously sent a fresh un-owned DTO on every GetInfo.  Keep the small state map
    in the player row so purchases and the selected pet survive relogin.
    """
    if now is None:
        now = int(time.time())
    raw = player.get("garden_pet_data") or ""
    try:
        parsed = json.loads(raw) if raw else {}
    except (TypeError, ValueError):
        parsed = {}
    states = {}
    changed = not isinstance(parsed, dict)
    if isinstance(parsed, dict):
        for key, value in parsed.items():
            try:
                pid = int(key)
            except (TypeError, ValueError):
                continue
            if pid not in _GARDEN_ALL_PET_IDS or not isinstance(value, dict):
                continue
            state = {
                "owned": bool(value.get("owned", 0)),
                "forever": bool(value.get("forever", 0)),
                "expire": max(0, int(value.get("expire", 0) or 0)),
                "start": max(0, int(value.get("start", 0) or 0)),
                "used": bool(value.get("used", 0)),
            }
            if (not state["forever"] and state["expire"]
                    and state["expire"] <= now):
                changed = True
                continue
            states[pid] = state
            if value != state:
                changed = True
    if changed:
        _save_garden_pet_states(player, states)
    return states


def _save_garden_pet_states(player, states):
    """Persist only the fields represented by Dto_Pet."""
    clean = {}
    for pid, state in states.items():
        if pid not in _GARDEN_ALL_PET_IDS:
            continue
        clean[str(int(pid))] = {
            "owned": 1 if state.get("owned") else 0,
            "forever": 1 if state.get("forever") else 0,
            "expire": max(0, int(state.get("expire", 0) or 0)),
            "start": max(0, int(state.get("start", 0) or 0)),
            "used": 1 if state.get("used") else 0,
        }
    encoded = json.dumps(clean, ensure_ascii=False, separators=(",", ":"))
    player["garden_pet_data"] = encoded
    store.save_player(player["uin"], garden_pet_data=encoded)


def _garden_active_pet_id(player, now=None):
    """Return the currently selected, non-expired pet id (or 0)."""
    if now is None:
        now = int(time.time())
    states = _garden_pet_states(player, now)
    for pid, state in states.items():
        if not (state.get("owned") and state.get("used")):
            continue
        if state.get("forever") or int(state.get("expire", 0) or 0) > int(now):
            return int(pid)
    return 0


def _garden_pet_dtos(player, now=None):
    """Encode the free base pet plus all four buyable pets.

    Pet 1 is not shown in the pet-house cards, but the garden scene expects it as
    the free sleeping/default companion and sends UsePet(1) to wake it up.
    """
    if now is None:
        now = int(time.time())
    states = _garden_pet_states(player, now)
    paid_active = any(state.get("owned") and state.get("used")
                      for pid, state in states.items() if pid != 1)
    base = states.get(1, {})
    if paid_active:
        base_used = False
    else:
        # The free pet remains the selected companion while asleep; its zero expiry
        # makes the scene ask the server to wake it when clicked.
        base_used = True
    result = [_encode_garden_pet(
        1, owned=True, used=base_used, forever=False,
        expire=int(base.get("expire", 0) or 0),
        start=int(base.get("start", 0) or 0),
    )]
    result.extend([
        _encode_garden_pet(
            pid,
            owned=bool(states.get(pid, {}).get("owned")),
            used=bool(states.get(pid, {}).get("used")),
            forever=bool(states.get(pid, {}).get("forever")),
            expire=int(states.get(pid, {}).get("expire", 0) or 0),
            start=int(states.get(pid, {}).get("start", 0) or 0),
        )
        for pid in _GARDEN_PET_IDS
    ])
    return result


def load_garden_unlock():
    """{fieldId: levelRequired} from GardenUnlock.txt (fields 1-4 are free)."""
    global _GARDEN_UNLOCK
    if _GARDEN_UNLOCK is None:
        _GARDEN_UNLOCK = {}
        rows = _read_clientdb_table("GardenUnlock.txt")
        if rows:
            hdr = rows[0]; ci = {c: i for i, c in enumerate(hdr)}
            for c in rows[1:]:
                try:
                    _GARDEN_UNLOCK[int(c[ci["id"]])] = int(c[ci["levelRequired"]])
                except (ValueError, KeyError, IndexError):
                    pass
    return _GARDEN_UNLOCK


def ensure_garden(player):
    """Unlock every garden field whose levelRequired <= the player's level (coin cost waived for
    the single-player sandbox), so pots open up as you level. Returns the {field:(seed,time)} map."""
    level = int(player.get("level", 1))
    have = store.get_garden_pots(player["uin"])
    for fid, need in load_garden_unlock().items():
        if fid not in have and need <= level:
            store.unlock_garden_field(player["uin"], fid)
    return store.get_garden_pots(player["uin"])


def _garden_crop_reward(desc):
    """Parse a type-2 crop's harvest reward from its desc -> (itemId, num). 金币->coin, 钻石->gift
    diamond, 合金元素->armor mat; 土壤 (soil, no bag item) -> a token coin amount."""
    m = re.search(r"(\d+)", desc or "")
    n = int(m.group(1)) if m else 0
    if "金币" in desc:
        return (1, n)                    # coin
    if "钻石" in desc:
        return (4, max(1, n))            # gift diamond
    if "合金元素" in desc:
        return (40003, max(1, n))        # armor material
    if "土壤" in desc:
        return (1, n * 100)              # soil has no bag item -> small coin payout
    return (1, n)


_GARDEN_SEED_TYPE_COLOR = 1        # E_Garden_SeedType.SevenColor / GardenGlobal.SEED_TYPE_COLOR
_GARDEN_SEED_TYPE_ITEM = 2         # E_Garden_SeedType.Item        / GardenGlobal.SEED_TYPE_ITEM

# One-time starter crop seeds (bag items, subType 232) so the seed picker isn't empty and the
# crop -> coins path is testable: 坚果 (fast 30s test), 胡萝卜 (100k coin), 蒲公英 (200k coin).
_GARDEN_STARTER_SEEDS = [(1041, 5), (1045, 5), (1046, 3)]


def _garden_seven_color_seed():
    """The seed id to store for a seven-color sunflower (any type-1 seed; they're identical:
    time 20, plantID 1101, 12 exp / cycle). Seeds 1-7 are the seven colours."""
    return min((sid for sid, s in load_garden_seeds().items() if s["type"] == 1), default=1)


def _garden_seed_by_itemid(itemid):
    """The crop seed id whose GardenSeed.itemID == the planted bag item (type-2 crops)."""
    for sid, s in load_garden_seeds().items():
        if s["type"] == _GARDEN_SEED_TYPE_ITEM and s["itemid"] == int(itemid or 0):
            return sid
    return 0


def _garden_fertilizer_state(seed_id, plant_time, now, fertilizer_id=0, last_fertilizer_time=0):
    """Normalize the persisted fertilizer fields for one pot.

    Old saves predate fertilizer columns.  Treat their sunflower pots as having
    ordinary fertilizer from planting, so adding this system does not suddenly
    erase an already-growing garden.  New pots still get the same one-timeslot
    baseline and can be upgraded by explicitly applying another fertilizer.
    """
    seed = load_garden_seeds().get(int(seed_id or 0))
    if not seed or seed["type"] != _GARDEN_SEED_TYPE_COLOR:
        return int(fertilizer_id or 0), int(last_fertilizer_time or 0), False
    fid = int(fertilizer_id or 0) or _GARDEN_DEFAULT_FERTILIZER
    last = int(last_fertilizer_time or 0) or int(plant_time or 0)
    need = not last or int(now) >= last + _GARDEN_FERTILIZER_TIME
    return fid, last, need


def _garden_pending_exp(seed, plant_time, now, pet_id=0, fertilizer_id=0,
                        last_fertilizer_time=0, pot_level=1):
    """Whole-cycle exp a sunflower pot has produced since plant_time (capped).

    A selected pet automatically collects the experience balls.  The clientDB pet
    template expresses its average critical multiplier and its fixed per-pickup
    bonus; applying both here makes the pet useful beyond just changing the card art.
    """
    if not plant_time:
        return 0
    seed_id = int(seed.get("id") or (1 if seed.get("type") == _GARDEN_SEED_TYPE_COLOR else 0))
    fertilizer_id, last_fertilizer_time, need_fertilizer = _garden_fertilizer_state(
        seed_id, plant_time, now, fertilizer_id, last_fertilizer_time)
    if need_fertilizer:
        return 0
    period = max(1, seed["time"])
    cycles = min((now - int(plant_time)) // period, _GARDEN_MAX_IDLE_CYCLES)
    cycles = max(0, cycles)
    per_cycle = _GARDEN_SUNFLOWER_EXP
    upgrade = load_garden_upgrades().get(max(1, int(pot_level or 1)))
    if upgrade:
        per_cycle = (per_cycle * int(upgrade.get("expBonus") or 10000)) // 10000
    fertilizer = load_garden_fertilizers().get(int(fertilizer_id), {})
    # GardenUtils.getFertilizerPercent() divides expBuff by 100; the final
    # getTotalExp() divides that percentage by 100 again.  Thus 10000 = 1x,
    # 15000 = 1.5x, 25000 = 2.5x.
    exp_buff = max(10000, int(fertilizer.get("expBuff") or 10000))
    per_cycle = (per_cycle * exp_buff) // 10000
    pet = load_garden_pets().get(int(pet_id or 0))
    if pet:
        per_cycle = (per_cycle * max(100, int(pet.get("averagePercent") or 100))) // 100
        per_cycle += max(0, int(pet.get("addExp") or 0))
    return cycles * per_cycle


def _encode_garden_pot(seed_id, plant_time, now, pet_id=0, fertilizer_id=0,
                       last_fertilizer_time=0, level=1):
    """Dto_Pot{level(1), issevencolor(2), seedid(3), planttime(4), nextharvesttime(5),
    lastfertilizetime(6), needfertilize(7), fertilizerid(8), exp(9), bigball(11)}.
    An empty pot (seed_id=0) is just level=1.

    For a seven-color sunflower nextharvesttime = plant_time + cycle: once it's in the past the
    client shows an exp ball whose roll-over fires Cmd_Garden_Harvest_CS (banking the pot's
    accrued exp into the garden pool). needfertilize=0 + a SevenColor seed are what make the
    client's '+N经验/时' rate (getTotalExpByPotVO) non-zero. For a crop it's the maturity clock."""
    level = max(1, int(level or 1))
    d = pb_varint_field(1, level)                           # level
    if not seed_id:
        return d
    seed = load_garden_seeds().get(seed_id, {"id": seed_id, "type": 1, "time": 60})
    is_sun = seed["type"] == _GARDEN_SEED_TYPE_COLOR
    if is_sun:
        d += pb_varint_field(2, 1)                         # issevencolor
    d += pb_varint_field(3, seed_id) + pb_varint_field(4, int(plant_time))
    d += pb_varint_field(5, int(plant_time) + seed["time"])   # nextharvesttime
    fert_id, fert_time, need = _garden_fertilizer_state(
        seed_id, plant_time, now, fertilizer_id, last_fertilizer_time)
    d += pb_varint_field(6, fert_time)                         # lastfertilizetime
    d += pb_bool(7, need)                                      # needfertilize
    if fert_id:
        d += pb_varint_field(8, fert_id)                       # fertilizerid
    if is_sun:
        d += pb_varint_field(9, _garden_pending_exp(
            dict(seed, id=seed_id), plant_time, now, pet_id, fert_id, fert_time, level))   # pending exp
        d += pb_bool(11, False)                               # bigball (non-null for the client)
    return d


def _garden_fields_blob(player, now):
    """The repeated Dto_Field(1)=[fieldid(1), pot(2)] portion — identical in the GetInfo and Sync
    messages (only the exp/bean field NUMBERS differ between them)."""
    d = b""
    pet_id = _garden_active_pet_id(player, now)
    details = store.get_garden_pot_details(player["uin"])
    for fid, row in sorted(details.items()):
        pot = _encode_garden_pot(row["seed_id"], row["plant_time"], now, pet_id,
                                 row.get("fertilizer_id", 0), row.get("last_fertilizer_time", 0),
                                 row.get("level", 1))
        field = pb_varint_field(1, fid) + pb_tag(2, 2) + uvarint(len(pot)) + pot   # Dto_Field{fieldid, pot}
        d += pb_tag(1, 2) + uvarint(len(field)) + field                            # fields (repeated)
    return d


def _garden_field_dto(player, field_id, now):
    """Encode one Dto_Field for the garden action responses."""
    row = store.get_garden_pot_details(player["uin"]).get(int(field_id))
    if row is None:
        return b""
    pot = _encode_garden_pot(row["seed_id"], row["plant_time"], now,
                             _garden_active_pet_id(player, now),
                             row.get("fertilizer_id", 0), row.get("last_fertilizer_time", 0),
                             row.get("level", 1))
    return pb_varint_field(1, int(field_id)) + pb_tag(2, 2) + uvarint(len(pot)) + pot


def _garden_refresh_kettle(player):
    """Reset the ten watering uses when the calendar day changes."""
    today = time.strftime("%Y%m%d")
    if str(player.get("garden_kettle_day") or "") != today:
        player["garden_kettle_day"] = today
        player["garden_kettlelimit"] = _GARDEN_KETTLE_MAX
        store.save_player(player["uin"], garden_kettle_day=today,
                          garden_kettlelimit=_GARDEN_KETTLE_MAX)
    return max(0, int(player.get("garden_kettlelimit") or 0))


def make_garden_getinfo(player, now):
    """Cmd_Garden_GetInfo_SC {fields(1), exp(2), bean(3), pets(4)=[Dto_Pet], petExp(8)=好感度}. The
    garden exp POOL (banked via per-pot harvest) drives the bar: exp = pool % 10000 (progress),
    bean = pool // 10000 (whole 小经验豆). We also send the 4 buyable pets (so the pet house opens
    without a null-crash) and the 好感度 goodwill total that gates them."""
    kettle = _garden_refresh_kettle(player)
    pool = int(player.get("garden_exp") or 0)
    d = (_garden_fields_blob(player, now)
         + pb_varint_field(2, pool % _GARDEN_BEAN_EXP)      # bar progress toward next bean
         + pb_varint_field(3, pool // _GARDEN_BEAN_EXP))    # whole beans waiting to be taken
    for pet in _garden_pet_dtos(player, now):                # pets(4) — prices + ownership state
        d += pb_tag(4, 2) + uvarint(len(pet)) + pet
    d += pb_varint_field(8, int(player.get("garden_goodwill") or 0))   # petExp = 好感度 goodwill
    # The client treats field 5 as the currently selected fertilizer even when
    # auto-use is off.  Older saves contain zero here, which made the fertilizer
    # bar select nothing and caused manual use to send fertilizerid=0 forever.
    selected_fertilizer = int(player.get("garden_autofertilizer") or _GARDEN_DEFAULT_FERTILIZER)
    d += (pb_varint_field(5, selected_fertilizer)
          + pb_bool(6, bool(player.get("garden_autouse")))
          + pb_varint_field(7, kettle))
    return d


def _garden_sync(player, now):
    """A Cmd_Sync_Garden_Info_SC push so the exp bar / pots refresh LIVE after a plant/harvest/
    takebean (not only on garden re-entry). NOTE its field NUMBERS differ from GetInfo:
    fields(1), pets(2), exp(3), bean(4) — so exp/bean go at 3/4, not 2/3."""
    kettle = _garden_refresh_kettle(player)
    pool = int(player.get("garden_exp") or 0)
    body = _garden_fields_blob(player, now)
    for pet in _garden_pet_dtos(player, now):
        body += pb_tag(2, 2) + uvarint(len(pet)) + pet
    body += (pb_varint_field(3, pool % _GARDEN_BEAN_EXP)
             + pb_varint_field(4, pool // _GARDEN_BEAN_EXP)
             + pb_varint_field(8, int(player.get("garden_goodwill") or 0))
             + pb_varint_field(5, int(player.get("garden_autofertilizer") or _GARDEN_DEFAULT_FERTILIZER))
             + pb_bool(6, bool(player.get("garden_autouse")))
             + pb_varint_field(7, kettle))
    return ("PVZ.Cmd.Cmd_Sync_Garden_Info_SC", body)


def handle_garden_getinfo(cmd_data, player):
    """Cmd_Garden_GetInfo_CS -> the whole garden (unlocking new pots for the player's level, and
    handing out the one-time starter crop seeds so the seed picker has crops to plant)."""
    ensure_garden(player)
    now = int(time.time())
    extra = []
    if not int(player.get("garden_seeds_granted") or 0):
        upd = grant_items(player, _GARDEN_STARTER_SEEDS)
        player["garden_seeds_granted"] = 1
        store.save_player(player["uin"], garden_seeds_granted=1)
        if upd:
            extra.append(upd)
        log.info("    garden: granted starter crop seeds to uin=%s", player["uin"])
    pool = int(player.get("garden_exp") or 0)
    log.info("    garden: %d pots, pool=%d exp(bar)=%d beans=%d",
             len(store.get_garden_pots(player["uin"])), pool, pool % _GARDEN_BEAN_EXP, pool // _GARDEN_BEAN_EXP)
    return [("PVZ.Cmd.Cmd_Garden_GetInfo_SC", make_garden_getinfo(player, now))] + extra


def handle_garden_plant(cmd_data, player):
    """Cmd_Garden_Plant_CS{fieldid(1), seedtype(2), itemid(3)} -> plant a seed. seedtype is a
    TYPE, not a seed id: 1=seven-color sunflower (the exp producer, from the always-present colour
    slot), 2=a crop chosen by its bag itemid. Reply Cmd_Garden_Plant_SC{field(3)=Dto_Field} plus a
    Sync so the pot shows up immediately."""
    f = parse_varint_fields(cmd_data)
    fid, seedtype, itemid = f.get(1, 0), f.get(2, 0), f.get(3, 0)
    now = int(time.time())
    if fid not in store.get_garden_pots(player["uin"]):
        return []                                            # field locked / nonexistent
    consume = None
    if seedtype == _GARDEN_SEED_TYPE_ITEM:
        seed_id = _garden_seed_by_itemid(itemid)
        if not seed_id or store.get_item_count(player["uin"], itemid) <= 0:
            return []                                        # unknown / unowned crop seed item
        consume = grant_items(player, [(itemid, -1)])        # planting a crop uses one seed
    else:                                                    # SEED_TYPE_COLOR (or default)
        seed_id = _garden_seven_color_seed()
    store.set_garden_pot(player["uin"], fid, seed_id, now)
    # Keep the historical garden behavior (a newly planted sunflower starts
    # producing immediately at the ordinary 1x rate), while honoring the
    # client's optional automatic fertilizer setting when the selected item is
    # actually in the bag.
    planted_fertilizer = 0
    planted_fertilizer_time = 0
    if load_garden_seeds().get(seed_id, {}).get("type") == _GARDEN_SEED_TYPE_COLOR:
        planted_fertilizer = _GARDEN_DEFAULT_FERTILIZER
        planted_fertilizer_time = now
        selected = int(player.get("garden_autofertilizer") or 0)
        if bool(player.get("garden_autouse")) and selected in load_garden_fertilizers():
            selected_tpl = load_garden_fertilizers()[selected]
            selected_item = int(selected_tpl.get("itemID") or selected)
            if store.get_item_count(player["uin"], selected_item) > 0:
                selected_consume = grant_items(player, [(selected_item, -1)])
                if selected_consume:
                    consume = [consume, selected_consume] if consume else selected_consume
                planted_fertilizer = selected
        store.update_garden_pot_meta(player["uin"], fid, planted_fertilizer, planted_fertilizer_time)
    pot_level = store.get_garden_pot_details(player["uin"]).get(fid, {}).get("level", 1)
    pot = _encode_garden_pot(seed_id, now, now, 0, planted_fertilizer,
                             planted_fertilizer_time, pot_level)
    field = pb_varint_field(1, fid) + pb_tag(2, 2) + uvarint(len(pot)) + pot
    plant_sc = pb_tag(3, 2) + uvarint(len(field)) + field    # Cmd_Garden_Plant_SC.field(3)
    log.info("    garden plant: field %d seed %d (seedtype %d itemid %d)", fid, seed_id, seedtype, itemid)
    msgs = [("PVZ.Cmd.Cmd_Garden_Plant_SC", plant_sc), _garden_sync(player, now)]
    if consume:
        if isinstance(consume, list):
            msgs.extend(consume)
        else:
            msgs.append(consume)
    msgs += _quest_record_condition(player, 48, 0, 1)
    return msgs


def handle_garden_harvest(cmd_data, player):
    """Harvest one or more pots.

    Manual clicks send repeated ``fieldid`` values.  The pet's 20-second timer
    calls the same command with *no* ids, which means "collect every ready pot".
    The old handler read a single varint and returned nothing for that empty
    request, so the pet animation ran but no experience was ever banked.
    """
    requested = parse_repeated_varint(cmd_data, 1)
    now = int(time.time())
    pots = store.get_garden_pots(player["uin"])
    uin = player["uin"]
    grant_msgs = []
    details = store.get_garden_pot_details(uin)
    if requested:
        field_ids = list(dict.fromkeys(int(fid) for fid in requested if int(fid) in pots))
    else:
        # Empty fieldid list is the protocol used by the pet auto-collector.
        field_ids = sorted(pots)
    result_blob = b""
    harvested = 0
    pet_id = _garden_active_pet_id(player, now)
    for fid in field_ids:
        seed_id, plant_time = pots[fid]
        seed = load_garden_seeds().get(seed_id)
        if not seed_id or not seed:
            continue
        meta = details.get(fid, {})
        result = pb_varint_field(1, fid) + pb_varint_field(2, seed["type"])
        if seed["type"] == _GARDEN_SEED_TYPE_COLOR:
            exp_gain = _garden_pending_exp(
                dict(seed, id=seed_id), plant_time, now, pet_id,
                meta.get("fertilizer_id", 0), meta.get("last_fertilizer_time", 0),
                meta.get("level", 1))
            if exp_gain <= 0:
                continue
            player["garden_exp"] = int(player.get("garden_exp") or 0) + exp_gain
            player["garden_goodwill"] = int(player.get("garden_goodwill") or 0) + exp_gain
            # A sunflower keeps its fertilizer tier but starts a fresh 4-hour
            # fertilizer window after each collection, matching the client timer.
            store.set_garden_pot(uin, fid, seed_id, now)
            store.update_garden_pot_meta(uin, fid,
                                         meta.get("fertilizer_id") or _GARDEN_DEFAULT_FERTILIZER,
                                         now)
            result += pb_varint_field(3, exp_gain) + pb_varint_field(4, 1)
            log.info("    garden harvest: field %d sunflower +%d exp (pool=%d, goodwill=%d)",
                     fid, exp_gain, player["garden_exp"], player["garden_goodwill"])
        else:
            if now < int(plant_time) + seed["time"]:
                continue
            item_id, num = _garden_crop_reward(seed["desc"])
            grant_msgs.extend(grant_fuben_reward(player, [(item_id, num)]))
            store.set_garden_pot(uin, fid, 0, 0)
            item = pb_varint_field(1, item_id) + pb_varint_field(2, num)
            result += pb_tag(5, 2) + uvarint(len(item)) + item
            log.info("    garden harvest: field %d crop -> item %d x%d", fid, item_id, num)
        result_blob += pb_tag(1, 2) + uvarint(len(result)) + result
        harvested += 1
    if harvested:
        store.save_player(uin, garden_exp=player["garden_exp"],
                          garden_goodwill=player["garden_goodwill"])
    # Always acknowledge an empty pet sweep.  The client treats an empty result
    # as a normal tick and remains ready for the next 20-second interval.
    return [("PVZ.Cmd.Cmd_Garden_Harvest_SC", result_blob), _garden_sync(player, now)] + grant_msgs


def handle_garden_takebean(cmd_data, player):
    """Cmd_Garden_TakeBean_CS -> move the whole beans sitting in the pool (pool // 10000) into the
    bag as 小经验豆 (item 2002); keep the remainder as the bar progress. Reply
    Cmd_Garden_TakeBean_SC{beannum(1)=beans taken, exp(2)=remaining} + a Sync to refresh."""
    uin = player["uin"]
    now = int(time.time())
    pool = int(player.get("garden_exp") or 0)
    beans = pool // _GARDEN_BEAN_EXP
    grant_msgs = []
    if beans > 0:
        player["garden_exp"] = pool - beans * _GARDEN_BEAN_EXP
        store.save_player(uin, garden_exp=player["garden_exp"])
        grant_msgs = grant_fuben_reward(player, [(_GARDEN_EXP_BEAN_ITEM, beans)])
    remainder = int(player.get("garden_exp") or 0)
    log.info("    garden takebean: %d beans (exp left %d)", beans, remainder)
    body = pb_varint_field(1, beans) + pb_varint_field(2, remainder)
    return [("PVZ.Cmd.Cmd_Garden_TakeBean_SC", body), _garden_sync(player, now)] + grant_msgs


def _garden_speed_price(remaining):
    """Diamonds to instantly finish `remaining` seconds — mirrors GardenUtils.getSpeedPrice: 1 per
    started 10 min under 4h, then 2 per started hour beyond."""
    if remaining <= 0:
        return 0
    if remaining < 14400:
        return -(-remaining // 600)                          # ceil(remaining / 600)
    return 24 + -(-(remaining - 14400) // 3600) * 2          # 14400/600 + ceil(rest/3600)*2


def _spend_diamonds(player, cost):
    """Spend `cost` diamonds, gift (present_ticket) first then gold (ticket) — the standard order,
    preserving paid currency. Returns the HUD sync messages, or None if the player can't afford it."""
    if cost <= 0:
        return []
    gift, gold = int(player.get("present_ticket") or 0), int(player.get("ticket") or 0)
    if gift + gold < cost:
        return None                                          # client normally blocks this
    msgs = []
    from_gift = min(gift, cost)
    if from_gift:
        player["present_ticket"] = gift - from_gift
        store.save_player(player["uin"], present_ticket=player["present_ticket"])
        msgs.append(("PVZ.Cmd.Cmd_SyncPresentTicket_SC", pb_varint_field(1, player["present_ticket"])))
    from_gold = cost - from_gift
    if from_gold:
        player["ticket"] = gold - from_gold
        store.save_player(player["uin"], ticket=player["ticket"])
        msgs.append(("PVZ.Cmd.Cmd_SyncTicket_SC", pb_varint_field(1, player["ticket"])))
    return msgs


def _garden_coin_sync(player):
    return ("PVZ.Cmd.Cmd_SyncCoin_SC", pb_varint_field(1, int(player.get("coin") or 0)))


def handle_garden_buyfertilizer(cmd_data, player):
    """Buy stackable garden fertilizer from the clientDB price table."""
    f = parse_varint_fields(cmd_data)
    fertilizer_id = int(f.get(1, 0) or 0)
    amount = max(1, min(100, int(f.get(2, 1) or 1)))
    tpl = load_garden_fertilizers().get(fertilizer_id)
    if not tpl:
        return []
    need_vip = int(tpl.get("needVIP") or 0)
    if int(player.get("vip_level") or 0) < need_vip:
        log.info("    garden fertilizer buy rejected: id=%d needs VIP%d", fertilizer_id, need_vip)
        return []
    item_id = int(tpl.get("itemID") or fertilizer_id)
    if int(tpl.get("diamond") or 0) > 0:
        price = int(tpl["diamond"]) * amount
        charge = _spend_diamonds(player, price)
        if charge is None:
            return []
    else:
        price = int(tpl.get("coin") or 0) * amount
        if int(player.get("coin") or 0) < price:
            return []
        player["coin"] = int(player.get("coin") or 0) - price
        store.save_player(player["uin"], coin=player["coin"])
        charge = [_garden_coin_sync(player)] if price else []
    item_update = grant_items(player, [(item_id, amount)])
    total = store.get_item_count(player["uin"], item_id)
    body = (pb_varint_field(1, fertilizer_id) + pb_varint_field(2, amount)
            + pb_varint_field(3, total))
    log.info("    garden fertilizer buy: id=%d item=%d x%d price=%d", fertilizer_id, item_id, amount, price)
    msgs = [("PVZ.Cmd.Cmd_Garden_BuyFertilizer_SC", body)]
    if item_update:
        msgs.append(item_update)
    return msgs + charge


_MALL_CATALOG = None


def mall_catalog():
    """Available shopId -> item, price and wallet from the served clientDB."""
    global _MALL_CATALOG
    if _MALL_CATALOG is None:
        rows = _read_clientdb_table("MallItemTemplate.txt")
        catalog = {}
        if rows:
            ci = {name: index for index, name in enumerate(rows[0])}
            required = {"id", "itemID", "price", "useGold", "needVIP"}
            if required.issubset(ci):
                for row in rows[1:]:
                    try:
                        shop_id = int(row[ci["id"]])
                        item_id = int(row[ci["itemID"]])
                        price = int(row[ci["price"]])
                        gold_only = int(row[ci["useGold"]]) != 0
                        need_vip = int(row[ci["needVIP"]])
                    except (ValueError, IndexError):
                        continue
                    if shop_id > 0 and item_id > 0 and price >= 0:
                        catalog[shop_id] = (item_id, price, gold_only, need_vip)
        _MALL_CATALOG = catalog
    return _MALL_CATALOG


def handle_shop_getlist(cmd_data, player):
    """The shop filters every tab by these ids; an absent reply leaves it empty."""
    body = b"".join(pb_varint_field(1, shop_id) for shop_id in sorted(mall_catalog()))
    return [("PVZ.Cmd.Cmd_Shop_GetList_SC", body)]


def handle_shop_buyitem(cmd_data, player):
    """Buy a catalog item using the exact clientDB price and currency rule."""
    f = parse_varint_fields(cmd_data)
    requested_id = int(f.get(1, 0) or 0)
    amount = int(f.get(2, 1) or 0)
    if not 1 <= amount <= 1000:
        return []
    catalog = mall_catalog()
    shop_id = requested_id
    # Older callers occasionally supply the garden kettle's item id directly.
    if shop_id == _GARDEN_KETTLE_ITEM:
        shop_id = _GARDEN_KETTLE_SHOP_ID
    entry = catalog.get(shop_id)
    if entry is None:
        return []
    item_id, unit_price, gold_only, need_vip = entry
    if int(player.get("vip_level") or 0) < need_vip:
        return []
    price = unit_price * amount
    with store._db() as con:
        con.execute("BEGIN IMMEDIATE")
        row = con.execute("SELECT present_ticket,ticket FROM players WHERE uin=?",
                          (player["uin"],)).fetchone()
        if row is None:
            return []
        gift, gold = int(row["present_ticket"]), int(row["ticket"])
        if gold_only:
            if gold < price:
                return []
            gift_cost, gold_cost = 0, price
        else:
            if gift + gold < price:
                return []
            gift_cost = min(gift, price)
            gold_cost = price - gift_cost
        if price:
            con.execute("UPDATE players SET present_ticket=present_ticket-?, "
                        "ticket=ticket-? WHERE uin=?",
                        (gift_cost, gold_cost, player["uin"]))
        con.execute("INSERT INTO items(uin,item_id,count) VALUES(?,?,?) "
                    "ON CONFLICT(uin,item_id) DO UPDATE SET count=count+excluded.count",
                    (player["uin"], item_id, amount))
        total = con.execute("SELECT count FROM items WHERE uin=? AND item_id=?",
                            (player["uin"], item_id)).fetchone()["count"]
    player["present_ticket"] = gift - gift_cost
    player["ticket"] = gold - gold_cost
    dto = build_item_dto(item_id, total)
    messages = [("PVZ.Cmd.Cmd_Shop_BuyItem_SC", pb_varint_field(1, requested_id)),
                ("PVZ.Cmd.Cmd_Item_Update_SC", pb_tag(1, 2) + uvarint(len(dto)) + dto)]
    if gift_cost:
        messages.append(("PVZ.Cmd.Cmd_SyncPresentTicket_SC",
                         pb_varint_field(1, player["present_ticket"])))
    if gold_cost:
        messages.append(("PVZ.Cmd.Cmd_SyncTicket_SC",
                         pb_varint_field(1, player["ticket"])))
    log.info("    shop buy: shopId=%d item=%d x%d price=%d gold_only=%s",
             shop_id, item_id, amount, price, gold_only)
    return messages


def handle_garden_fertilize(cmd_data, player):
    """Consume one fertilizer and apply its four-hour multiplier to a sunflower pot."""
    f = parse_varint_fields(cmd_data)
    field_id, fertilizer_id = int(f.get(1, 0) or 0), int(f.get(2, 0) or 0)
    now = int(time.time())
    pots = store.get_garden_pots(player["uin"])
    row = store.get_garden_pot_details(player["uin"]).get(field_id)
    seed_id, plant_time = pots.get(field_id, (0, 0))
    tpl = load_garden_fertilizers().get(fertilizer_id)
    if not row or not seed_id or load_garden_seeds().get(seed_id, {}).get("type") != _GARDEN_SEED_TYPE_COLOR or not tpl:
        return []
    item_id = int(tpl.get("itemID") or fertilizer_id)
    if store.get_item_count(player["uin"], item_id) <= 0:
        return []
    consume = grant_items(player, [(item_id, -1)])
    store.update_garden_pot_meta(player["uin"], field_id, fertilizer_id, now)
    field = _garden_field_dto(player, field_id, now)
    body = (pb_varint_field(1, field_id)
            + (pb_tag(2, 2) + uvarint(len(field)) + field if field else b""))
    log.info("    garden fertilize: field=%d fertilizer=%d", field_id, fertilizer_id)
    msgs = [("PVZ.Cmd.Cmd_Garden_Fertilize_SC", body), _garden_sync(player, now)]
    if consume:
        msgs.append(consume)
    msgs += _quest_record_condition(player, 49, 0, 1)
    return msgs


def handle_garden_autousefertilizer(cmd_data, player):
    """Persist the fertilizer selected by the auto-use checkbox."""
    f = parse_varint_fields(cmd_data)
    auto = bool(f.get(1, 0))
    fertilizer_id = int(f.get(2, 0) or 0)
    if fertilizer_id and fertilizer_id not in load_garden_fertilizers():
        return []
    player["garden_autouse"] = 1 if auto else 0
    # Selecting a fertilizer while the checkbox is off is still a real
    # selection: the next manual fertilize click uses this id.  Do not clear it
    # merely because auto-use was disabled.
    if fertilizer_id:
        player["garden_autofertilizer"] = fertilizer_id
    elif not int(player.get("garden_autofertilizer") or 0):
        player["garden_autofertilizer"] = _GARDEN_DEFAULT_FERTILIZER
    store.save_player(player["uin"], garden_autouse=player["garden_autouse"],
                      garden_autofertilizer=player["garden_autofertilizer"])
    body = pb_bool(1, auto) + pb_varint_field(2, player["garden_autofertilizer"])
    return [("PVZ.Cmd.Cmd_Garden_AutoUseFertilizer_SC", body), _garden_sync(player, int(time.time()))]


def handle_garden_potuplevel(cmd_data, player):
    """Upgrade one garden pot using GardenUpgrade.txt's target-level row.

    The Flash client only sends ``fieldid`` and expects both the upgraded
    ``Dto_Field`` and a garden sync.  Persisting the level in the pot row is
    important: otherwise a relogin (or a later fertilize/water response) would
    silently render every pot back at Lv1.
    """
    field_id = int(parse_varint_fields(cmd_data).get(1, 0) or 0)
    details = store.get_garden_pot_details(player["uin"])
    row = details.get(field_id)
    if not row:
        return []
    current = max(1, int(row.get("level", 1) or 1))
    target = current + 1
    template = load_garden_upgrades().get(target)
    if not template:
        log.info("    garden pot upgrade rejected: field=%d already at max level=%d", field_id, current)
        return []
    role_level = int(player.get("level") or 1)
    need_level = int(template.get("levelRequired") or 0)
    need_vip = int(template.get("needVIP") or 0)
    if role_level < need_level or int(player.get("vip_level") or 0) < need_vip:
        log.info("    garden pot upgrade rejected: field=%d target=%d needs level=%d/vip=%d (have level=%d/vip=%d)",
                 field_id, target, need_level, need_vip, role_level, int(player.get("vip_level") or 0))
        return []
    coin_cost = int(template.get("coin") or 0)
    diamond_cost = int(template.get("diamond") or 0)
    if coin_cost:
        if int(player.get("coin") or 0) < coin_cost:
            return []
        player["coin"] = int(player.get("coin") or 0) - coin_cost
        store.save_player(player["uin"], coin=player["coin"])
        money_msgs = [_garden_coin_sync(player)]
    else:
        money_msgs = _spend_diamonds(player, diamond_cost) if diamond_cost else []
        if money_msgs is None:
            return []
    store.update_garden_pot_level(player["uin"], field_id, target)
    now = int(time.time())
    field = _garden_field_dto(player, field_id, now)
    body = (pb_varint_field(1, field_id)
            + (pb_tag(2, 2) + uvarint(len(field)) + field if field else b""))
    log.info("    garden pot upgraded: field=%d level=%d->%d coin=%d diamond=%d",
             field_id, current, target, coin_cost, diamond_cost)
    return [("PVZ.Cmd.Cmd_Garden_PotUpLevel_SC", body), _garden_sync(player, now)] + money_msgs


def handle_garden_water(cmd_data, player):
    """Use one golden watering can and advance the selected plant by one hour."""
    field_id = int(parse_varint_fields(cmd_data).get(1, 0) or 0)
    now = int(time.time())
    left = _garden_refresh_kettle(player)
    pots = store.get_garden_pots(player["uin"])
    if field_id not in pots or not pots[field_id][0] or left <= 0:
        return []
    if store.get_item_count(player["uin"], _GARDEN_KETTLE_ITEM) <= 0:
        return []
    seed_id, plant_time = pots[field_id]
    consume = grant_items(player, [(_GARDEN_KETTLE_ITEM, -1)])
    # The original UI describes the can as one hour of acceleration.  Moving
    # plant_time backwards preserves all existing crop/sunflower timing logic.
    store.set_garden_pot(player["uin"], field_id, seed_id,
                         max(0, int(plant_time) - _GARDEN_WATER_SECONDS))
    player["garden_kettlelimit"] = left - 1
    store.save_player(player["uin"], garden_kettlelimit=player["garden_kettlelimit"])
    field = _garden_field_dto(player, field_id, now)
    body = (pb_varint_field(1, field_id)
            + (pb_tag(2, 2) + uvarint(len(field)) + field if field else b""))
    log.info("    garden water: field=%d remaining=%d", field_id, player["garden_kettlelimit"])
    msgs = [("PVZ.Cmd.Cmd_Garden_Water_SC", body), _garden_sync(player, now)]
    if consume:
        msgs.append(consume)
    msgs += _quest_record_condition(player, 52, 0, 1)
    return msgs


def handle_garden_speedup(cmd_data, player):
    """Cmd_Garden_TicketSpeedUp_CS{fieldid} -> spend diamonds to instantly mature a growing crop.
    We charge the same getSpeedPrice the client's confirm dialog showed (gift diamonds first, then
    gold), backdate plant_time so it's ripe, and reply Cmd_Garden_TicketSpeedUp_SC{fieldid(1),
    result(2)=1} + a Sync (pot flips to 'reward ready') + the diamond HUD syncs. (Sunflowers have no
    maturity clock, so this only applies to crops.)"""
    fid = parse_varint_fields(cmd_data).get(1, 0)
    now = int(time.time())
    pots = store.get_garden_pots(player["uin"])
    if fid not in pots:
        return []
    seed_id, plant_time = pots[fid]
    seed = load_garden_seeds().get(seed_id)
    if not seed_id or not seed or seed["type"] != _GARDEN_SEED_TYPE_ITEM:
        return []                                            # empty pot or a sunflower (no timer)
    remaining = int(plant_time) + seed["time"] - now
    if remaining <= 0:
        return []                                            # already mature — nothing to speed up
    diamond_msgs = _spend_diamonds(player, _garden_speed_price(remaining))
    if diamond_msgs is None:
        return []                                            # can't afford (client should've blocked)
    store.set_garden_pot(player["uin"], fid, seed_id, now - seed["time"])   # backdate -> mature now
    log.info("    garden speedup: field %d crop matured (-%d diamonds)", fid, _garden_speed_price(remaining))
    body = pb_varint_field(1, fid) + pb_varint_field(2, 1)   # fieldid, result=success
    return [("PVZ.Cmd.Cmd_Garden_TicketSpeedUp_SC", body), _garden_sync(player, now)] + diamond_msgs


def handle_garden_dig(cmd_data, player):
    """Cmd_Garden_DigPlant_CS{fieldid} -> shovel up whatever's planted, leaving an empty (plantable)
    pot. Reply Cmd_Garden_DigPlant_SC{fieldid(1), field(2)=Dto_Field} + a Sync so the pot re-renders
    with the 'click to plant' prompt. (The dug seed/crop is lost — no refund, matching the original.)"""
    fid = parse_varint_fields(cmd_data).get(1, 0)
    now = int(time.time())
    pots = store.get_garden_pots(player["uin"])
    if fid not in pots or not pots[fid][0]:
        return []                                            # locked field or already empty
    store.set_garden_pot(player["uin"], fid, 0, 0)           # clear the pot
    pot_level = store.get_garden_pot_details(player["uin"]).get(fid, {}).get("level", 1)
    pot = _encode_garden_pot(0, 0, now, level=pot_level)       # empty pot (level only)
    dto_field = pb_varint_field(1, fid) + pb_tag(2, 2) + uvarint(len(pot)) + pot   # Dto_Field
    body = pb_varint_field(1, fid) + pb_tag(2, 2) + uvarint(len(dto_field)) + dto_field
    log.info("    garden dig: field %d cleared", fid)
    return [("PVZ.Cmd.Cmd_Garden_DigPlant_SC", body), _garden_sync(player, now)]


def handle_garden_buypet(cmd_data, player):
    """Buy a one-day or permanent garden pet with diamonds.

    The Flash pet house sends ``petid`` plus ``forever`` and then immediately sends
    UsePet for the same id.  Keep the operation idempotent, enforce the goodwill
    unlock thresholds from GardenPet.txt, and send the garden sync *before* the
    result event so the pet-house mediator redraws from the new state.
    """
    fields = parse_varint_fields(cmd_data)
    pid = int(fields.get(1, 0) or 0)
    forever_buy = bool(fields.get(2, 0))
    now = int(time.time())
    template = load_garden_pets().get(pid)
    result = False
    diamond_msgs = []
    if pid in _GARDEN_PET_IDS and template:
        goodwill = int(player.get("garden_goodwill") or 0)
        states = _garden_pet_states(player, now)
        state = states.get(pid, {})
        already_owned = bool(state.get("owned"))
        already_forever = bool(state.get("forever"))
        if goodwill >= int(template.get("unlock", 0) or 0):
            # Buying a permanent copy that is already owned is an idempotent success;
            # otherwise charge the configured blue-diamond price.
            need = int(template["forever"] if forever_buy else template["trial"])
            if (already_owned and ((forever_buy and already_forever)
                                   or ((not forever_buy) and not already_forever))):
                result = True
            else:
                spent = _spend_diamonds(player, need)
                if spent is not None:
                    result = True
                    diamond_msgs = spent
                    if forever_buy:
                        state = {"owned": True, "forever": True, "expire": 0,
                                 "start": now, "used": False}
                    else:
                        state = {"owned": True, "forever": False,
                                 "expire": now + 86400, "start": now, "used": False}
                    states[pid] = state
                    _save_garden_pet_states(player, states)
        if not result:
            log.info("    garden buy pet rejected: uin=%s pet=%d forever=%s goodwill=%d",
                     player["uin"], pid, forever_buy, goodwill)
    body = pb_varint_field(1, pid) + pb_varint_field(2, 1 if result else 0)
    if not result:
        return [("PVZ.Cmd.Cmd_Garden_BuyPet_SC", body)]
    log.info("    garden buy pet: uin=%s pet=%d forever=%s", player["uin"], pid, forever_buy)
    now = int(time.time())
    return [_garden_sync(player, now)] + diamond_msgs + [("PVZ.Cmd.Cmd_Garden_BuyPet_SC", body)]


def handle_garden_usepet(cmd_data, player):
    """Select one owned garden pet for automatic experience-ball collection.

    ``petid=0`` is accepted as an unequip operation for compatibility with older
    clients, although the current pet house normally always selects a concrete id.
    """
    pid = int(parse_varint_fields(cmd_data).get(1, 0) or 0)
    now = int(time.time())
    states = _garden_pet_states(player, now)
    result = False
    if pid == 0:
        for state in states.values():
            state["used"] = False
        _save_garden_pet_states(player, states)
        result = True
    elif pid == 1:
        # The base companion is free.  The scene wakes it for a 24-hour work
        # period when it is clicked after sleeping/expiry.
        for other in states.values():
            other["used"] = False
        states[1] = {"owned": True, "forever": False,
                     "expire": now + 86400, "start": now, "used": True}
        _save_garden_pet_states(player, states)
        result = True
    elif pid in _GARDEN_PET_IDS:
        template = load_garden_pets().get(pid, {})
        state = states.get(pid, {})
        if (state.get("owned") and int(player.get("garden_goodwill") or 0)
                >= int(template.get("unlock", 0) or 0)):
            for other in states.values():
                other["used"] = False
            state["used"] = True
            state["start"] = now
            states[pid] = state
            _save_garden_pet_states(player, states)
            result = True
    body = pb_varint_field(1, pid) + pb_varint_field(2, 1 if result else 0)
    if not result:
        log.info("    garden use pet rejected: uin=%s pet=%d", player["uin"], pid)
        return [("PVZ.Cmd.Cmd_Garden_UsePet_SC", body)]
    log.info("    garden use pet: uin=%s pet=%d", player["uin"], pid)
    return [_garden_sync(player, now), ("PVZ.Cmd.Cmd_Garden_UsePet_SC", body)]


# --- Idle heartbeat (server-time sync) -----------------------------------------
# The client's IdleMessageSendManager sends Cmd_Idle_CS every 30s and feeds the reply's
# serverTime straight into DateUtils.setServerTime(). If serverTime is 0 (the generic empty
# reply) the client's whole clock collapses to epoch 0 -> every absolute-time countdown (garden
# crop maturity, activity/cooldown/pet timers, ...) reads as a ~55-year value. So the heartbeat
# MUST echo the real Unix time in SECONDS (same units as Cmd_Init_SC.now). Verified via the
# compiled Game_n.swf P-code: the client really does send this (the Assets/src decompile that
# showed the send commented-out is a stale/other build).
def handle_idle(cmd_data, player):
    """Cmd_Idle_CS -> Cmd_Idle_SC{serverTime(2)=now} (heartbeat keeps the client clock correct). Also push
    a fresh energy value if it regenerated since the last sync, so the 体力 bar visibly ticks up while the
    player idles/plays (the client has no local regen timer)."""
    msgs = [("PVZ.Cmd.Cmd_Idle_SC", pb_varint_field(2, int(time.time())))]
    if player:
        before = int(player.get("energy") or 0)
        if current_energy(player) != before:
            msgs.append(energy_sync_msg(player))
    return msgs


# CS name -> function(cmd_data, player) -> response body bytes.
# ============================ Laboratory (实验室, Building_Lab) ============================
# The lab is a shelf of "science bottles" (labId == Lab.txt bottleId). Two client modes:
#   PRODUCE (制作): shows ALL bottles; a locked (NoProduce) one is unlocked by paying its base
#                   level's unlockCost -> becomes HaveProduce at that base level.
#   UPGRADE (升级): shows produced bottles; each upgrade pays the current level's upgradeCost and
#                   bumps labLevel by 1 (until maxLevel). Basic bottles 1-4 (type 1) are
#                   pre-produced at level 0; every other bottle (type 2) starts locked at level 1.
# Wire: Cmd_Lab_GetLabInfo_SC{allLab[](Dto_LabItem), hasNewLab}, Cmd_Lab_ProduceLab_SC{changeLab},
#       Cmd_Lab_UpgradeLab_SC{changeLab}.  Dto_LabItem = {1:labId, 2:labLevel, 3:labStatus}.
_LAB_STATUS_NOPRODUCE = 1   # E_LabStatus_NoProduce   (locked / not yet made)
_LAB_STATUS_HAVEPRODUCE = 2  # E_LabStatus_HaveProduce (made -> upgradeable)
_LAB = None

# One-time starter lab-material stash so PRODUCE mode is usable out of the box. These are the star-1
# 'sand' materials (ItemInfo type 8) that unlock the first four producible bottles 5-8
# (crit/dodge/hit/tenacity): 40001 普通砂 (5+10+15+20=50 across the four) + one each of 40003-40006.
# Higher-tier bottles still need the themed materials that drop from adventure chapters. Note: the
# bottle ICON art (image/lab/*.png) isn't in this build, so unproduced bottles are invisible on the
# shelf — but with the materials in-bag they GLOW on hover (isMeetCondition) and their tooltip shows
# the name + unlock cost, so they're findable by hovering the produce-mode grid.
_LAB_STARTER_MATS = [(40001, 100), (40003, 2), (40004, 2), (40005, 2), (40006, 2)]


def load_lab():
    """{bottleId: {minLevel,maxLevel,type,star,sort, levels:{lvl:{unlockCost,upgradeCost,upgradeLvNeed}}}}
    parsed once from clientDB Lab.txt. Cost strings 'id,cnt:id,cnt' -> [(itemId, count)]."""
    global _LAB
    if _LAB is None:
        _LAB = {}
        rows = _read_clientdb_table("Lab.txt")
        if rows:
            hdr = rows[0]; ci = {c: i for i, c in enumerate(hdr)}

            def col(c, k):
                i = ci.get(k)
                return c[i] if i is not None and i < len(c) else ""

            def cost(s):
                out = []
                for p in (s or "").split(":"):
                    b = p.split(",")
                    if len(b) == 2:
                        try:
                            out.append((int(b[0]), int(b[1])))
                        except ValueError:
                            pass
                return out
            for c in rows[1:]:
                try:
                    bid, lvl = int(col(c, "bottleId")), int(col(c, "level"))
                except ValueError:
                    continue
                b = _LAB.setdefault(bid, {"minLevel": lvl, "maxLevel": lvl, "type": 1,
                                          "star": 1, "sort": bid, "levels": {}})
                b["minLevel"] = min(b["minLevel"], lvl)

                def num(k, d):
                    try:
                        return int(float(col(c, k) or d))
                    except ValueError:
                        return d
                b["maxLevel"] = num("maxLevel", b["maxLevel"])
                b["type"] = num("type", b["type"])
                b["star"] = num("starLv", b["star"])
                b["sort"] = num("sort", b["sort"])
                b["levels"][lvl] = {"unlockCost": cost(col(c, "unlockCost")),
                                    "upgradeCost": cost(col(c, "upgradeCost")),
                                    "upgradeLvNeed": num("upgradeLvNeed", 0),
                                    "stat": _lab_stat_pair(col(c, "upgradeResult"))}
        log.info("loaded %d lab bottles", len(_LAB))
    return _LAB


# upgradeResult "statType,value" -> (statType, value). value is the DISPLAYED bonus x100 (e.g. "1,1000"
# reads "攻击+10"), so /_LAB_STAT_SCALE gives the in-battle number, on the same scale as card stats.
_LAB_STAT_SCALE = 100
# statType -> the effective-stat field it buffs on every DEPLOYED plant. 1=atk 2=def 3=hp 5=技力(ability);
# 6-9 (命中/闪避/暴击/韧性 = hit/dodge/crit/tenacity) aren't modelled in the power sim yet, so ignored.
_LAB_STAT_FIELDS = {1: "atk", 2: "def_", 3: "hp", 5: "ability"}


def _lab_stat_pair(s):
    """'statType,value' -> (int type, int value), or None."""
    b = (s or "").split(",")
    if len(b) == 2:
        try:
            return (int(b[0]), int(b[1]))
        except ValueError:
            return None
    return None


def lab_stat_bonus(player):
    """The Lab's all-deployed-plant stat bonus: sum, over every PRODUCED bottle at its current level, of
    that level's upgradeResult (÷_LAB_STAT_SCALE) keyed by stat. {atk,def_,hp,ability} of ints (>=0).
    Level 0 (base) has no upgradeResult, so an un-upgraded produced bottle contributes nothing."""
    bonus = {"atk": 0, "def_": 0, "hp": 0, "ability": 0}
    for lid, (level, status) in _lab_load_state(player).items():
        if status != _LAB_STATUS_HAVEPRODUCE:
            continue
        pair = load_lab().get(lid, {}).get("levels", {}).get(level, {}).get("stat")
        if not pair:
            continue
        field = _LAB_STAT_FIELDS.get(pair[0])
        if field:
            bonus[field] += pair[1] // _LAB_STAT_SCALE
    return bonus


def _lab_default_state():
    """Fresh {labId: (level, status)}: type-1 basics produced at their level-0 base; all type-2
    bottles locked (NoProduce) at their minimum (base) level so their template still resolves."""
    state = {}
    for bid, b in load_lab().items():
        state[bid] = (b["minLevel"],
                      _LAB_STATUS_HAVEPRODUCE if b["type"] == 1 else _LAB_STATUS_NOPRODUCE)
    return state


def _lab_load_state(player):
    """Fresh defaults with the player's saved produce/upgrade overrides ('labId:level:status;...')."""
    state = _lab_default_state()
    for part in (player.get("lab_bottles") or "").split(";"):
        bits = part.split(":")
        if len(bits) == 3:
            try:
                lid, lvl, st = int(bits[0]), int(bits[1]), int(bits[2])
            except ValueError:
                continue
            state[lid] = (lvl, st)
    return state


def _lab_save_bottle(player, lab_id, level, status):
    """Record one bottle's new (level, status); persist only bottles that deviate from default."""
    state = _lab_load_state(player)
    state[lab_id] = (level, status)
    defaults = _lab_default_state()
    parts = ["%d:%d:%d" % (lid, state[lid][0], state[lid][1])
             for lid in sorted(state) if state[lid] != defaults.get(lid)]
    player["lab_bottles"] = ";".join(parts)
    store.save_player(player["uin"], lab_bottles=player["lab_bottles"])


def _encode_lab_item(lab_id, level, status):
    """Dto_LabItem{1:labId, 2:labLevel, 3:labStatus}."""
    return pb_varint_field(1, lab_id) + pb_varint_field(2, level) + pb_varint_field(3, status)


def _lab_afford(player, pairs):
    """True if the player holds every (itemId, count) — coin/gift-diamond via HUD fields, else bag."""
    for iid, cnt in pairs:
        if iid in _CURRENCY_SYNC:
            field, _ = _CURRENCY_SYNC[iid]
            if int(player.get(field, 0)) < cnt:
                return False
        elif iid in _UNMODELED_CURRENCIES:
            continue
        else:
            if store.get_item_count(player["uin"], iid) < cnt:
                return False
    return True


def _lab_charge(player, pairs):
    """Deduct [(itemId, count)] (assumes _lab_afford passed); return the HUD/bag sync messages."""
    return grant_fuben_reward(player, [(iid, -cnt) for iid, cnt in pairs])


def make_lab_getinfo(player):
    """Cmd_Lab_GetLabInfo_SC: every bottle as a Dto_LabItem + hasNewLab=false."""
    state = _lab_load_state(player)
    d = b""
    for lid in sorted(state, key=lambda x: load_lab().get(x, {}).get("sort", x)):
        lvl, st = state[lid]
        dto = _encode_lab_item(lid, lvl, st)
        d += pb_tag(1, 2) + uvarint(len(dto)) + dto      # allLab (field 1, repeated message)
    d += pb_varint_field(2, 0)                           # hasNewLab (field 2) = false
    return d


def handle_lab_getlabinfo(cmd_data, player):
    """Cmd_Lab_GetLabInfo_CS{from} -> the whole shelf. On the FIRST open, also drop the one-time
    starter lab-material stash (item update sent BEFORE the shelf so isHaveAllItems is already true
    when the board first renders and the producible bottles glow on hover)."""
    msgs = []
    if not int(player.get("lab_mats_granted") or 0):
        upd = grant_items(player, _LAB_STARTER_MATS)
        if upd:
            msgs.append(upd)
        player["lab_mats_granted"] = 1
        store.save_player(player["uin"], lab_mats_granted=1)
        log.info("    lab: granted one-time starter materials %s", _LAB_STARTER_MATS)
    msgs.append(("PVZ.Cmd.Cmd_Lab_GetLabInfo_SC", make_lab_getinfo(player)))
    return msgs


def handle_lab_produce(cmd_data, player):
    """Cmd_Lab_ProduceLab_CS{labId}: unlock a locked bottle by paying its base-level unlockCost."""
    lab_id = parse_varint_fields(cmd_data).get(1, 0)
    b = load_lab().get(lab_id)
    if not b:
        return []
    level, status = _lab_load_state(player).get(lab_id, (b["minLevel"], _LAB_STATUS_NOPRODUCE))
    if status != _LAB_STATUS_NOPRODUCE:
        return []                                        # already produced
    cost = b["levels"].get(b["minLevel"], {}).get("unlockCost", [])
    if not _lab_afford(player, cost):
        return []                                        # client greys the button; guard anyway
    charge = _lab_charge(player, cost)
    _lab_save_bottle(player, lab_id, b["minLevel"], _LAB_STATUS_HAVEPRODUCE)
    dto = _encode_lab_item(lab_id, b["minLevel"], _LAB_STATUS_HAVEPRODUCE)
    body = pb_tag(1, 2) + uvarint(len(dto)) + dto        # changeLab (field 1, message)
    log.info("    lab: produced bottle %d (cost %s)", lab_id, cost)
    return ([ ("PVZ.Cmd.Cmd_Lab_ProduceLab_SC", body) ] + charge
            + _quest_record_condition(player, 15, lab_id, 1))


def handle_lab_upgrade(cmd_data, player):
    """Cmd_Lab_UpgradeLab_CS{labId}: pay the current level's upgradeCost, bump labLevel by 1."""
    lab_id = parse_varint_fields(cmd_data).get(1, 0)
    b = load_lab().get(lab_id)
    if not b:
        return []
    level, status = _lab_load_state(player).get(lab_id, (b["minLevel"], _LAB_STATUS_NOPRODUCE))
    if status != _LAB_STATUS_HAVEPRODUCE or level >= b["maxLevel"]:
        return []                                        # not produced / already maxed
    lv = b["levels"].get(level, {})
    if int(player.get("level", 1)) < lv.get("upgradeLvNeed", 0):
        return []                                        # actor level too low
    cost = lv.get("upgradeCost", [])
    if not cost or not _lab_afford(player, cost):
        return []
    charge = _lab_charge(player, cost)
    new_level = level + 1
    _lab_save_bottle(player, lab_id, new_level, _LAB_STATUS_HAVEPRODUCE)
    dto = _encode_lab_item(lab_id, new_level, _LAB_STATUS_HAVEPRODUCE)
    body = pb_tag(1, 2) + uvarint(len(dto)) + dto        # changeLab (field 1, message)
    log.info("    lab: upgraded bottle %d -> lv %d (cost %s)", lab_id, new_level, cost)
    return ([ ("PVZ.Cmd.Cmd_Lab_UpgradeLab_SC", body) ] + charge
            + _quest_record_condition(player, 14, lab_id, new_level))


# ============================ World Tree (世界树/树屋, Building_WORLD_TREE=220) ============================
# A "tree of wisdom": you FOSTER (培养) it to gain exp; when exp fills needExp the server auto-levels it,
# and every level grants +atk/def/hp/power to all deployed plants (client reads the props from clientDB).
# Three foster tiers (FosterType): Normal(1)=free for the first 5/day then costs fosterTicket, Free(3)=VIP's
# way to spend those same 5 free/day, Advanced(2)=gift-diamonds (half-price for the first 5/day). Each foster
# rolls a CRIT for bonus exp. One-key Upgrade (Cmd_WorldTree_Upgrade) buys +1 level with diamonds, but only
# unlocks at the first level whose oneKeyCost>0 (level 200). Wire: Dto_WorldTree_Info{1:level, 2:exp,
# 3:freeTimes(used), 4:advancedTimes(used)}; GetInfo_SC.info=f1, Foster_SC{1:fosterType,2:isCrit,3:addExp,
# 4:info}, Upgrade_SC.info=f1. freeTimes/advancedTimes are USED counts (client shows 5-used remaining).
_WT = None
_WT_CRIT_CHANCE = 0.20            # foster crit chance -> bonus exp
_WT_CRIT_MULT = 2                 # crit multiplies the foster's addExp
_WT_FREE_PER_DAY = 5             # normal/free fosters free per day (matches WTData: 5 - freeTimes)
_WT_ADV_HALF_PER_DAY = 5         # advanced fosters at half price per day
_WT_STARTER_FOSTER_TICKET = 500  # one-time stash so the paid normal-foster path is testable
_WT_FOSTERTYPE_NORMAL = 1
_WT_FOSTERTYPE_ADVANCED = 2
_WT_FOSTERTYPE_FREE = 3


def load_wt():
    """{level: {needExp, norAddExp, advAddExp, costNor, costAdv, oneKeyCost}} from WTTemplateCE.txt.
    norCost/advCost are 'itemId:amount' -> we keep the amount (costNor=fosterTicket, costAdv=gift diamonds)."""
    global _WT
    if _WT is None:
        _WT = {}
        rows = _read_clientdb_table("WTTemplateCE.txt")
        if rows:
            hdr = rows[0]; ci = {c: i for i, c in enumerate(hdr)}

            def col(r, k):
                i = ci.get(k)
                return r[i] if i is not None and i < len(r) else ""

            def amt(s):
                p = (s or "").split(":")
                try:
                    return int(p[1]) if len(p) > 1 else 0
                except ValueError:
                    return 0
            for r in rows[1:]:
                try:
                    lid = int(col(r, "id"))
                except ValueError:
                    continue

                def num(k):
                    try:
                        return int(float(col(r, k) or 0))
                    except ValueError:
                        return 0
                _WT[lid] = {"needExp": num("needExp"), "norAddExp": num("norAddExp"),
                            "advAddExp": num("advAddExp"), "costNor": amt(col(r, "norCost")),
                            "costAdv": amt(col(r, "advCost")), "oneKeyCost": num("oneKeyCost"),
                            "atk": num("atk"), "def_": num("def"), "hp": num("hp"),
                            "power": num("power")}
        log.info("loaded %d world-tree levels", len(_WT))
    return _WT


# WTTemplate atk/def/hp/power are per-level DELTAS on the x100 display scale (level 1 atk 1000 = +10); the
# client sums 1..currentLevel (getLevelProp is cumulative). So the tree bonus at level L = sum of the deltas
# for levels 1..L, ÷ this scale — same units as the Lab bonus and card stats.
_WT_STAT_SCALE = 100
_WT_CUM_CACHE = None            # {level: {atk,def_,hp,power}} cumulative through that level


def wt_stat_bonus(player):
    """The World Tree's all-deployed-plant stat bonus at the player's tree level: cumulative atk/def/hp
    (÷_WT_STAT_SCALE) summed over levels 1..wt_level. {atk,def_,hp} of ints (>=0)."""
    global _WT_CUM_CACHE
    if _WT_CUM_CACHE is None:
        _WT_CUM_CACHE = {}
        a = d = h = p = 0
        for lv in sorted(load_wt()):
            r = _WT[lv]
            a += r.get("atk", 0); d += r.get("def_", 0); h += r.get("hp", 0); p += r.get("power", 0)
            _WT_CUM_CACHE[lv] = {"atk": a // _WT_STAT_SCALE, "def_": d // _WT_STAT_SCALE,
                                 "hp": h // _WT_STAT_SCALE, "power": p // _WT_STAT_SCALE}
    level = int(player.get("wt_level") or 1)
    cum = _WT_CUM_CACHE.get(level) or _WT_CUM_CACHE.get(max(_WT_CUM_CACHE) if _WT_CUM_CACHE else 0, {})
    return {"atk": cum.get("atk", 0), "def_": cum.get("def_", 0), "hp": cum.get("hp", 0)}


def _wt_max_level():
    lv = load_wt()
    return max(lv) if lv else 1


def _wt_daily_reset(player):
    """Reset the per-day free/half-price foster counters when the calendar day rolls over."""
    today = time.strftime("%Y%m%d")
    if (player.get("wt_day") or "") != today:
        player["wt_free_used"], player["wt_adv_used"], player["wt_day"] = 0, 0, today
        store.save_player(player["uin"], wt_free_used=0, wt_adv_used=0, wt_day=today)


def _encode_wt_info(player):
    """Dto_WorldTree_Info{1:level, 2:exp, 3:freeTimes(used), 4:advancedTimes(used)}."""
    return (pb_varint_field(1, int(player.get("wt_level") or 1))
            + pb_varint_field(2, int(player.get("wt_exp") or 0))
            + pb_varint_field(3, int(player.get("wt_free_used") or 0))
            + pb_varint_field(4, int(player.get("wt_adv_used") or 0)))


def _wt_info_field(player, field):
    """The tree info wrapped as message field `field` (GetInfo/Upgrade use 1, Foster uses 4)."""
    info = _encode_wt_info(player)
    return pb_tag(field, 2) + uvarint(len(info)) + info


def _wt_apply_exp(player, add_exp):
    """Add exp and auto-level while it fills needExp (stops at max level)."""
    level = int(player.get("wt_level") or 1)
    exp = int(player.get("wt_exp") or 0) + add_exp
    maxlv = _wt_max_level()
    while level < maxlv:
        need = load_wt().get(level, {}).get("needExp", 0)
        if need > 0 and exp >= need:
            exp -= need
            level += 1
        else:
            break
    player["wt_level"], player["wt_exp"] = level, exp


def handle_wt_getinfo(cmd_data, player):
    """Cmd_WorldTree_GetInfo_CS -> the tree state. First open also drops the one-time fosterTicket stash."""
    _wt_daily_reset(player)
    msgs = []
    if not int(player.get("wt_granted") or 0):
        player["foster_ticket"] = int(player.get("foster_ticket") or 0) + _WT_STARTER_FOSTER_TICKET
        player["wt_granted"] = 1
        store.save_player(player["uin"], foster_ticket=player["foster_ticket"], wt_granted=1)
        msgs.append(("PVZ.Cmd.Cmd_SyncFosterTicket_SC", pb_varint_field(1, player["foster_ticket"])))
        log.info("    world-tree: granted %d starter fosterTicket", _WT_STARTER_FOSTER_TICKET)
    msgs.append(("PVZ.Cmd.Cmd_WorldTree_GetInfo_SC", _wt_info_field(player, 1)))
    return msgs


def handle_wt_foster(cmd_data, player):
    """Cmd_WorldTree_Foster_CS{fosterType} -> charge the tier, add exp (with a crit roll), auto-level."""
    ftype = parse_varint_fields(cmd_data).get(1, _WT_FOSTERTYPE_NORMAL)
    _wt_daily_reset(player)
    tpl = load_wt().get(int(player.get("wt_level") or 1))
    if not tpl:
        return []
    free_used = int(player.get("wt_free_used") or 0)
    adv_used = int(player.get("wt_adv_used") or 0)
    syncs = []
    if ftype == _WT_FOSTERTYPE_ADVANCED:
        base = tpl["advAddExp"]
        if adv_used < _WT_ADV_HALF_PER_DAY:
            cost, adv_used = tpl["costAdv"] // 2, adv_used + 1
        else:
            cost = tpl["costAdv"]
        spent = _spend_diamonds(player, cost)
        if spent is None:
            return []                                        # can't afford (client normally blocks)
        syncs += spent
        player["wt_adv_used"] = adv_used
    else:                                                    # Normal(1) or Free(3)
        base = tpl["norAddExp"]
        if free_used < _WT_FREE_PER_DAY:
            player["wt_free_used"] = free_used + 1            # a free daily foster
        elif ftype == _WT_FOSTERTYPE_FREE:
            return []                                        # no free times left (client blocks)
        else:
            cost = tpl["costNor"]
            if int(player.get("foster_ticket") or 0) < cost:
                return []
            player["foster_ticket"] = int(player["foster_ticket"]) - cost
            store.save_player(player["uin"], foster_ticket=player["foster_ticket"])
            syncs.append(("PVZ.Cmd.Cmd_SyncFosterTicket_SC", pb_varint_field(1, player["foster_ticket"])))
    is_crit = 1 if random.random() < _WT_CRIT_CHANCE else 0
    add_exp = base * (_WT_CRIT_MULT if is_crit else 1)
    _wt_apply_exp(player, add_exp)
    store.save_player(player["uin"], wt_level=player["wt_level"], wt_exp=player["wt_exp"],
                      wt_free_used=int(player.get("wt_free_used") or 0),
                      wt_adv_used=int(player.get("wt_adv_used") or 0))
    body = (pb_varint_field(1, ftype) + pb_varint_field(2, is_crit)
            + pb_varint_field(3, add_exp) + _wt_info_field(player, 4))
    log.info("    world-tree: foster type=%d crit=%d +%d exp -> lv%d exp%d",
             ftype, is_crit, add_exp, player["wt_level"], player["wt_exp"])
    return [("PVZ.Cmd.Cmd_WorldTree_Foster_SC", body)] + syncs + _quest_record_condition(
        player, 55, 0, int(player.get("wt_level", 1)))


def handle_wt_upgrade(cmd_data, player):
    """Cmd_WorldTree_Upgrade_CS -> one-key: spend the level's oneKeyCost diamonds for +1 level
    (only levels with oneKeyCost>0, i.e. 200+, allow this; client greys the button otherwise)."""
    _wt_daily_reset(player)
    level = int(player.get("wt_level") or 1)
    tpl = load_wt().get(level)
    if not tpl or level >= _wt_max_level() or tpl["oneKeyCost"] <= 0:
        return []
    spent = _spend_diamonds(player, tpl["oneKeyCost"])
    if spent is None:
        return []
    player["wt_level"] = level + 1
    store.save_player(player["uin"], wt_level=player["wt_level"])
    log.info("    world-tree: one-key upgrade -> lv%d (cost %d diamonds)",
             player["wt_level"], tpl["oneKeyCost"])
    return [("PVZ.Cmd.Cmd_WorldTree_Upgrade_SC", _wt_info_field(player, 1))] + spent + _quest_record_condition(
        player, 55, 0, int(player.get("wt_level", 1)))


# ===== Trial Road (试炼之路, Building_TrialRoad=200) — SAFE-OPEN STUB, full build deferred =====
# ===================== Trial Road (试炼之路, ScrewUp=Normal / NewScrewUp=Hard, Building unlocks @L15) =====================
# A 150-stage adventure-style battle CLIMB. Progress is PERSISTENT (tr_max = best stage reached); DAILY you
# farm Upgrade/Equipment materials — the higher you've climbed, the bigger the daily haul (wiki). Wire (both
# modes share the layout): GetInfo_SC{1:currentStage,2:maxStage,3:restartNum,4:boxTaken[],5:boxTotal[],
# 6:remainTime(=leftBattleTimes),7:vipRestartNum}; Fight_CS{1:stageId,2:isSweep}->Fight_SC{1:stageId,2:isSweep,
# 3:report(Dto_FightReport),4:firstPass,5:win,6:rewardList[]}; TakeReward_CS{1:stageId}->TakeReward_SC{1:stageId,
# 2:rewardList[]}; SendFormation_SC{1:formation}; SetFormation_CS{1:formation}; Restart_SC{1:result,2:restartNum,
# 3:vipRestartNum}; Sweep_SC{1:currentStageId,2:rewardList[]}. The client fights currentStage+1 (onClickPt); the
# report carries fightType=ScrewUp(11) so FightChestsWDMedator opens FightResultWD_TrialLoad (win AND loss).
# Model: a WIN advances currentStage. A NEW-frontier win (stage>maxStage) raises maxStage, costs one daily
# battle time, and grants firstReward. A re-clear (stage<=maxStage, after a Restart) grants sweepReward for
# free. Restart resets currentStage to 0 to re-run the ladder. Chests at milestone stages give the big bundles.
_TR_NORMAL = None
_TR_DAILY_BATTLES = 10        # NEW-stage climbs allowed per day (leftBattleTimes)
_TR_DAILY_RESTARTS = 5        # free restarts per day (re-run the ladder for materials)
_TR_HARD_DAILY_BATTLES = 10
_TR_HARD_DAILY_RESTARTS = 5


def load_trial_road():
    """{stage: {power, first:[(id,n)], sweep:[(id,n)], chest:[(id,n)]}} from clientDB trialRoad.txt."""
    global _TR_NORMAL
    if _TR_NORMAL is None:
        _TR_NORMAL = {}
        rows = _read_clientdb_table("trialRoad.txt")
        if rows:
            hdr = rows[0]; ci = {c: i for i, c in enumerate(hdr)}

            def col(r, k):
                i = ci.get(k)
                return r[i] if i is not None and i < len(r) else ""
            for r in rows[1:]:
                try:
                    sid = int(col(r, "id"))
                except ValueError:
                    continue
                _TR_NORMAL[sid] = {
                    "power": int(float(col(r, "power") or 0)),
                    "first": _tr_parse_reward(col(r, "firstRewardStr")),
                    "sweep": _tr_parse_reward(col(r, "sweepReardStr")),
                    "chest": _tr_parse_reward(col(r, "chestItemsStr")),
                }
        log.info("loaded %d trial-road stages", len(_TR_NORMAL))
    return _TR_NORMAL


def _tr_parse_reward(spec):
    """'id:num,id:num' (Trial Road uses COMMA separators, unlike fuben's ';') -> [(itemId, num)]."""
    out = []
    for part in re.split(r"[,;]", spec or ""):
        if ":" in part:
            a, b = part.split(":", 1)
            try:
                out.append((int(a), int(b)))
            except ValueError:
                pass
    return out


def _tr_chest_stages():
    """Sorted stageIds that award a milestone chest (non-empty chestItemsStr)."""
    return sorted(s for s, d in load_trial_road().items() if d["chest"])


def _tr_daily_reset(player):
    """Reset the per-day climb/restart counters when the calendar day rolls over (currentStage persists)."""
    today = time.strftime("%Y%m%d")
    if (player.get("tr_day") or "") != today:
        player["tr_battles_used"], player["tr_restarts_used"], player["tr_day"] = 0, 0, today
        store.save_player(player["uin"], tr_battles_used=0, tr_restarts_used=0, tr_day=today)


def _tr_hard_daily_reset(player):
    """Reset nightmare's daily counters without touching normal Trial Road."""
    today = time.strftime("%Y%m%d")
    if (player.get("tr_hard_day") or "") != today:
        player["tr_hard_battles_used"] = 0
        player["tr_hard_restarts_used"] = 0
        player["tr_hard_day"] = today
        store.save_player(player["uin"], tr_hard_battles_used=0,
                          tr_hard_restarts_used=0, tr_hard_day=today)


def _tr_boxes_taken(player):
    return [int(x) for x in (player.get("tr_boxes") or "").split(",") if x.strip().isdigit()]


def _tr_hard_boxes_taken(player):
    return [int(x) for x in (player.get("tr_hard_boxes") or "").split(",") if x.strip().isdigit()]


def _tr_reward_bytes(field, reward_items):
    """Repeated Dto_ItemInfo reward list as message `field` (rewardList) bytes."""
    d = b""
    for iid, num in reward_items:
        dto = build_item_dto(iid, num)
        d += pb_tag(field, 2) + uvarint(len(dto)) + dto
    return d


def make_trialroad_getinfo(player):
    """GetInfo_SC body from the player's Trial Road state (currentStage/maxStage, daily battles/restarts
    left, milestone chests unlocked/claimed)."""
    cur, mx = int(player.get("tr_current") or 0), int(player.get("tr_max") or 0)
    restarts_left = max(0, _TR_DAILY_RESTARTS - int(player.get("tr_restarts_used") or 0))
    battles_left = max(0, _TR_DAILY_BATTLES - int(player.get("tr_battles_used") or 0))
    d = pb_varint_field(1, cur) + pb_varint_field(2, mx) + pb_varint_field(3, restarts_left)
    for s in _tr_boxes_taken(player):
        d += pb_varint_field(4, s)                              # boxTaken[]
    for s in _tr_chest_stages():
        if s <= mx:
            d += pb_varint_field(5, s)                          # boxTotal[] (chests unlocked by progress)
    d += pb_varint_field(6, battles_left) + pb_varint_field(7, 0)   # remainTime(leftBattleTimes), vipRestartNum
    return d


def make_newtrialroad_getinfo(player):
    """Nightmare GetInfo_SC.  It intentionally reuses the normal stage table until a separate
    nightmare table is available, but all progress/counters are independent."""
    cur = int(player.get("tr_hard_current") or 0)
    mx = int(player.get("tr_hard_max") or 0)
    restarts_left = max(0, _TR_HARD_DAILY_RESTARTS - int(player.get("tr_hard_restarts_used") or 0))
    battles_left = max(0, _TR_HARD_DAILY_BATTLES - int(player.get("tr_hard_battles_used") or 0))
    d = pb_varint_field(1, cur) + pb_varint_field(2, mx) + pb_varint_field(3, restarts_left)
    for s in _tr_hard_boxes_taken(player):
        d += pb_varint_field(4, s)
    for s in _tr_chest_stages():
        if s <= mx:
            d += pb_varint_field(5, s)
    d += pb_varint_field(6, battles_left) + pb_varint_field(7, 0)
    return d


def _trialroad_formation_msg(player, sc_name):
    """The player's team as a (sc_name, SendFormation_SC{formation}) message — same team as adventure."""
    ensure_player_cards(player)
    formation = build_formation_info(player, 1, default_formation_placements(player))
    return (sc_name, pb_tag(1, 2) + uvarint(len(formation)) + formation)


def handle_screwup_getinfo(cmd_data, player):
    """Cmd_ScrewUp_GetInfo_CS (Trial Road, Normal) -> the real climb + daily state, and PUSH the formation
    so the scene has the team without a separate request."""
    _tr_daily_reset(player)
    # The lineup window that opens from here previews the ENEMY squad, so tell the preview which mode it
    # is looking at (see preview_enemy_units).
    note_battle_scene(player, "screwup")
    return [("PVZ.Cmd.Cmd_ScrewUp_GetInfo_SC", make_trialroad_getinfo(player)),
            _trialroad_formation_msg(player, "PVZ.Cmd.Cmd_ScrewUp_SendFormation_SC")]


def handle_screwup_getformation(cmd_data, player):
    """Cmd_ScrewUp_GetFormation_CS -> Cmd_ScrewUp_SendFormation_SC{formation} (same team as adventure)."""
    note_battle_scene(player, "screwup")
    return [_trialroad_formation_msg(player, "PVZ.Cmd.Cmd_ScrewUp_SendFormation_SC")]


def handle_screwup_setformation(cmd_data, player):
    """Cmd_ScrewUp_SetFormation_CS{formation} -> persist the team (team 1) + echo SendFormation_SC."""
    placements = {}
    fsub = parse_repeated_submessages(cmd_data, 1)
    if fsub:
        for cp in parse_repeated_submessages(fsub[0], 1):
            c = parse_varint_fields(cp)
            pos, uid = c.get(1, 0), c.get(2, 0)
            if pos and uid:
                placements[pos] = uid
    if placements:
        store.set_formation(player["uin"], 1, placements)
    log.info("    trial road SET formation: %s", placements)
    return [_trialroad_formation_msg(player, "PVZ.Cmd.Cmd_ScrewUp_SendFormation_SC")]


def _tr_enemy_squad(power, stage):
    """A themed zombie squad totalling ~`power` Fighting Power for a trial stage (world rotates by tier so
    the climb changes scenery: Egypt -> Great Wall -> Pirate -> Future across the 150 stages)."""
    world = ("egypt", "greatwall", "pirate", "future")[min(3, (stage - 1) // 38)]
    cards = [c for c in _WORLD_ZOMBIES.get(world, _DEFAULT_ENEMY_CARDS) if c in _BATTLE_CARDS] \
        or [c for c in _DEFAULT_ENEMY_CARDS if c in _BATTLE_CARDS] or [next(iter(_BATTLE_CARDS), 111)]
    count = max(1, min(3 + (stage - 1) // 15, len(_ENEMY_POS)))
    z_power = max(1, power // count)
    z_hp = max(1, z_power * 9 // _ZOMBIE_HP_TEST_DIVISOR)
    atk, dfn = _enemy_atk_def(z_power)
    right = []
    for i in range(count):
        zc = cards[i % len(cards)]
        zst = _BATTLE_CARDS.get(zc, {"skill1": 0, "name": "Zombie"})
        right.append({"pos": _ENEMY_POS[i], "card_id": zc, "hp": z_hp, "atk": atk, "def_": dfn,
                      "skill1": zst.get("skill1", 0), "skill2": zst.get("skill2", 0), "level": 1,
                      "shield": max(0, int(zst.get("shield", 0) or 0)),
                      "is_leader": i == 0, "power": z_power, "name": zst.get("name", "Zombie")})
    return right


def handle_screwup_fight(cmd_data, player):
    """Cmd_ScrewUp_Fight_CS{stageId,isSweep} -> Cmd_ScrewUp_Fight_SC{stageId,isSweep,report,firstPass,win,
    rewardList}. Fights stageId (= currentStage+1) with the losable combat. A WIN advances the climb; a
    first-clear (stage>maxStage) costs a daily battle time + grants firstReward, a re-clear grants
    sweepReward for free; a LOSS advances nothing and grants nothing (retry). Reward -> report.leftSide.
    reward (FightResultWD_TrialLoad reads that) + granted server-side."""
    f = parse_varint_fields(cmd_data)
    stage_id = f.get(1, 0)
    _tr_daily_reset(player)
    lvl_data = load_trial_road().get(stage_id)
    if not lvl_data:
        return []
    uin = player["uin"]
    cur, mx = int(player.get("tr_current") or 0), int(player.get("tr_max") or 0)
    is_new = stage_id > mx
    battles_left = max(0, _TR_DAILY_BATTLES - int(player.get("tr_battles_used") or 0))
    # The client only lets you fight currentStage+1, and gates a NEW stage on leftBattleTimes; guard both.
    if stage_id != cur + 1 or (is_new and battles_left <= 0):
        log.info("    trial road fight REJECTED: stage=%d cur=%d max=%d battlesLeft=%d",
                 stage_id, cur, mx, battles_left)
        return []
    left_units = build_player_units(player)
    right_units = _tr_enemy_squad(lvl_data["power"], stage_id)
    # Same contract as adventure: fight the zombies the lineup window previewed.
    right_units = apply_previewed_enemy_types(player, right_units, "screwup")
    won, lp, rp = resolve_battle(left_units, right_units)
    rounds = simulate_battle(left_units, right_units, won) \
        if (left_units and right_units) else []
    replay_bytes = encode_fight_replay(rounds)
    reward_items = (lvl_data["first"] if is_new else lvl_data["sweep"]) if won else []
    report = build_fight_report(player, 0, 0, stage_id, won, reward_items, is_new,
                                left_units, right_units, replay_bytes, card_exp_gain=0,
                                fight_type=11)   # BattleTargetType_ScrewUp -> FightResultWD_TrialLoad
    fight_sc = (pb_varint_field(1, stage_id) + pb_varint_field(2, 0)          # stageId, isSweep=false
                + pb_tag(3, 2) + uvarint(len(report)) + report                # report
                + pb_bool(4, won and is_new) + pb_bool(5, won)                # firstPass, win
                + _tr_reward_bytes(6, reward_items))                          # rewardList[]
    msgs = [("PVZ.Cmd.Cmd_ScrewUp_Fight_SC", fight_sc)]
    if won:
        player["tr_current"] = stage_id
        if is_new:
            player["tr_max"] = stage_id
            player["tr_battles_used"] = int(player.get("tr_battles_used") or 0) + 1
        store.save_player(uin, tr_current=player["tr_current"], tr_max=int(player.get("tr_max") or mx),
                          tr_battles_used=int(player.get("tr_battles_used") or 0))
        msgs += grant_fuben_reward(player, reward_items)
        # Push a fresh GetInfo so the scene unlocks the next stage IMMEDIATELY: the client's proxy never
        # advances its own currentStage on a win (only the server does) — onCmd_Fight_SC just re-renders
        # from cached data — so without this the next level stays locked until you leave and re-enter.
        msgs.append(("PVZ.Cmd.Cmd_ScrewUp_GetInfo_SC", make_trialroad_getinfo(player)))
        msgs += _quest_record_condition(player, 63, 0, int(player.get("tr_max", 0)))
        log.info("    TRIAL ROAD %s: stage=%d WIN (team %d vs %d 战力) reward=%s -> cur=%d max=%d",
                 "CLIMB" if is_new else "RECLEAR", stage_id, lp, rp, reward_items,
                 player["tr_current"], int(player.get("tr_max") or 0))
    else:
        log.info("    TRIAL ROAD FIGHT: stage=%d LOSS (team %d vs %d 战力) — no advance, retry",
                 stage_id, lp, rp)
    return msgs


def handle_screwup_sweep(cmd_data, player):
    """Cmd_ScrewUp_Sweep_CS -> Cmd_ScrewUp_Sweep_SC{currentStageId,rewardList}. Bulk re-clears every beaten
    stage from currentStage+1..maxStage for their sweepReward (the daily material haul), jumping
    currentStage to maxStage."""
    _tr_daily_reset(player)
    tr = load_trial_road()
    cur, mx = int(player.get("tr_current") or 0), int(player.get("tr_max") or 0)
    merged = {}
    for s in range(cur + 1, mx + 1):
        for iid, num in tr.get(s, {}).get("sweep", []):
            merged[iid] = merged.get(iid, 0) + num
    reward_items = sorted(merged.items())
    player["tr_current"] = mx
    store.save_player(player["uin"], tr_current=mx)
    msgs = [("PVZ.Cmd.Cmd_ScrewUp_Sweep_SC", pb_varint_field(1, mx) + _tr_reward_bytes(2, reward_items))]
    msgs += grant_fuben_reward(player, reward_items)
    log.info("    TRIAL ROAD SWEEP: stages %d..%d -> currentStage=%d reward=%s", cur + 1, mx, mx, reward_items)
    return msgs


def handle_screwup_takereward(cmd_data, player):
    """Cmd_ScrewUp_TakeReward_CS{stageId} -> Cmd_ScrewUp_TakeReward_SC{stageId,rewardList}. Claim the
    one-time milestone chest at stageId (chestItemsStr), if unlocked (stageId<=maxStage) and not taken."""
    stage_id = parse_varint_fields(cmd_data).get(1, 0)
    lvl = load_trial_road().get(stage_id)
    mx = int(player.get("tr_max") or 0)
    taken = _tr_boxes_taken(player)
    if not lvl or not lvl["chest"] or stage_id > mx or stage_id in taken:
        return []
    taken.append(stage_id)
    player["tr_boxes"] = ",".join(str(s) for s in sorted(taken))
    store.save_player(player["uin"], tr_boxes=player["tr_boxes"])
    reward_items = lvl["chest"]
    msgs = [("PVZ.Cmd.Cmd_ScrewUp_TakeReward_SC",
             pb_varint_field(1, stage_id) + _tr_reward_bytes(2, reward_items))]
    msgs += grant_fuben_reward(player, reward_items)
    log.info("    TRIAL ROAD CHEST: stage=%d reward=%s", stage_id, reward_items)
    return msgs


def handle_screwup_restart(cmd_data, player):
    """Cmd_ScrewUp_Restart_CS -> Cmd_ScrewUp_Restart_SC{result,restartNum,vipRestartNum}. Reset the climb
    position to 0 (to re-run/sweep the ladder), consuming one daily restart."""
    _tr_daily_reset(player)
    used = int(player.get("tr_restarts_used") or 0)
    if used >= _TR_DAILY_RESTARTS:
        return [("PVZ.Cmd.Cmd_ScrewUp_Restart_SC", pb_varint_field(1, 0)          # result=0 (out of restarts)
                 + pb_varint_field(2, 0) + pb_varint_field(3, 0))]
    player["tr_restarts_used"], player["tr_current"] = used + 1, 0
    store.save_player(player["uin"], tr_restarts_used=player["tr_restarts_used"], tr_current=0)
    left = max(0, _TR_DAILY_RESTARTS - player["tr_restarts_used"])
    log.info("    TRIAL ROAD RESTART: currentStage->0 (%d restarts left today)", left)
    # Restart_SC only updates restartNum client-side (not currentStage), so push a fresh GetInfo to
    # re-render the ladder at currentStage=0 (otherwise the scene keeps the old position until re-entry).
    return [("PVZ.Cmd.Cmd_ScrewUp_Restart_SC", pb_varint_field(1, 1)              # result=1
             + pb_varint_field(2, left) + pb_varint_field(3, 0)),
            ("PVZ.Cmd.Cmd_ScrewUp_GetInfo_SC", make_trialroad_getinfo(player))]


