def handle_newscrewup_fight(cmd_data, player):
    """Nightmare fight; mirrors normal Trial Road with separate progress/counters."""
    f = parse_varint_fields(cmd_data)
    stage_id = f.get(1, 0)
    _tr_hard_daily_reset(player)
    lvl_data = load_trial_road().get(stage_id)
    if not lvl_data:
        return []
    uin = player["uin"]
    cur, mx = int(player.get("tr_hard_current") or 0), int(player.get("tr_hard_max") or 0)
    is_new = stage_id > mx
    battles_left = max(0, _TR_HARD_DAILY_BATTLES - int(player.get("tr_hard_battles_used") or 0))
    if stage_id != cur + 1 or (is_new and battles_left <= 0):
        log.info("    nightmare fight REJECTED: stage=%d cur=%d max=%d battlesLeft=%d",
                 stage_id, cur, mx, battles_left)
        return []
    left_units = build_player_units(player)
    right_units = _tr_enemy_squad(max(1, int(lvl_data["power"] * 2)), stage_id)
    # Nightmare shares the trial-road preview family, so the lineup window stays authoritative here too.
    right_units = apply_previewed_enemy_types(player, right_units, "screwup")
    won, lp, rp = resolve_battle(left_units, right_units)
    rounds = simulate_battle(left_units, right_units, won) \
        if (left_units and right_units) else []
    replay_bytes = encode_fight_replay(rounds)
    reward_items = (lvl_data["first"] if is_new else lvl_data["sweep"]) if won else []
    report = build_fight_report(player, 0, 0, stage_id, won, reward_items, is_new,
                                left_units, right_units, replay_bytes, card_exp_gain=0,
                                fight_type=11)
    fight_sc = (pb_varint_field(1, stage_id) + pb_varint_field(2, 0)
                + pb_tag(3, 2) + uvarint(len(report)) + report
                + pb_bool(4, won and is_new) + pb_bool(5, won)
                + _tr_reward_bytes(6, reward_items))
    msgs = [("PVZ.Cmd.Cmd_NewScrewUp_Fight_SC", fight_sc)]
    if won:
        player["tr_hard_current"] = stage_id
        if is_new:
            player["tr_hard_max"] = stage_id
            player["tr_hard_battles_used"] = int(player.get("tr_hard_battles_used") or 0) + 1
        store.save_player(uin, tr_hard_current=player["tr_hard_current"],
                          tr_hard_max=int(player.get("tr_hard_max") or mx),
                          tr_hard_battles_used=int(player.get("tr_hard_battles_used") or 0))
        msgs += grant_fuben_reward(player, reward_items)
        msgs.append(("PVZ.Cmd.Cmd_NewScrewUp_GetInfo_SC", make_newtrialroad_getinfo(player)))
        log.info("    NIGHTMARE: stage=%d WIN (team %d vs %d) -> cur=%d max=%d",
                 stage_id, lp, rp, player["tr_hard_current"], int(player.get("tr_hard_max") or 0))
    else:
        log.info("    NIGHTMARE: stage=%d LOSS (team %d vs %d)", stage_id, lp, rp)
    return msgs


