# ================================ VIP (会员, 3 tiers — GM-set on this private server) ================================
# VIP is a membership that grants a BUNDLE of privileges (VipInfo.txt privilegeString "id:param;..."). The
# client's PrivilegeProxy.hasPrivilege(id) simply checks the list the server sends in Cmd_PVZPrivilege_SC, and
# the badge/UI reads Cmd_VipInfo_SC (Dto_VipInfo.cardId=tier). So VIP is fully server-driven: set vip_level
# (0-3) and push both messages at login. Most privileges then work CLIENT-side (4x battle speed, sweeps, UI);
# the server delivers the rest: the exclusive Winter Melon plant (priv 41), the deployed-plant stat boosts
# (priv 25-28), and the daily energy(13)/diamond(24) gifts. Tiers: 1 阳光VIP1, 2 财富VIP2, 3 金壶VIP3.
_VIP_PLANT = 6900              # 冰冻西瓜 (Winter Melon) — the VIP3 exclusive TD plant (priv 41)
_VIP_PRIV_ENDTIME = 4102444800  # 2100-01-01 UTC — far future so privileges never read as expired
_GARDEN_AUTO_FERTILIZER_PRIV = 43  # VipPrivilegeInfo: 阳光房自动施肥
# Deployed-plant stat boost per VIP stat privilege (25-28 = the "VIP exclusive Lab tech"). Values from the
# VipPrivilegeInfo names (+atk/def/hp/ability); applied server-side like the Lab / World Tree bonuses.
_VIP_STAT_PRIV = {25: ("atk", 100), 26: ("def_", 50), 27: ("hp", 300), 28: ("ability", 50)}
_VIP_ENERGY_PRIV = 13          # daily energy gift (privilege param = amount)
_VIP_DIAMOND_PRIV = 24         # daily diamond gift (privilege param = amount)
_VIP_PLANT_PRIV = 41           # TD exclusive plant (Winter Melon)
_VIP_TIERS = None


def load_vip_tiers():
    """{level: {cardId, name, price, privileges:{id:param}, gift:[(id,n)]}} for the 3 PAID VIP tiers
    (vipType=1) from clientDB VipInfo.txt. privilegeString 'id:param;...' -> {id:param}."""
    global _VIP_TIERS
    if _VIP_TIERS is None:
        _VIP_TIERS = {}
        rows = _read_clientdb_table("VipInfo.txt")
        if rows:
            hdr = rows[0]; ci = {c: i for i, c in enumerate(hdr)}

            def col(r, k):
                i = ci.get(k)
                return r[i] if i is not None and i < len(r) else ""

            def parse_privs(s):
                out = {}
                for p in (s or "").split(";"):
                    if ":" in p:
                        a, b = p.split(":", 1)
                        try:
                            out[int(a)] = int(b)
                        except ValueError:
                            pass
                return out
            for r in rows[1:]:
                if col(r, "vipType") != "1":       # paid tiers only (levels 1/2/3)
                    continue
                try:
                    lvl = int(col(r, "level"))
                except ValueError:
                    continue
                _VIP_TIERS[lvl] = {
                    "cardId": int(col(r, "id")), "name": col(r, "name"),
                    "price": int(float(col(r, "price") or 0)),
                    "privileges": parse_privs(col(r, "privilegeString")),
                    "gift": _tr_parse_reward(col(r, "giftString")),   # giftString also uses ; / , item lists
                }
        log.info("loaded %d VIP tiers", len(_VIP_TIERS))
    return _VIP_TIERS


def vip_tier(player):
    """The tier dict for the player's vip_level, or None (no VIP)."""
    lvl = int(player.get("vip_level") or 0)
    return load_vip_tiers().get(lvl) if lvl else None


def vip_privileges(player):
    """{privilegeId: param} the player currently has from their VIP tier ({} if not VIP)."""
    t = vip_tier(player)
    return t["privileges"] if t else {}


def vip_stat_bonus(player):
    """Deployed-plant stat boost from the player's VIP stat privileges (25-28). {atk,def_,hp,ability}."""
    bonus = {"atk": 0, "def_": 0, "hp": 0, "ability": 0}
    privs = vip_privileges(player)
    for pid, (field, val) in _VIP_STAT_PRIV.items():
        if pid in privs:
            bonus[field] += val
    return bonus


def _vip_daily_reset(player):
    """Reset the per-day VIP gift flags (energy/diamond) when the calendar day rolls over."""
    today = time.strftime("%Y%m%d")
    if (player.get("vip_day") or "") != today:
        player["vip_energy_taken"], player["vip_ticket_taken"], player["vip_day"] = 0, 0, today
        store.save_player(player["uin"], vip_energy_taken=0, vip_ticket_taken=0, vip_day=today)


def build_pvzprivilege_sc(player):
    """Cmd_PVZPrivilege_SC{privilege(1)=[Dto_PVZPrivilege{privilegeId(1),privilegeParam(2),endTime(3)}]}.
    The list the client's hasPrivilege() checks — send the whole tier's privilege set. Empty for non-VIP."""
    d = b""
    privileges = dict(vip_privileges(player))
    # This is an offline/private build with no payment service.  Expose only
    # the garden auto-fertilizer switch to every local account so the client
    # does not block the checkbox before sending the garden command.  Other VIP
    # features remain governed by the normal VIP table.
    privileges.setdefault(_GARDEN_AUTO_FERTILIZER_PRIV, 0)
    for pid, param in sorted(privileges.items()):
        dto = (pb_varint_field(1, pid) + pb_varint_field(2, param)
               + pb_varint_field(3, _VIP_PRIV_ENDTIME))
        d += pb_tag(1, 2) + uvarint(len(dto)) + dto
    return d


def build_vipinfo_sc(player):
    """Cmd_VipInfo_SC{vipInfo(1)=Dto_VipInfo}. Dto_VipInfo{cardId(1),endTime(2),gotGift(3),todayEnergy(4),
    renewalPrice(5),type(6),bHasVip3Privilege(7),todayTicket(8),hasTakenEnergy(9),hasTakenTicket(10),
    hasRenewGift(11)}. cardId=0 => no VIP."""
    _vip_daily_reset(player)
    t = vip_tier(player)
    if not t:
        info = pb_varint_field(1, 0) + pb_varint_field(6, 0)
        return pb_tag(1, 2) + uvarint(len(info)) + info
    privs = t["privileges"]
    lvl = int(player.get("vip_level") or 0)
    info = (pb_varint_field(1, t["cardId"])                            # cardId (the tier)
            + pb_varint_field(2, _VIP_PRIV_ENDTIME)                    # endTime
            + pb_varint_field(3, int(player.get("vip_gift_taken") or 0))       # gotGift (activation gift)
            + pb_varint_field(4, privs.get(_VIP_ENERGY_PRIV, 0))              # todayEnergy amount
            + pb_varint_field(5, t["price"])                          # renewalPrice
            + pb_varint_field(6, 1)                                   # type = paid
            + pb_varint_field(7, 1 if lvl >= 3 else 0)                # bHasVip3Privilege
            + pb_varint_field(8, privs.get(_VIP_DIAMOND_PRIV, 0))            # todayTicket amount
            + pb_varint_field(9, int(player.get("vip_energy_taken") or 0))    # hasTakenEnergy
            + pb_varint_field(10, int(player.get("vip_ticket_taken") or 0))   # hasTakenTicket
            + pb_varint_field(11, 0))                                 # hasRenewGift
    return pb_tag(1, 2) + uvarint(len(info)) + info


def vip_login_messages(player):
    """The VIP state pushed right after Cmd_Init_SC: the privilege list (populates hasPrivilege) + the VIP
    info (badge/tier UI). Sent for everyone (non-VIP gets an empty list + cardId 0)."""
    _vip_daily_reset(player)
    return [("PVZ.Cmd.Cmd_PVZPrivilege_SC", build_pvzprivilege_sc(player)),
            ("PVZ.Cmd.Cmd_VipInfo_SC", build_vipinfo_sc(player))]


def handle_vip_getinfo(cmd_data, player):
    """Cmd_VipInfo_CS -> Cmd_VipInfo_SC (when the VIP window opens / refreshes)."""
    return [("PVZ.Cmd.Cmd_VipInfo_SC", build_vipinfo_sc(player))]


def handle_pvzprivilege_getinfo(cmd_data, player):
    """Cmd_PVZPrivilege_CS -> Cmd_PVZPrivilege_SC (client re-requesting the privilege list)."""
    return [("PVZ.Cmd.Cmd_PVZPrivilege_SC", build_pvzprivilege_sc(player))]


def handle_vip_getgift(cmd_data, player):
    """Cmd_VipGetGift_CS -> Cmd_VipGetGift_SC{itemList} — the one-time first-activation gift (giftString)."""
    t = vip_tier(player)
    if not t or not t["gift"] or int(player.get("vip_gift_taken") or 0):
        return []
    player["vip_gift_taken"] = 1
    store.save_player(player["uin"], vip_gift_taken=1)
    body = b""
    for iid, num in t["gift"]:
        dto = build_item_dto(iid, num)
        body += pb_tag(1, 2) + uvarint(len(dto)) + dto              # itemList
    msgs = [("PVZ.Cmd.Cmd_VipGetGift_SC", body)]
    msgs += grant_fuben_reward(player, t["gift"])
    msgs.append(("PVZ.Cmd.Cmd_VipInfo_SC", build_vipinfo_sc(player)))
    log.info("    VIP activation gift claimed (uin=%d tier=%d): %s", player["uin"], player["vip_level"], t["gift"])
    return msgs


def handle_vip_gettodayenergy(cmd_data, player):
    """Cmd_Vip_GetTodayEnergy_CS -> claim the daily VIP energy gift (priv 13 param) + SyncEnergy + VipInfo."""
    _vip_daily_reset(player)
    amt = vip_privileges(player).get(_VIP_ENERGY_PRIV, 0)
    if not amt or int(player.get("vip_energy_taken") or 0):
        return [("PVZ.Cmd.Cmd_Vip_GetTodayEnergy_SC", b"")]
    player["vip_energy_taken"] = 1
    player["energy"] = current_energy(player) + amt        # fold regen in first, then add (may overflow cap)
    store.save_player(player["uin"], vip_energy_taken=1, energy=player["energy"])
    log.info("    VIP daily energy gift: +%d energy (uin=%d)", amt, player["uin"])
    return [("PVZ.Cmd.Cmd_Vip_GetTodayEnergy_SC", b""),
            ("PVZ.Cmd.Cmd_SyncEnergy_SC", pb_varint_field(1, player["energy"])),
            ("PVZ.Cmd.Cmd_VipInfo_SC", build_vipinfo_sc(player))]


def handle_vip_gettodayticket(cmd_data, player):
    """Cmd_Vip_GetTodayTicket_CS -> claim the daily VIP diamond gift (priv 24 param, item 4) + VipInfo."""
    _vip_daily_reset(player)
    amt = vip_privileges(player).get(_VIP_DIAMOND_PRIV, 0)
    if not amt or int(player.get("vip_ticket_taken") or 0):
        return [("PVZ.Cmd.Cmd_Vip_GetTodayTicket_SC", b"")]
    player["vip_ticket_taken"] = 1
    store.save_player(player["uin"], vip_ticket_taken=1)
    log.info("    VIP daily diamond gift: +%d diamond (uin=%d)", amt, player["uin"])
    msgs = [("PVZ.Cmd.Cmd_Vip_GetTodayTicket_SC", b"")]
    msgs += grant_fuben_reward(player, [(4, amt)])   # item 4 = gift diamond (present_ticket)
    msgs.append(("PVZ.Cmd.Cmd_VipInfo_SC", build_vipinfo_sc(player)))
    return msgs


# ============================ Nutrition Room (营养室, Building_Nutrition=170) ============================
# A reagent (试剂) system that grants flat combat stats to the deployed team, like the Lab/World Tree.
# TWO entry points, both driving ModuleNutrition/ModuleNutritionExchange:
#   - Building 170 (gotoNutrition, L22): the full room = OBTAIN view (click a "dietician plant" to CALL a
#     reagent into a temp bag, then collect it) + USE view (equip owned reagents onto the 7 plant positions).
#   - The Player's House 营养 button (NutritionExchangeViewCmd): a "Fast Exchange" that bulk-swaps all the
#     reagents equipped on one plant position with another (Cmd_Nutrition_ExchangePosition).
# Reagent baseId = 60<tier><stat> (tier 1..5 = quality 2..6/green..red; stat 1..8 = ATK/DEF/HP/ABILITY/
# HIT/DODGE/CRIT/TOUGH). nutritionProperty.txt maps (baseId, level) -> propertyType(=buffType)/quality/
# propertyValue(=buffValue). buffValue is /_NUTRITION_SCALE(100) to a stat point, same scale as the Lab, so
# equipping a green ATK reagent = +220 atk on every deployed plant. 7 positions x 8 grids (grids 5-8 unlock
# at role level 20/25/30/35). A plant can't hold two reagents of the same stat type.
_NUTRITION_SCALE = 100
_NUTRITION_POSITIONS = [3, 7, 9, 11, 13, 15, 17]     # the 7 left/plant embattle positions
_NUTRITION_SLOT_LEVELS = {5: 20, 6: 25, 7: 30, 8: 35}  # grids 1-4 free; 5-8 role-level gated
_NUTRITION_TEMP_MAX = 14                              # CONST_TEMP_BAG_BOUNDS
_NUTRITION_BAG_MAX = 18                               # NUTRITION_USE_BAG_MAX (unequipped reagents)
_NUTRITION_GOLD_REAGENT = 60000                       # CONST_GOLD_REAGENT (exchange currency)
_NUTRITION_WHITE_RESIDUAL = 60001                     # CONST_WHITE_RESIDUAL (junk -> bottle exp)
_NUTRITION_STAT_FIELDS = {1: "atk", 2: "def_", 3: "hp", 5: "ability",
                          6: "hit", 7: "dodge", 8: "critical", 9: "tough"}
# Per-dietician quality tier weights (higher dietician/cost -> better reagents). tier -> baseId 60<tier>0<stat>.
_NUTRITION_DIETICIAN_TIERS = {
    1: [(1, 90), (2, 10)],
    2: [(1, 55), (2, 40), (3, 5)],
    3: [(2, 50), (3, 40), (4, 10)],
    4: [(3, 50), (4, 40), (5, 10)],
    5: [(4, 45), (5, 55)],
    6: [(4, 30), (5, 70)],
}
_NUTRITION_OBTAIN = None
_NUTRITION_PROP = None


def _nut_cost(spec):
    """Parse an 'id:num;id:num' cost/need string into [(itemId, num)]."""
    out = []
    for part in (spec or "").replace(" ", "").split(";"):
        if ":" in part:
            a, b = part.split(":", 1)
            try:
                out.append((int(a), int(b)))
            except ValueError:
                pass
    return out


def load_nutrition_obtain():
    """{dieticianId: {cost:[(iid,num)], spCost:[(iid,num)]}} from nutritionObtain.txt (6 dieticians)."""
    global _NUTRITION_OBTAIN
    if _NUTRITION_OBTAIN is None:
        _NUTRITION_OBTAIN = {}
        rows = _read_clientdb_table("nutritionObtain.txt")
        if rows:
            hdr = rows[0]; ci = {c: i for i, c in enumerate(hdr)}

            def col(r, k):
                i = ci.get(k)
                return r[i] if i is not None and i < len(r) else ""
            for r in rows[1:]:
                try:
                    did = int(col(r, "id"))
                except ValueError:
                    continue
                _NUTRITION_OBTAIN[did] = {"cost": _nut_cost(col(r, "originalCost")),
                                          "spCost": _nut_cost(col(r, "originalSpCost"))}
        log.info("loaded %d nutrition dieticians", len(_NUTRITION_OBTAIN))
    return _NUTRITION_OBTAIN


def load_nutrition_property():
    """{baseId: {type, quality, levels:{lv:(value,exp,needExp)}, maxlv}} from nutritionProperty.txt."""
    global _NUTRITION_PROP
    if _NUTRITION_PROP is None:
        _NUTRITION_PROP = {}
        rows = _read_clientdb_table("nutritionProperty.txt")
        if rows:
            hdr = rows[0]; ci = {c: i for i, c in enumerate(hdr)}

            def col(r, k):
                i = ci.get(k)
                return r[i] if i is not None and i < len(r) else "0"
            for r in rows[1:]:
                try:
                    bid = int(col(r, "itemID")); lv = int(col(r, "level"))
                    pt = int(col(r, "propertyType")); q = int(col(r, "quality"))
                    pv = int(col(r, "propertyValue")); ex = int(col(r, "exp")); ne = int(col(r, "needExp"))
                except ValueError:
                    continue
                d = _NUTRITION_PROP.setdefault(bid, {"type": pt, "quality": q, "levels": {}, "maxlv": 1})
                d["type"] = pt; d["quality"] = q
                d["levels"][lv] = (pv, ex, ne)
                d["maxlv"] = max(d["maxlv"], lv)
        log.info("loaded %d nutrition reagent bases", len(_NUTRITION_PROP))
    return _NUTRITION_PROP


def _reagent_props(base_id, level):
    """(buffType, buffValue, quality) for a reagent at `level` (clamped to its maxlv)."""
    d = load_nutrition_property().get(base_id)
    if not d:
        return (0, 0, 1)
    lv = max(1, min(int(level), d["maxlv"]))
    pv = d["levels"].get(lv, d["levels"].get(1, (0, 0, 0)))[0]
    return (d["type"], pv, d["quality"])


def _reagent_fight_power(base_id, level):
    """A reagent's contribution to the 战力 display (buffValue folded to the stat-point scale)."""
    _, bv, _ = _reagent_props(base_id, level)
    return max(1, bv // _NUTRITION_SCALE)


def _is_real_reagent(base_id):
    """True for an equippable reagent (not the gold/white-residual currencies, and a known stat type)."""
    if base_id in (_NUTRITION_GOLD_REAGENT, _NUTRITION_WHITE_RESIDUAL):
        return False
    d = load_nutrition_property().get(base_id)
    return bool(d) and d["type"] != 0


def _encode_reagent_dto(r):
    """Dto_Reagent from a stored {uid, base_id, level, position, slot_id}."""
    bt, bv, q = _reagent_props(r["base_id"], r["level"])
    body = pb_int64_field(1, r["uid"])
    body += pb_varint_field(2, r["base_id"])
    body += pb_varint_field(3, q)
    body += pb_varint_field(4, max(1, int(r["level"])))
    body += pb_varint_field(5, max(0, int(r.get('exp') or 0))) # persisted merge progress
    body += pb_varint_field(6, bt)                              # buffType
    body += pb_varint_field(7, bv)                              # buffValue
    body += pb_varint_field(8, r["position"])
    body += pb_varint_field(9, r["slot_id"])
    body += pb_varint_field(10, _reagent_fight_power(r["base_id"], r["level"]))
    return body


def nutrition_stat_bonus(player):
    """The all-deployed-plant bonus from equipped reagents.

    Primary attributes are centi-units; hit/dodge/critical/tough are already
    basis points in nutritionProperty and battleCard, so retain their value.
    """
    bonus = {field: 0 for field in ("atk", "def_", "hp", "ability",
                                   "hit", "dodge", "critical", "tough")}
    uin = player.get("uin")
    if not uin:
        return bonus
    for r in store.get_reagents(uin):
        if r["slot_id"] <= 0 or r["position"] <= 0:
            continue
        bt, bv, _ = _reagent_props(r["base_id"], r["level"])
        field = _NUTRITION_STAT_FIELDS.get(bt)
        if field:
            bonus[field] += bv if field in ("hit", "dodge", "critical", "tough") \
                else bv // _NUTRITION_SCALE
    return bonus


def _nutrition_roll(dietician_id):
    """Roll one reagent baseId from a dietician: pick a quality tier by that dietician's weights, then a
    uniform stat type. baseId = 60<tier>0<stat>."""
    tiers = _NUTRITION_DIETICIAN_TIERS.get(dietician_id, [(1, 100)])
    total = sum(w for _, w in tiers)
    pick = random.randint(1, total)
    tier, acc = tiers[-1][0], 0
    for t, w in tiers:
        acc += w
        if pick <= acc:
            tier = t
            break
    stat = random.randint(1, 8)
    return 60000 + tier * 100 + stat


def _nutrition_temp_list(player):
    return [int(p) for p in (player.get("nutrition_temp") or "").split(",") if p.strip().isdigit()]


def _nutrition_save_temp(player, lst):
    player["nutrition_temp"] = ",".join(str(x) for x in lst)
    store.save_player(player["uin"], nutrition_temp=player["nutrition_temp"])


def _nutrition_bag_count(player):
    return sum(1 for r in store.get_reagents(player["uin"]) if r["slot_id"] == 0 and r["position"] == 0)


def _nutrition_bank_reagent(player, base_id):
    """Move one collected temp-bag baseId into permanent state: real reagent -> a new owned reagent
    (level 1, in the bag); gold (60000) -> gold pool; white residual/junk -> bottle-exp pool."""
    if base_id == _NUTRITION_GOLD_REAGENT:
        player["nutrition_gold"] = int(player.get("nutrition_gold") or 0) + 1
        store.save_player(player["uin"], nutrition_gold=player["nutrition_gold"])
        return
    if not _is_real_reagent(base_id):
        add = load_nutrition_property().get(base_id, {}).get("levels", {}).get(1, (0, 5, 0))[1] or 5
        player["nutrition_bottle_exp"] = int(player.get("nutrition_bottle_exp") or 0) + add
        store.save_player(player["uin"], nutrition_bottle_exp=player["nutrition_bottle_exp"])
        return
    uid = store.next_reagent_uid(player["uin"])
    store.add_reagent(player["uin"], uid, base_id, level=1, position=0, slot_id=0)


def handle_nutrition_gettempbag(cmd_data, player):
    """Cmd_Nutrition_GetTempBag_CS -> the obtain view's state. activateList MUST be non-empty or the
    obtain view's onListChange null-derefs the "last activatable" plant (#1009), so send every dietician."""
    load_nutrition_obtain()
    body = b"".join(pb_varint_field(1, bid) for bid in _nutrition_temp_list(player))   # reagentList (baseIds)
    body += pb_varint_field(2, int(player.get("nutrition_bottle_exp") or 0))            # bottleExp
    for did in sorted(load_nutrition_obtain()):                                         # activateList
        body += pb_varint_field(3, did)
    body += pb_varint_field(4, int(player.get("nutrition_gold") or 0))                  # goldReagentNum
    return [("PVZ.Cmd.Cmd_Nutrition_GetTempBag_SC", body)]


def handle_nutrition_normalcall(cmd_data, player):
    """Cmd_Nutrition_NormalCall_CS{dieticianId} -> spend that dietician's coin cost, roll a reagent into
    the temp bag. Can't-afford / full temp bag = silent no-op (the client's auto-call already stops broke)."""
    did = parse_varint_fields(cmd_data).get(1, 0)
    dinfo = load_nutrition_obtain().get(did)
    if not dinfo:
        return []
    temp = _nutrition_temp_list(player)
    if len(temp) >= _NUTRITION_TEMP_MAX or not _lab_afford(player, dinfo["cost"]):
        return []
    charge = _lab_charge(player, dinfo["cost"])
    base_id = _nutrition_roll(did)
    temp.append(base_id)
    _nutrition_save_temp(player, temp)
    body = pb_varint_field(1, did)                                                      # dieticianId
    for d2 in sorted(load_nutrition_obtain()):                                          # activateList
        body += pb_varint_field(2, d2)
    body += pb_varint_field(3, base_id)                                                 # reagent
    body += pb_varint_field(4, int(player.get("nutrition_gold") or 0))                  # goldReagentNum
    log.info("    nutrition: dietician %d call -> reagent %d (uin=%d)", did, base_id, player["uin"])
    return [("PVZ.Cmd.Cmd_Nutrition_NormalCall_SC", body)] + charge + _quest_record_condition(
        player, 45, 0, 1)


def handle_nutrition_collect(cmd_data, player):
    """Cmd_Nutrition_Collect_CS{baseId, bagIndex} -> bank one temp-bag reagent into the owned bag."""
    f = parse_varint_fields(cmd_data)
    base_id, bag_index = f.get(1, 0), f.get(2, 0)
    temp = _nutrition_temp_list(player)
    if bag_index < 0 or bag_index >= len(temp) or temp[bag_index] != base_id:
        return []                                          # stale index (client resyncs on reopen)
    temp.pop(bag_index)
    _nutrition_save_temp(player, temp)
    _nutrition_bank_reagent(player, base_id)
    _daily_quest_touch(player, "nutrition", 1)
    body = (pb_varint_field(1, base_id) + pb_varint_field(2, bag_index) +
            pb_varint_field(3, int(player.get("nutrition_gold") or 0)))
    return [("PVZ.Cmd.Cmd_Nutrition_Collect_SC", body)]


def handle_nutrition_collectall(cmd_data, player):
    """Cmd_Nutrition_CollectAll_CS -> bank every temp-bag reagent (up to the 18-reagent bag cap; leftover
    stays in the temp bag). remainReagent = the baseIds not collected."""
    temp = _nutrition_temp_list(player)
    remain, count = [], _nutrition_bag_count(player)
    for base_id in temp:
        if _is_real_reagent(base_id):
            if count >= _NUTRITION_BAG_MAX:
                remain.append(base_id)
                continue
            _nutrition_bank_reagent(player, base_id)
            count += 1
        else:
            _nutrition_bank_reagent(player, base_id)
    _nutrition_save_temp(player, remain)
    if count:
        _daily_quest_touch(player, "nutrition", 1)
    body = pb_varint_field(1, int(player.get("nutrition_gold") or 0))                   # goldReagentNum
    for bid in remain:
        body += pb_varint_field(2, bid)                                                 # remainReagent
    body += pb_varint_field(3, 0)                                                       # stopReason (no popup)
    return [("PVZ.Cmd.Cmd_Nutrition_CollectAll_SC", body)]


def handle_nutrition_getreagentall(cmd_data, player):
    """Cmd_Nutrition_GetReagentAll_CS -> the full owned-reagent list (used by the Use view AND the house
    Fast Exchange window)."""
    body = b""
    for r in store.get_reagents(player["uin"]):
        dto = _encode_reagent_dto(r)
        body += pb_tag(1, 2) + uvarint(len(dto)) + dto                                  # reagentList (message)
    body += pb_varint_field(2, int(player.get("nutrition_bottle_exp") or 0))            # bottleExp
    return [("PVZ.Cmd.Cmd_Nutrition_GetReagentAll_SC", body)]


def handle_nutrition_equipreagent(cmd_data, player):
    """Cmd_Nutrition_EquipReagent_CS{reagentUID, position, slotId} -> equip a reagent onto a plant slot.
    Guards: valid position/slot, slot level-unlocked, slot free, no duplicate stat type on that plant."""
    f = parse_varint_fields(cmd_data)
    uid, position, slot_id = f.get(1, 0), f.get(2, 0), f.get(3, 0)
    if position not in _NUTRITION_POSITIONS or not (1 <= slot_id <= 8):
        return []
    if int(player.get("level", 1)) < _NUTRITION_SLOT_LEVELS.get(slot_id, 0):
        return []                                          # grid still level-locked
    reagents = {r["uid"]: r for r in store.get_reagents(player["uin"])}
    r = reagents.get(uid)
    if not r:
        return []
    bt, _, _ = _reagent_props(r["base_id"], r["level"])
    for other in reagents.values():
        if other["uid"] == uid or other["position"] != position:
            continue
        if other["slot_id"] == slot_id:
            return []                                      # target grid occupied
        if _reagent_props(other["base_id"], other["level"])[0] == bt:
            return []                                      # same stat type already on this plant
    store.set_reagent_pos(player["uin"], uid, position, slot_id)
    slot = pb_varint_field(1, position) + pb_int64_field(2, uid) + pb_varint_field(3, slot_id)
    body = pb_tag(1, 2) + uvarint(len(slot)) + slot                                     # slotInfo (message)
    body += pb_varint_field(2, int(player.get("nutrition_bottle_exp") or 0))            # bottleExp
    log.info("    nutrition: equip reagent %d -> pos %d slot %d (uin=%d)", uid, position, slot_id, player["uin"])
    return [("PVZ.Cmd.Cmd_Nutrition_EquipReagent_SC", body)] + _quest_record_condition(
        player, 36, 0, 1)


def handle_nutrition_unequipreagent(cmd_data, player):
    """Cmd_Nutrition_UnEquipReagent_CS{reagentUID, ...} -> move a reagent back to the bag."""
    uid = parse_varint_fields(cmd_data).get(1, 0)
    if not any(r["uid"] == uid for r in store.get_reagents(player["uin"])):
        return []
    store.set_reagent_pos(player["uin"], uid, 0, 0)
    body = pb_int64_field(1, uid) + pb_varint_field(2, 1)                               # reagentUID + result
    return [("PVZ.Cmd.Cmd_Nutrition_UnEquipReagent_SC", body)]


def _nutrition_exchange_table():
    """Return the real nutritionExchange.txt offers: exchange ID -> (base ID, gold cost)."""
    rows = _read_clientdb_table("nutritionExchange.txt")
    if not rows:
        return {}
    header = {name: i for i, name in enumerate(rows[0])}
    result = {}
    for row in rows[1:]:
        try:
            exchange_id = int(row[header["id"]])
            base_id = int(row[header["itemID"]])
            needs = _nut_cost(row[header["originalNeed"]])
            if len(needs) == 1 and needs[0][0] == _NUTRITION_GOLD_REAGENT and _is_real_reagent(base_id):
                result[exchange_id] = (base_id, needs[0][1])
        except (ValueError, IndexError, KeyError):
            continue
    return result


def _nutrition_add_item_sync(item_id, count):
    dto = build_item_dto(item_id, count)
    return ("PVZ.Cmd.Cmd_Item_Update_SC", pb_tag(1, 2) + uvarint(len(dto)) + dto)


def _nutrition_sync_changes(changed=(), deleted=()):
    body = b""
    for reagent in changed:
        dto = _encode_reagent_dto(reagent)
        body += pb_tag(1, 2) + uvarint(len(dto)) + dto
    for uid in deleted:
        body += pb_int64_field(3, uid)
    return ("PVZ.Cmd.Cmd_Nutrition_SyncFullInfo_SC", body)


def handle_nutrition_ticketactivate(cmd_data, player):
    """Consume one nutrition ticket (2026), or the configured 200 gift diamonds, for one call."""
    temp = _nutrition_temp_list(player)
    if len(temp) >= _NUTRITION_TEMP_MAX:
        return []
    special = load_nutrition_obtain().get(5, {}).get("spCost", [])
    diamond_cost = next((amount for item_id, amount in special if item_id == 4), 200)
    base_id = _nutrition_roll(6)
    with store._db() as con:
        con.execute("BEGIN IMMEDIATE")
        row = con.execute("SELECT count FROM items WHERE uin=? AND item_id=2026", (player["uin"],)).fetchone()
        tickets = int(row[0]) if row else 0
        wallet = con.execute("SELECT present_ticket,nutrition_temp FROM players WHERE uin=?", (player["uin"],)).fetchone()
        if not wallet:
            return []
        current_temp = [int(x) for x in (wallet["nutrition_temp"] or "").split(",") if x.isdigit()]
        if len(current_temp) >= _NUTRITION_TEMP_MAX:
            return []
        if tickets > 0:
            con.execute("UPDATE items SET count=count-1 WHERE uin=? AND item_id=2026", (player["uin"],))
            pay_ticket = True
            new_present = int(wallet["present_ticket"])
        elif int(wallet["present_ticket"]) >= diamond_cost:
            con.execute("UPDATE players SET present_ticket=present_ticket-? WHERE uin=?",
                        (diamond_cost, player["uin"]))
            pay_ticket = False
            new_present = int(wallet["present_ticket"]) - diamond_cost
        else:
            return []
        current_temp.append(base_id)
        temp_text = ",".join(str(x) for x in current_temp)
        con.execute("UPDATE players SET nutrition_temp=? WHERE uin=?", (temp_text, player["uin"]))
    player["nutrition_temp"] = temp_text
    player["present_ticket"] = new_present
    messages = [_nutrition_add_item_sync(2026, tickets - 1)] if pay_ticket else [
        ("PVZ.Cmd.Cmd_SyncPresentTicket_SC", pb_varint_field(1, new_present))]
    body = b"".join(pb_varint_field(1, did) for did in sorted(load_nutrition_obtain()))
    body += pb_varint_field(2, base_id)
    messages.append(("PVZ.Cmd.Cmd_Nutrition_TicketActivate_SC", body))
    return messages


def handle_nutrition_exchange(cmd_data, player):
    """Exchange 30 gold reagents for the selected real base reagent (table-driven)."""
    exchange_id = parse_varint_fields(cmd_data).get(1, 0)
    offer = _nutrition_exchange_table().get(exchange_id)
    if not offer:
        return []
    base_id, cost = offer
    with store._db() as con:
        con.execute("BEGIN IMMEDIATE")
        row = con.execute("SELECT nutrition_gold,reagent_seq FROM players WHERE uin=?", (player["uin"],)).fetchone()
        if not row or int(row["nutrition_gold"]) < cost:
            return []
        count = con.execute("SELECT count(*) FROM reagents WHERE uin=? AND position=0 AND slot_id=0",
                            (player["uin"],)).fetchone()[0]
        if count >= _NUTRITION_BAG_MAX:
            return []
        uid = store.REAGENT_UID_BASE + int(row["reagent_seq"]) + 1
        gold = int(row["nutrition_gold"]) - cost
        con.execute("UPDATE players SET nutrition_gold=?, reagent_seq=reagent_seq+1 WHERE uin=?",
                    (gold, player["uin"]))
        con.execute("INSERT INTO reagents (uin,uid,base_id,level,exp,position,slot_id) VALUES (?,?,?,?,?,?,?)",
                    (player["uin"], uid, base_id, 1, 0, 0, 0))
    player["nutrition_gold"] = gold
    body = pb_varint_field(1, exchange_id) + pb_varint_field(2, uid) + pb_varint_field(3, gold)
    return [("PVZ.Cmd.Cmd_Nutrition_Exchange_SC", body)] + handle_nutrition_getreagentall(b"", player)


def handle_nutrition_supertrade(cmd_data, player):
    """Bulk-brew reagents, extracting only the qualities selected in the client.

    The three ``changeType`` values mean decompose green/blue, through purple,
    or through orange respectively.  The result window reports *kept* reagent
    counts and says they are available in the reagent bag, so they must be
    persisted rather than only listed in the reply.  The original server's
    exact random rates are unavailable; keep the existing local roll and
    10,000-coin-per-call approximation while respecting those client rules.
    """
    fields = parse_varint_fields(cmd_data)
    costs = {1: 200000, 2: 500000, 3: 1000000}
    requested_cost = costs.get(fields.get(1, 0))
    change_type = fields.get(2, 0)
    if requested_cost is None or change_type not in (3, 4, 5):
        return [puppet_error(6316)]
    properties = load_nutrition_property()
    kept = []
    quality_counts = {}
    exp_gain = 0
    with store._db() as con:
        con.execute("BEGIN IMMEDIATE")
        row = con.execute("SELECT coin,nutrition_gold,nutrition_bottle_exp,reagent_seq FROM players WHERE uin=?",
                          (player["uin"],)).fetchone()
        if not row:
            return [puppet_error(6316)]
        if int(row["coin"]) < requested_cost:
            return [puppet_error(202)]
        bag_count = con.execute(
            "SELECT count(*) FROM reagents WHERE uin=? AND position=0 AND slot_id=0",
            (player["uin"],)).fetchone()[0]
        attempts = 0
        stop_reason = 0
        for _ in range(requested_cost // 10000):
            base_id = _nutrition_roll(change_type)
            info = properties.get(base_id)
            if not info:
                continue
            quality = int(info["quality"])
            # SuperTrade can still dissolve selected low-quality results when the
            # reagent bag is full. Stop only when a result that must be retained
            # cannot fit; do not charge for that rejected roll.
            if quality > change_type and bag_count >= _NUTRITION_BAG_MAX:
                stop_reason = 6301
                break
            attempts += 1
            if quality <= change_type:
                exp_gain += int(info["levels"][1][1])
            else:
                kept.append(base_id)
                quality_counts[quality] = quality_counts.get(quality, 0) + 1
                bag_count += 1
        if not attempts:
            return [puppet_error(stop_reason or 6316)]
        cost = attempts * 10000
        gold_gain = attempts // 10
        old_exp = int(row["nutrition_bottle_exp"])
        new_exp = old_exp + exp_gain
        new_gold = int(row["nutrition_gold"]) + gold_gain
        new_coin = int(row["coin"]) - cost
        seq = int(row["reagent_seq"])
        for base_id in kept:
            seq += 1
            uid = store.REAGENT_UID_BASE + seq
            con.execute("INSERT INTO reagents (uin,uid,base_id,level,exp,position,slot_id) "
                        "VALUES (?,?,?,?,?,?,?)", (player["uin"], uid, base_id, 1, 0, 0, 0))
        con.execute("UPDATE players SET coin=?,nutrition_gold=?,nutrition_bottle_exp=?,reagent_seq=? "
                    "WHERE uin=?", (new_coin, new_gold, new_exp, seq, player["uin"]))
    player.update(coin=new_coin, nutrition_gold=new_gold, nutrition_bottle_exp=new_exp)
    body = (pb_varint_field(1, old_exp) + pb_varint_field(2, new_exp) +
            pb_varint_field(3, new_gold) + pb_varint_field(4, cost))
    for quality, amount in sorted(quality_counts.items()):
        pair = pb_varint_field(1, quality) + pb_varint_field(2, amount)
        body += pb_tag(5, 2) + uvarint(len(pair)) + pair
    body += pb_varint_field(6, stop_reason)
    for did in sorted(load_nutrition_obtain()):
        body += pb_varint_field(7, did)
    messages = [("PVZ.Cmd.Cmd_SyncCoin_SC", pb_varint_field(1, new_coin)),
                ("PVZ.Cmd.Cmd_Nutrition_SuperTrade_SC", body)]
    # The result panel and the reagent bag have separate client models.
    # Refresh the latter so reopening the bag immediately shows kept reagents.
    messages.extend(handle_nutrition_getreagentall(b"", player))
    if stop_reason:
        # The client displays a result only on SuperTrade_SC; LogicError_SC on
        # its own makes the confirmation window close without any result panel.
        messages.append(puppet_error(stop_reason))
    return messages


def handle_nutrition_merge(cmd_data, player):
    """Merge the weaker reagent into the stronger, preserving partial exp across relogins."""
    fields = parse_varint_fields(cmd_data)
    source_uid, dest_uid = fields.get(1, 0), fields.get(2, 0)
    if source_uid <= 0 or dest_uid <= 0 or source_uid == dest_uid:
        return []
    with store._db() as con:
        con.execute("BEGIN IMMEDIATE")
        rows = [dict(r) for r in con.execute(
            "SELECT uid,base_id,level,exp,position,slot_id FROM reagents WHERE uin=? AND uid IN (?,?)",
            (player["uin"], source_uid, dest_uid))]
        if len(rows) != 2:
            return []
        by_uid = {r["uid"]: r for r in rows}
        source, dest = by_uid[source_uid], by_uid[dest_uid]
        # Both on-field reagents may be dragged together, but never consume a reagent
        # from a different plant position while its slot still displays it.
        if source["position"] and dest["position"] and source["position"] != dest["position"]:
            return []
        source_rank = (_reagent_props(source["base_id"], source["level"])[2], source["level"])
        dest_rank = (_reagent_props(dest["base_id"], dest["level"])[2], dest["level"])
        survivor, consumed = (source, dest) if source_rank > dest_rank else (dest, source)
        prop = load_nutrition_property().get(survivor["base_id"])
        old_level = int(survivor["level"])
        exp = int(survivor.get("exp") or 0) + _nutrition_reagent_exp(consumed) + int(consumed.get("exp") or 0)
        level = old_level
        while level < int(prop["maxlv"]):
            need = int(prop["levels"][level][2])
            if need <= 0 or exp < need:
                break
            exp -= need
            level += 1
        if level >= int(prop["maxlv"]):
            exp = 0
        con.execute("UPDATE reagents SET level=?,exp=? WHERE uin=? AND uid=?",
                    (level, exp, player["uin"], survivor["uid"]))
        con.execute("DELETE FROM reagents WHERE uin=? AND uid=?", (player["uin"], consumed["uid"]))
    survivor.update(level=level, exp=exp)
    dto = _encode_reagent_dto(survivor)
    merge_body = pb_tag(1, 2) + uvarint(len(dto)) + dto + pb_varint_field(2, int(player.get("nutrition_bottle_exp") or 0))
    return [_nutrition_sync_changes([survivor], [consumed["uid"]]),
            ("PVZ.Cmd.Cmd_Nutrition_Merge_SC", merge_body)]


def handle_nutrition_noop(cmd_data, player):
    """Deferred Nutrition sub-actions (分解/合成/升级/兑换/提取经验/VIP超级召唤/门票召唤). Reply with NOTHING
    so the button is cleanly inert — a generic empty SC would instead insert a phantom reagent (TicketActivate)
    or clear the temp-bag display (ChangeAll). The core call/collect/equip loop + Fast Exchange are real."""
    return []


# --- low-coupling daily systems migrated from the community build -----------
def _load_json_state(player, field, default):
    raw = player.get(field) or ""
    if raw:
        try:
            value = json.loads(raw)
            if isinstance(value, dict):
                return value
        except (TypeError, ValueError):
            pass
    return dict(default)


def _save_json_state(player, field, value):
    raw = json.dumps(value, ensure_ascii=False, separators=(",", ":"))
    player[field] = raw
    store.save_player(player["uin"], **{field: raw})


# Online reward --------------------------------------------------------------
# onlineDailyReward.txt in clientDB defines five milestones: 5/10/15/20/30
# minutes.  The previous port returned one Dto_OnlineReward only, and deducted
# the time after claiming it, so the Flash panel could never unlock rows 2-5.
# Keep the original five-minute reward intact and provide deterministic local
# rewards for the remaining milestones (the original server-side reward table
# is not present in this PoC build).
ONLINE_REWARD_INTERVAL = 300  # compatibility alias: the first milestone
ONLINE_REWARD_ITEMS = [(1, 5000), (1041, 1), (4, 50)]
ONLINE_REWARD_SPECS = (
    (1, 300, ((1, 5000), (1041, 1), (4, 50))),
    (2, 600, ((1, 8000), (1041, 1), (4, 80))),
    (3, 900, ((1, 12000), (1041, 2), (4, 100))),
    (4, 1200, ((1, 16000), (2003, 1), (4, 120))),
    (5, 1800, ((1, 25000), (1041, 3), (4, 150))),
)


def _online_reward_data(player):
    return _load_json_state(player, "online_reward_data", {
        "day": "", "last_touch": 0, "daily_time": 0,
        "weekly_time": 0, "last_reward_time": 0, "claimed_ids": [],
    })


def _online_reward_touch(player, now=None):
    """Accumulate elapsed wall time between requests, bounded to one hour.

    The client asks for the panel on login and when opening the reward window, so
    this remains useful without a background task and does not award time while
    the server is stopped for days.
    """
    now = int(now or time.time())
    data = _online_reward_data(player)
    today = time.strftime("%Y%m%d", time.localtime(now))
    legacy_single_tier = "claimed_ids" not in data
    if data.get("day") != today:
        data.update({"day": today, "daily_time": 0, "last_reward_time": 0,
                     "claimed_ids": []})
    elif legacy_single_tier:
        # The former implementation subtracted five minutes whenever the only
        # reward was claimed.  Preserve that player's progress as at least the
        # first milestone and mark it claimed, so the new panel exposes the
        # following tiers immediately instead of making the player start over.
        data["claimed_ids"] = []
        if int(data.get("last_reward_time") or 0) > 0:
            data["claimed_ids"] = [1]
            data["daily_time"] = min(86400, int(data.get("daily_time") or 0) + ONLINE_REWARD_INTERVAL)
    # Migrate the single-tier state written by the previous implementation.
    # A malformed value must not make all rewards permanently unavailable.
    claimed = data.get("claimed_ids")
    if not isinstance(claimed, list):
        data["claimed_ids"] = []
    last = int(data.get("last_touch") or 0)
    if last > 0:
        delta = max(0, min(now - last, 3600))
        data["daily_time"] = min(86400, int(data.get("daily_time") or 0) + delta)
        data["weekly_time"] = min(604800, int(data.get("weekly_time") or 0) + delta)
    data["last_touch"] = now
    _save_json_state(player, "online_reward_data", data)
    return data


def _online_reward_items_dto(items):
    body = b""
    for item_id, amount in items:
        item_dto = pb_varint_field(1, item_id) + pb_varint_field(2, amount)
        body += pb_tag(2, 2) + uvarint(len(item_dto)) + item_dto
    return body


def _online_reward_next_id(data):
    """Return the sequential next daily reward id expected by the Flash client.

    The client treats this as a cursor, not as a boolean "currently claimable"
    flag: rows below the cursor are already claimed, the cursor row is the
    current milestone, and rows above it are greyed out.  Returning 0 while a
    player is merely waiting for the next milestone made every row look empty.
    """
    claimed = {int(x) for x in (data.get("claimed_ids") or []) if str(x).isdigit()}
    for reward_id, _online_secs, _items in ONLINE_REWARD_SPECS:
        if reward_id not in claimed:
            return reward_id
    # OnlineRewardModel uses `> Total_Daily_Reward` to represent completion.
    return len(ONLINE_REWARD_SPECS) + 1


def handle_online_reward_getinfo(cmd_data, player):
    data = _online_reward_touch(player)
    if int(data.get("daily_time") or 0) >= ONLINE_REWARD_INTERVAL:
        _daily_quest_touch(player, "online", 1)
    body = (pb_varint_field(1, int(data.get("daily_time") or 0)) +
            pb_varint_field(2, int(data.get("weekly_time") or 0)) +
            pb_varint_field(3, int(data.get("last_touch") or 0)) +
            pb_varint_field(4, int(data.get("last_reward_time") or 0)) +
            pb_varint_field(5, _online_reward_next_id(data)) +
            pb_varint_field(7, 0))
    for _reward_id, online_secs, items in ONLINE_REWARD_SPECS:
        dto = pb_varint_field(1, online_secs) + _online_reward_items_dto(items)
        body += pb_tag(8, 2) + uvarint(len(dto)) + dto
    return [("PVZ.Cmd.Cmd_OnlineReward_GetInfo_SC", body)]


def handle_online_reward_takereward(cmd_data, player):
    data = _online_reward_touch(player)
    reward_id = _online_reward_next_id(data)
    if reward_id > len(ONLINE_REWARD_SPECS):
        return [("PVZ.Cmd.Cmd_OnlineReward_TakeReward_SC", pb_varint_field(1, 0))]
    spec = next((row for row in ONLINE_REWARD_SPECS if row[0] == reward_id), None)
    if spec is None:
        return [("PVZ.Cmd.Cmd_OnlineReward_TakeReward_SC", pb_varint_field(1, 0))]
    _reward_id, _online_secs, items = spec
    if int(data.get("daily_time") or 0) < int(_online_secs):
        return [("PVZ.Cmd.Cmd_OnlineReward_TakeReward_SC", pb_varint_field(1, 0))]
    claimed = [int(x) for x in (data.get("claimed_ids") or []) if str(x).isdigit()]
    if reward_id not in claimed:
        claimed.append(reward_id)
    data["claimed_ids"] = claimed
    data["last_reward_time"] = int(time.time())
    _save_json_state(player, "online_reward_data", data)
    messages = grant_fuben_reward(player, items)
    body = pb_varint_field(1, reward_id) + _online_reward_items_dto(items)
    messages.append(("PVZ.Cmd.Cmd_OnlineReward_TakeReward_SC", body))
    # TakeReward_SC is only the flying-item animation; the Flash service does
    # not advance OnlineRewardModel from that packet.  Push fresh state so the
    # cursor advances immediately and the next tile becomes usable.
    messages.extend(handle_online_reward_getinfo(b"", player))
    return messages


def handle_online_reward_takerewardweekly(cmd_data, player):
    # The client still expects an SC even though this local build has no weekly
    # reward table.  Returning an empty, valid message keeps the panel usable.
    return [("PVZ.Cmd.Cmd_OnlineReward_TakeRewardWeekly_SC", b"")]


# Question / quiz ------------------------------------------------------------
_QUESTION_POOL = [
    {"id": 1, "question": "向日葵每次生产多少阳光？", "answers": ["25", "50", "75", "100"], "correct": 1},
    {"id": 2, "question": "豌豆射手一次发射几颗豌豆？", "answers": ["1", "2", "3", "4"], "correct": 0},
    {"id": 3, "question": "坚果墙主要作用是什么？", "answers": ["攻击", "减速", "防御", "生产阳光"], "correct": 2},
    {"id": 4, "question": "樱桃炸弹的伤害范围？", "answers": ["单格", "3x3", "一行", "全屏"], "correct": 1},
    {"id": 5, "question": "土豆雷需要准备后才能生效吗？", "answers": ["需要", "不需要", "只在夜晚", "只在水上"], "correct": 0},
    {"id": 6, "question": "寒冰射手的主要效果是什么？", "answers": ["点燃", "减速", "治疗", "召唤"], "correct": 1},
]
_QUESTION_DAILY_LIMIT = 5
_QUESTION_RETRY_LIMIT = 3
_QUESTION_REWARDS = [(2002, 5), (2012, 1)]


def _question_state(player):
    today = time.strftime("%Y%m%d")
    data = _load_json_state(player, "question_data", {})
    if data.get("day") != today:
        data = {"day": today, "answered": 0, "correct": 0, "wrong": 0,
                "retry": 0, "status": 0, "current": 0, "last_answer": 0,
                "answered_ids": []}
        _save_json_state(player, "question_data", data)
    return data


def handle_question_info(cmd_data, player):
    data = _question_state(player)
    if int(data.get("answered") or 0) >= _QUESTION_DAILY_LIMIT:
        data["status"] = 1
        _save_json_state(player, "question_data", data)
    return (pb_bool(1, True) + pb_varint_field(2, int(data.get("status") or 0)) +
            pb_varint_field(3, max(0, _QUESTION_DAILY_LIMIT - int(data.get("answered") or 0))) +
            pb_varint_field(4, max(0, _QUESTION_RETRY_LIMIT - int(data.get("retry") or 0))) +
            (pb_varint_field(7, int(data.get("last_answer") or 0)) if data.get("last_answer") else b""))


def handle_question_data(cmd_data, player):
    data = _question_state(player)
    answered = set(int(x) for x in data.get("answered_ids", []) if str(x).isdigit())
    pool = [q for q in _QUESTION_POOL if q["id"] not in answered] or _QUESTION_POOL
    question = random.choice(pool)
    data["current"] = question["id"]
    _save_json_state(player, "question_data", data)
    body = (pb_varint_field(1, question["id"]) + pb_varint_field(2, int(time.time())) +
            pb_string(3, question["question"]))
    for answer in question["answers"]:
        body += pb_tag(4, 2) + uvarint(len(answer.encode("utf-8"))) + answer.encode("utf-8")
    return [("PVZ.Cmd.Cmd_Question_Data_SC", body)]


def handle_question_answer(cmd_data, player):
    answer = parse_varint_fields(cmd_data).get(1, 0)
    data = _question_state(player)
    if int(data.get("answered") or 0) >= _QUESTION_DAILY_LIMIT or int(data.get("retry") or 0) >= _QUESTION_RETRY_LIMIT:
        return [("PVZ.Cmd.Cmd_Question_Answer_SC", pb_bool(1, False))]
    question = next((q for q in _QUESTION_POOL if q["id"] == int(data.get("current") or 0)), None)
    if not question:
        return [("PVZ.Cmd.Cmd_Question_Answer_SC", pb_bool(1, False))]
    ok = int(answer) == int(question["correct"])
    data["last_answer"] = int(answer)
    if ok:
        data["answered"] = int(data.get("answered") or 0) + 1
        data["correct"] = int(data.get("correct") or 0) + 1
        data["retry"] = 0
        data.setdefault("answered_ids", []).append(question["id"])
        if data["answered"] >= _QUESTION_DAILY_LIMIT:
            data["status"] = 1
        _daily_quest_touch(player, "question", 1)
    else:
        data["wrong"] = int(data.get("wrong") or 0) + 1
        data["retry"] = int(data.get("retry") or 0) + 1
    _save_json_state(player, "question_data", data)
    return [("PVZ.Cmd.Cmd_Question_Answer_SC", pb_bool(1, ok))]


def handle_question_takereward(cmd_data, player):
    data = _question_state(player)
    if int(data.get("status") or 0) != 1:
        return [("PVZ.Cmd.Cmd_Question_TakeReward_SC", b"")]
    data["status"] = 2
    _save_json_state(player, "question_data", data)
    messages = grant_fuben_reward(player, _QUESTION_REWARDS)
    body = b""
    for item_id, amount in _QUESTION_REWARDS:
        dto = pb_varint_field(1, item_id) + pb_varint_field(2, amount)
        body += pb_tag(1, 2) + uvarint(len(dto)) + dto
    messages.append(("PVZ.Cmd.Cmd_Question_TakeReward_SC", body))
    return messages


def handle_question_getrank(cmd_data, player):
    body = b""
    try:
        with store._db() as con:
            rows = con.execute("SELECT uin,name,level,question_data FROM players").fetchall()
        ranked = []
        for row in rows:
            try:
                q = json.loads(row["question_data"] or "{}")
                value = int(q.get("correct", 0))
            except (TypeError, ValueError, json.JSONDecodeError):
                value = 0
            ranked.append((value, int(row["uin"]), row["name"] or "Player", int(row["level"] or 1)))
        for rank, (value, uin, name, level) in enumerate(sorted(ranked, reverse=True)[:10], 1):
            dto = (pb_int64_field(1, uin) + pb_varint_field(2, value) + pb_varint_field(4, 0) +
                   pb_string(5, name) + pb_varint_field(6, level) + pb_varint_field(7, int(time.time())))
            body += pb_tag(1, 2) + uvarint(len(dto)) + dto
    except Exception:
        log.exception("question rank build failed")
    return [("PVZ.Cmd.Cmd_Question_GetRank_SC", body)]


def handle_question_giveup(cmd_data, player):
    data = _question_state(player)
    data["current"] = 0
    _save_json_state(player, "question_data", data)
    return [("PVZ.Cmd.Cmd_Question_GiveUp_SC", b"")]


# Daily quests ---------------------------------------------------------------
# Only wire up tasks for which this local server has the matching gameplay
# event. These IDs and rewards must come from DailyQuestInfo, not invented rows
# 2..5 (which mean sign-in, vault harvest, gift energy and friend fights).
_DAILY_QUEST_EVENTS = {1: "login", 50: "fuben", 43: "question"}
_DAILY_QUEST_SPECS = None


def _daily_quest_specs():
    global _DAILY_QUEST_SPECS
    if _DAILY_QUEST_SPECS is None:
        rows = _read_clientdb_table("DailyQuestInfo.txt")
        header = {name: i for i, name in enumerate(rows[0])}
        found = {}
        for row in rows[1:]:
            if not row or not row[0].isdigit():
                continue
            qid = int(row[0])
            if qid in _DAILY_QUEST_EVENTS:
                found[qid] = (qid, _DAILY_QUEST_EVENTS[qid],
                              int(row[header["allTimes"]]),
                              tuple(parse_bonus_items(row[header["reward"]])),
                              int(row[header["openLv"]]))
        if set(found) != set(_DAILY_QUEST_EVENTS):
            raise ValueError("DailyQuestInfo 缺少本地实现所需的任务配置")
        _DAILY_QUEST_SPECS = tuple(found[qid] for qid in _DAILY_QUEST_EVENTS)
    return _DAILY_QUEST_SPECS


def _daily_quest_load_locked(con, player):
    """Read the current committed record while holding the writer lock."""
    row = con.execute("SELECT daily_quest_data FROM players WHERE uin=?", (player["uin"],)).fetchone()
    if row is None:
        raise ValueError("player missing")
    try:
        data = json.loads(row[0] or "{}")
        if not isinstance(data, dict):
            data = {}
    except (TypeError, ValueError, json.JSONDecodeError):
        data = {}
    today = time.strftime("%Y%m%d")
    changed = False
    if data.get("day") != today:
        data = {"schema": 2, "day": today, "quests": {}}
        changed = True
    elif int(data.get("schema", 0)) < 2:
        # Preserve a reward already taken today under the old wrong IDs.
        quests = data.setdefault("quests", {})
        for old_id, configured_id in ((2, 50), (3, 43)):
            old = quests.get(str(old_id), {})
            if old:
                current = quests.setdefault(str(configured_id), {"count": 0, "taken": False})
                current["count"] = max(int(current.get("count") or 0), int(old.get("count") or 0))
                current["taken"] = bool(current.get("taken")) or bool(old.get("taken"))
        data["schema"] = 2
        changed = True
    quests = data.setdefault("quests", {})
    for qid, _, _, _, _ in _daily_quest_specs():
        if str(qid) not in quests:
            quests[str(qid)] = {"count": 0, "taken": False}
            changed = True
    return data, changed


def _daily_quest_state(player):
    with store._db() as con:
        con.execute("BEGIN IMMEDIATE")
        data, changed = _daily_quest_load_locked(con, player)
        raw = json.dumps(data, ensure_ascii=False, separators=(",", ":"))
        if changed:
            con.execute("UPDATE players SET daily_quest_data=? WHERE uin=?", (raw, player["uin"]))
    player["daily_quest_data"] = raw
    return data


def _daily_quest_touch(player, key, amount=1):
    with store._db() as con:
        con.execute("BEGIN IMMEDIATE")
        data, changed = _daily_quest_load_locked(con, player)
        for qid, qkey, target, _, _ in _daily_quest_specs():
            if qkey != key:
                continue
            row = data["quests"][str(qid)]
            new = min(target, int(row.get("count") or 0) + max(0, int(amount)))
            if new != int(row.get("count") or 0):
                row["count"] = new
                changed = True
        raw = json.dumps(data, ensure_ascii=False, separators=(",", ":"))
        if changed:
            con.execute("UPDATE players SET daily_quest_data=? WHERE uin=?", (raw, player["uin"]))
    player["daily_quest_data"] = raw
    return data


def _daily_quest_dto(qid, count, target, taken):
    state = 4 if taken else (3 if count >= target else 2)
    return pb_varint_field(1, qid) + pb_varint_field(2, min(target, count)) + pb_varint_field(3, state)


def handle_dailyquest_getinfo(cmd_data, player):
    _daily_quest_touch(player, "login", 1)
    data = _daily_quest_state(player)
    body = b""
    for qid, _, target, _, _ in _daily_quest_specs():
        row = data.get("quests", {}).get(str(qid), {})
        dto = _daily_quest_dto(qid, int(row.get("count") or 0), target, bool(row.get("taken")))
        body += pb_tag(1, 2) + uvarint(len(dto)) + dto
    return [("PVZ.Cmd.Cmd_DailyQuest_GetInfo_SC", body)]


def handle_dailyquest_takereward(cmd_data, player):
    qid = parse_varint_fields(cmd_data).get(1, 0)
    spec = next((q for q in _daily_quest_specs() if q[0] == qid), None)
    if spec is None:
        return handle_dailyquest_getinfo(b"", player)
    with store._db() as con:
        con.execute("BEGIN IMMEDIATE")
        data, changed = _daily_quest_load_locked(con, player)
        row = data["quests"][str(qid)]
        allowed = (not row.get("taken") and int(row.get("count") or 0) >= spec[2]
                   and int(player.get("level") or 0) >= spec[4])
        if allowed:
            row["taken"] = True
            changed = True
            rewards = spec[3]
            currencies = {}
            items = {}
            for item_id, amount in rewards:
                if item_id in _CURRENCY_SYNC:
                    field, _ = _CURRENCY_SYNC[item_id]
                    currencies[field] = currencies.get(field, 0) + amount
                elif item_id not in _UNMODELED_CURRENCIES:
                    items[item_id] = items.get(item_id, 0) + amount
            columns = ["daily_quest_data=?"] + [field + "=" + field + "+?" for field in currencies]
            values = [json.dumps(data, ensure_ascii=False, separators=(",", ":"))]
            values.extend(currencies.values())
            con.execute("UPDATE players SET " + ",".join(columns) + " WHERE uin=?", values + [player["uin"]])
            item_counts = {}
            for item_id, amount in items.items():
                con.execute("INSERT INTO items(uin,item_id,count) VALUES(?,?,?) "
                            "ON CONFLICT(uin,item_id) DO UPDATE SET count=count+excluded.count",
                            (player["uin"], item_id, amount))
                item_counts[item_id] = con.execute("SELECT count FROM items WHERE uin=? AND item_id=?",
                                               (player["uin"], item_id)).fetchone()[0]
            wallet = {field: con.execute("SELECT " + field + " FROM players WHERE uin=?",
                                         (player["uin"],)).fetchone()[0] for field in currencies}
        elif changed:
            con.execute("UPDATE players SET daily_quest_data=? WHERE uin=?",
                        (json.dumps(data, ensure_ascii=False, separators=(",", ":")), player["uin"]))
    player["daily_quest_data"] = json.dumps(data, ensure_ascii=False, separators=(",", ":"))
    if not allowed:
        # No success response: QuestService would play the collection sound
        # even for an empty reward. Refresh the panel from authoritative state.
        return handle_dailyquest_getinfo(b"", player)
    messages = []
    for item_id in rewards:
        iid = item_id[0]
        if iid in _CURRENCY_SYNC:
            field, sc = _CURRENCY_SYNC[iid]
            player[field] = int(wallet[field])
            messages.append((sc, pb_varint_field(1, player[field])))
    if item_counts:
        messages.append(("PVZ.Cmd.Cmd_Item_Update_SC", b"".join(
            pb_tag(1, 2) + uvarint(len(dto)) + dto
            for dto in (build_item_dto(iid, count) for iid, count in item_counts.items()))))
    dto = _daily_quest_dto(qid, int(row["count"]), spec[2], True)
    messages.append(("PVZ.Cmd.Cmd_DailyQuest_Sync_SC", pb_tag(1, 2) + uvarint(len(dto)) + dto))
    body = pb_varint_field(1, qid)
    for item_id, amount in rewards:
        dto = pb_varint_field(1, item_id) + pb_varint_field(2, amount)
        body += pb_tag(2, 2) + uvarint(len(dto)) + dto
    messages.append(("PVZ.Cmd.Cmd_DailyQuest_TakeReward_SC", body))
    return messages


def handle_dailyactivity_getinfo(cmd_data, player):
    # DailyActInfo.txt (not dailyActivityInfo.txt) is the table used by the
    # QuestModel/DailyActInfo client model.  The old code sent every task id
    # (including ids 9..28 which do not exist in the client's DailyActInfo
    # table); its sort/checkNeedShow path then dereferenced a null object and
    # produced the ActionScript #1009 shown during login and in town.
    now = int(time.time())
    body = b""
    rows = _read_clientdb_table("DailyActInfo.txt") or []
    for row in rows[1:]:
        try:
            activity_id = int(row[0])
        except (ValueError, IndexError):
            continue
        dto = pb_varint_field(1, activity_id) + pb_varint_field(2, now - 86400 * 30) + pb_varint_field(3, now + 86400 * 30)
        body += pb_tag(1, 2) + uvarint(len(dto)) + dto
    return [("PVZ.Cmd.Cmd_DailyActivity_GetInfo_SC", body)]


def handle_dailyactivity_sync(cmd_data, player):
    activity_id = parse_varint_fields(cmd_data).get(1, 0)
    valid_ids = set()
    rows = _read_clientdb_table("DailyActInfo.txt") or []
    for row in rows[1:]:
        try:
            valid_ids.add(int(row[0]))
        except (ValueError, IndexError):
            pass
    if activity_id not in valid_ids:
        return [("PVZ.Cmd.Cmd_DailyActivity_Sync_SC", b"")]
    now = int(time.time())
    dto = pb_varint_field(1, activity_id) + pb_varint_field(2, now - 86400 * 30) + pb_varint_field(3, now + 86400 * 30)
    return [("PVZ.Cmd.Cmd_DailyActivity_Sync_SC", pb_tag(1, 2) + uvarint(len(dto)) + dto)]


