# Arena / ranked arena -------------------------------------------------------
def _warm_up_templates():
    """Pre-parse every lazily-loaded clientDB table the login sequence touches.

    Without this the FIRST login after a server start pays a 2-3s tax while
    GetPackage / GetFormation handlers block on template parsing (the `loaded ...`
    log lines). Every loader here is an idempotent cached getter, so calling them
    at boot is free at request time; failures never block the server from starting.
    """
    loaders = (
        load_battle_cards, load_level_rewards, td_lab_material_ids, need_exp,
        load_item_sell_info, load_buildings, load_fuben_chapters, load_fuben_stages,
        load_energy_buy, _load_level_energy_max, load_card_fruit_info,
        load_plant_evolution, load_plant_armor, load_card_dna, load_card_puzzle,
        load_card_forge, load_card_forge_chances, load_recruit_recipes,
        load_card_avatar_templates, load_card_avatar_forge, load_card_avatar_assets,
        load_plant_talents, load_lab, load_wt, load_nutrition_property,
        load_baptize_tables, load_zombie_island_levels, load_zombie_island_template,
        load_dummy_config, load_hdfuben_config, load_awake_rules, load_awake_config,
    )
    for loader in loaders:
        try:
            if loader is need_exp:
                need_exp(999)            # load all role-level exp thresholds at once
            else:
                loader()
        except Exception as exc:         # one bad table must not stop the boot
            log.warning("template warm-up %s failed (non-fatal): %s", loader.__name__, exc)
    log.info("template warm-up done (%d tables preloaded)", len(loaders))


# --- bot card development (真实养成) -------------------------------------------------
# 植物战力不是只靠等级 —— 等级上限就是 300 级 —— 还要靠 拼图 / 锻造 / 果实 / 觉醒(威望) /
# 护甲 / 洗炼。机器人因此按同一个"养成进度"同时推进所有系统，这样面板显示的战力就是它真实
# 的战斗强度（arena 现在按真实阵容开打，显示≠实力会立刻穿帮）。
_BOT_CARD_MAX_LEVEL = 300        # cardLevel.txt / 植物等级上限
_BOT_FRUIT_SLOTS = 14            # card_fruits 的 slot（quality 列）
_BOT_FRUIT_MAX_LEVEL = 20
_BOT_FORGE_MAX = 10
_BOT_EVOLVE_MAX = 200            # plantEvolutionLevelTemplate.txt
_BOT_FILL_MAX = 45               # cardPuzzle.txt 段数
_BOT_BAPTIZE_CAP = {"attack": 300000, "defense": 150000, "hp": 900000, "ability": 150000}


def bot_develop_card(uin, uid, cid, fraction):
    """Push one bot card's progression to `fraction` (0..1] on EVERY track at once.

    Returns the card level that was set. All tracks are read back by effective_card_stats, so the
    power computed from them is exactly what the client displays and what resolve_battle fights."""
    f = max(0.0, min(1.0, float(fraction)))
    level = max(1, int(round(1 + f * (_BOT_CARD_MAX_LEVEL - 1))))
    store.set_card_level(uin, uid, level, 0)
    store.set_card_fill_quality(uin, uid, int(round(f * _BOT_FILL_MAX)))
    store.set_card_forge_level(uin, uid, int(round(f * _BOT_FORGE_MAX)))
    for slot in range(1, _BOT_FRUIT_SLOTS + 1):
        store.set_card_fruit_level(uin, uid, slot, int(round(f * _BOT_FRUIT_MAX_LEVEL)))
    store.set_card_evolve_level(uin, uid, int(round(f * _BOT_EVOLVE_MAX)))
    for armor_type in (1, 2, 3):
        star = int(round(f * 5))
        store.set_card_armor(uin, uid, armor_type, star, max(0, star - 1),
                             max(1, int(round(f * 300))), 0)
    store.set_card_baptize(uin, uid, {key: int(round(value * f))
                                      for key, value in _BOT_BAPTIZE_CAP.items()},
                           int(f * 999))
    return level


def _seed_bots():
    """Wire the bots module to the real store/card pipelines and (idempotently) create the bot
    accounts, their lineups, arena scores, and the two bot guilds. Runs once at server start."""
    try:
        bots_local.initialize(
            db_path=store.DB_PATH,
            guild_db_path=guild_local._DB_PATH,
            api={
                "log": log.info,
                "get_or_create_player": lambda uin: store.get_or_create_player(uin),
                "save_player": store.save_player,
                "add_card": store.add_card,
                "get_cards": store.get_cards,
                "clear_cards_and_formation": store.clear_cards_and_formation,
                "get_formation": store.get_formation,
                "set_formation": store.set_formation,
                "card_power_at": lambda cid, level: card_power(card_stats_at_level(cid, level)),
                "develop_card": bot_develop_card,
                "card_power_full": (lambda uin, cid, level, uid:
                                    card_power(effective_card_stats(
                                        store.get_or_create_player(uin)[0], cid, level, uid=uid))),
            })
        bots_local.ensure_bots()
    except Exception as exc:                      # bots must never block the server from booting
        log.warning("bots seeding failed (non-fatal): %s", exc)


def _bot_roster_with_state():
    """[(roster_entry, state_dict)] for every seeded bot, sorted by arena score DESC."""
    out = []
    for b in bots_local.bots():
        state = bots_local.bot_state(b["uin"]) or {"score": b["score"], "power": 0,
                                                   "wins": 0, "losses": 0}
        out.append((b, state))
    out.sort(key=lambda pair: -int(pair[1]["score"]))
    return out


def _bot_diamond(uin):
    bot_player, _ = store.get_or_create_player(uin)
    return build_player_diamond(bot_player)


def _arena_leaderboard_entries(player, rank_arena=False):
    """Leaderboard DTOs for the arena / ranked-arena boards: every bot plus the requester,
    ordered by score. The client draws the standing from the list order, so the DTOs reuse
    _arena_top_dto's exact field shapes."""
    entries = []
    for b, state in _bot_roster_with_state():
        bot_player, _ = store.get_or_create_player(b["uin"])
        entries.append({"uin": b["uin"], "score": int(state["score"]),
                        "dto": _arena_top_dto(bot_player, b["uin"], b["name"], 0,
                                              rank_arena=rank_arena)})
    data = _arena_state(player, "rank_arena_data" if rank_arena else "arena_data")
    entries.append({"uin": player["uin"], "score": int(data.get("score") or 0),
                    "dto": _arena_top_dto(player, player["uin"], player.get("name", "Player"), 0,
                                          rank_arena=rank_arena)})
    entries.sort(key=lambda e: -e["score"])
    return entries


def _arena_state(player, field):
    today = time.strftime("%Y%m%d")
    data = _load_json_state(player, field, {})
    if data.get("day") != today:
        data.update({"day": today, "challenges": 0, "cooldown": 0, "taken": False})
    data.setdefault("score", 100); data.setdefault("wins", 0); data.setdefault("losses", 0)
    data.setdefault("records", [])
    _save_json_state(player, field, data)
    return data


def _arena_recorder(player, opponent_id=0, opponent_name="训练对手", win=True, change=10, rank=False,
                    report_uid=0):
    """Dto_RankArenaRecorder{reportUid(1,I64), enemyRoleId(2,I64), enemyName(3), ...}.

    reportUid must be the id of a report the server can hand back: RankArenaProxy takes it straight
    from Challenge_SC and calls GameFlowCmd.queryReport(reportUid) to replay the match. Passing a
    bare timestamp (the previous behaviour) pointed at a report that never existed."""
    now = int(time.time())
    uid = int(report_uid or now)
    if rank:
        return (pb_int64_field(1, uid) + pb_int64_field(2, opponent_id) + pb_string(3, opponent_name) +
                pb_varint_field(4, 0) + pb_varint_field(5, 1) + pb_bool(7, win) + pb_bool(8, True) +
                pb_varint_field(9, now))
    return (pb_int64_field(1, uid) + pb_int64_field(2, opponent_id) + pb_string(3, opponent_name) +
            pb_varint_field(4, 0) + pb_varint_field(5, 1) + pb_varint_field(6, max(0, change)) +
            pb_bool(7, win) + pb_bool(8, True))


def _arena_rank(data):
    return max(1, 1000 - int(data.get("score") or 0))


def handle_arena_getmyinfo(cmd_data, player):
    data = _arena_state(player, "arena_data")
    body = (pb_varint_field(1, _arena_rank(data)) + pb_varint_field(2, int(data.get("score") or 0)) +
            pb_varint_field(3, 1) + pb_varint_field(4, 2) +
            pb_varint_field(5, max(0, 5 - int(data.get("challenges") or 0))) + pb_varint_field(6, 0) + pb_bool(7, True))
    for rec in data.get("records", [])[-20:]:
        dto = _arena_recorder(player, int(rec.get("opponent", 0)), rec.get("name", "训练对手"), bool(rec.get("win", True)), int(rec.get("change", 10)))
        body += pb_tag(8, 2) + uvarint(len(dto)) + dto
    return [("PVZ.Cmd.Cmd_Arena_GetMyInfo_SC", body)]


def _arena_top_dto(player, uin, name, rank, rank_arena=False):
    if rank_arena:
        return (pb_int64_field(1, uin) + pb_string(2, name) + pb_varint_field(3, 0) + pb_varint_field(4, 1) +
                pb_varint_field(8, rank) + pb_varint_field(14, 0))
    diamond = build_player_diamond(player)
    return (pb_int64_field(1, uin) + pb_varint_field(2, 0) + pb_string(3, name) + pb_string(4, "") +
            pb_tag(5, 2) + uvarint(len(diamond)) + diamond)


def handle_arena_getrank(cmd_data, player):
    # A real ladder now: every bot + the requester ordered by arena score (bots included via
    # bots_local so the board is never empty and the ranking moves as matches are fought).
    body = b""
    for entry in _arena_leaderboard_entries(player, rank_arena=False):
        body += pb_tag(1, 2) + uvarint(len(entry["dto"])) + entry["dto"]
    return [("PVZ.Cmd.Cmd_Arena_GetRank_SC", body)]


def handle_arena_gettopplayers(cmd_data, player):
    grade = parse_varint_fields(cmd_data).get(1, 1)
    body = b""
    for entry in _arena_leaderboard_entries(player, rank_arena=False):
        body += pb_tag(2, 2) + uvarint(len(entry["dto"])) + entry["dto"]
    return [("PVZ.Cmd.Cmd_Arena_GetTopPlayers_SC", pb_varint_field(1, grade) + body)]


def _arena_getformation(player, team_id=2, sc_name="PVZ.Cmd.Cmd_Arena_GetFormation_SC"):
    ensure_player_cards(player)
    formation = build_formation_info(player, team_id, default_formation_placements(player))
    return [(sc_name, pb_tag(1, 2) + uvarint(len(formation)) + formation)]


def handle_arena_getformation(cmd_data, player):
    return _arena_getformation(player)


def _store_arena_setformation(cmd_data, player, leader_team_id):
    """Persist an arena-family lineup.

    The slot ARRANGEMENT is shared through team 1 (every arena-family Get handler reads it
    from ``default_formation_placements``), but the chosen LEADER is stored per mode so
    build_formation_info can hand it back on the matching Get*_SC: ranked arena -> team 2,
    ladder battle/defense -> team 3, cross-server attack -> team 1, cross-server defense ->
    team 3.  ``leader_team_id`` selects the formation_leader row to write.  Previously the
    Dto_FormationInfo.leaderUid (field 3) was dropped entirely, so "set captain" never stuck.
    """
    placements, leader_uid = {}, 0
    fsub = parse_repeated_submessages(cmd_data, 1)
    if fsub:
        leader_uid = parse_varint_fields(fsub[0]).get(3, 0)
        for cp in parse_repeated_submessages(fsub[0], 1):
            fields = parse_varint_fields(cp)
            if fields.get(1) and fields.get(2):
                placements[int(fields[1])] = int(fields[2])
    if placements:
        store.set_formation(player["uin"], 1, placements)
        if leader_uid in placements.values():
            store.set_formation_leader(player["uin"], leader_team_id, leader_uid)
    return placements


def handle_arena_setformation(cmd_data, player):
    placements = _store_arena_setformation(cmd_data, player, 2)
    log.info("    arena SET formation: %s", placements)
    # There is no Cmd_Arena_SetFormation_SC.  The client's existing
    # Cmd_Arena_GetFormation_SC listeners replace its local formation VO
    # and refresh the embattle page; without this reply the drag rolls back.
    return _arena_getformation(player)


def _stable_roll(seed, salt, lo, hi):
    """Deterministic pseudo-random in [lo, hi]: the same fight seeds the same roll, so repeated
    previews of one match agree (local random stream, no global RNG perturbation)."""
    h = (int(seed or 0) * 1103515245 + int(salt or 0) * 12345 + 0x5DEECE6D) & 0x7FFFFFFF
    h = (h >> 7) & 0xFFFF
    return lo + (hi - lo) * h / 65535.0


def _player_formation_power(player):
    """Sum of card_power over the player's team-1 formation (their arena strength)."""
    ensure_player_cards(player)
    placements = store.get_formation(player["uin"], 1)
    if not placements:
        placements = default_formation_placements(player)
    total = 0
    for uid in placements.values():
        card = next((c for c in store.get_cards(player["uin"]) if c[0] == int(uid)), None)
        if card:
            total += card_power(card_stats_at_level(card[1], max(1, int(card[2] or 1))))
    return total


def _arena_challenge(player, field, sc_name, rank=False):
    data = _arena_state(player, field)
    limit = 10 if rank else 5
    if int(data.get("challenges") or 0) >= limit:
        # Never answer with an empty (sc_name, b"") here. The client ArenaService
        # dereferences the recorder from _SC (arenaModel.addRecorder(recorder) +
        # queryReport(recorder.reportUid)), so a zero-length packet decodes to
        # recorder=null and throws Error #1009 - the button just looks dead.
        # 7705 = 当日挑战次数已用尽 (clientDB ErrorInfo.txt, handlerID=0).
        return [_logic_error(7705)]
    data["challenges"] = int(data.get("challenges") or 0) + 1
    # Pick the bot whose score is closest to the player's (never the same one twice in a row)
    # and settle the match on POWER: both sides roll 0.8-1.25x of their strength, so the strong
    # bot lineups are genuine threats ("人机的战力也不能弱") while a developed player roster
    # still wins more often than not.
    opponent = bots_local.pick_opponent(int(data.get("score") or 0),
                                        exclude=[int(data.get("last_opponent") or 0)])
    bot_power = int(opponent["power"]) if opponent else 0
    bot_name, bot_uin = ("训练对手", 0)
    if opponent:
        bot = next((b for b in bots_local.bots() if b["uin"] == opponent["uin"]), None)
        if bot:
            bot_name, bot_uin = bot["name"], bot["uin"]
    player_power = _player_formation_power(player)
    win = (player_power * _stable_roll(player["uin"], data["challenges"], 0.8, 1.25)
           >= bot_power * _stable_roll(bot_uin or 900001, data["challenges"], 0.8, 1.25))
    if win:
        change = 15 if not rank else 1
        data["score"] = int(data.get("score") or 0) + change
        data["wins"] = int(data.get("wins") or 0) + 1
    else:
        change = -8 if not rank else -1
        data["score"] = max(0, int(data.get("score") or 0) + change)
        data["losses"] = int(data.get("losses") or 0) + 1
    data["cooldown"] = int(time.time()) + 30
    data["last_opponent"] = bot_uin
    data.setdefault("records", []).append({"opponent": bot_uin, "name": bot_name,
                                           "win": win, "change": change})
    _save_json_state(player, field, data)
    if opponent:
        bots_local.apply_match_result(bot_uin, win)
    if rank:
        rec = _arena_recorder(player, bot_uin, bot_name, win=win, rank=True)
        return [(sc_name, pb_varint_field(1, _arena_rank(data)) + pb_bool(2, win) + pb_tag(3, 2) + uvarint(len(rec)) + rec)]
    # 段位 must hand the client a REAL report that carries its OWN fightType (Arena = 4): the
    # battle map is chosen from report.fightType (BattleSceneViewMediator -> arena_bottom.swf
    # for Arena, ladder_bottom.swf for RankArena = 12). A bare timestamp as reportUid made
    # GameFlowCmd.queryReport() miss and the stand-in report defaulted to 12, so 段位 rendered
    # 天梯 old ladder_bottom.swf. The body below is the SAME simulation the stand-in produced,
    # so only which built-in map the client loads changes; 天梯 keeps fight_type 12.
    left = build_player_units(player)
    right = _build_fallback_enemies(1, 1) or []
    shown_won, _lp, _rp = resolve_battle(left, right) if (left and right) else (True, 0, 0)
    rounds = simulate_battle(left, right, shown_won) if (left and right) else []
    report = build_fight_report(player, 0, 0, 0, shown_won, None, False, left, right,
                                encode_fight_replay(rounds), fight_type=_ARENA_TARGET)
    report_id = _store_battle_report(report)
    rec = _arena_recorder(player, bot_uin, bot_name, win=win, change=change, report_uid=report_id)
    return [(sc_name, pb_varint_field(1, _arena_rank(data)) + pb_varint_field(2, int(data["score"])) + pb_tag(3, 2) + uvarint(len(rec)) + rec)]


def handle_arena_challenge(cmd_data, player):
    _daily_quest_touch(player, "arena", 1)
    return _arena_challenge(player, "arena_data", "PVZ.Cmd.Cmd_Arena_Challenge_SC")


def handle_arena_showdailyreward(cmd_data, player):
    data = _arena_state(player, "arena_data")
    body = pb_varint_field(1, _arena_rank(data)) + pb_varint_field(2, 1) + pb_varint_field(3, 1) + pb_varint_field(4, 0) + pb_varint_field(5, 2) + pb_varint_field(6, 0) + pb_bool(7, bool(data.get("taken")))
    for item_id, amount in ((1, 5000), (4, 10)):
        dto = pb_varint_field(1, item_id) + pb_varint_field(2, amount)
        body += pb_tag(8, 2) + uvarint(len(dto)) + dto
